const FACTORY_AUTOMATION_ASSET_SCAN_LIMIT = 120;
const COMP_MARKET_STATE_RESULT_LIMIT = 80;
const COMP_MARKET_STATE_IMAGE_LIMIT = 80;
const FACTORY_PAGE_SESSION_ID = (() => {
  try {
    return (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
      ? crypto.randomUUID()
      : `page_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  } catch(_) {
    return `page_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  }
})();

function renderFactoryCompetitorPanel(factory) {
  const competitors = factoryCurrentWorkCompetitors(factory);
  const rows = [];
  competitors.slice(0, 20).forEach((item, index) => {
    if (item && typeof item === 'object') factoryFlattenDbRows(item, `경쟁사 ${index + 1}`, 'competitor', '', rows, 0);
  });
  const compact = competitors.slice(0, 6).map((item, index) => {
    const name = item?.product_name || item?.name || item?.title || item?.상품명 || `경쟁사 ${index + 1}`;
    const price = item?.price || item?.sale_price || item?.판매가 || item?.consumer_price || '';
    const url = item?.url || item?.link || item?.detail_url || '';
    return `<div class="factory-mini">
      참고 ${index + 1}<b>${escapeHtml(name)}</b>
      ${price ? `<span class="factory-small">${escapeHtml(String(price))}</span>` : ''}
      ${url ? `<span class="factory-small" title="${escAttr(url)}">${escapeHtml(String(url).slice(0, 46))}</span>` : ''}
    </div>`;
  }).join('');
  return `<div class="factory-card" style="margin-top:12px">
    <div class="factory-db-review-head" style="margin-bottom:8px">
      <div>
        <h4>경쟁사 참고자료</h4>
        <p>경쟁사 자료는 완성 DB 값으로 섞지 않고, 상세페이지 섹션/카피/구성 참고용으로만 따로 봅니다.</p>
      </div>
      <div class="factory-toolbar">
        <button class="btn-sm" id="factoryImportCompetitorBottom" type="button"><span class="material-icons-outlined" style="font-size:14px">travel_explore</span>경쟁사 결과 가져오기</button>
      </div>
    </div>
    ${competitors.length ? `<div class="factory-mini-grid">${compact}</div>` : `<div class="factory-small">아직 경쟁사 자료가 없습니다. 경쟁사 분석 탭 결과를 가져오거나 제품/DB 확보를 실행하면 여기에 따로 쌓입니다.</div>`}
    <details class="factory-db-raw" ${rows.length ? '' : 'style="display:none"'}>
      <summary>경쟁사 자료 필드 보기 (${rows.length}개)</summary>
      <div class="factory-db-raw-table">
        ${rows.slice(0, 160).map(row => `<div class="factory-db-raw-row">
          <b>${escapeHtml(row.sourceLabel)}</b>
          <code title="${escAttr(row.key)}">${escapeHtml(row.key)}</code>
          <span class="factory-db-raw-value" title="${escAttr(row.value)}">${escapeHtml(row.value)}</span>
          <span class="factory-db-source">참고</span>
        </div>`).join('')}
      </div>
    </details>
  </div>`;
}

function factoryCompetitorMatchesCurrentWork(item = {}, factory = factoryRuntimeReadFactory()) {
  let current = null;
  try {
    if (typeof compMarketCurrentWorkScope === 'function') current = compMarketCurrentWorkScope();
  } catch(_) {
    current = null;
  }
  const currentWorkspaceId = String(
    state.currentProjectId ||
    factory?.workspace?.id ||
    factory?.currentProjectId ||
    ''
  ).trim();
  const itemWorkspaceId = String(
    item?.workspaceId ||
    item?.currentProjectId ||
    item?.projectId ||
    item?.metadata?.workspaceId ||
    item?.metadata?.currentProjectId ||
    ''
  ).trim();
  if (!currentWorkspaceId || (itemWorkspaceId && currentWorkspaceId !== itemWorkspaceId)) return false;
  if (!itemWorkspaceId && typeof compMarketCandidateMatchesCurrentWork !== 'function') return false;
  return typeof compMarketCandidateMatchesCurrentWork !== 'function'
    || compMarketCandidateMatchesCurrentWork(item, current, { allowHistoricalRun: true });
}

function factoryCurrentWorkCompetitors(factory = factoryRuntimeReadFactory()) {
  const list = Array.isArray(factory?.product?.competitors) ? factory.product.competitors : [];
  return list.filter(item => factoryCompetitorMatchesCurrentWork(item, factory));
}

function factoryEnsureAutomationRunScope(factory) {
  if (!factory || typeof factory !== 'object') return '';
  factory.automation = factory.automation && typeof factory.automation === 'object' ? factory.automation : {};
  let scopeKey = '';
  try {
    scopeKey = String(compMarketCurrentWorkScope()?.scopeKey || '').trim();
  } catch(_) {
    scopeKey = '';
  }
  if (!scopeKey) return '';
  const previous = String(factory.automation.startRunScopeKey || '').trim();
  if (previous && previous !== scopeKey) {
    factory.automation.startRunCounts = {};
  }
  factory.automation.startRunScopeKey = scopeKey;
  factory.automation.startRunCounts = factory.automation.startRunCounts && typeof factory.automation.startRunCounts === 'object'
    ? factory.automation.startRunCounts
    : {};
  return scopeKey;
}

function factorySinhwaCandidateKey(candidate) {
  return String(candidate?.jcode || candidate?.id || candidate?.product_name || candidate?.jname || '').trim();
}

function factoryCandidateScore(candidate, type = '') {
  const raw = type === 'cafe24'
    ? (candidate?.match_score ?? candidate?.local_match_score ?? candidate?.gpt_similarity_score ?? candidate?.score)
    : (candidate?.score ?? candidate?.match_score);
  const num = Number(raw);
  return Number.isFinite(num) ? Math.round(num) : null;
}

function factoryCandidateMetaItems(candidate, type = '') {
  if (type === 'cafe24') {
    const raw = parseCafe24Raw(candidate);
    const groups = factoryExtractCafe24OptionGroups(candidate, 'Cafe24 후보', 'cafe24');
    const optionCount = groups.reduce((sum, group) => sum + (group.values?.length || 0), 0);
    return [
      candidate?.factory_recent_append ? (candidate.factory_append_label || '이번 추가검색') : '',
      candidate?.direct_recall ? 'Cafe24 직접검색' : '',
      candidate?.product_no || raw.product_no ? `상품번호 ${candidate?.product_no || raw.product_no}` : '',
      candidate?.product_code || raw.product_code || '',
      candidate?.price || raw.price ? `${candidate?.price || raw.price}원` : '',
      candidate?.display || raw.display || candidate?.selling || raw.selling ? `진열 ${candidate?.display || raw.display || '-'} · 판매 ${candidate?.selling || raw.selling || '-'}` : '',
      optionCount ? `옵션 ${optionCount}개` : '',
    ].filter(Boolean);
  }
  return [
    candidate?.jcode ? `코드 ${candidate.jcode}` : '',
    candidate?.dimensions || candidate?.size || '',
    candidate?.sale_price ? `판매가 ${candidate.sale_price}` : '',
    Number.isFinite(Number(candidate?.stock_qty)) ? `재고 ${Number(candidate.stock_qty).toLocaleString('ko-KR')}` : '',
  ].filter(Boolean);
}

function factoryCandidateName(candidate, type = '') {
  if (type === 'cafe24') {
    const raw = parseCafe24Raw(candidate);
    return candidate?.product_name || raw.product_name || candidate?.product_code || raw.product_code || `Cafe24 후보`;
  }
  return candidate?.product_name || candidate?.jname || candidate?.jname2 || candidate?.jcode || '신화사DB 후보';
}

function factoryNormalizeWebImageUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  if (/^\/\//.test(raw)) return `https:${raw}`;
  return raw;
}

function factoryCandidateBrowserImageUrl(url) {
  const normalized = factoryNormalizeWebImageUrl(url);
  if (!normalized) return '';
  try {
    const parsed = new URL(normalized);
    if (parsed.hostname === '03030.co.kr' || parsed.hostname === 'www.03030.co.kr') {
      const base = typeof factoryBackendBaseUrl === 'function' ? factoryBackendBaseUrl() : 'http://127.0.0.1:5050';
      return `${String(base).replace(/\/+$/, '')}/api/image-proxy?raw=1&url=${encodeURIComponent(normalized)}`;
    }
  } catch (_) {
    return normalized;
  }
  return normalized;
}

function factoryCandidateImageUrl(candidate, type = '') {
  if (!candidate || typeof candidate !== 'object') return '';
  if (type === 'cafe24') {
    const raw = parseCafe24Raw(candidate);
    return factoryCandidateBrowserImageUrl(
      candidate.image ||
      candidate.detail_image ||
      raw.detail_image ||
      raw.list_image ||
      raw.small_image ||
      raw.tiny_image ||
      raw.image ||
      ''
    );
  }
  const images = Array.isArray(candidate.images) ? candidate.images : [];
  const first = images[0] || null;
  return factoryCandidateBrowserImageUrl(absoluteSinhwaMediaUrl(
    candidate.image ||
    candidate.thumb_url ||
    candidate.image_url ||
    candidate.file_path ||
    first?.thumb_url ||
    first?.url ||
    first?.file_path ||
    ''
  ));
}

function factoryCafe24CandidateProductUrl(candidate = {}) {
  if (!candidate || typeof candidate !== 'object') return '';
  const raw = parseCafe24Raw(candidate) || {};
  const direct = [
    candidate.product_url,
    candidate.productUrl,
    candidate.detail_url,
    candidate.detailUrl,
    candidate.link,
    candidate.url,
    raw.product_url,
    raw.productUrl,
    raw.detail_url,
    raw.detailUrl,
    raw.link,
    raw.url,
  ].map(value => String(value || '').trim()).find(value => /^https?:\/\//i.test(value));
  if (direct) return direct;
  const productNo = String(candidate.product_no || candidate.productNo || raw.product_no || raw.productNo || '').trim();
  if (!productNo) return '';
  const rawMall = String(candidate.mall_id || candidate.mallId || raw.mall_id || raw.mallId || 'bojagi1928').trim();
  const mallHost = /^https?:\/\//i.test(rawMall)
    ? rawMall.replace(/^https?:\/\//i, '').replace(/\/+$/, '')
    : (rawMall.includes('.') ? rawMall : `${rawMall}.cafe24.com`);
  return `https://${mallHost}/product/detail.html?product_no=${encodeURIComponent(productNo)}`;
}

function factoryCandidateCollectionStatusView(factory = {}, type = '', candidateCount = 0) {
  const taskId = type === 'cafe24' ? 'cafe24' : 'sinhwa';
  const progress = factory?.automation?.parallelProgress?.[taskId];
  const status = String(progress?.status || '').trim();
  const message = String(progress?.message || '').trim();
  const count = Math.max(0, Number(candidateCount || 0));
  if (status === 'queued') return { state: 'queued', label: '수집 대기', detail: message || '연결 확인을 기다리고 있습니다.' };
  if (status === 'running') {
    const ratio = Math.max(0, Math.min(100, Math.round(Number(progress?.progress || 0))));
    return { state: 'running', label: '수집 중', detail: [ratio ? `${ratio}%` : '', message].filter(Boolean).join(' · ') || '후보를 확인하고 있습니다.' };
  }
  if (status === 'error') return { state: 'error', label: '수집 실패', detail: message || '연결 상태를 확인한 뒤 다시 시도해주세요.' };
  if (status === 'skipped') return { state: 'skipped', label: '이번 수집에서 제외', detail: message || '선택한 수집 범위에 포함되지 않았습니다.' };
  if (status === 'done') {
    return count
      ? { state: 'found', label: `후보 ${count}건`, detail: message || '실제 제품과 맞는 후보를 선택해주세요.' }
      : { state: 'empty', label: '검색 결과 없음', detail: message || '신제품이면 아래 후보 없음으로 진행할 수 있습니다.' };
  }
  return count
    ? { state: 'found', label: `후보 ${count}건`, detail: '저장된 후보를 확인해주세요.' }
    : { state: 'idle', label: '아직 후보를 확인하지 않음', detail: '제품명 확인 후 후보 수집을 실행해주세요.' };
}

function factoryCandidateCollectionEmptyMessage(view = {}) {
  if (view.state === 'running') return '후보를 수집하고 있습니다. 응답이 도착하면 이 목록에 표시됩니다.';
  if (view.state === 'queued') return '후보 수집을 시작할 때까지 기다리고 있습니다.';
  if (view.state === 'found') return '후보 수집을 마쳤습니다. 목록을 정리하고 있습니다.';
  if (view.state === 'empty') return '검색 결과가 없습니다. 신제품이면 아래 후보 없음으로 진행할 수 있습니다.';
  if (view.state === 'error') return '후보 수집에 실패했습니다. 위 상태를 확인한 뒤 다시 시도해주세요.';
  return '아직 후보를 확인하지 않았습니다. 제품명을 확인하고 후보 수집을 실행해주세요.';
}

function renderFactoryCandidateCollectionStatus(factory = {}, type = '', candidateCount = 0) {
  const view = factoryCandidateCollectionStatusView(factory, type, candidateCount);
  return `<div class="factory-candidate-collection-status" data-factory-candidate-collection-status="${escAttr(type === 'cafe24' ? 'cafe24' : 'sinhwa')}" data-state="${escAttr(view.state)}" role="status" aria-live="polite" ${['queued', 'running'].includes(view.state) ? 'aria-busy="true"' : ''}>
    <span class="factory-candidate-collection-marker" aria-hidden="true"></span>
    <strong data-factory-candidate-collection-label>${escapeHtml(view.label)}</strong>
    <span data-factory-candidate-collection-detail>${escapeHtml(view.detail)}</span>
  </div>`;
}

function renderFactoryCandidateCards(candidates = [], type = '', factory = factoryRuntimeReadFactory()) {
  if (!candidates.length) {
    const collection = factoryCandidateCollectionStatusView(factory, type, 0);
    const emptyMessage = factoryCandidateCollectionEmptyMessage(collection);
    return `<div class="factory-small" data-factory-candidate-empty-state="${escAttr(type === 'cafe24' ? 'cafe24' : 'sinhwa')}">${escapeHtml(emptyMessage)}</div>
      ${type === 'cafe24' ? `<button class="btn-sm" data-factory-find-cafe24-inline data-factory-guide-action="rerun-cafe24-query" type="button" style="margin-top:8px" title="현재 제품명/이미지 판독명을 기준으로 Cafe24 후보만 다시 검색합니다."><span class="material-icons-outlined" style="font-size:14px">manage_search</span>Cafe24 후보만 찾기</button>` : ''}`;
  }
  const selectedKey = type === 'cafe24' ? factory.product.selectedCafe24CandidateKey : factory.product.selectedDbCandidateKey;
  return `<div class="factory-candidate-list">
    ${candidates.length > 20 ? `<div class="factory-small" style="margin-bottom:8px">${escapeHtml(type === 'cafe24' ? `Cafe24 후보 전체 ${candidates.length}건 중 현재 상위 20건을 표시합니다. 추가검색 새 후보는 맨 위에 먼저 표시됩니다.` : `후보 전체 ${candidates.length}건 중 현재 상위 20건을 표시합니다.`)}</div>` : ''}
    ${candidates.slice(0, 20).map((candidate, index) => {
      const key = type === 'cafe24' ? factoryCafe24CandidateKey(candidate) : factorySinhwaCandidateKey(candidate);
      const selected = key && selectedKey && key === selectedKey;
      const score = factoryCandidateScore(candidate, type);
      const query = candidate?.match_query || '';
      const meta = factoryCandidateMetaItems(candidate, type);
      const actionAttr = type === 'cafe24' ? 'data-factory-apply-cafe24-candidate' : 'data-factory-apply-db-candidate';
      const clearActionAttr = type === 'cafe24' ? 'data-factory-clear-cafe24-candidate' : 'data-factory-clear-db-candidate';
      const actionText = type === 'cafe24' ? '이 Cafe24 상품 맞음' : '이 신화사DB 맞음';
      const selectable = typeof factoryCandidateReviewCanApply === 'function' ? factoryCandidateReviewCanApply(candidate, factory) : true;
      const candidateScopeKey = typeof factoryCandidateReviewScopeKeyFromCandidate === 'function'
        ? factoryCandidateReviewScopeKeyFromCandidate(candidate)
        : String(candidate?.reviewProductScopeKey || '').trim();
      const currentScopeKey = typeof factoryCandidateReviewScopeKey === 'function'
        ? factoryCandidateReviewScopeKey(factory)
        : '';
      const actionTitle = selectable
        ? (type === 'cafe24' ? '이 Cafe24 후보를 실제 상품으로 확정하고 상품 입력판/옵션/가격 정보를 불러옵니다.' : '이 신화사DB 후보를 실제 상품으로 확정하고 완성 DB 기준값으로 사용합니다.')
        : `이 후보는 현재 작업파일의 제품 기준과 다릅니다. 후보 범위: ${candidateScopeKey || '미기록'} · 현재 범위: ${currentScopeKey || '미기록'}`;
      const imageUrl = factoryCandidateImageUrl(candidate, type);
      const productUrl = type === 'cafe24' ? factoryCafe24CandidateProductUrl(candidate) : '';
      return `<article class="factory-candidate-card ${selected ? 'selected' : ''}">
        <div class="factory-candidate-card-top">
          <span class="factory-candidate-rank">${index + 1}</span>
          <div class="factory-candidate-thumb" title="${imageUrl ? '후보 상품 이미지' : '후보 이미지 없음'}">
          ${imageUrl ? `<img src="${escAttr(imageUrl)}" alt="${escAttr(factoryCandidateName(candidate, type))}" loading="lazy" decoding="async">` : '<span class="material-icons-outlined">image_not_supported</span>'}
          </div>
          <div class="factory-candidate-text">
            <div class="factory-candidate-name">${escapeHtml(factoryCandidateName(candidate, type))}</div>
            <div class="factory-candidate-code">${escapeHtml([query ? `검색어 ${query}` : '', key ? `키 ${key}` : ''].filter(Boolean).join(' · '))}</div>
          </div>
          <div class="factory-candidate-actions" style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;justify-content:flex-end">
            ${productUrl ? `<a class="btn-sm" href="${escAttr(productUrl)}" target="_blank" rel="noopener" title="Cafe24 쇼핑몰의 이 후보 상품을 새 탭에서 엽니다." style="text-decoration:none;white-space:nowrap"><span class="material-icons-outlined" style="font-size:14px">open_in_new</span>제품 링크</a>` : (type === 'cafe24' ? '<span class="factory-small" title="상품번호가 없어 제품 링크를 만들 수 없습니다.">제품 링크 없음</span>' : '')}
            ${selected
              ? `<button class="btn-sm" ${actionAttr}="${index}" type="button" disabled>확정됨</button><button class="btn-sm" ${clearActionAttr} type="button" title="선택을 해제하고 후보 목록으로 돌아갑니다.">선택 해제</button>`
              : `<button class="btn-sm" ${actionAttr}="${index}" type="button" title="${escAttr(actionTitle)}" ${selectable ? '' : 'disabled'}>${selectable ? actionText : '현재 제품 기준 아님'}</button>`}
          </div>
        </div>
        <div class="factory-candidate-meta">
          ${score !== null ? `<span>점수 ${score}</span>` : ''}
          ${meta.map(item => `<span>${escapeHtml(item)}</span>`).join('')}
        </div>
        ${candidate?.gpt_reason ? `<div class="factory-candidate-note">${escapeHtml(candidate.gpt_reason)}</div>` : ''}
      </article>`;
    }).join('')}
  </div>`;
}

function renderFactorySinhwaDbProgramPrompt(factory) {
  const status = factory?.product?.sinhwaDbProgramStatus;
  if (!status || typeof status !== 'object') return '';
  const stateText = String(status.state || '');
  const showPrompt = !!status.offline || !!status.starting || stateText === 'offline' || stateText === 'starting' || stateText === 'error';
  if (!showPrompt) return '';
  const starting = !!status.starting || stateText === 'starting';
  const detail = String(status.detail || '').trim();
  const message = String(status.message || '').trim() || '신화사DB 후보가 꺼져 있어서 DB 수집을 할 수 없습니다. 신화사DB 프로그램을 실행하시겠습니까?';
  return `<div class="factory-card" style="margin:10px 0 12px;padding:12px;border-color:rgba(245,158,11,.58);background:rgba(245,158,11,.10)">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap">
      <div style="min-width:220px;flex:1">
        <div style="font-size:13px;font-weight:950;color:#fbbf24">신화사DB 실행 필요</div>
        <div style="font-size:13px;font-weight:900;color:var(--text);line-height:1.5;margin-top:4px">${escapeHtml(message)}</div>
        <div class="factory-small" style="margin-top:5px">실행되면 신화사DB 후보 수집을 자동으로 다시 시도합니다. Cafe24 후보와 VM 후보는 현재 작업 기준으로 유지됩니다.</div>
        ${detail ? `<div class="factory-small" style="margin-top:5px;color:var(--text-d)">진단: ${escapeHtml(factoryVisibleRunLogText(detail))}</div>` : ''}
      </div>
      <button class="btn-primary" type="button" data-factory-guide-action="start-sinhwa-db-and-rerun" ${starting ? 'disabled' : ''}>
        <span class="material-icons-outlined" style="font-size:16px">${starting ? 'hourglass_empty' : 'power_settings_new'}</span>${starting ? '신화사DB 실행 중...' : '신화사DB 실행 후 다시 수집'}
      </button>
    </div>
  </div>`;
}

function renderFactoryCafe24ProgramPrompt(factory) {
  const oauthStatus = factory?.product?.cafe24OAuthStatus;
  const oauthNeedsAction = oauthStatus && typeof oauthStatus === 'object'
    && ['reauth_required', 'scope_required', 'connection_error', 'unknown'].includes(String(oauthStatus.state || ''));
  const oauthPreventiveWarning = oauthStatus && typeof oauthStatus === 'object'
    && (oauthStatus.refreshWarning === true || oauthStatus.callbackWarning === true);
  if (oauthStatus && typeof oauthStatus === 'object' && (oauthNeedsAction || oauthPreventiveWarning)) {
    const mallId = String(oauthStatus.mallId || 'bojagi1928').trim();
    const tokenMessage = String(oauthStatus.tokenMessage || '').trim();
    const scopeMessage = oauthStatus.missingScopes?.length
      ? `확인 필요한 권한 범위 ${oauthStatus.missingScopes.length}개`
      : '필요 권한 범위 확인 완료';
    const warningOnly = !oauthNeedsAction;
    const title = oauthStatus.state === 'reauth_required'
      ? 'Cafe24 OAuth 재연결 필요'
      : (oauthStatus.refreshWarning ? 'Cafe24 OAuth 갱신 권한 만료 전 점검 필요' : 'Cafe24 OAuth 재승인 경로 확인 필요');
    const warningDetails = [oauthStatus.refreshWarningMessage, oauthStatus.callbackWarningMessage]
      .map(value => String(value || '').trim())
      .filter(Boolean)
      .join(' ');
    const message = warningOnly
      ? (warningDetails || '현재 연결은 정상이며, 만료 전 연결 상태를 점검해야 합니다.')
      : (oauthStatus.message || 'Cafe24 access 토큰이 만료되어 후보 조회 전에 OAuth 재연결이 필요합니다.');
    const oauthStartButton = oauthStatus.callbackWarning
      ? `<div class="factory-small" style="max-width:280px;color:var(--text-d);line-height:1.5">공개 HTTPS 콜백을 먼저 연결해야 재승인 창을 열 수 있습니다.</div>`
      : `<button class="btn-primary" type="button" data-factory-guide-action="cafe24-oauth-start" style="justify-content:center;max-width:100%;padding:10px 12px;white-space:nowrap"><span class="material-icons-outlined" style="font-size:16px">open_in_new</span>Cafe24 OAuth 연결 시작</button>`;
    return `<div class="factory-card" data-factory-cafe24-oauth="${warningOnly ? 'preventive-warning' : 'reauth-required'}" style="margin:10px 0 12px;padding:12px;border-color:rgba(245,158,11,.58);background:rgba(245,158,11,.10)">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap">
        <div style="min-width:220px;flex:1">
          <div style="font-size:13px;font-weight:950;color:#fbbf24">${escapeHtml(title)}</div>
          <div style="font-size:13px;font-weight:900;color:var(--text);line-height:1.5;margin-top:4px">${escapeHtml(message)}</div>
          <div class="factory-small" style="margin-top:5px">몰 ID: ${escapeHtml(mallId)} · ${escapeHtml(scopeMessage)} · API&nbsp;Hub 경로</div>
          ${tokenMessage ? `<div class="factory-small" style="margin-top:5px;color:var(--text-d)">상태: ${escapeHtml(tokenMessage)}</div>` : ''}
          <div class="factory-small" style="margin-top:5px">저장된 갱신 권한으로 access 토큰을 자동 연장합니다. 연결된 Cafe24 호출은 후보 수집 전에 갱신 권한을 먼저 점검하며, 갱신 권한 만료나 콜백 불일치는 실패 전에 표시합니다.</div>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;align-items:stretch;max-width:100%">
          ${oauthNeedsAction ? oauthStartButton : ''}
          <button class="btn-sm" type="button" data-factory-guide-action="cafe24-oauth-status-refresh-and-rerun" style="justify-content:center;max-width:100%;white-space:nowrap"><span class="material-icons-outlined" style="font-size:14px">sync</span>인증 확인 후 후보 다시 수집</button>
        </div>
      </div>
    </div>`;
  }
  const status = factory?.product?.cafe24ProgramStatus;
  if (!status || typeof status !== 'object') return '';
  const stateText = String(status.state || '');
  const showPrompt = !!status.offline || !!status.starting || stateText === 'offline' || stateText === 'starting' || stateText === 'error';
  if (!showPrompt) return '';
  const starting = !!status.starting || stateText === 'starting';
  const detail = String(status.detail || '').trim();
  const message = String(status.message || '').trim() || 'Cafe24 Control Tower가 꺼져 있어 후보를 조회할 수 없습니다.';
  return `<div class="factory-card" style="margin:10px 0 12px;padding:12px;border-color:rgba(245,158,11,.58);background:rgba(245,158,11,.10)">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap">
      <div style="min-width:220px;flex:1">
        <div style="font-size:13px;font-weight:950;color:#fbbf24">Cafe24 Control Tower 실행 필요</div>
        <div style="font-size:13px;font-weight:900;color:var(--text);line-height:1.5;margin-top:4px">${escapeHtml(message)}</div>
        <div class="factory-small" style="margin-top:5px">API Hub는 연결되어 있습니다. Control Tower를 실행한 뒤 후보 조회는 API Hub 경로로만 다시 시도합니다.</div>
        ${detail ? `<div class="factory-small" style="margin-top:5px;color:var(--text-d)">진단: ${escapeHtml(factoryVisibleRunLogText(detail))}</div>` : ''}
      </div>
      <button class="btn-primary" type="button" data-factory-guide-action="start-cafe24-control-and-rerun" ${starting ? 'disabled' : ''}>
        <span class="material-icons-outlined" style="font-size:16px">${starting ? 'hourglass_empty' : 'power_settings_new'}</span>${starting ? 'Cafe24 실행 중...' : '실행 후 API Hub로 다시 수집'}
      </button>
    </div>
  </div>`;
}

function renderFactoryCandidateReviewPanels(factory) {
  const pendingDb = factory.product.pendingDbCandidates || [];
  const pendingCafe24 = factory.product.pendingCafe24Candidates || [];
  const sourceDbCandidates = pendingDb.length ? pendingDb : (factory.product.dbCandidates || []);
  const sourceCafe24Candidates = pendingCafe24.length ? pendingCafe24 : (factory.product.cafe24Candidates || []);
  const dbCandidates = sourceDbCandidates.filter(candidate => factoryCandidateReviewCanApply(candidate, factory));
  const cafe24Candidates = sourceCafe24Candidates.filter(candidate => factoryCandidateReviewCanApply(candidate, factory));
  const hiddenCandidateCount = (sourceDbCandidates.length - dbCandidates.length)
    + (sourceCafe24Candidates.length - cafe24Candidates.length);
  const hasAny = sourceDbCandidates.length || sourceCafe24Candidates.length || factory.product.candidateReviewStatus || factory.product.sinhwaDbProgramStatus || factory.product.cafe24ProgramStatus || factory.product.cafe24OAuthStatus || factory.product.dbCandidateResolution || factory.product.cafe24CandidateResolution;
  if (!hasAny) return '';
  const dbAbsent = factory.product.dbCandidateResolution === 'none';
  const cafeAbsent = factory.product.cafe24CandidateResolution === 'none';
  const dbConfirmed = !!factory.product.selectedDbCandidateKey || !!factory.product.confirmedDb || dbAbsent;
  const cafeConfirmed = !!factory.product.selectedCafe24CandidateKey || cafeAbsent;
  const hiddenCandidateNotice = hiddenCandidateCount ? `<div class="factory-card" data-factory-stale-candidate-notice style="margin:0 0 10px;padding:11px 12px;border-color:rgba(245,158,11,.58);background:rgba(245,158,11,.10)">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">
      <div><div style="font-size:13px;font-weight:950;color:var(--warn)">현재 작업과 다른 후보 ${hiddenCandidateCount}건을 숨겼습니다.</div><div class="factory-small" style="margin-top:3px">다른 제품이나 이전 작업의 후보는 선택할 수 없습니다. 현재 제품 기준으로 다시 검색해주세요.</div></div>
      <button class="btn-sm" type="button" data-factory-guide-action="rerun-db-query">현재 제품 후보 다시 수집</button>
    </div>
  </div>` : '';
  return `${hiddenCandidateNotice}<div class="factory-candidate-review">
    <div class="factory-candidate-panel ${dbConfirmed ? 'confirmed' : ''}">
      <h5>신화사DB 후보 확인</h5>
      <p>${dbAbsent ? '신화사DB에 없는 신제품으로 확정했습니다. 다음 단계에서 필수 상품 정보를 직접 검수합니다.' : (dbConfirmed ? '선택한 신화사DB 상품을 완성 DB 기준값으로 사용 중입니다.' : '아래 후보 중 실제 제품이 맞는지 골라주세요. 고르기 전에는 완성 DB에 자동 반영하지 않습니다.')}</p>
      ${renderFactoryCandidateCollectionStatus(factory, 'sinhwa', dbCandidates.length)}
      ${renderFactorySinhwaDbProgramPrompt(factory)}
      ${renderFactoryCandidateCards(dbCandidates, 'sinhwa', factory)}
      ${renderFactoryCandidateSizeGenerationWait(factory)}
      <button class="btn-sm" type="button" data-factory-confirm-no-db-candidate style="margin-top:8px" ${dbAbsent ? 'disabled' : ''}>${dbAbsent ? '신화사DB 후보 없음 확정됨' : '신화사DB 후보 없음으로 진행'}</button>
    </div>
    <div class="factory-candidate-panel ${cafeConfirmed ? 'confirmed' : ''}">
      <h5>Cafe24 후보 확인</h5>
      <p>${cafeAbsent ? 'Cafe24에 없는 신제품으로 확정했습니다. 기존 상품 수정 없이 새 상품 등록 초안으로 다음 단계에 진행합니다.' : (cafeConfirmed
        ? '선택한 Cafe24 상품의 상세 입력값과 옵션을 불러왔습니다.'
        : (cafe24Candidates.length ? '저장된 Cafe24 후보가 있습니다. 새 후보를 찾거나 기존 후보를 확정할 수 있습니다.' : 'Cafe24도 별도로 확인합니다. 선택한 상품만 옵션/가격/상품번호 기준으로 올라갑니다.'))}</p>
      ${renderFactoryCandidateCollectionStatus(factory, 'cafe24', cafe24Candidates.length)}
      ${renderFactoryCafe24ProgramPrompt(factory)}
      ${renderFactoryCandidateCards(cafe24Candidates, 'cafe24', factory)}
      <button class="btn-sm" type="button" data-factory-confirm-no-cafe24-candidate style="margin-top:8px" ${cafeAbsent ? 'disabled' : ''}>${cafeAbsent ? 'Cafe24 후보 없음 · 신제품 확정됨' : 'Cafe24 후보 없음 · 신제품으로 진행'}</button>
    </div>
  </div>
  ${factory.product.candidateReviewStatus ? `<div class="factory-small" data-factory-candidate-review-status style="margin-top:8px">${escapeHtml(factory.product.candidateReviewStatus)}</div>` : ''}
  ${renderFactoryDetachedDbSelectionRestore(factory)}`;
}

// 신원 불일치로 떼어낸 이전 DB/Cafe24 선택을 사용자가 직접 되살릴 수 있게 한다.
// 자동으로 버리면 되돌릴 방법이 없어서, 무엇을 떼어냈는지 보여주고 선택권을 준다.
function renderFactoryDetachedDbSelectionRestore(factory = factoryRuntimeReadFactory()) {
  const detached = factory?.product?.detachedDbSelection;
  if (!detached || typeof detached !== 'object') return '';
  const dbKey = String(detached.selectedDbCandidateKey || '').trim();
  const cafe24Key = String(detached.selectedCafe24CandidateKey || '').trim();
  const from = String(detached.detachedFromProductName || '').trim();
  const when = detached.detachedAt ? new Date(detached.detachedAt).toLocaleString('ko-KR') : '';
  const parts = [
    dbKey ? `신화사DB 키 ${escapeHtml(dbKey)}` : '',
    cafe24Key ? `Cafe24 키 ${escapeHtml(cafe24Key)}` : '',
  ].filter(Boolean).join(' · ');
  return `<div class="factory-automation-panel" data-factory-detached-db-selection style="margin-top:10px;border-color:rgba(245,158,11,.5);background:rgba(245,158,11,.06)">
    <div style="font-size:12px;font-weight:900;color:var(--warn)">이전 DB 선택을 보관해 두었습니다</div>
    <div class="factory-small" style="margin-top:4px;line-height:1.6">
      ${from ? `${escapeHtml(from)} 기준으로 고르셨던 값입니다. ` : ''}${parts ? `${parts}. ` : ''}${when ? `${escapeHtml(when)}에 분리했습니다. ` : ''}지우지 않았으니 그대로 되살릴 수 있습니다.
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
      <button class="btn-sm primary" type="button" data-factory-restore-detached-db>이전 DB 선택 되돌리기</button>
      <button class="btn-sm" type="button" data-factory-discard-detached-db>보관본 버리기</button>
    </div>
  </div>`;
}

function renderFactoryCandidateSizeGenerationWait(factory = factoryRuntimeReadFactory()) {
  const stage = factory?.stages?.size || {};
  const message = factoryStageMessageForCurrentProduct(stage, factory);
  if (stage.status !== 'blocked' || !message) return '';
  const review = typeof factoryAutomationSizeReviewStatus === 'function'
    ? factoryAutomationSizeReviewStatus(factory)
    : null;
  const canGenerate = !!review
    && !review.requiredMissing.length
    && review.fields.some(item => String(item?.value || '').trim());
  const disabledReason = '가로/세로/규격을 확인한 뒤 사이즈이미지를 생성할 수 있습니다.';
  return `<div class="factory-card" data-factory-candidate-size-wait style="margin:10px 8px 0 0;max-width:calc(100% - 8px);box-sizing:border-box;padding:12px;border-color:rgba(245,158,11,.58);background:rgba(245,158,11,.10)">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap">
      <div style="min-width:220px;flex:1">
        <div style="font-size:13px;font-weight:950;color:var(--warn)">사이즈이미지 생성 대기</div>
        <div style="font-size:12px;color:var(--text);font-weight:800;line-height:1.55;margin-top:4px;word-break:keep-all;overflow-wrap:break-word;line-break:strict">${escapeHtml(message)}</div>
        <div class="factory-small" style="margin-top:5px;word-break:keep-all;overflow-wrap:break-word;line-break:strict">${canGenerate ? '현재 값을 생성 버튼에서 자동 확인한 뒤 바로 생성합니다.' : disabledReason}</div>
      </div>
      <div class="factory-automation-actions" style="margin:0;justify-content:flex-end">
        <button class="btn-primary" type="button" data-factory-run-stage="size" onclick="return factoryRunStageButtonInline(this,event)" style="white-space:nowrap" ${disabledAttr(!canGenerate, disabledReason)}><span class="material-icons-outlined" style="font-size:15px">play_arrow</span>사이즈이미지 생성</button>
        <button class="btn-sm" type="button" data-factory-guide-action="focus-size">생성컷 선택에서 확인</button>
      </div>
    </div>
  </div>`;
}

function factoryGoalRunNeedsAttention(goal = {}, stageText = '') {
  const text = `${String(stageText || goal.currentStage || '')} ${String(goal.failureReason || '')}`;
  return !goal.running && /확인 필요|후보 0건|후보 선택 대기|이전 이미지 생성이 화면 복원 중|신화사 자산관(?: 자동)? 동기화.*(?:실패|보류)/.test(text);
}

function factoryGoalRunHasFailure(goal = {}, stageText = '') {
  const text = `${String(stageText || goal.currentStage || '')} ${String(goal.failureReason || '')}`;
  const explicitFailure = /실패|error|오류|중단|fetch failed|조회 실패/i.test(text);
  const recoveryWarningOnly = /이전 이미지 생성이 화면 복원 중 끊겨 진행 표시를 해제했습니다/.test(String(goal.failureReason || ''))
    && !/실패|error|오류|중단|fetch failed|조회 실패/i.test(text.replace(/이전 이미지 생성이 화면 복원 중 끊겨 진행 표시를 해제했습니다/g, ''));
  const backgroundServiceWarningOnly = /Cafe24 OAuth 자동 점검 (?:실패|보류)|신화사 자산관(?: 자동)? 동기화.*(?:실패|보류)/.test(text);
  const attentionOnly = factoryGoalRunNeedsAttention(goal, stageText) && !explicitFailure;
  return !recoveryWarningOnly && !backgroundServiceWarningOnly && !attentionOnly
    && (!!String(goal.failureReason || '').trim() || explicitFailure);
}

function factoryGoalRunDisplayProgress(goal = {}, stageText = '') {
  const rawProgress = Math.max(0, Math.min(100, Math.round(Number(goal.progress || 0) || 0)));
  const stage = String(stageText || goal.currentStage || '');
  const reason = String(goal.failureReason || '');
  const failed = factoryGoalRunHasFailure(goal, stage);
  const completed = !failed && !goal.running && /완료|검색 완료|수집 완료|확보/.test(`${stage} ${reason}`);
  return completed ? 100 : rawProgress;
}

function factoryGoalRunPillText(goal = {}, stageText = '', hasLog = false) {
  const progress = factoryGoalRunDisplayProgress(goal, stageText);
  const text = `${stageText || goal.currentStage || ''} ${goal.failureReason || ''}`;
  if (goal.running) return `${progress}%`;
  if (factoryGoalRunHasFailure(goal, stageText)) return `실패 · ${progress}%`;
  if (factoryGoalRunNeedsAttention(goal, stageText) || /확인 필요|후보 0건/.test(text)) return `확인 필요 · ${progress}%`;
  if (progress >= 100 || /완료|검색 완료|수집 완료|확보/.test(text)) return '완료';
  return hasLog ? '최근 기록' : '대기';
}

function renderFactoryProductActionStatus(factory) {
  if (typeof factoryNormalizeStoppedGoalRun === 'function') factoryNormalizeStoppedGoalRun(factory);
  const goal = factory.goalRun || {};
  const logs = factoryVisibleFactoryLogs(factory).slice(0, 4);
  const latestLog = logs[0] || null;
  const dbStage = factory.stages?.db || {};
  const running = !!goal.running;
  const stage = goal.currentStage || dbStage.message || latestLog?.message || '대기';
  const progress = factoryGoalRunDisplayProgress(goal, stage);
  const isImageAnalysis = factory.automation?.activeTaskId === 'product-analysis' || /이미지.*분석|제품 이미지/.test(String(stage || ''));
  const failed = factoryGoalRunHasFailure(goal, stage) || dbStage.status === 'error';
  const needsAttention = !failed && (factoryGoalRunNeedsAttention(goal, stage) || dbStage.status === 'review');
  const toneColor = running ? 'var(--primary-h)' : (failed ? 'var(--danger)' : (needsAttention ? 'var(--warn)' : 'var(--text-m)'));
  const borderColor = running ? 'rgba(99,102,241,.42)' : (failed ? 'rgba(239,68,68,.72)' : (needsAttention ? 'rgba(245,158,11,.62)' : 'rgba(255,255,255,.10)'));
  const bg = running ? 'rgba(99,102,241,.10)' : (failed ? 'rgba(127,29,29,.20)' : (needsAttention ? 'rgba(245,158,11,.10)' : 'rgba(255,255,255,.025)'));
  const helperText = running
    ? (isImageAnalysis
      ? '현재 제품 사진을 AI가 판독 중입니다. 완료되면 섹션/이미지 생성 기준으로 저장됩니다.'
      : '조립공장 작업이 진행 중입니다. 오른쪽 실행 상태에서 현재 단계를 확인할 수 있습니다.')
    : (latestLog
      ? '최근 작업 상태입니다. 버튼을 다시 누르면 이 자리에서 새 진행상황이 갱신됩니다.'
      : '버튼을 누르면 현재 이미지 분석, DB 수집, 경쟁사 수집, 이미지 생성 진행상황이 이 자리에서 표시됩니다.');
  const visibleLog = message => `${escapeHtml(factoryVisibleRunLogText(message || ''))}${running ? factoryLiveEllipsisMarkup() : ''}`;
  return `<div id="factoryProductActionStatus" data-factory-goal-status="product" style="border:1px solid ${borderColor};background:${bg};border-radius:10px;padding:10px 12px;margin:0 0 12px">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap">
      <div style="min-width:220px;flex:1">
        <div data-factory-goal-title style="font-size:12px;font-weight:950;color:${toneColor}">${running ? (isImageAnalysis ? '현재 이미지 AI 분석 진행 중' : '조립공장 실행 중') : (failed ? '조립공장 실행 실패' : (needsAttention ? '조립공장 확인 필요' : '조립공장 실행 상태'))}</div>
        <div data-factory-goal-stage data-running="${running ? '1' : '0'}" style="font-size:14px;font-weight:950;color:var(--text);line-height:1.42;margin-top:3px">${visibleLog(stage)}</div>
        <div class="factory-small" data-factory-goal-helper style="margin-top:4px">${escapeHtml(helperText)}</div>
        <div class="factory-small" data-factory-goal-failure style="margin-top:4px;color:${failed ? 'var(--danger)' : 'var(--warn)'};font-weight:${failed ? '950' : 'normal'};${goal.failureReason ? '' : 'display:none'}">${goal.failureReason ? escapeHtml(goal.failureReason) : ''}</div>
      </div>
      <span class="factory-pill" data-factory-goal-pill>${escapeHtml(factoryGoalRunPillText(goal, stage, !!latestLog))}</span>
    </div>
    <div class="factory-progress ${failed ? 'failed' : ''}" style="margin-top:9px"><span data-factory-goal-progress-bar style="--p:${running || progress ? progress : 0}%"></span></div>
  </div>`;
}

function renderFactoryProductPanel(factory) {
  const preview = displayableImageSrc(factoryProductPreview(factory));
  const hasInputPayload = !!(typeof currentProductImagePayload === 'function'
    ? currentProductImagePayload({ allowDerived: false, allowAssetFallback: false, prefer: 'factory' })?.base64
    : false);
  const storedProductCandidate = hasInputPayload ? null : factoryStoredProductCandidateForDisplay(factory);
  const storedProductImage = storedProductCandidate && factoryStoredProductCandidateIsInputSource(storedProductCandidate)
    ? storedProductCandidate
    : null;
  const analysis = factory.product.analysis || state.analysis || {};
  const confirmedDb = factory.product.confirmedDb || {};
  const dbCandidates = factory.product.dbCandidates || [];
  const cafe24Candidates = factory.product.cafe24Candidates || analysis.cafe24_candidates || [];
  const pendingDbCandidates = factory.product.pendingDbCandidates || [];
  const pendingCafe24Candidates = factory.product.pendingCafe24Candidates || [];
  const competitors = factoryCurrentWorkCompetitors(factory);
  const cafe24ReviewCount = pendingCafe24Candidates.length || (cafe24Candidates || []).length;
  const dbName = confirmedDb.product_name || confirmedDb.name || analysis.db_product_name || analysis.product_name || '미확정';
  const category = analysis.category || analysis.product_category || analysis.category_guess || '미확정';
  const productName = factoryLiveInputDraft.productName !== null
    ? factoryLiveInputDraft.productName
    : (factory.product.productName || state.productName || '');
  const naturalHint = factoryLiveInputDraft.naturalHint !== null
    ? factoryLiveInputDraft.naturalHint
    : (factory.product.naturalHint || '');
  const quickProjectName = state.currentProjectName || factory.product.productName || state.productName || deriveProjectName();
  const goal = factory.goalRun || {};
  const running = !!goal.running;
 const productAnalysisRunning = running && (factory.automation?.activeTaskId === 'product-analysis' || /이미지.*분석|제품 이미지/.test(String(goal.currentStage || '')));
  return `<section class="factory-section" id="factoryProductDbPanel">
    <div class="factory-section-head">
      <div>
        <h3>제품 입력 / DB 확정</h3>
        <p>스케치의 시작점입니다. 제품 사진과 이름을 넣고 DB/경쟁사 재료를 먼저 잡은 뒤 아래 공정으로 넘깁니다.</p>
      </div>
      <div class="factory-toolbar">
        <button class="btn-sm" id="factorySyncCurrent"><span class="material-icons-outlined" style="font-size:14px">sync</span>현재 작업 가져오기</button>
        <button class="btn-sm" id="factoryAnalyzeCurrentImage" title="DB/경쟁사 수집이나 이미지 생성은 시작하지 않고, 현재 조립공장 제품 사진만 AI로 다시 분석해 섹션/이미지 생성 기준으로 저장합니다." ${disabledAttr(running, '현재 조립공장 작업이 진행 중입니다. 완료 후 다시 눌러주세요.')}><span class="material-icons-outlined" style="font-size:14px">image_search</span>${productAnalysisRunning ? '이미지 분석 중...' : '현재 이미지 AI 분석'}</button>
        <button class="btn-primary" id="factoryRunDb" title="현재 제품 이미지를 먼저 AI 분석으로 고정한 뒤 DB/Cafe24 후보, 경쟁사 참고자료, 대표이미지와 이미지컷 생성을 이어서 진행합니다." ${disabledAttr(running, '이미 조립공장 작업이 진행 중입니다. 상단 진행상태를 확인해주세요.')}><span class="material-icons-outlined" style="font-size:18px">rocket_launch</span>${running && !productAnalysisRunning ? '조립공장 실행 중...' : 'DB/경쟁사·제품분석·이미지 생성'}</button>
      </div>
    </div>
    ${renderFactoryProductActionStatus(factory)}
    <div class="factory-product-grid">
      <div class="factory-card">
        <h4>제품사진과 이름기입</h4>
        <div class="factory-drop" id="factoryProductDrop" draggable="${preview ? 'true' : 'false'}" data-factory-product-drag="1" data-factory-has-image="${preview ? '1' : '0'}" data-factory-stored-product-candidate="${storedProductImage?.src ? '1' : '0'}" data-factory-needs-input-archive-restore="${hasInputPayload ? '0' : '1'}" title="${preview ? '이미지 교체 버튼을 누르거나 다른 공정 입력 슬롯으로 드래그합니다.' : '클릭/드래그로 제품 사진을 업로드합니다.'}">
    ${preview ? `${renderFactoryLightImage(preview, '조립공장 제품 이미지', 'data-factory-light-priority="1"')}
            <button class="btn-sm" type="button" data-factory-open-product-file="main" style="position:absolute;right:10px;bottom:10px;z-index:2;background:rgba(10,12,20,.86);border-color:rgba(255,255,255,.18)">이미지 교체</button>` : renderFactoryProductDropEmpty(storedProductImage, 'main')}
        </div>
        <input type="file" id="factoryProductFile" accept="image/*" style="display:none">
        <div class="factory-input-row" style="margin-top:12px">
          <div>
            <label class="label">제품명 직접 입력</label>
            <input class="input" id="factoryProductName" value="${escAttr(productName)}" placeholder="예: 방울수저집">
          </div>
          <div>
            <label class="label">자연어 힌트</label>
            <input class="input" id="factoryNaturalHint" value="${escAttr(naturalHint)}" placeholder="예: 색동, 지갑형, 선물용">
          </div>
        </div>
      </div>
      <div class="factory-card">
        <h4>DB / 후보 / 경쟁사 재료</h4>
        <div class="factory-mini-grid">
          <div class="factory-mini">이미지 판독명<b>${escapeHtml(analysis.product_name || analysis.ai_product_name || '없음')}</b></div>
          <div class="factory-mini">카테고리<b>${escapeHtml(category)}</b></div>
          <div class="factory-mini">DB 확정명<b>${escapeHtml(dbName)}</b></div>
          <div class="factory-mini">신화사 후보<b>${pendingDbCandidates.length ? `${pendingDbCandidates.length}건 확인 대기` : `${dbCandidates.length}건`}</b></div>
          <div class="factory-mini">Cafe24 후보<b>${pendingCafe24Candidates.length ? `${pendingCafe24Candidates.length}건 확인 대기` : `${(cafe24Candidates || []).length}건`}</b></div>
          <div class="factory-mini">상태<b>${factory.product.dbLocked ? 'DB 확정 잠금' : '검수 가능'}</b></div>
        </div>
        <div class="factory-stage-actions" style="margin-top:12px">
          <label class="factory-review-toggle" title="끄면 DB/Cafe24 후보를 따로 확인한 뒤 선택한 상품만 원본 DB로 불러옵니다.">
            <input type="checkbox" id="factoryCandidateAutoApply" ${factory.product.candidateAutoApply ? 'checked' : ''}>
            최상위 후보 자동 확정
          </label>
          <span class="factory-small">${factory.product.candidateAutoApply ? '켜짐: 1순위를 바로 적용합니다.' : '꺼짐: 후보를 먼저 보여주고 선택 대기합니다.'}</span>
        </div>
        <div class="factory-stage-actions" style="margin-top:12px">
          <button class="btn-sm" id="factoryImportCompetitor"><span class="material-icons-outlined" style="font-size:14px">travel_explore</span>경쟁사 결과 가져오기</button>
          <button class="btn-sm" id="factoryFindCafe24Candidates" title="현재 제품명/이미지 판독명을 기준으로 Cafe24 상품 후보만 다시 검색합니다. 신화사DB 확정값은 건드리지 않습니다."><span class="material-icons-outlined" style="font-size:14px">manage_search</span>Cafe24 후보만 찾기</button>
          <button class="btn-sm primary" id="factoryApplyTopCafe24Candidate" title="현재 Cafe24 후보 목록의 1순위 상품을 선택 상품으로 확정하고, 상품 입력판에 불러올 준비를 합니다." ${disabledAttr(!cafe24ReviewCount, '먼저 Cafe24 후보를 검색해주세요.')}><span class="material-icons-outlined" style="font-size:14px">done_all</span>Cafe24 1순위 확정</button>
          <button class="btn-sm" id="factoryToggleDbLock" title="${factory.product.dbLocked ? 'DB 잠금을 풀어 후보 재선택과 재수집이 가능하게 합니다.' : '현재 선택한 신화사DB/Cafe24/완성 DB를 기준값으로 잠가 자동 덮어쓰기를 막습니다.'}"><span class="material-icons-outlined" style="font-size:14px">${factory.product.dbLocked ? 'lock_open' : 'lock'}</span>${factory.product.dbLocked ? 'DB 잠금 해제' : '현재 DB 확정'}</button>
        </div>
        <div class="factory-small" style="margin-top:10px">
          사이즈컷은 확정 DB나 수동값에서 실제 규격이 확인될 때만 생성됩니다. 없으면 goal 루프가 자동으로 멈춥니다.
        </div>
      </div>
    </div>
  </section>`;
}

function factoryUiPanelOpen(factory, panelId, fallback = false) {
  const panels = factory?.uiPanels && typeof factory.uiPanels === 'object' ? factory.uiPanels : {};
  if (Object.prototype.hasOwnProperty.call(panels, panelId)) return !!panels[panelId];
  return !!fallback;
}

function factoryUiPanelSummaryCard(message, actionLabel = '펼치기') {
  return `<div class="factory-card" style="border-style:dashed;background:rgba(15,23,42,.42)">
    <div class="factory-small" style="color:var(--text);font-weight:800">${escapeHtml(message)}</div>
    <div class="factory-small" style="margin-top:6px;color:var(--text-m)">닫힌 구역은 실제 내용을 만들지 않아 스크롤 렉과 렌더러 메모리를 줄입니다. 필요할 때 ${escapeHtml(actionLabel)}를 누르세요.</div>
  </div>`;
}

const FACTORY_LIGHT_IMAGE_SRC_LIMIT = 12000;
const FACTORY_LIGHT_IMAGE_HYDRATE_BATCH = 8;
const FACTORY_LIGHT_IMAGE_VIEWPORT_MARGIN = 180;
const FACTORY_LIGHT_IMAGE_STORE_LIMIT = 180;
const FACTORY_LIGHT_IMAGE_URL_LIMIT = 60;
const FACTORY_LIGHT_IMAGE_PRIORITY_LIMIT = 2;

function factoryLightImageStore() {
  if (typeof window === 'undefined') return null;
  window.__factoryLightImageStore = window.__factoryLightImageStore || new Map();
  window.__factoryLightImageUrls = window.__factoryLightImageUrls || new Map();
  return window.__factoryLightImageStore;
}

function factoryLightImageKey(src = '') {
  const text = String(src || '');
  const sample = `${text.slice(0, 1600)}|${text.slice(Math.max(0, Math.floor(text.length / 2) - 600), Math.floor(text.length / 2) + 600)}|${text.slice(-1600)}`;
  let hash = 2166136261;
  for (let i = 0; i < sample.length; i += 1) {
    hash ^= sample.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `img_${text.length}_${(hash >>> 0).toString(36)}`;
}

function factoryTrimLightImageUrls(keepKeys = new Set()) {
  if (typeof window === 'undefined') return;
  const urls = window.__factoryLightImageUrls;
  if (!urls || typeof urls.keys !== 'function') return;
  let guard = 0;
  while (urls.size > FACTORY_LIGHT_IMAGE_URL_LIMIT && guard < FACTORY_LIGHT_IMAGE_URL_LIMIT * 3) {
    guard += 1;
    const oldestKey = urls.keys().next().value;
    if (!oldestKey) break;
    if (keepKeys.has(oldestKey) && urls.size > keepKeys.size) {
      const value = urls.get(oldestKey);
      urls.delete(oldestKey);
      urls.set(oldestKey, value);
      continue;
    }
    const objectUrl = urls.get(oldestKey);
    urls.delete(oldestKey);
    try { URL.revokeObjectURL(objectUrl); } catch(e) {}
  }
}

function factoryTrimLightImageStore(activeKey = '') {
  if (typeof window === 'undefined') return;
  const store = window.__factoryLightImageStore;
  const urls = window.__factoryLightImageUrls;
  if (!store || typeof store.keys !== 'function') return;
  let guard = 0;
  while (store.size > FACTORY_LIGHT_IMAGE_STORE_LIMIT && guard < FACTORY_LIGHT_IMAGE_STORE_LIMIT * 3) {
    guard += 1;
    const oldestKey = store.keys().next().value;
    if (!oldestKey) break;
    if (oldestKey === activeKey && store.size > 1) {
      const value = store.get(oldestKey);
      store.delete(oldestKey);
      store.set(oldestKey, value);
      continue;
    }
    store.delete(oldestKey);
    const objectUrl = urls?.get?.(oldestKey);
    if (urls?.delete) urls.delete(oldestKey);
    try { if (objectUrl) URL.revokeObjectURL(objectUrl); } catch(e) {}
  }
}

function factoryRememberLightImage(src = '') {
  const store = factoryLightImageStore();
  const text = String(src || '');
  if (!store || !text) return '';
  const key = factoryLightImageKey(text);
  if (store.has(key)) {
    const current = store.get(key);
    if (current !== text) {
      const urls = window.__factoryLightImageUrls;
      const staleObjectUrl = urls?.get?.(key);
      if (urls?.delete) urls.delete(key);
      try { if (staleObjectUrl) URL.revokeObjectURL(staleObjectUrl); } catch(e) {}
    }
    store.delete(key);
    store.set(key, text);
  } else {
    store.set(key, text);
  }
  factoryTrimLightImageStore(key);
  return key;
}

function factoryLightImagePlaceholder(label = '이미지 보관됨') {
  const safe = String(label || '이미지 보관됨').slice(0, 28);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="220" viewBox="0 0 320 220"><rect width="320" height="220" rx="18" fill="#101422"/><rect x="18" y="18" width="284" height="184" rx="14" fill="#171c2d" stroke="#6366f1" stroke-opacity=".42"/><text x="160" y="102" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#e5e7eb">${escapeHtml(safe)}</text><text x="160" y="130" text-anchor="middle" font-family="Arial, sans-serif" font-size="12" fill="#94a3b8">원본은 메모리 저장소에서 불러옵니다</text></svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

function renderFactoryLightImage(src = '', alt = '이미지', attrs = '', label = '') {
  const displaySrc = typeof displayableImageSrc === 'function' ? displayableImageSrc(src) : String(src || '');
  if (!displaySrc) return '';
  const safeAlt = escAttr(alt || '이미지');
  const attrText = String(attrs || '').trim();
  const isPriority = /data-factory-light-priority\s*=\s*["']?1/i.test(attrText);
  const loadingAttr = /loading\s*=/i.test(attrText) ? '' : ` loading="${isPriority ? 'eager' : 'lazy'}"`;
  const priorityAttr = /fetchpriority\s*=/i.test(attrText) ? '' : ` fetchpriority="${isPriority ? 'high' : 'low'}"`;
  const errorAttr = /onerror\s*=/i.test(attrText)
    ? ''
    : ' onerror="if(window.factoryHandleRenderedImageError)window.factoryHandleRenderedImageError(this,event)"';
  if (/^data:image\//i.test(displaySrc) && displaySrc.length > FACTORY_LIGHT_IMAGE_SRC_LIMIT) {
    const key = factoryRememberLightImage(displaySrc);
    const cachedObjectUrl = key && typeof window !== 'undefined'
      ? window.__factoryLightImageUrls?.get?.(key)
      : '';
    if (cachedObjectUrl) {
      return `<img src="${escAttr(cachedObjectUrl)}" data-factory-light-image-key="${escAttr(key)}" data-factory-light-loaded="1" alt="${safeAlt}"${loadingAttr} decoding="async"${priorityAttr}${errorAttr} ${attrText}>`;
    }
    const placeholder = factoryLightImagePlaceholder(label || alt || '이미지 보관됨');
    return `<img src="${escAttr(placeholder)}" data-factory-light-image-key="${escAttr(key)}" alt="${safeAlt}"${loadingAttr} decoding="async"${priorityAttr}${errorAttr} ${attrText}>`;
  }
  return `<img src="${escAttr(displaySrc)}" alt="${safeAlt}"${loadingAttr} decoding="async"${priorityAttr}${errorAttr} ${attrText}>`;
}

function factoryDataUrlToBlob(dataUrl = '') {
  const match = /^data:([^;,]+)?;base64,(.+)$/i.exec(String(dataUrl || ''));
  if (!match) return null;
  const declaredMime = match[1] || 'image/png';
  const mime = typeof inferImageMimeFromBase64 === 'function'
    ? inferImageMimeFromBase64(match[2] || '', declaredMime)
    : declaredMime;
  const binary = atob(match[2]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

function factoryHydrateLightImages(root = document) {
  if (typeof window === 'undefined') return;
  const store = window.__factoryLightImageStore;
  const urls = window.__factoryLightImageUrls = window.__factoryLightImageUrls || new Map();
  if (!store || typeof root?.querySelectorAll !== 'function') return;
  const allNodes = Array.from(root.querySelectorAll('img[data-factory-light-image-key]:not([data-factory-light-loaded="1"])'));
  const viewportHeight = window.innerHeight || document.documentElement?.clientHeight || 900;
  const margin = FACTORY_LIGHT_IMAGE_VIEWPORT_MARGIN;
  const priorityNodes = [];
  const visibleNodes = [];
  allNodes.forEach(img => {
    const priority = img.dataset.factoryLightPriority === '1';
    let visible = priority;
    if (!visible && typeof img.getBoundingClientRect === 'function') {
      const rect = img.getBoundingClientRect();
      visible = rect.bottom >= -margin && rect.top <= viewportHeight + margin;
    }
    if (priority) priorityNodes.push(img);
    else if (visible) visibleNodes.push(img);
  });
  const candidates = [...priorityNodes, ...visibleNodes];
  const nodes = candidates.slice(0, FACTORY_LIGHT_IMAGE_HYDRATE_BATCH);
  const pendingVisibleCount = Math.max(0, candidates.length - nodes.length);
  const activeKeys = new Set(nodes.map(img => img.dataset.factoryLightImageKey || '').filter(Boolean));
  nodes.forEach(img => {
    const key = img.dataset.factoryLightImageKey || '';
    const dataUrl = store.get(key);
    if (!dataUrl) return;
    try {
      let objectUrl = urls.get(key);
      if (!objectUrl) {
        const blob = factoryDataUrlToBlob(dataUrl);
        if (!blob) return;
        objectUrl = URL.createObjectURL(blob);
        urls.set(key, objectUrl);
      }
      img.src = objectUrl;
      img.dataset.factoryLightLoaded = '1';
    } catch(e) {
      img.title = `이미지 표시 준비 실패: ${e.message || e}`;
    }
  });
  factoryTrimLightImageUrls(activeKeys);
  return { hydrated: nodes.length, pendingVisibleCount };
}

function scheduleFactoryHydrateLightImages(root = document) {
  if (typeof window === 'undefined') return;
  const roots = window.__factoryLightImageHydrateRoots = window.__factoryLightImageHydrateRoots || new Set();
  roots.add(root || document);
  if (window.__factoryLightImageHydrateTimer) return;
  const run = () => {
    window.__factoryLightImageHydrateTimer = null;
    const pendingRoots = Array.from(roots);
    roots.clear();
    let needsAnotherPass = false;
    pendingRoots.forEach(target => {
      const result = factoryHydrateLightImages(target || document);
      if (result?.pendingVisibleCount > 0) {
        roots.add(target || document);
        needsAnotherPass = true;
      }
    });
    if ((needsAnotherPass || roots.size > 0) && typeof window !== 'undefined') {
      window.__factoryLightImageHydrateTimer = setTimeout(run, 80);
    }
  };
  window.__factoryLightImageHydrateTimer = setTimeout(run, 60);
}

function renderFactoryMaterialPanels(factory, options = {}) {
  const open = factoryUiPanelOpen(factory, 'materials');
  const candidateCount = (factory.product?.dbCandidates?.length || 0) + (factory.product?.cafe24Candidates?.length || 0);
  const competitorCount = factoryCurrentWorkCompetitors(factory).length;
  const selectedChannels = factoryOpenMarketSelectedChannels(factory).length;
  const activeAutoTab = String(factory.automation?.activeTab || '').trim().replace(/^factory\//, '');
  const showInlineFinalRegistration = activeAutoTab !== 'publish';
  return `<section class="factory-section" id="factoryMaterialReviewSection" data-factory-lazy-panel="materials">
    <div class="factory-section-head">
      <div>
        <h3>DB 입력판 / 자료 검수</h3>
        <p>컨베이어 공정 아래에서 Cafe24 입력판, 신화사DB 비교값, 완성 DB, 경쟁사 참고자료를 한 번에 검수합니다.</p>
      </div>
      <div class="factory-toolbar">
        <span class="factory-pill">후보 ${candidateCount}개</span>
        <span class="factory-pill">경쟁사 ${competitorCount}건</span>
        <span class="factory-pill">마켓 ${selectedChannels}개</span>
        <button class="btn-sm" type="button" data-factory-toggle-panel="materials">${open ? '자료 검수판 접기' : '자료 검수판 펼치기'}</button>
      </div>
    </div>
    ${open
      ? `${renderFactoryDbSourcePanels(factory, options)}
        ${renderFactoryDbReview(factory)}
        ${renderFactoryOpenMarketSalesPanel(factory, { ...options, finalRegistration: showInlineFinalRegistration })}
        ${renderFactoryCompetitorPanel(factory)}`
      : factoryUiPanelSummaryCard('DB 입력판, Cafe24/마켓플러스 전송 패널, 경쟁사 참고자료는 현재 접혀 있습니다.', '자료 검수판 펼치기')}
  </section>`;
}

