const FACTORY_OPEN_MARKET_DEFAULT_REQUIRED_FIELDS = ['상품분류', '판매가', '대표이미지', '상세페이지', '옵션재고', '배송/반품', '원산지', '상품고시/소재'];

function factoryNormalizeOpenMarketChannel(raw = {}, fallbackIndex = 0) {
  const label = String(raw.label || raw.name || '').trim();
  const idSource = String(raw.id || label || `custom-${fallbackIndex + 1}`).trim();
  const id = idSource
    .toLowerCase()
    .replace(/[^a-z0-9가-힣_-]+/g, '-')
    .replace(/^-+|-+$/g, '') || `custom-${fallbackIndex + 1}`;
  const aliases = Array.isArray(raw.marketPlusAliases)
    ? raw.marketPlusAliases
    : (Array.isArray(raw.aliases) ? raw.aliases : []);
  const keywords = Array.isArray(raw.keywords) ? raw.keywords : [];
  return {
    id,
    label: label || id,
    connectorIds: Array.isArray(raw.connectorIds) ? raw.connectorIds.filter(Boolean) : [],
    keywords: uniqueApiKeys([id, label, ...keywords].filter(Boolean)),
    marketPlusAliases: uniqueApiKeys([label, ...aliases].filter(Boolean)),
    requiredFields: Array.isArray(raw.requiredFields) && raw.requiredFields.length
      ? raw.requiredFields.filter(Boolean)
      : FACTORY_OPEN_MARKET_DEFAULT_REQUIRED_FIELDS.slice(),
    note: String(raw.note || '마켓플러스 채널 프로필로 상품 보내기 결과를 확인합니다.').trim(),
    custom: !!raw.custom,
  };
}

function factoryOpenMarketChannels(factory = factoryRuntimeReadFactory()) {
  const sync = factory?.openMarketSync && typeof factory.openMarketSync === 'object' ? factory.openMarketSync : {};
  const extraChannels = Array.isArray(sync.extraChannels) ? sync.extraChannels : [];
  const merged = [
    ...FACTORY_OPEN_MARKET_CHANNELS.map((channel, index) => factoryNormalizeOpenMarketChannel(channel, index)),
    ...extraChannels.map((channel, index) => factoryNormalizeOpenMarketChannel({ ...channel, custom: true }, index)),
  ];
  const seen = new Set();
  return merged.filter(channel => {
    if (!channel.id || seen.has(channel.id)) return false;
    seen.add(channel.id);
    return true;
  });
}

function factoryOpenMarketFindChannel(channelId, factory = factoryRuntimeReadFactory()) {
  const id = String(channelId || '').trim();
  return factoryOpenMarketChannels(factory).find(channel => channel.id === id) || null;
}

function factoryOpenMarketSelectedChannels(factory = factoryRuntimeReadFactory()) {
  const sync = factory?.openMarketSync && typeof factory.openMarketSync === 'object' ? factory.openMarketSync : {};
  const selected = new Set(Array.isArray(sync.selectedChannels) ? sync.selectedChannels : []);
  const channels = factoryOpenMarketChannels(factory);
  return channels.filter(channel => selected.has(channel.id));
}

function factoryOpenMarketChannelLabelList(channels = []) {
  return channels.map(channel => channel.label || channel.id).filter(Boolean).join(', ');
}

const FACTORY_MARKETPLUS_STATUS_KEYWORDS = {
  success: ['성공', '완료', '등록완료', '전송완료', '연동완료', '정상', '판매중', '생성완료', '처리완료'],
  hold: ['보류', '대기', '검수', '심사', '처리중', '진행중', '확인중', '요청', '승인대기'],
  failed: ['실패', '오류', '에러', '반려', '불가', '불가능', '누락', '필수', '권한', '인증', '거절'],
};

function factoryMarketPlusChannelAliases(channel = {}) {
  return uniqueApiKeys([
    channel.label,
    channel.id,
    ...(Array.isArray(channel.marketPlusAliases) ? channel.marketPlusAliases : []),
    ...(Array.isArray(channel.keywords) ? channel.keywords : []),
  ].map(value => String(value || '').trim()).filter(Boolean));
}

function factoryMarketPlusTextIncludes(text, keyword) {
  const body = String(text || '');
  const needle = String(keyword || '').trim();
  if (!needle) return false;
  return body.includes(needle) || body.toLowerCase().includes(needle.toLowerCase());
}

function factoryMarketPlusChannelMatch(text, channel = {}) {
  const aliases = factoryMarketPlusChannelAliases(channel);
  return aliases.find(alias => factoryMarketPlusTextIncludes(text, alias)) || '';
}

function factoryMarketPlusStatusKeywordHit(text, channel = {}, type = 'success') {
  const channelSpecific = Array.isArray(channel[`${type}Keywords`]) ? channel[`${type}Keywords`] : [];
  const keywords = [...channelSpecific, ...(FACTORY_MARKETPLUS_STATUS_KEYWORDS[type] || [])];
  return keywords.find(keyword => factoryMarketPlusTextIncludes(text, keyword)) || '';
}

const FACTORY_OPEN_MARKET_TEST_PRODUCT_NAME = '방울수저집test';
