function factoryMarketPlusBrandManufacturerReady(baseDraft = {}) {
  const manufacturer = factoryMarketPlusRawValue(baseDraft, [
    'manufacturer_name',
    'manufacturer',
    'manufacturer_code',
    'made_by',
    'supplier_name',
    'supplier',
    'supplier_code',
  ]);
  const brand = factoryMarketPlusRawValue(baseDraft, [
    'brand_name',
    'brand',
    'brand_code',
    'trend_name',
    'trend_code',
  ]);
  const value = [manufacturer ? `제조 ${manufacturer}` : '', brand ? `브랜드 ${brand}` : ''].filter(Boolean).join(' · ');
  return {
    ok: !!manufacturer || !!brand,
    label: '브랜드/제조',
    value: value || '값 없음',
    detail: value
      ? 'Cafe24/완성 DB에서 제조사, 공급사, 브랜드 관련 값 감지'
      : '쿠팡 등 일부 채널에서 제조/브랜드 매핑이 필요할 수 있습니다.',
  };
}

function factoryMarketPlusRequirementStatus(requirement = '', baseDraft = {}) {
  const text = String(requirement || '').trim();
  const byLabel = factoryMarketPlusChecklist(baseDraft).find(item => item.label === text);
  if (byLabel) return byLabel;
  if (text.includes('상품분류')) return factoryMarketPlusChecklistItemByKey(baseDraft, 'category') || { key: 'category', label: text, ok: false, value: '' };
  if (text.includes('판매가') || text.includes('가격')) return factoryMarketPlusChecklistItemByKey(baseDraft, 'price') || { key: 'price', label: text, ok: false, value: '' };
  if (text.includes('대표이미지')) return factoryMarketPlusChecklistItemByKey(baseDraft, 'image') || { key: 'image', label: text, ok: false, value: '' };
  if (text.includes('상세페이지')) return factoryMarketPlusChecklistItemByKey(baseDraft, 'detail') || { key: 'detail', label: text, ok: false, value: '' };
  if (text.includes('옵션재고')) {
    const options = factoryMarketPlusChecklistItemByKey(baseDraft, 'options') || { key: 'options', label: '옵션/품목', ok: false, value: '' };
    const stock = factoryMarketPlusChecklistItemByKey(baseDraft, 'stock') || { key: 'stock', label: '재고/품절', ok: false, value: '' };
    return {
      key: 'options_stock',
      label: '옵션재고',
      ok: !!options.ok && !!stock.ok,
      value: `${options.value || '옵션 없음'} · ${stock.value || '재고값 없음'}`,
      detail: [options.detail, stock.detail].filter(Boolean).join(' · '),
    };
  }
  if (text.includes('배송/반품') || (text.includes('배송') && text.includes('반품'))) return factoryMarketPlusShippingReturnReady(baseDraft);
  if (text.includes('배송')) return factoryMarketPlusShippingReady(baseDraft);
  if (text.includes('원산지')) return factoryMarketPlusOriginReady(baseDraft);
  if (text.includes('상품고시') || text.includes('소재')) return factoryMarketPlusNoticeReady(baseDraft);
  if (text.includes('브랜드') || text.includes('제조')) return factoryMarketPlusBrandManufacturerReady(baseDraft);
  if (text.includes('SEO')) return factoryMarketPlusChecklistItemByKey(baseDraft, 'seo') || { key: 'seo', label: text, ok: false, value: '' };
  return { key: text, label: text || '필수값', ok: false, value: '확인 필요', detail: '아직 자동 매핑되지 않은 마켓별 필수값입니다.' };
}

function factoryMarketPlusChannelReadiness(sync = {}, baseDraft = {}) {
  const selected = new Set(Array.isArray(sync.selectedChannels) ? sync.selectedChannels : []);
  const channels = factoryOpenMarketChannels(factoryRuntimeReadFactory())
    .filter(channel => selected.has(channel.id))
    .map(channel => {
      const requirements = Array.isArray(channel.requiredFields) ? channel.requiredFields : [];
      const checks = requirements.map(req => {
        const item = factoryMarketPlusRequirementStatus(req, baseDraft);
        return {
          requirement: req,
          key: item.key || req,
          label: item.label || req,
          ok: !!item.ok,
          value: item.value || '',
          detail: item.detail || '',
        };
      });
      const missing = checks.filter(item => !item.ok);
      return {
        id: channel.id,
        label: channel.label,
        note: channel.note || '',
        custom: !!channel.custom,
        selected: selected.has(channel.id),
        ready: checks.length - missing.length,
        total: checks.length,
        ok: missing.length === 0,
        missingLabels: missing.map(item => item.requirement || item.label),
        checks,
      };
    });
  const selectedChannels = channels.filter(channel => channel.selected);
  const readyChannels = selectedChannels.filter(channel => channel.ok).length;
  return {
    channels,
    readyChannels,
    totalChannels: selectedChannels.length,
    allReady: selectedChannels.length > 0 && readyChannels === selectedChannels.length,
    missingByChannel: Object.fromEntries(selectedChannels.map(channel => [channel.id, channel.missingLabels])),
  };
}

function renderFactoryMarketPlusChannelReadinessMatrix(sync = {}, baseDraft = {}) {
  const readiness = factoryMarketPlusChannelReadiness(sync, baseDraft);
  const channels = readiness.channels;
  if (!channels.length) return '';
  return `<div style="border:1px solid rgba(34,197,94,.26);background:rgba(6,78,59,.10);border-radius:10px;padding:10px;margin-top:10px">
    <div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start;flex-wrap:wrap">
      <div>
        <div style="font-size:12px;color:var(--text);font-weight:950">${channels.length}채널 송출 준비 매트릭스</div>
        <div class="factory-small" style="margin-top:3px;color:var(--text-m);line-height:1.55">
          Cafe24 상품을 원장으로 삼고 <b>마켓플러스 상품 보내기</b> 화면에서 채널별로 확인할 필수값입니다. 직접 오픈마켓 API 등록이 아닙니다.
        </div>
      </div>
      <span class="api-badge" style="color:${readiness.allReady ? 'var(--ok)' : 'var(--warn)'}">준비 채널 ${readiness.readyChannels}/${readiness.totalChannels}</span>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;margin-top:9px">
      ${channels.map(channel => {
        const color = channel.ok ? 'var(--ok)' : 'var(--warn)';
        const bg = channel.ok ? 'rgba(34,197,94,.075)' : 'rgba(245,158,11,.075)';
        const border = channel.ok ? 'rgba(34,197,94,.30)' : 'rgba(245,158,11,.32)';
        const missing = channel.missingLabels.length ? channel.missingLabels.join(', ') : '없음';
        return `<div style="border:1px solid ${border};background:${bg};border-radius:9px;padding:8px;min-width:0">
          <div style="display:flex;justify-content:space-between;gap:6px;align-items:center;flex-wrap:wrap">
            <b style="font-size:12px;color:var(--text)">${escapeHtml(channel.label)}</b>
            <span class="api-badge" style="color:${color}">${channel.ok ? '준비' : '확인 필요'} ${channel.ready}/${channel.total}</span>
          </div>
          ${channel.note ? `<div class="factory-small" style="margin-top:5px;color:var(--text-m);line-height:1.45">${escapeHtml(channel.note)}</div>` : ''}
          <div class="factory-small" style="margin-top:6px;color:${color};font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escAttr(missing)}">부족: ${escapeHtml(missing)}</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:7px">
            ${channel.checks.map(item => `<span class="api-badge" title="${escAttr([item.value, item.detail].filter(Boolean).join(' · '))}" style="color:${item.ok ? 'var(--ok)' : 'var(--warn)'}">${item.ok ? '✓' : '!'} ${escapeHtml(item.requirement)}</span>`).join('')}
          </div>
        </div>`;
      }).join('')}
    </div>
  </div>`;
}

function factoryMarketPlusAdminUrl(sync = factoryEnsureOpenMarketSync(factoryRuntimeReadFactory())) {
  const saved = String(sync?.marketPlusUrl || '').trim();
  if (factoryMarketPlusIsAllowedAdminUrl(saved)) {
    return saved;
  }
  return 'https://eclogin.cafe24.com/Shop/';
}

function factoryMarketPlusIsAllowedAdminUrl(value = '') {
  const text = String(value || '').trim();
  return /^https:\/\/[^/\s]*(cafe24|marketplus)[^/\s]*\//i.test(text)
    || /^https:\/\/[^/\s]*(cafe24|marketplus)[^/\s]*$/i.test(text);
}

function factoryMarketPlusSnapshotUrl(sync = {}) {
  const snapshot = sync?.browserSnapshot && typeof sync.browserSnapshot === 'object' ? sync.browserSnapshot : null;
  const urls = [
    snapshot?.page?.url,
    snapshot?.tab?.url,
    sync?.browserAutomation?.openedUrl,
    sync?.browserAutomation?.openedTab?.url,
  ];
  return urls.map(url => String(url || '').trim()).find(factoryMarketPlusIsAllowedAdminUrl) || '';
}

function factoryMarketPlusActionPayload(channelIds = [], baseDraft = {}) {
  const channels = factoryOpenMarketChannels(factoryRuntimeReadFactory()).filter(channel => channelIds.includes(channel.id));
  const summary = factoryMarketPlusReadySummary(baseDraft);
  const channelReadiness = factoryMarketPlusChannelReadiness({
    selectedChannels: channelIds,
  }, baseDraft);
  const channelMissing = channels
    .map(channel => {
      const missing = channelReadiness.missingByChannel?.[channel.id] || [];
      return missing.length ? `${channel.label}: ${missing.join(', ')}` : '';
    })
    .filter(Boolean);
  const missingLabels = uniqueApiKeys([...(summary.missingLabels || []), ...channelMissing]);
  return {
    startedAt: Date.now(),
    productNo: baseDraft.productNo || '',
    productName: baseDraft.productName || '',
    productCode: baseDraft.rawCafe24Payload?.product_code || '',
    adminUrl: factoryMarketPlusAdminUrl(factoryEnsureOpenMarketSync(factoryRuntimeReadFactory())),
    channels: channels.map(channel => ({ id: channel.id, label: channel.label })),
    channelResults: Object.fromEntries(channels.map(channel => [channel.id, {
      channelId: channel.id,
      label: channel.label,
      status: 'pending',
      reason: '',
      updatedAt: null,
    }])),
    checklist: summary.checklist.map(item => ({
      key: item.key,
      label: item.label,
      ok: !!item.ok,
      value: item.value || '',
      detail: item.detail || '',
    })),
    channelReadiness,
    missingLabels,
    readyCount: summary.ready,
    totalCount: summary.total,
    state: missingLabels.length ? 'needs_values' : 'ready_to_open_marketplus',
    nextAction: missingLabels.length
      ? `마켓플러스 상품 보내기 전 누락/채널 확인 항목 보강: ${missingLabels.join(', ')}`
      : 'Cafe24 관리자에서 마켓플러스 상품보내기 화면을 열어 선택 채널의 마켓 상품 생성을 확인하세요.',
  };
}

function factoryMarketPlusActionText(action = null) {
  if (!action) return '';
  const channels = (Array.isArray(action.channels) ? action.channels : []).map(item => item.label || item.id).filter(Boolean).join(', ');
  const missing = Array.isArray(action.missingLabels) && action.missingLabels.length ? action.missingLabels.join(', ') : '없음';
  const checks = (Array.isArray(action.checklist) ? action.checklist : [])
    .map(item => `${item.ok ? '[준비]' : '[확인]'} ${item.label}: ${item.value || '값 없음'}`)
    .join('\n');
  return [
    'Cafe24 마켓플러스 상품 보내기 준비 메모',
    `상품: ${action.productName || '상품명 없음'}${action.productNo ? ` (#${action.productNo})` : ''}`,
    `대상 채널: ${channels || '선택 없음'}`,
    `준비 상태: ${action.readyCount || 0}/${action.totalCount || 0}`,
    `누락/확인 항목: ${missing}`,
    `다음 행동: ${action.nextAction || ''}`,
    '주의: 이 메모는 Cafe24/마켓플러스 상품 보내기 준비 기록이며, 채널별 마켓 상품 생성 성공/실패는 관리자 결과 확인 후 별도로 기록해야 합니다.',
    '',
    checks,
  ].join('\n');
}

