async function factoryReadMarketPlusCafe24LinkageStatus(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:read-cafe24-linkage',
      'cafe24',
      draft => factoryReadMarketPlusCafe24LinkageStatus({ ...options, factory: draft, render: false }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const baseDraft = factoryOpenMarketBuildBaseDraft(factory);
  const liveSync = () => factoryEnsureOpenMarketSync(factory);
  let sync = liveSync();
  const productName = String(
    baseDraft.productName
    || sync.testProductName
    || FACTORY_OPEN_MARKET_TEST_PRODUCT_NAME
    || ''
  ).trim();
  const productNo = String(
    baseDraft.productNo
    || sync.testProductNo
    || FACTORY_OPEN_MARKET_TEST_PRODUCT_NO
    || ''
  ).trim();
  const productCode = String(
    baseDraft.rawCafe24Payload?.product_code
    || baseDraft.productCode
    || ''
  ).trim();
  const selectedChannels = Array.isArray(sync.selectedChannels) ? sync.selectedChannels.filter(Boolean) : [];
  const reading = {
    ok: null,
    checkedAt: Date.now(),
    target: { productName, productNo, productCode },
    note: 'Cafe24 상품목록의 오픈마켓 연동 표시를 읽는 중입니다. 클릭/저장/전송은 하지 않습니다.',
  };
  sync.marketPlusCafe24LinkageStatus = reading;
  sync.lastMarketPlusCafe24LinkageCheckedAt = reading.checkedAt;
  sync.status = reading.note;
  factoryOpenMarketLog(reading.note, 'info', factory);
  sync = liveSync();
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  if (options.render !== false) renderPreservingMainScroll();
  try {
    const params = new URLSearchParams();
    params.set('port', '9224');
    params.set('channels', selectedChannels.join(','));
    if (productName) params.set('productName', productName);
    if (productNo) params.set('productNo', productNo);
    if (productCode) params.set('productCode', productCode);
    const timeoutSignal = typeof AbortSignal !== 'undefined' && AbortSignal.timeout
      ? AbortSignal.timeout(9000)
      : undefined;
    const res = await fetch(`${factoryBackendBaseUrl()}/api/marketplus/cafe24-product-linkage-status?${params.toString()}`, {
      cache: 'no-store',
      signal: timeoutSignal,
    });
    const data = await res.json().catch(() => ({}));
    const checkedAt = Date.now();
    data.checkedAt = checkedAt;
    sync = liveSync();
    sync.marketPlusCafe24LinkageStatus = data;
    sync.lastMarketPlusCafe24LinkageCheckedAt = checkedAt;
    if (!res.ok || data.ok === false) {
      sync.status = data.note || data.error || `Cafe24 상품목록 연동 표시 읽기 실패: HTTP ${res.status}`;
      factoryOpenMarketLog(sync.status, 'error', factory);
    } else {
      const detail = data.detail && typeof data.detail === 'object' ? data.detail : {};
      const linkedLabels = (Array.isArray(detail.linkedChannels) ? detail.linkedChannels : [])
        .map(channel => channel.label || channel.id)
        .filter(Boolean)
        .join(', ');
      const missingLabels = (Array.isArray(detail.missingChannels) ? detail.missingChannels : [])
        .map(channel => channel.label || channel.id)
        .filter(Boolean)
        .join(', ');
      sync.status = detail.linked
        ? `Cafe24 상품목록 연동 표시 확인: ${linkedLabels || '선택 채널'}`
        : (detail.rowFound
          ? `Cafe24 상품목록 행은 찾았지만 연동 표시 부족: ${missingLabels || '선택 채널'}`
          : 'Cafe24 상품목록에서 대상 상품 행을 찾지 못했습니다.');
      factoryOpenMarketLog(sync.status, detail.linked ? 'ok' : 'error', factory);
    }
    return data;
  } catch(e) {
    const data = {
      ok: false,
      checkedAt: Date.now(),
      target: { productName, productNo, productCode },
      note: `Cafe24 상품목록 연동 표시 읽기 실패: ${formatAppErrorMessage(e.message || String(e))}`,
    };
    sync = liveSync();
    sync.marketPlusCafe24LinkageStatus = data;
    sync.lastMarketPlusCafe24LinkageCheckedAt = data.checkedAt;
    sync.status = data.note;
    factoryOpenMarketLog(data.note, 'error', factory);
    return data;
  } finally {
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
  }
}

async function factoryRunMarketPlusSendLimitAction(action, options = {}) {
  const normalized = String(action || '').trim().toLowerCase();
  if (!['dismiss', 'retry'].includes(normalized)) return null;
  if (options.skipConfirm !== true) {
    const message = normalized === 'dismiss'
      ? "수량 안내의 '나중에 할게요' 버튼만 누릅니다. 송출은 실행하지 않습니다. 계속할까요?"
      : "마켓플러스의 '조정했어요, 다시 전송해 볼게요' 버튼을 누릅니다. 실제 MarketPlus 재전송이 시도될 수 있습니다. 계속할까요?";
    if (!window.confirm(message)) return null;
  }
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:run-send-limit-action',
      'cafe24',
      draft => factoryRunMarketPlusSendLimitAction(action, {
        ...options, factory: draft, render: false, skipConfirm: true,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const liveSync = () => factoryEnsureOpenMarketSync(factory);
  let sync = liveSync();
  const startedAt = Date.now();
  sync.marketPlusSendLimitAction = {
    ok: null,
    action: normalized,
    startedAt,
    note: normalized === 'dismiss'
      ? '마켓플러스 수량 안내 닫기를 실행하는 중입니다.'
      : '마켓플러스 조정 후 재전송 시도를 실행하는 중입니다.',
  };
  sync.status = sync.marketPlusSendLimitAction.note;
  factoryOpenMarketLog(sync.status, 'info', factory);
  sync = liveSync();
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  if (options.render !== false) renderPreservingMainScroll();
  try {
    const timeoutSignal = typeof AbortSignal !== 'undefined' && AbortSignal.timeout
      ? AbortSignal.timeout(8000)
      : undefined;
    const res = await fetch(`${factoryBackendBaseUrl()}/api/marketplus/send-limit-action`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ port: 9224, action: normalized, dryRun: !!options.dryRun }),
      cache: 'no-store',
      signal: timeoutSignal,
    });
    const data = await res.json().catch(() => ({}));
    data.checkedAt = Date.now();
    sync = liveSync();
    sync.marketPlusSendLimitAction = data;
    sync.status = data.note || (data.ok === false ? '마켓플러스 수량 안내 버튼 처리 실패' : '마켓플러스 수량 안내 버튼 처리 완료');
    factoryOpenMarketLog(sync.status, (!res.ok || data.ok === false) ? 'error' : 'ok', factory);
    await factoryReadMarketPlusSendLimitStatus({ render: false, factory });
    await factoryReadMarketPlusDetailStatus({ render: false, factory });
    await factoryReadMarketPlusCategoryFields({ render: false, factory });
    return data;
  } catch(e) {
    const data = {
      ok: false,
      checkedAt: Date.now(),
      action: normalized,
      note: `마켓플러스 수량 안내 버튼 처리 실패: ${formatAppErrorMessage(e.message || String(e))}`,
    };
    sync = liveSync();
    sync.marketPlusSendLimitAction = data;
    sync.status = data.note;
    factoryOpenMarketLog(data.note, 'error', factory);
    return data;
  } finally {
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
  }
}

async function factoryApplyMarketPlusCategoryFields(marketId, options = {}) {
  const id = String(marketId || '').trim();
  if (!id) return null;
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:apply-category-fields',
      'cafe24',
      draft => factoryApplyMarketPlusCategoryFields(marketId, {
        ...options, factory: draft, render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const fieldNodes = Array.from(document.querySelectorAll(`[data-marketplus-category-field^="${CSS.escape(id)}:"]`));
  const fields = fieldNodes.map(node => {
    const [, levelText] = String(node.dataset.marketplusCategoryField || '').split(':');
    const selected = node.options && node.selectedIndex >= 0 ? node.options[node.selectedIndex] : null;
    return {
      level: Number(levelText || 0),
      value: String(node.value || '').trim(),
      text: String(selected?.textContent || '').trim(),
    };
  }).filter(field => field.level >= 1 && field.level <= 4 && (field.value || field.text));
  if (!fields.length) {
    factoryOpenMarketLog('적용할 카테고리 선택값이 없습니다. 먼저 대분류부터 선택해주세요.', 'error', factory);
    saveLastWorkNow();
    renderPreservingMainScroll();
    return null;
  }
  if (options.skipConfirm !== true) {
    const ok = window.confirm('현재 열린 마켓플러스 화면의 카테고리 선택값을 변경합니다. 저장/전송은 하지 않습니다. 진행할까요?');
    if (!ok) return null;
  }
  const sync = factoryEnsureOpenMarketSync(factory);
  const startedAt = Date.now();
  sync.marketPlusCategoryApply = {
    ok: null,
    startedAt,
    marketId: id,
    fields,
    note: '마켓플러스 카테고리 값을 적용하는 중입니다. 저장/전송은 하지 않습니다.',
  };
  sync.status = sync.marketPlusCategoryApply.note;
  factoryOpenMarketLog(`${sync.marketPlusCategoryApply.note} (${id})`, 'info', factory);
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  renderPreservingMainScroll();
  try {
    const timeoutSignal = typeof AbortSignal !== 'undefined' && AbortSignal.timeout
      ? AbortSignal.timeout(18000)
      : undefined;
    const res = await fetch(`${factoryBackendBaseUrl()}/api/marketplus/category-apply`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      cache: 'no-store',
      signal: timeoutSignal,
      body: JSON.stringify({
        port: 9224,
        dryRun: !!options.dryRun,
        markets: [{ id, fields }],
      }),
    });
    const data = await res.json().catch(() => ({}));
    data.checkedAt = Date.now();
    sync.marketPlusCategoryApply = data;
    if (!res.ok || data.ok === false) {
      sync.status = data.note || data.error || `마켓플러스 카테고리 적용 실패: HTTP ${res.status}`;
      factoryOpenMarketLog(sync.status, 'error', factory);
    } else {
      sync.status = data.note || '마켓플러스 카테고리 값을 적용했습니다. 저장/전송은 실행하지 않았습니다.';
      factoryOpenMarketLog(sync.status, 'ok', factory);
    }
    saveLastWorkNow({ sync: false, persistent: false, server: false });
    await factoryReadMarketPlusCategoryFields({ render: false, factory });
    return data;
  } catch(e) {
    const data = {
      ok: false,
      checkedAt: Date.now(),
      note: `마켓플러스 카테고리 적용 실패: ${formatAppErrorMessage(e.message || String(e))}`,
    };
    sync.marketPlusCategoryApply = data;
    sync.status = data.note;
    factoryOpenMarketLog(data.note, 'error', factory);
    return data;
  } finally {
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
  }
}

function factoryMarketPlusProgressSummary(progress = {}) {
  const total = Number(progress.total || 0);
  const checked = Number(progress.checked || 0);
  const success = Number(progress.success || 0);
  const failed = Number(progress.failed || 0);
  const hold = Number(progress.hold || 0);
  const sending = Number(progress.sending || 0);
  const pending = Number(progress.pending || 0);
  return `확인 ${checked}/${total} · 성공 ${success} · 실패 ${failed} · 보류 ${hold} · 진행 ${sending} · 대기 ${pending}`;
}

function factoryMarketPlusWait(ms = 1000) {
  return new Promise(resolve => setTimeout(resolve, Math.max(0, Number(ms || 0))));
}

async function factoryWaitForMarketPlusReady(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:wait-ready',
      'cafe24',
      draft => factoryWaitForMarketPlusReady({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const attempts = Math.max(1, Math.min(60, Number(options.attempts || 20)));
  const intervalMs = Math.max(1200, Math.min(15000, Number(options.intervalMs || 3000)));
  const shouldOpenAdmin = options.openAdmin !== false;
  const startFactory = factory;
  const startSync = factoryEnsureOpenMarketSync(startFactory);
  startSync.browserAutomation = {
    ...(startSync.browserAutomation || {}),
    status: 'waiting_marketplus',
    checkedAt: Date.now(),
    note: shouldOpenAdmin
      ? 'Cafe24 관리자/마켓플러스 화면을 열고 로그인 완료와 상품보내기 화면 진입을 기다립니다.'
      : '현재 열린 Chrome 탭에서 마켓플러스 상품보내기 화면 진입을 기다립니다.',
  };
  startSync.status = startSync.browserAutomation.note;
  factoryOpenMarketLog(startSync.status, 'info', factory);
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  renderPreservingMainScroll();

  if (shouldOpenAdmin) {
    await factoryOpenMarketPlusAdmin({ factory });
  }

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    const automation = await factoryCheckMarketPlusBrowserAutomation({ render: false, factory });
    const loopFactory = factory;
    const loopSync = factoryEnsureOpenMarketSync(loopFactory);
    const hasMarketPlus = !!automation?.hasMarketPlusTab || automation?.status === 'marketplus_tab_detected';
    if (hasMarketPlus) {
      loopSync.status = '마켓플러스 탭을 감지했습니다. 현재 화면 읽기와 보내기 조건 점검을 이어갑니다.';
      factoryOpenMarketLog(loopSync.status, 'ok', factory);
      saveLastWorkNow({ sync: false, persistent: false, server: false });
      renderPreservingMainScroll();
      await factorySnapshotMarketPlusPage({ render: false, factory });
      await factorySafeClickMarketPlusSend({ dryRun: true, skipConfirm: true, factory });
      saveLastWorkNow({ sync: false });
      renderPreservingMainScroll();
      return true;
    }
    const waitingNote = automation?.hasCafe24LoginTab
      ? `로그인 대기 ${attempt}/${attempts}: Cafe24 로그인 탭이 감지됐습니다. 로그인 완료 후 마켓플러스 상품보내기 화면으로 이동해주세요.`
      : (automation?.hasCafe24AdminTab
        ? `마켓플러스 이동 대기 ${attempt}/${attempts}: Cafe24 관리자 탭은 감지됐지만 상품보내기 화면은 아직 아닙니다.`
        : `마켓플러스 화면 대기 ${attempt}/${attempts}: Cafe24/마켓플러스 탭을 찾는 중입니다.`);
    loopSync.browserAutomation = {
      ...(automation || loopSync.browserAutomation || {}),
      status: 'waiting_marketplus',
      checkedAt: Date.now(),
      note: waitingNote,
    };
    loopSync.status = waitingNote;
    factoryOpenMarketLog(waitingNote, attempt === 1 || attempt === attempts ? 'info' : 'debug', factory);
    saveLastWorkNow({ sync: false, persistent: false, server: false });
    renderPreservingMainScroll();
    if (attempt < attempts) {
      await factoryMarketPlusWait(intervalMs);
    }
  }

  const finalFactory = factory;
  const finalSync = factoryEnsureOpenMarketSync(finalFactory);
  finalSync.browserAutomation = {
    ...(finalSync.browserAutomation || {}),
    status: 'blocked_or_unavailable',
    checkedAt: Date.now(),
    reason: 'no_marketplus_tab',
    note: '자동 재점검 제한 시간 안에 마켓플러스 상품보내기 화면을 찾지 못했습니다. 로그인/화면 이동 후 다시 실행해주세요.',
  };
  finalSync.status = finalSync.browserAutomation.note;
  factoryOpenMarketLog(finalSync.status, 'error', factory);
  saveLastWorkNow({ sync: false });
  renderPreservingMainScroll();
  return false;
}

async function factoryPollMarketPlusResults(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:poll-results',
      'cafe24',
      draft => factoryPollMarketPlusResults({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const sync = factoryEnsureOpenMarketSync(factory);
  const action = sync.marketPlusAction && typeof sync.marketPlusAction === 'object'
    ? sync.marketPlusAction
    : null;
  const attempts = Math.max(1, Math.min(12, Number(options.attempts || 6)));
  const intervalMs = Math.max(1200, Math.min(15000, Number(options.intervalMs || 4000)));
  if (!action || !Array.isArray(action.channels) || !action.channels.length) {
    sync.status = '마켓플러스 채널 결과를 확인하려면 먼저 상품 보내기 절차를 시작해야 합니다.';
    factoryOpenMarketLog(sync.status, 'error', factory);
    saveLastWorkNow();
    if (options.render !== false) renderPreservingMainScroll();
    return false;
  }
  sync.status = `마켓플러스 채널 결과 자동 확인을 시작합니다. 최대 ${attempts}회, ${Math.round(intervalMs / 100) / 10}초 간격으로 화면을 다시 읽습니다.`;
  factoryOpenMarketLog(sync.status, 'info', factory);
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  if (options.render !== false) renderPreservingMainScroll();

  let settled = false;
  let stoppedByMissingTab = false;
  let lastProgress = factoryMarketPlusActionProgress(action);
  for (let index = 1; index <= attempts; index += 1) {
    const loopFactory = factory;
    const loopSync = factoryEnsureOpenMarketSync(loopFactory);
    loopSync.status = `마켓플러스 채널 결과 확인 ${index}/${attempts}: 화면을 다시 읽는 중입니다.`;
    factoryOpenMarketLog(loopSync.status, 'info', factory);
    saveLastWorkNow({ sync: false, persistent: false, server: false });

    const snapshot = await factorySnapshotMarketPlusPage({ render: false, factory });
    const currentFactory = factory;
    const currentSync = factoryEnsureOpenMarketSync(currentFactory);
    const currentAction = currentSync.marketPlusAction && typeof currentSync.marketPlusAction === 'object'
      ? currentSync.marketPlusAction
      : action;
    lastProgress = factoryMarketPlusActionProgress(currentAction);
    factoryOpenMarketLog(`마켓플러스 채널 결과 확인 ${index}/${attempts}: ${factoryMarketPlusProgressSummary(lastProgress)}`, lastProgress.failed || lastProgress.hold ? 'error' : 'info', factory);

    if (lastProgress.total > 0 && lastProgress.checked >= lastProgress.total) {
      settled = true;
      break;
    }
    if (snapshot?.ok === false && /탭을 찾지|마켓플러스 탭|backend_unavailable|실패/i.test(String(snapshot.note || snapshot.status || ''))) {
      stoppedByMissingTab = true;
      break;
    }
    if (index < attempts) {
      await factoryMarketPlusWait(intervalMs);
    }
  }

  const finalFactory = factory;
  const finalSync = factoryEnsureOpenMarketSync(finalFactory);
  const finalAction = finalSync.marketPlusAction && typeof finalSync.marketPlusAction === 'object'
    ? finalSync.marketPlusAction
    : action;
  lastProgress = factoryMarketPlusActionProgress(finalAction);
  if (settled) {
    finalSync.status = lastProgress.failed || lastProgress.hold
      ? `마켓플러스 채널 결과 확인 완료: ${factoryMarketPlusProgressSummary(lastProgress)}. 실패/보류 채널을 보강하세요.`
      : `마켓플러스 채널 결과 확인 완료: ${factoryMarketPlusProgressSummary(lastProgress)}. 선택 채널이 모두 성공으로 감지되었습니다.`;
  } else if (stoppedByMissingTab) {
    finalSync.status = '마켓플러스 채널 결과 확인 중단: 마켓플러스 결과 화면 탭을 찾지 못했습니다. 관리자 화면을 연 뒤 다시 확인해주세요.';
  } else {
    finalSync.status = `마켓플러스 채널 결과 확인 제한 시간 도달: ${factoryMarketPlusProgressSummary(lastProgress)}. 아직 남은 채널은 관리자 화면에서 다시 확인해야 합니다.`;
  }
  factoryOpenMarketLog(finalSync.status, settled && !lastProgress.failed && !lastProgress.hold ? 'ok' : 'error', factory);
  saveLastWorkNow({ sync: false });
  if (options.render !== false) renderPreservingMainScroll();
  return settled;
}

async function factorySafeClickMarketPlusSend(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:safe-click-send',
      'cafe24',
      draft => factorySafeClickMarketPlusSend({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  factoryUpdateFromInputs(factory);
  const sync = factoryEnsureOpenMarketSync(factory);
  const baseDraft = factoryOpenMarketBuildBaseDraft(factory);
  const action = sync.marketPlusAction && typeof sync.marketPlusAction === 'object'
    ? sync.marketPlusAction
    : factoryMarketPlusActionPayload(sync.selectedChannels || [], baseDraft);
  const snapshot = sync.browserSnapshot && typeof sync.browserSnapshot === 'object' ? sync.browserSnapshot : null;
  const analysis = snapshot?.analysis && typeof snapshot.analysis === 'object'
    ? snapshot.analysis
    : factoryAnalyzeMarketPlusSnapshot(snapshot || {}, baseDraft, action);
  const backendOnlyCheck = options.dryRun === true;
  if (!analysis.canSafeClickSend && !backendOnlyCheck) {
    const reason = analysis.nextAction || '마켓플러스 화면에서 대상 상품과 상품 보내기 버튼 후보가 확인되지 않아 실행하지 않았습니다.';
    sync.status = reason;
    factoryOpenMarketLog(reason, 'error', factory);
    saveLastWorkNow();
    renderPreservingMainScroll();
    return false;
  }
  const channels = Array.isArray(action.channels) && action.channels.length
    ? action.channels
    : factoryOpenMarketSelectedChannels(factory);
  const firstButton = Array.isArray(analysis.sendButtonCandidateDetails) && analysis.sendButtonCandidateDetails.length
    ? analysis.sendButtonCandidateDetails[0]
    : null;
  const channelText = channels.map(channel => channel.label || channel.id).filter(Boolean).join(', ');
  const ok = options.skipConfirm === true || window.confirm([
    '마켓플러스 관리자 화면의 상품보내기/전송 버튼 후보를 실행합니다.',
    '',
    `상품: ${baseDraft.productName || action.productName || '상품명 없음'}${baseDraft.productNo ? ` (#${baseDraft.productNo})` : ''}`,
    `채널: ${channelText || '선택 채널 없음'}`,
    `버튼 후보: ${firstButton?.text || analysis.sendButtonCandidates?.[0] || '후보 없음'}`,
    '',
    '이 동작은 직접 오픈마켓 API 등록이 아니라 열린 Cafe24 마켓플러스 관리자 화면에서 클릭을 실행합니다.',
  ].join('\n'));
  if (!ok) return false;
  const payload = {
    port: 9224,
    dryRun: !!options.dryRun,
    productName: baseDraft.productName || action.productName || '',
    productNo: baseDraft.productNo || action.productNo || '',
    productCode: baseDraft.rawCafe24Payload?.product_code || action.productCode || '',
    channelLabels: channels.map(channel => channel.label || channel.id).filter(Boolean),
    buttonText: firstButton?.text || analysis.sendButtonCandidates?.[0] || '',
    buttonIndex: firstButton?.index,
    planBMode: options.dryRun ? 'off' : 'dry-run',
    captureNetwork: !options.dryRun,
  };
  const liveSync = () => factoryEnsureOpenMarketSync(factory);
  sync.status = payload.dryRun
    ? '마켓플러스 보내기 조건을 점검 중입니다. 실제 클릭은 하지 않습니다.'
    : '마켓플러스 상품 보내기 버튼 안전 실행 중입니다. 화면/상품/버튼 조건을 백엔드에서 다시 확인합니다.';
  factoryOpenMarketLog(sync.status, 'info', factory);
  saveLastWorkNow({ sync: false, persistent: false, server: false });
  renderPreservingMainScroll();
  try {
    const timeoutSignal = typeof AbortSignal !== 'undefined' && AbortSignal.timeout
      ? AbortSignal.timeout(8000)
      : undefined;
    const res = await fetch(`${factoryBackendBaseUrl()}/api/marketplus/safe-click-send`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      cache: 'no-store',
      signal: timeoutSignal,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.ok === false) {
      const failureText = factoryMarketPlusBackendFailureText(data);
      const tabInfo = data?.tab && typeof data.tab === 'object' ? data.tab : {};
      const hasMarketPlus = !!data?.hasMarketPlusTab || !!tabInfo.isMarketPlus;
      const hasCafe24Admin = !!data?.hasCafe24AdminTab || !!tabInfo.isCafe24Admin;
      const hasCafe24Login = !!data?.hasCafe24LoginTab || !!tabInfo.isCafe24Login;
      const hasCafe24 = !!data?.hasCafe24Tab || !!tabInfo.isCafe24;
      const failureStatus = data?.reason === 'no_marketplus_tab'
        ? factoryMarketPlusBrowserStatusFromData(data)
        : (hasMarketPlus ? 'safecheck_failed' : 'blocked_or_unavailable');
      const resultSync = liveSync();
      resultSync.browserAutomation = {
        ...(resultSync.browserAutomation || {}),
        status: failureStatus,
        checkedAt: Date.now(),
        connected: data?.connected !== false,
        debugPort: data?.debugPort || 9224,
        ...factoryMarketPlusBrowserProfileMeta(data || {}, resultSync.browserAutomation || {}),
        tabCount: Number(data?.tabCount || resultSync.browserAutomation?.tabCount || 0),
        hasCafe24Tab: hasCafe24,
        hasCafe24LoginTab: hasCafe24Login,
        hasCafe24AdminTab: hasCafe24Admin,
        hasMarketPlusTab: hasMarketPlus,
        cafe24Tabs: Array.isArray(data?.cafe24Tabs) ? data.cafe24Tabs : [],
        cafe24LoginTabs: Array.isArray(data?.cafe24LoginTabs) ? data.cafe24LoginTabs : [],
        cafe24AdminTabs: Array.isArray(data?.cafe24AdminTabs) ? data.cafe24AdminTabs : [],
        marketPlusTabs: Array.isArray(data?.marketPlusTabs) ? data.marketPlusTabs : [],
        tabsSample: Array.isArray(data?.tabsSample) ? data.tabsSample : [],
        tab: tabInfo,
        matchedTargets: Array.isArray(data?.matchedTargets) ? data.matchedTargets : [],
        channelHits: Array.isArray(data?.channelHits) ? data.channelHits : [],
        missingChannels: Array.isArray(data?.missingChannels) ? data.missingChannels : [],
        candidates: Array.isArray(data?.candidates) ? data.candidates : [],
        expected: data?.expected && typeof data.expected === 'object' ? data.expected : null,
        requiredNextSteps: Array.isArray(data?.requiredNextSteps) ? data.requiredNextSteps : [],
        detected: data?.detected && typeof data.detected === 'object' ? data.detected : null,
        planB: data?.planB && typeof data.planB === 'object' ? data.planB : null,
        recipeCapture: data?.recipeCapture && typeof data.recipeCapture === 'object' ? data.recipeCapture : null,
        reason: data?.reason || '',
        stage: data?.stage || '',
        note: failureText,
      };
      throw new Error(failureText || `HTTP ${res.status}`);
    }
    const resultSync = liveSync();
    const tabInfo = data?.tab && typeof data.tab === 'object' ? data.tab : {};
    resultSync.browserAutomation = {
      ...(resultSync.browserAutomation || {}),
      status: payload.dryRun ? 'safecheck_ready' : 'marketplus_clicked',
      checkedAt: Date.now(),
      connected: data?.connected !== false,
      debugPort: data?.debugPort || 9224,
      ...factoryMarketPlusBrowserProfileMeta(data || {}, resultSync.browserAutomation || {}),
      hasCafe24Tab: !!tabInfo.isCafe24 || !!resultSync.browserAutomation?.hasCafe24Tab,
      hasCafe24LoginTab: !!tabInfo.isCafe24Login || !!resultSync.browserAutomation?.hasCafe24LoginTab,
      hasCafe24AdminTab: !!tabInfo.isCafe24Admin || !!resultSync.browserAutomation?.hasCafe24AdminTab,
      hasMarketPlusTab: !!tabInfo.isMarketPlus || !!resultSync.browserAutomation?.hasMarketPlusTab,
      tab: tabInfo,
      matchedTargets: Array.isArray(data?.matchedTargets) ? data.matchedTargets : [],
      channelHits: Array.isArray(data?.channelHits) ? data.channelHits : [],
      missingChannels: Array.isArray(data?.missingChannels) ? data.missingChannels : [],
      candidates: Array.isArray(data?.candidates) ? data.candidates : [],
      picked: data?.picked && typeof data.picked === 'object' ? data.picked : null,
      expected: data?.expected && typeof data.expected === 'object' ? data.expected : payload,
      requiredNextSteps: Array.isArray(data?.requiredNextSteps) ? data.requiredNextSteps : [],
      detected: data?.detected && typeof data.detected === 'object' ? data.detected : null,
      planB: data?.planB && typeof data.planB === 'object' ? data.planB : null,
      recipeCapture: data?.recipeCapture && typeof data.recipeCapture === 'object' ? data.recipeCapture : null,
      dryRun: !!payload.dryRun,
      clicked: !!data?.clicked,
      reason: payload.dryRun ? 'safecheck_ready' : 'marketplus_clicked',
      stage: payload.dryRun ? 'safecheck_ready' : 'marketplus_clicked',
      note: data.note || (payload.dryRun ? '마켓플러스 안전 클릭 조건을 통과했습니다.' : '마켓플러스 상품 보내기 버튼을 클릭했습니다.'),
    };
    resultSync.marketPlusAction = action;
    action.state = payload.dryRun ? 'ready_to_open_marketplus' : 'marketplus_sending';
    action.nextAction = data.note || '마켓플러스 클릭을 실행했습니다. 결과 화면을 다시 읽어 채널별 마켓 상품 생성 성공/보류/실패를 확인하세요.';
    Object.values(action.channelResults || {}).forEach(result => {
      result.status = payload.dryRun ? 'pending' : 'sending';
      result.reason = data.note || '';
      result.updatedAt = Date.now();
    });
    resultSync.status = data.note || '마켓플러스 상품 보내기 버튼 후보를 실행했습니다.';
    factoryOpenMarketLog(resultSync.status, 'ok', factory);
    if (data?.planB?.enabled) {
      const planBText = data.planB.ok
        ? `플랜B dry-run 통과: 내부 API 레시피 ${data.planB.matchedCount || 0}개가 현재 채널과 맞습니다.`
        : `플랜B dry-run: ${data.planB.note || '맞는 레시피가 없어 기존 화면 클릭 루트로 진행했습니다.'}`;
      factoryOpenMarketLog(planBText, data.planB.ok ? 'ok' : 'info', factory);
    }
    if (data?.recipeCapture?.ok) {
      factoryOpenMarketLog(`마켓플러스 전송 레시피 저장: 신규 ${data.recipeCapture.saved || 0}개, 갱신 ${data.recipeCapture.updated || 0}개`, 'ok', factory);
    } else if (payload.captureNetwork && data?.recipeCapture?.reason) {
      factoryOpenMarketLog(`마켓플러스 전송 레시피 캡처: ${data.recipeCapture.note || data.recipeCapture.reason}`, 'info', factory);
    }
    if (!payload.dryRun) {
      setTimeout(() => factoryPollMarketPlusResults({ attempts: 6, intervalMs: 4000, render: true }), 1800);
    }
    return true;
  } catch(e) {
    const resultSync = liveSync();
    resultSync.status = payload.dryRun
      ? `마켓플러스 보내기 조건 점검 결과: ${formatAppErrorMessage(e.message || String(e))}`
      : `마켓플러스 상품 보내기 버튼 실행 실패: ${formatAppErrorMessage(e.message || String(e))}`;
    factoryOpenMarketLog(resultSync.status, 'error', factory);
    return false;
  } finally {
    saveLastWorkNow({ sync: false });
    renderPreservingMainScroll();
  }
}

async function factoryCopyMarketPlusActionText(action) {
  const text = factoryMarketPlusActionText(action);
  if (!text || !navigator?.clipboard?.writeText) return false;
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch(_) {
    return false;
  }
}

async function factoryCopyMarketPlusGuideValue(kind = '', options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:copy-guide',
      'cafe24',
      draft => factoryCopyMarketPlusGuideValue(kind, {
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow();
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  const sync = factoryEnsureOpenMarketSync(factory);
  const baseDraft = factoryOpenMarketBuildBaseDraft(factory);
  const valueMap = {
    memo: factoryMarketPlusOperatorText(baseDraft, sync),
    productName: baseDraft.productName || sync.testProductName || FACTORY_OPEN_MARKET_TEST_PRODUCT_NAME,
    productNo: baseDraft.productNo || sync.testProductNo || FACTORY_OPEN_MARKET_TEST_PRODUCT_NO || '',
    productCode: baseDraft.rawCafe24Payload?.product_code || '',
    menuSearch: factoryMarketPlusMenuSearchText(baseDraft, sync),
  };
  const text = String(valueMap[kind] || '').trim();
  if (!text) {
    factoryOpenMarketLog('복사할 마켓플러스 작업 값이 없습니다.', 'error', factory);
    return false;
  }
  if (!navigator?.clipboard?.writeText) {
    factoryOpenMarketLog('브라우저 클립보드 권한이 없어 복사하지 못했습니다.', 'error', factory);
    return false;
  }
  try {
    await navigator.clipboard.writeText(text);
    const label = kind === 'memo'
      ? '작업 메모'
      : (kind === 'productNo'
        ? '상품번호'
        : (kind === 'productCode'
          ? '상품코드'
          : (kind === 'menuSearch' ? '메뉴/검색어' : '상품명')));
    factoryOpenMarketLog(`마켓플러스 ${label}을 클립보드에 복사했습니다.`, 'ok', factory);
    return true;
  } catch(e) {
    factoryOpenMarketLog(`마켓플러스 값 복사 실패: ${formatAppErrorMessage(e.message || String(e))}`, 'error', factory);
    return false;
  }
}

function factoryOpenMarketChannelDraft(channel, baseDraft) {
  const marketNotes = {
    coupang: ['카테고리와 배송/반품 템플릿은 쿠팡 계정 기준 매핑 필요', '옵션 재고는 품목별 수량으로 변환'],
    smartstore: ['네이버 카테고리 ID와 속성값 매핑 필요', '대표/상세 이미지는 네이버 이미지 규격 확인'],
    gmarket: ['ESM 카테고리와 배송정책 코드 매핑 필요', 'G마켓 노출/판매 상태 별도 확인'],
    auction: ['ESM 카테고리와 배송정책 코드 매핑 필요', '옥션 노출/판매 상태 별도 확인'],
    elevenst: ['11번가 카테고리/배송비 템플릿 매핑 필요', '상품고시정보와 옵션 재고 변환 필요'],
  };
  return {
    ...cloneData(baseDraft),
    channelId: channel.id,
    channelLabel: channel.label,
    createdAt: Date.now(),
    marketNotes: marketNotes[channel.id] || [],
  };
}

function factoryAddOpenMarketChannelFromInputs(options = {}) {
  if (!options.factory) {
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:add-channel',
      'cafe24',
      draft => factoryAddOpenMarketChannelFromInputs({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow();
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  const sync = factoryEnsureOpenMarketSync(factory);
  const label = String(document.getElementById('factoryOpenMarketNewChannelLabel')?.value || '').trim();
  const aliases = String(document.getElementById('factoryOpenMarketNewChannelAliases')?.value || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
  const requiredFields = String(document.getElementById('factoryOpenMarketNewChannelRequired')?.value || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
  if (!label) {
    factoryOpenMarketLog('추가할 마켓플러스 채널명을 입력해주세요.', 'error', factory);
    return;
  }
  const normalized = factoryNormalizeOpenMarketChannel({
    label,
    marketPlusAliases: aliases,
    requiredFields,
    custom: true,
  }, sync.extraChannels?.length || 0);
  const exists = factoryOpenMarketChannels(factory).some(channel => channel.id === normalized.id);
  if (exists) {
    factoryOpenMarketLog(`${normalized.label} 채널 프로필은 이미 있습니다. 기존 채널을 선택해서 사용해주세요.`, 'error', factory);
    return;
  }
  sync.extraChannels = [...(sync.extraChannels || []), normalized];
  sync.selectedChannels = uniqueApiKeys([...(sync.selectedChannels || []), normalized.id]);
  sync.selectedChannelsUserTouched = true;
  factoryOpenMarketLog(`${normalized.label} 마켓플러스 채널 프로필을 추가했습니다.`, 'ok', factory);
}

function factoryRemoveOpenMarketChannel(channelId = '', options = {}) {
  if (!options.factory) {
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/openmarket:remove-channel',
      'cafe24',
      draft => factoryRemoveOpenMarketChannel(channelId, {
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow();
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  const sync = factoryEnsureOpenMarketSync(factory);
  const channel = factoryOpenMarketFindChannel(channelId, factory);
  if (!channel?.custom) {
    factoryOpenMarketLog('기본 마켓플러스 채널 프로필은 제거하지 않습니다. 선택 해제로만 제외할 수 있습니다.', 'error', factory);
    return;
  }
  sync.extraChannels = (sync.extraChannels || []).filter(item => item.id !== channel.id);
  sync.selectedChannels = (sync.selectedChannels || []).filter(id => id !== channel.id);
  sync.selectedChannelsUserTouched = true;
  if (sync.drafts && typeof sync.drafts === 'object') delete sync.drafts[channel.id];
  if (sync.dryRuns && typeof sync.dryRuns === 'object') delete sync.dryRuns[channel.id];
  if (sync.channelStatus && typeof sync.channelStatus === 'object') delete sync.channelStatus[channel.id];
  factoryOpenMarketLog(`${channel.label} 추가 채널 프로필을 제거했습니다.`, 'info', factory);
}

