function factoryFinalRegistrationCafe24Model(factory = factoryRuntimeReadFactory(), options = {}) {
  const settings = factoryFinalRegistrationSettings(factory);
  const targetInfo = typeof factoryCafe24TargetInfo === 'function' ? factoryCafe24TargetInfo(factory) : {};
  const productNo = String(targetInfo.productNo || '').trim();
  if (settings.cafe24RegistrationMode === 'update') {
    if (!productNo) {
      return {
        mode: 'update',
        canRun: false,
        productNo: '',
        label: '기존 상품 수정',
        reason: '기존 상품 수정은 Cafe24 상품번호가 확정되어야 실행할 수 있습니다.',
        fieldCount: 0,
      };
    }
    return {
      mode: 'update',
      canRun: true,
      productNo,
      label: `기존 상품 #${productNo} 저장`,
      reason: '',
      fieldCount: 2,
    };
  }
  const createModel = Object.prototype.hasOwnProperty.call(options, 'createModel')
    ? options.createModel
    : (typeof factoryCafe24CreatePreviewModel === 'function'
      ? factoryCafe24CreatePreviewModel(factory)
      : null);
  const requiredMissing = Array.isArray(createModel?.requiredMissing) ? createModel.requiredMissing : [];
  const fieldCount = createModel?.fieldNames?.length || 0;
  if (requiredMissing.length) {
    return {
      mode: 'create',
      canRun: false,
      productNo: '',
      label: '새 상품 등록',
      reason: `새 상품 등록 필수값 누락: ${requiredMissing.join(', ')}`,
      fieldCount,
    };
  }
  if (!fieldCount) {
    return {
      mode: 'create',
      canRun: false,
      productNo: '',
      label: '새 상품 등록',
      reason: '새 상품으로 보낼 상품 기본 입력값이 없습니다.',
      fieldCount,
    };
  }
  return {
    mode: 'create',
    canRun: true,
    productNo: '',
    label: productNo ? `새 상품 등록 (${fieldCount}) · 기존 #${productNo} 참고만` : `새 상품 등록 (${fieldCount})`,
    reason: '',
    fieldCount,
  };
}

function renderFactoryCafe24FinalFlagOptions(kind = 'display', selectedValue = 'T') {
  const options = typeof CAFE24_FORM_SELECTS !== 'undefined'
    ? (kind === 'selling' ? CAFE24_FORM_SELECTS.selling : CAFE24_FORM_SELECTS.display)
    : [
      { value: 'T', label: kind === 'selling' ? '판매함' : '진열함' },
      { value: 'F', label: kind === 'selling' ? '판매안함' : '진열안함' },
    ];
  const selected = factoryNormalizeCafe24FinalFlag(selectedValue);
  return (options || []).map(option =>
    `<option value="${escAttr(option.value)}" ${option.value === selected ? 'selected' : ''}>${escapeHtml(option.label)}</option>`
  ).join('');
}

function factoryFinalRegistrationFirstText(...values) {
  return values
    .map(value => String(value ?? '').trim())
    .find(Boolean) || '';
}

function factoryFinalRegistrationAuthoritativeProductName(factory = factoryRuntimeReadFactory(), fallbacks = []) {
  const product = factory?.product || {};
  if (typeof factoryAuthoritativeProductName === 'function') {
    const resolved = factoryAuthoritativeProductName(factory);
    if (resolved) return resolved;
  }
  return factoryFinalRegistrationFirstText(
    product.userProductName,
    product.productName,
    state?.productName,
    ...(Array.isArray(fallbacks) ? fallbacks : [fallbacks]),
    product.cafe24FinalRegistration?.productName,
    product.cafe24FinalRegistration?.product_name,
  );
}

function factoryFinalRegistrationCreateModel(factory, options) {
  const config = options || {};
  if (Object.prototype.hasOwnProperty.call(config, 'createModel') && config.createModel !== undefined) return config.createModel;
  return typeof factoryCafe24CreatePreviewModel === 'function' ? factoryCafe24CreatePreviewModel(factory) : null;
}

function factoryFinalRegistrationBasicInfoModel(factory = factoryRuntimeReadFactory(), options = {}) {
  const createModel = factoryFinalRegistrationCreateModel(factory, options);
  const product = createModel?.product || {};
  const finalDb = createModel?.dbModel?.finalDb || factory?.product?.finalDb || {};
  const finalRegistration = factory?.product?.cafe24FinalRegistration || {};
  const liveFactory = typeof factoryRuntimeReadCommittedFactory === 'function'
    ? factoryRuntimeReadCommittedFactory()
    : factory;
  const requiredRows = [
    ['size', '사이즈'],
    ['width_mm', '가로'],
    ['depth_mm', '세로'],
    ['weight', '무게'],
    ['material', '소재'],
    ['usage', '용도'],
  ].map(([fieldId, label]) => ({
    fieldId,
    label,
    value: factoryFinalRegistrationFirstText(
      liveFactory?.product?.finalDb?.[fieldId],
      liveFactory?.product?.dbFieldSettings?.[fieldId]?.manualValue,
      finalDb[fieldId],
      factory?.product?.dbFieldSettings?.[fieldId]?.manualValue,
    ),
  }));
  const automationSalePrice = typeof factoryAutomationFieldValue === 'function'
    ? factoryAutomationFieldValue(factory, 'sale_price', ['price', 'selling_price', '판매가격']).value
    : '';
  const liveAutomationSalePrice = typeof factoryAutomationFieldValue === 'function'
    ? factoryAutomationFieldValue(liveFactory, 'sale_price', ['price', 'selling_price', '판매가격']).value
    : '';
  const reviewedSaleField = factory?.automation?.fieldReview?.sale_price;
  const liveReviewedSaleField = liveFactory?.automation?.fieldReview?.sale_price;
  const reviewedSalePrice = reviewedSaleField
    && typeof factoryFieldReviewMatchesCurrentWork === 'function'
    && factoryFieldReviewMatchesCurrentWork(reviewedSaleField, factory)
    ? String(reviewedSaleField.value ?? '').trim()
    : '';
  const liveReviewedSalePrice = liveReviewedSaleField
    && typeof factoryFieldReviewMatchesCurrentWork === 'function'
    && factoryFieldReviewMatchesCurrentWork(liveReviewedSaleField, liveFactory)
    ? String(liveReviewedSaleField.value ?? '').trim()
    : '';
  const salePriceCandidates = [
    finalRegistration.price,
    finalRegistration.salePrice,
    finalRegistration.sale_price,
    automationSalePrice,
    liveAutomationSalePrice,
    reviewedSalePrice,
    liveReviewedSalePrice,
    product.price,
    finalDb.sale_price,
    finalDb.price,
  ].map(value => String(value ?? '').trim());
  const salePrice = salePriceCandidates.find(value => factoryCafe24PositiveMoneyText(value))
    || factoryFinalRegistrationFirstText(...salePriceCandidates);
  const productName = factoryFinalRegistrationFirstText(
    finalRegistration.productName,
    finalRegistration.product_name,
    product.product_name,
    finalDb.product_name,
    factory?.product?.confirmedDb?.product_name,
    factoryFinalRegistrationAuthoritativeProductName(factory),
  );
  const originPlaceNo = product.origin_place_no || product.origin_place_code;
  const originClassification = { F: '국내', T: '국외', E: '기타' }[String(product.origin_classification || '').toUpperCase()] || '';
  const originValue = String(product.origin_place_value || '').trim()
    || (typeof factoryCafe24ReferenceOverrideName === 'function'
      ? factoryCafe24ReferenceOverrideName('originPlaces', originPlaceNo)
      : '')
    || [originClassification, originPlaceNo].filter(Boolean).join(' > ')
    || String(product.made_in_code || '').trim();
  const createReferenceDefaults = [
    { label: '제조사', apiField: 'manufacturer_code', type: 'manufacturers', code: product.manufacturer_code },
    { label: '공급사', apiField: 'supplier_code', type: 'suppliers', code: product.supplier_code },
    { label: '브랜드', apiField: 'brand_code', type: 'brands', code: product.brand_code },
    { label: '원산지', apiField: 'origin_classification · origin_place_no', value: originValue },
  ].map(item => ({
    label: item.label,
    apiField: item.apiField,
    value: item.value || (typeof factoryCafe24ReferenceOverrideName === 'function'
      ? factoryCafe24ReferenceOverrideName(item.type, item.code)
      : '') || String(item.code || '').trim(),
  }));
  const rows = [
    {
      fieldId: 'product_name',
      apiField: 'product_name',
      label: '상품명',
      value: productName,
      required: true,
      inputMode: 'text',
      help: 'Cafe24 등록 payload의 상품명만 바뀝니다. 현재 작업파일의 제품 기준과 이미지·후보 범위는 유지됩니다.',
    },
    {
      fieldId: 'sale_price',
      apiField: 'price',
      label: '판매가',
      value: salePrice,
      required: true,
      inputMode: 'numeric',
      help: 'Cafe24 판매가입니다.',
    },
    {
      fieldId: 'consumer_price',
      apiField: 'retail_price',
      label: '소비자가',
      value: factoryFinalRegistrationFirstText(finalRegistration.retailPrice, finalRegistration.consumerPrice, finalRegistration.consumer_price, finalRegistration.retail_price, product.retail_price, finalDb.consumer_price, finalDb.retail_price),
      required: false,
      inputMode: 'numeric',
      help: '필요할 때만 입력합니다.',
    },
    {
      fieldId: 'purchase_price',
      apiField: 'supply_price',
      label: '공급가/원가',
      value: factoryFinalRegistrationFirstText(finalRegistration.supplyPrice, finalRegistration.purchasePrice, finalRegistration.purchase_price, finalRegistration.supply_price, product.supply_price, finalDb.purchase_price, finalDb.supply_price),
      required: false,
      inputMode: 'numeric',
      help: 'Cafe24 공급가/원가 기준입니다.',
    },
  ];
  return {
    rows,
    requiredRows,
    createReferenceDefaults,
    productName,
    salePrice: rows.find(row => row.fieldId === 'sale_price')?.value || '',
    requiredMissing: rows.filter(row => row.required && !String(row.value || '').trim()).map(row => row.label),
  };
}

function renderFactoryFinalRegistrationBasicInfoPanel(factory = factoryRuntimeReadFactory(), options = {}) {
  const model = factoryFinalRegistrationBasicInfoModel(factory, options);
  const missing = model.requiredMissing;
  return `<div class="factory-cafe24-save-panel" data-factory-final-basic-info-panel="1" style="margin-top:10px;border-color:${missing.length ? 'rgba(245,158,11,.38)' : 'rgba(99,102,241,.26)'};background:${missing.length ? 'rgba(245,158,11,.055)' : 'rgba(15,23,42,.30)'}">
    <div class="factory-cafe24-save-head">
      <div>
        <div class="factory-cafe24-save-title">등록 기본정보 확인/수정</div>
        <div class="factory-cafe24-save-sub">아래 값이 최종 Cafe24 등록 payload에 들어갑니다. 등록 직전에 바로 고칠 수 있습니다.</div>
      </div>
      <button class="btn-sm" type="button" data-factory-apply-final-basic-info="1" title="아래 기본정보를 DB 입력판과 최종 등록 기준에 반영합니다.">
        <span class="material-icons-outlined" style="font-size:14px">done</span>기본정보 적용
      </button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:8px">
      ${model.rows.map(row => `<label style="display:flex;flex-direction:column;gap:5px;font-size:11px;color:var(--text-m);font-weight:900;min-width:0">
        <span style="display:flex;align-items:center;gap:5px;justify-content:space-between">
          <span>${escapeHtml(row.label)}${row.required ? ' *' : ''}</span>
          <span class="factory-db-source">${escapeHtml(row.apiField)}</span>
        </span>
        <input class="input" data-factory-final-basic-field="${escAttr(row.fieldId)}" value="${escAttr(row.value)}" inputmode="${escAttr(row.inputMode)}" placeholder="${row.required ? '필수 입력' : '선택 입력'}" title="${escAttr(row.help)}">
      </label>`).join('')}
    </div>
    <div data-factory-final-required-values="1" style="margin-top:10px">
      <div class="factory-cafe24-save-title">필수값/사이즈 확인</div>
      <div class="factory-cafe24-save-sub">현재 작업에 저장된 실제 값입니다. 빈 항목은 값을 만들지 않고 비워 둡니다.</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:8px">
        ${model.requiredRows.map(row => `<div class="factory-cafe24-save-stat" data-factory-final-required-field="${escAttr(row.fieldId)}"${row.fieldId === 'usage' ? ' style="grid-column:1 / -1"' : ''}><b data-factory-final-required-value="${escAttr(row.fieldId)}">${escapeHtml(row.value)}</b><span>${escapeHtml(row.label)} · ${escapeHtml(row.fieldId)}</span></div>`).join('')}
      </div>
    </div>
    <div class="factory-cafe24-save-stats" data-factory-final-create-reference-defaults="1" style="margin-top:8px">
      ${model.createReferenceDefaults.map(item => `<div class="factory-cafe24-save-stat"><b>${escapeHtml(item.value)}</b><span>${escapeHtml(item.label)} · ${escapeHtml(item.apiField)}</span></div>`).join('')}
    </div>
    <div class="factory-small" data-factory-final-origin-default-note="1" style="color:var(--text-m);line-height:1.5">새 상품 등록 기준입니다. 원산지는 신화사DB/Cafe24 값을 우선하고, 둘 다 없을 때 국내 &gt; 대구광역시 &gt; 서구를 사용합니다.</div>
    ${missing.length ? `<div class="factory-cafe24-save-note">필수 기본정보가 비어 있습니다: ${escapeHtml(missing.join(', '))}</div>` : `<div class="factory-small" style="color:var(--text-m);line-height:1.5">상품명과 판매가는 기본정보 적용을 누르거나 최종 등록 실행 시 반영됩니다.</div>`}
  </div>`;
}

function factoryNormalizeFinalRegistrationBasicValue(fieldId, value) {
  const text = String(value ?? '').trim();
  if (['sale_price', 'consumer_price', 'purchase_price'].includes(fieldId)) {
    return text.replace(/,/g, '');
  }
  return text;
}

function factorySetFinalRegistrationBasicValue(factory, fieldId, value) {
  if (!fieldId) return;
  const normalizedValue = factoryNormalizeFinalRegistrationBasicValue(fieldId, value);
  if (!factory.product) factory.product = {};
  if (!factory.product.cafe24FinalRegistration || typeof factory.product.cafe24FinalRegistration !== 'object') factory.product.cafe24FinalRegistration = {};
  if (!factory.product.finalDb || typeof factory.product.finalDb !== 'object') factory.product.finalDb = {};
  if (fieldId === 'product_name') {
    factory.product.cafe24FinalRegistration.productName = normalizedValue;
  } else if (fieldId === 'sale_price') {
    factory.product.cafe24FinalRegistration.price = normalizedValue;
    factory.product.cafe24FinalRegistration.salePrice = normalizedValue;
  } else if (fieldId === 'consumer_price') {
    factory.product.cafe24FinalRegistration.retailPrice = normalizedValue;
    factory.product.cafe24FinalRegistration.consumerPrice = normalizedValue;
  } else if (fieldId === 'purchase_price') {
    factory.product.cafe24FinalRegistration.supplyPrice = normalizedValue;
    factory.product.cafe24FinalRegistration.purchasePrice = normalizedValue;
  }
  if (typeof factorySetDbFieldManualValue === 'function') {
    factorySetDbFieldManualValue(fieldId, normalizedValue, {
      enabled: true,
      force: true,
      deferFinalize: true,
      factory,
    });
  } else {
    if (!factory.product.dbFieldSettings || typeof factory.product.dbFieldSettings !== 'object') factory.product.dbFieldSettings = {};
    const setting = factory.product.dbFieldSettings[fieldId] ||= {};
    setting.enabled = true;
    setting.manualValue = normalizedValue;
    setting.manualTouched = true;
  }
  factory.product.finalDb[fieldId] = normalizedValue;
  if (factory.automation?.fieldDrafts && typeof factory.automation.fieldDrafts === 'object') {
    const { [fieldId]: _appliedDraft, ...remainingDrafts } = factory.automation.fieldDrafts;
    factory.automation.fieldDrafts = remainingDrafts;
  }
  if (typeof document !== 'undefined') {
    document.querySelectorAll('[data-factory-final-basic-field]').forEach(input => {
      if (input?.dataset?.factoryFinalBasicField !== fieldId) return;
      if (document.activeElement === input) return;
      input.value = normalizedValue;
    });
  }
}

function factoryApplyFinalRegistrationBasicInfoInputs(options = {}) {
  if (typeof document === 'undefined') return true;
  const container = options.container && typeof options.container.querySelectorAll === 'function'
    ? options.container
    : null;
  let inputs = [];
  if (container) {
    inputs = Array.from(container.querySelectorAll('[data-factory-final-basic-field]'));
  } else {
    const panels = Array.from(document.querySelectorAll('[data-factory-final-basic-info-panel]'))
      .filter(panel => panel.offsetParent !== null);
    const visiblePanel = panels[panels.length - 1] || null;
    inputs = visiblePanel
      ? Array.from(visiblePanel.querySelectorAll('[data-factory-final-basic-field]'))
      : Array.from(document.querySelectorAll('[data-factory-final-basic-field]'));
  }
  if (!inputs.length) return true;
  if (!options.factory) {
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/final-registration:apply-basic-info',
      'cafe24',
      draft => factoryApplyFinalRegistrationBasicInfoInputs({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  const values = {};
  inputs.forEach(input => {
    const fieldId = String(input.dataset.factoryFinalBasicField || '').trim();
    const value = factoryNormalizeFinalRegistrationBasicValue(fieldId, input.value);
    if (!fieldId) return;
    values[fieldId] = value;
    input.value = value;
    factorySetFinalRegistrationBasicValue(factory, fieldId, value);
  });
  factoryApplyFinalCafe24StatusToDb(factory);
  if (typeof factoryUpdateFinalDbFromFields === 'function') factoryUpdateFinalDbFromFields(factory);
  if (Object.prototype.hasOwnProperty.call(values, 'product_name')) {
    const name = values.product_name || '';
    if (!factory.product.finalDb || typeof factory.product.finalDb !== 'object') factory.product.finalDb = {};
    factory.product.finalDb.product_name = name;
  }
  factory.product.finalBasicInfoUpdatedAt = Date.now();
  if (!options.silent) {
    const name = values.product_name || factory.product.finalDb?.product_name || '미입력';
    const price = values.sale_price || factory.product.finalDb?.sale_price || '미입력';
    factoryOpenMarketLog(`최종 등록 기본정보 반영: 상품명 ${name} / 판매가 ${price}`, (values.product_name && values.sale_price) ? 'ok' : 'warn', factory);
  }
  return true;
}

function factoryFinalRegistrationDetailModel(factory) {
  const previewStatus = typeof factoryCurrentPreviewSectionStatus === 'function'
    ? factoryCurrentPreviewSectionStatus(state)
    : (() => {
        const requiredSections = typeof orderedSections === 'function' ? orderedSections() : [];
        const requiredIds = requiredSections.map(section => section.id).filter(Boolean);
        const generatedIds = requiredIds.filter(id => !!state.sectionContents?.[id]);
        return { generated: generatedIds.length, total: requiredIds.length };
      })();
  const total = previewStatus.total;
  const generated = previewStatus.generated;
  const detailAssets = typeof factoryUsableAssetsForStage === 'function'
    ? factoryUsableAssetsForStage('detail', factory).length
    : 0;
  const scoped = typeof factoryCafe24CurrentScopedDetailHtml === 'function'
    ? factoryCafe24CurrentScopedDetailHtml(factory)
    : { html: '' };
  const hasCurrentDetailHtml = !!String(scoped?.html || '').trim();
  const sourceBlocked = !!scoped?.blocked;
  const partialPreview = total > 0 && generated > 0 && generated < total;
  const partialGateAllowed = partialPreview && sourceBlocked && [
    'section-preview-incomplete',
    'section-scope-blocked',
  ].includes(String(scoped?.source || ''));
  const ok = hasCurrentDetailHtml && !sourceBlocked && (detailAssets > 0 || (total > 0 && generated >= total));
  const canProceed = (hasCurrentDetailHtml && !sourceBlocked) || partialGateAllowed;
  const label = total > 0
    ? `${generated}/${total}개 섹션 생성`
    : (detailAssets ? `${detailAssets}개 상세페이지 자산` : '상세페이지 조각 확인 필요');
  const warningParts = [];
  if (!ok && canProceed) warningParts.push(`상세페이지 섹션이 남아있습니다: ${label}`);
  if (sourceBlocked && scoped?.message) warningParts.push(scoped.message);
  if (canProceed && scoped?.productCheckWarning && scoped?.message) warningParts.push(scoped.message);
  const warning = warningParts.join(' ');
  const reason = canProceed
    ? ''
    : (sourceBlocked
      ? (scoped?.message || `상세페이지 HTML이 현재 상품/입력 이미지 기준과 맞지 않습니다: ${label}. 현재 미리보기 섹션을 다시 만들거나 상세페이지를 다시 생성해주세요.`)
      : `Cafe24에 전송할 현재 작업 상세페이지 HTML이 없습니다: ${label}`);
  if (!canProceed && factory?.stages?.detail && factory.stages.detail.status === 'done') {
    factory.stages.detail.status = 'blocked';
    factory.stages.detail.message = reason || `상세페이지 섹션 ${label} · 다시 생성 필요`;
  }
  return {
    ok,
    canProceed,
    generated,
    total,
    detailAssets,
    hasCurrentDetailHtml,
    detailHtmlSource: scoped?.source || '',
    sourceBlocked,
    productCheckWarning: !!scoped?.productCheckWarning,
    sourceMessage: scoped?.message || '',
    label,
    warning,
    reason,
  };
}

function factoryEnsureCurrentDetailHtmlAsset(factory) {
  if (typeof factoryCafe24CurrentScopedDetailHtml !== 'function') return { stored: false };
  let scoped = factoryCafe24CurrentScopedDetailHtml(factory);
  // 고른 A컷이 막혀 있으면 그것 때문에 새 A컷도 못 만든다. 이 함수의 일은 '지금 미리보기를
  // 남기는 것' 이므로, 막힌 A컷은 건너뛰고 현재 섹션으로 다시 만들어 본다. 그렇게 만든
  // 스냅샷이 깨끗하면 사람은 그것을 골라 빠져나갈 수 있다 — 실측 2026-08-29: 섹션을 전부
  // 다시 만들고도 오염된 A컷 하나 때문에 등록이 영영 풀리지 않았다.
  if (scoped && scoped.blocked && /^detail-(foreign-product|light-placeholder|admin-label)-blocked$/.test(String(scoped.source || ''))) {
    const rebuilt = factoryCafe24CurrentScopedDetailHtml(factory, { ignoreChosenDetail: true });
    if (rebuilt && !rebuilt.blocked && String(rebuilt.html || '').trim()) scoped = rebuilt;
  }
  let html = String(scoped?.html || '').trim();
  const previewStatus = typeof factoryCurrentPreviewSectionStatus === 'function'
    ? factoryCurrentPreviewSectionStatus(state)
    : null;
  const incompletePreview = !!(
    previewStatus &&
    previewStatus.generated > 0 &&
    previewStatus.generated < previewStatus.total
  );
  const imageRefs = typeof factoryRegistrationDetailImageRefs === 'function'
    ? factoryRegistrationDetailImageRefs(factory, { includeTransferSrc: true })
      .filter(ref => String(ref?.src || ref?.transferSrc || '').trim())
    : [];
  const renderedImageRefs = imageRefs.map(ref => {
    const transferSrc = String(ref?.transferSrc || '').trim();
    const source = String(ref?.src || transferSrc || '').trim();
    const label = String(ref?.label || '상세 이미지').trim() || '상세 이미지';
    const lightKey = transferSrc && typeof factoryRememberLightImage === 'function'
      ? factoryRememberLightImage(transferSrc)
      : '';
    const renderedSource = lightKey && typeof factoryLightImagePlaceholder === 'function'
      ? factoryLightImagePlaceholder(label)
      : source;
    const lightAttr = lightKey ? ` data-factory-light-image-key="${escAttr(lightKey)}"` : '';
    return {
      source,
      renderedSource,
      lightKey,
      label,
      html: `<img src="${escAttr(renderedSource)}"${lightAttr} alt="${escAttr(label)}" style="display:block;max-width:100%;height:auto;margin:0 auto">`,
    };
  });
  const wrapImageHtml = refs => refs.length
    ? `<div style="max-width:860px;margin:0 auto;background:#fff;text-align:center">${refs.map(ref => ref.html).join('')}</div>`
    : '';
  const imageHtml = wrapImageHtml(renderedImageRefs);
  if (html && renderedImageRefs.length) {
    const sectionLabels = new Set((typeof orderedSections === 'function'
      ? orderedSections({ includeHidden: true, includeAutoExcluded: true })
      : [])
      .map(section => String(section?.name || '').trim())
      .filter(Boolean));
    const labelCounts = renderedImageRefs.reduce((counts, ref) => {
      counts.set(ref.label, (counts.get(ref.label) || 0) + 1);
      return counts;
    }, new Map());
    const missingImageRefs = renderedImageRefs.filter(ref => {
      const markers = [
        ref.source,
        ref.source ? escAttr(ref.source) : '',
        ref.renderedSource,
        ref.renderedSource ? escAttr(ref.renderedSource) : '',
        ref.lightKey,
      ].filter(Boolean);
      if (labelCounts.get(ref.label) === 1 || sectionLabels.has(ref.label)) {
        const escapedLabel = escAttr(ref.label);
        markers.push(`alt="${escapedLabel}"`, `alt='${escapedLabel}'`);
      }
      return !markers.some(marker => html.includes(marker));
    });
    const missingImageHtml = wrapImageHtml(missingImageRefs);
    if (missingImageHtml) {
      const bodyClose = html.search(/<\/body\s*>/i);
      const htmlClose = html.search(/<\/html\s*>/i);
      const insertAt = bodyClose >= 0 ? bodyClose : htmlClose;
      html = insertAt >= 0
        ? `${html.slice(0, insertAt)}${missingImageHtml}${html.slice(insertAt)}`
        : `${html}${missingImageHtml}`;
      scoped = { ...scoped, html };
    }
  }
  const partialPreview = !!(
    incompletePreview &&
    ['section-preview-incomplete', 'section-scope-blocked'].includes(String(scoped?.source || ''))
  );
  if (!html && partialPreview && typeof buildExportHtml === 'function') {
    try {
      const rawHtml = buildExportHtml(
        state.analysis || factory.product?.analysis || {},
        state.sectionContents || {},
        state.sectionImages || {},
        state.detailImageBlocks || [],
      );
      const candidateHtml = typeof factoryCafe24StripDetailAdminLabels === 'function'
        ? factoryCafe24StripDetailAdminLabels(rawHtml)
        : String(rawHtml || '').trim();
      const safeCheck = typeof factoryCafe24DetailHtmlPreflight === 'function'
        ? factoryCafe24DetailHtmlPreflight(candidateHtml)
        : { ok: true };
      const foreignCheck = typeof factoryCafe24DetailForeignProductCheck === 'function'
        ? factoryCafe24DetailForeignProductCheck(candidateHtml, factory, state)
        : { ok: true };
      if (candidateHtml && /<img\b/i.test(candidateHtml) && safeCheck.ok && foreignCheck.ok) {
        scoped = {
          ...scoped,
          html: candidateHtml,
          source: 'current-section-export-partial',
          blocked: false,
          partialExport: true,
          sectionCount: previewStatus.generated,
          message: `${previewStatus.generated}/${previewStatus.total}개 섹션과 현재 이미지 자산으로 상세설명을 구성했습니다.`,
        };
        html = candidateHtml;
      }
    } catch(_) {}
  }
  if (!html && partialPreview && typeof factoryCafe24BuildMarketSafeDetailHtml === 'function') {
    const fallbackHtml = factoryCafe24BuildMarketSafeDetailHtml(factory.product?.finalDb || {}, factory);
    if (fallbackHtml) {
      scoped = {
        ...scoped,
        html: `${fallbackHtml}${imageHtml}`,
        source: 'partial-safe-fallback',
        blocked: false,
        partialFallback: true,
        sectionCount: previewStatus.generated,
        message: `${previewStatus.generated}/${previewStatus.total}개 섹션 상태로 현재 상품 기준 안전 상세설명을 사용합니다.`,
      };
      html = `${fallbackHtml}${imageHtml}`;
    }
  }
  if (!html || !['current-section-export', 'current-section-export-partial', 'partial-safe-fallback'].includes(String(scoped?.source || ''))) {
    // 새 자산을 만들지 않는 길(예: 이미 있는 보존본을 그대로 쓰는 detail-asset-richer-current)
    // 이라도 본문은 보관함에 남겨 둔다. 이 본문은 24000자를 넘으면 작업 상태에서 지워지고,
    // 그러면 그 변형이 무엇이었는지 뒤에 확인할 길이 사라진다.
    if (scoped?.asset && typeof archiveDetailVariantHtml === 'function') {
      void archiveDetailVariantHtml(scoped.asset, html);
    }
    return { ...scoped, stored: false };
  }
  const assets = Array.isArray(factory.assets) ? factory.assets : [];
  const existing = assets.find(asset =>
    asset &&
    !asset.rejected &&
    asset.stageId === 'detail' &&
    asset.type === 'html' &&
    String(asset.html || '').trim() === html
  );
  if (existing) {
    existing.used = true;
    existing.metadata = { ...(existing.metadata || {}), preservedFromCurrentPreviewAt: Date.now() };
    if (factory.stages?.detail) {
      factory.stages.detail.selectedAssetIds = uniqueApiKeys([...(factory.stages.detail.selectedAssetIds || []), existing.id]);
    }
    // 이 본문은 24000자를 넘으면 작업 상태에서 지워진다. 지워지기 전에 보관함에 사본을 남긴다.
    if (typeof archiveDetailVariantHtml === 'function') void archiveDetailVariantHtml(existing, html);
    return { ...scoped, asset: existing, stored: false, reused: true };
  }
  if (!factory.stages) factory.stages = {};
  if (!factory.stages.detail) factory.stages.detail = { selectedAssetIds: [] };
  const detailRunId = factoryCurrentStageRunId('detail', factory) || uid('detail_snapshot');
  factory.stages.detail.currentRunId = detailRunId;
  factory.stages.detail.latestGenerationRunId = detailRunId;
  const asset = factoryRegisterAsset('detail', html, {
    factory,
    type: 'html',
    title: `${deriveProjectName()} 현재 미리보기 상세페이지 HTML`,
    prompt: '최종 등록 직전 현재 미리보기 섹션 HTML 자동 보존',
    currentRunId: detailRunId,
    generationRunId: detailRunId,
    enforceCurrentJob: true,
    metadata: {
      source: '현재 미리보기 섹션',
      sectionCount: scoped.sectionCount || 0,
      productCheckWarning: !!scoped.productCheckWarning,
      preservedAt: Date.now(),
    },
    used: true,
  });
  if (asset && typeof archiveDetailVariantHtml === 'function') void archiveDetailVariantHtml(asset, html);
  return { ...scoped, asset, stored: !!asset };
}

function factoryPreserveCurrentDetailHtmlBeforeSectionReset(reason = '섹션 초기화', options = {}) {
  if (!options.factory) {
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/runtime:preserveDetailHtml',
      'factory-assets',
      draft => factoryPreserveCurrentDetailHtmlBeforeSectionReset(reason, {
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  try {
    const factory = options.factory;
    const preserved = factoryEnsureCurrentDetailHtmlAsset(factory);
    if (preserved?.stored) {
      factoryLog(`섹션을 비우기 전 현재 상세페이지 HTML을 보존했습니다: ${reason}`, 'ok', factory);
    } else if (preserved?.reused) {
      factoryLog(`섹션을 비우기 전 이미 보존된 상세페이지 HTML을 유지합니다: ${reason}`, 'info', factory);
    }
    return preserved || null;
  } catch(e) {
    console.warn('현재 상세페이지 HTML 보존 실패:', e);
    return null;
  }
}

function factoryRegistrationImageRef(src = '', label = '이미지', source = '', options = {}) {
  const image = typeof factoryCoerceImageSrc === 'function'
    ? factoryCoerceImageSrc(src)
    : (typeof displayableImageSrc === 'function' ? displayableImageSrc(src) : String(src || ''));
  if (!image) return null;
  const tooLarge = /^data:image\//i.test(image) && image.length > 180000;
  return {
    label: String(label || '이미지').trim(),
    source: String(source || '').trim(),
    src: tooLarge ? '' : image,
    ...(tooLarge && options.includeTransferSrc === true ? { transferSrc: image } : {}),
    hasImage: true,
    storedLarge: tooLarge,
  };
}

function factoryRegistrationCollectImageRefsFromValue(value, label = '상세이미지', source = '', out = [], seen = new WeakSet(), options = {}) {
  const limit = 24;
  if (out.length >= limit || value == null) return out;
  if (typeof value === 'string') {
    const ref = factoryRegistrationImageRef(value, label, source, options);
    if (ref) out.push(ref);
    return out;
  }
  if (Array.isArray(value)) {
    value.slice(0, limit).forEach((item, index) => {
      factoryRegistrationCollectImageRefsFromValue(item, `${label} ${index + 1}`, source, out, seen, options);
    });
    return out;
  }
  if (typeof value !== 'object') return out;
  if (seen.has(value)) return out;
  seen.add(value);
  const preferredKeys = ['image', 'dataUrl', 'preview', 'imageUrl', 'url', 'src', 'thumbnail', 'thumb', 'result'];
  preferredKeys.forEach(key => {
    if (out.length >= limit || value[key] == null) return;
    factoryRegistrationCollectImageRefsFromValue(value[key], value.label || value.title || label, source || key, out, seen, options);
  });
  return out;
}

function factoryRegistrationHeroImageRef(factory = factoryRuntimeReadFactory()) {
  const selected = typeof factorySelectedUsableAssets === 'function' ? factorySelectedUsableAssets('hero', factory) : [];
  const usable = typeof factoryUsableAssetsForStage === 'function' ? factoryUsableAssetsForStage('hero', factory) : [];
  const seen = new Set();
  const heroAsset = [...selected, ...usable].find(asset => {
    const id = asset?.id || asset?.title || '';
    if (!asset || seen.has(id)) return false;
    seen.add(id);
    return !!(typeof factoryAssetDisplayImage === 'function' ? factoryAssetDisplayImage(asset) : asset.image);
  });
  if (heroAsset) {
    return factoryRegistrationImageRef(
      typeof factoryAssetDisplayImage === 'function' ? factoryAssetDisplayImage(heroAsset) : heroAsset.image,
      heroAsset.title || '사용 대표이미지',
      `asset:${heroAsset.stageId || 'hero'}`
    );
  }
  const productImage = typeof factoryProductPreview === 'function' ? factoryProductPreview(factory) : '';
  return factoryRegistrationImageRef(productImage, '제품 기준 이미지', 'product');
}

function factoryRegistrationDetailImageRefs(factory = factoryRuntimeReadFactory(), options = {}) {
  const limit = 24;
  const refs = [];
  const add = (src, label, source) => {
    const ref = factoryRegistrationImageRef(src, label, source, options);
    if (!ref) return;
    const key = ref.src || `${ref.label}|${ref.source}|${ref.storedLarge}`;
    if (refs.some(item => (item.src || `${item.label}|${item.source}|${item.storedLarge}`) === key)) return;
    refs.push(ref);
  };
  const sections = typeof orderedSections === 'function' ? orderedSections({ includeHidden: true, includeAutoExcluded: true }) : [];
  sections.forEach(section => {
    if (refs.length >= limit) return;
    const image = state.sectionImages?.[section.id];
    if (image) add(image, section.name || section.id || '상세 섹션', `section:${section.id || ''}`);
    const variants = Array.isArray(state.sectionVariants?.[section.id]) ? state.sectionVariants[section.id] : [];
    const currentVariant = variants.find(variant => variant?.id && variant.id === state.currentSectionVariantIds?.[section.id]);
    const variantImage = currentVariant?.image || variants.find(variant => variant?.image)?.image || '';
    if (variantImage) add(variantImage, section.name || section.id || '상세 섹션', `variant:${section.id || ''}`);
    const contentRefs = factoryRegistrationCollectImageRefsFromValue(
      state.sectionContents?.[section.id],
      section.name || section.id || '상세 섹션',
      `content:${section.id || ''}`,
      [],
      new WeakSet(),
      options,
    );
    contentRefs.forEach(ref => {
      if (refs.length >= limit) return;
      const key = ref.src || `${ref.label}|${ref.source}|${ref.storedLarge}`;
      if (!refs.some(item => (item.src || `${item.label}|${item.source}|${item.storedLarge}`) === key)) refs.push(ref);
    });
  });
  (Array.isArray(state.detailImageBlocks) ? state.detailImageBlocks : []).forEach(block => {
    if (refs.length >= limit) return;
    add(block?.dataUrl, block?.label || '추가 상세 이미지', `detailBlock:${block?.afterSectionId || ''}`);
  });
  const detailAssets = [
    ...(typeof factorySelectedUsableAssets === 'function' ? factorySelectedUsableAssets('detail', factory) : []),
    ...(typeof factoryUsableAssetsForStage === 'function' ? factoryUsableAssetsForStage('detail', factory) : []),
  ];
  detailAssets.forEach(asset => {
    if (refs.length >= limit) return;
    const image = typeof factoryAssetDisplayImage === 'function' ? factoryAssetDisplayImage(asset) : asset?.image;
    add(image, asset?.title || '상세페이지 자산', `asset:${asset?.stageId || 'detail'}`);
  });
  return refs.slice(0, limit);
}

function factoryRegistrationFindRelatedProject(productName = '', productNo = '') {
  const projects = Array.isArray(state.projects) ? state.projects : [];
  const productKey = typeof factoryNormalizeIdentityText === 'function' ? factoryNormalizeIdentityText(productName) : String(productName || '').trim().toLowerCase();
  const no = String(productNo || '').trim();
  const scored = projects.map(project => {
    const summary = project.factorySummary || {};
    const text = [
      project.name,
      summary.product?.productName,
      summary.dbName,
      summary.cafe24Name,
      summary.finalRegistrationStatus,
    ].join(' ');
    const key = typeof factoryNormalizeIdentityText === 'function' ? factoryNormalizeIdentityText(text) : text.toLowerCase();
    let score = 0;
    if (state.currentProjectId && project.id === state.currentProjectId) score += 100;
    if (productKey && key.includes(productKey)) score += 40;
    if (no && String(summary.finalRegistrationStatus || '').includes(no)) score += 20;
    if (summary.finalRegistrationStatus) score += 5;
    score += Math.min(10, Math.max(0, (Number(project.updatedAt || 0) || 0) / 1000000000000));
    return { project, score };
  }).filter(item => item.score >= 40);
  scored.sort((a, b) => b.score - a.score);
  return scored[0]?.project || null;
}

function factoryRegistrationProjectStorageRef(productName = '', productNo = '') {
  const fallbackProject = factoryRegistrationFindRelatedProject(productName, productNo);
  const projectId = String(state.currentProjectId || fallbackProject?.id || '').trim();
  if (!projectId) {
    return {
      label: `로컬 IndexedDB ${WORKSPACE_DB.name} / 마지막 작업`,
      database: WORKSPACE_DB.name,
      store: 'lastWork',
      key: 'current',
      projectId: '',
    };
  }
  return {
    label: `로컬 IndexedDB ${WORKSPACE_DB.name} / projects / ${projectId}`,
    database: WORKSPACE_DB.name,
    store: WORKSPACE_DB.projects,
    key: projectId,
    projectId,
  };
}

function factoryBuildRegistrationHistoryRecord(options = {}) {
  const factory = options.factory || factoryRuntimeReadFactory();
  const settings = options.settings || factoryFinalRegistrationSettings(factory);
  const sync = factoryEnsureOpenMarketSync(factory);
  const targetInfo = typeof factoryCafe24TargetInfo === 'function' ? factoryCafe24TargetInfo(factory) : {};
  const channels = settings.includeOpenMarket ? factoryOpenMarketSelectedChannels(factory) : [];
  const detailModel = factoryFinalRegistrationDetailModel(factory);
  const productName = String(
    (typeof factoryAuthoritativeProductName === 'function' ? factoryAuthoritativeProductName(factory, [
      factory.product?.productName,
      state.productName,
      factory.product?.finalDb?.product_name,
      factory.product?.confirmedDb?.product_name,
    ]) : '') ||
    factory.product?.userProductName ||
    factory.product?.productName ||
    state.productName ||
    factory.product?.finalDb?.product_name ||
    factory.product?.confirmedDb?.product_name ||
    deriveProjectName()
  ).trim();
  const productNo = String(
    options.productNo ||
    targetInfo.productNo ||
    factory.product?.finalDb?.product_no ||
    factory.product?.finalDb?.cafe24_product_no ||
    ''
  ).trim();
  const storageRef = factoryRegistrationProjectStorageRef(productName, productNo);
  const project = (Array.isArray(state.projects) ? state.projects : [])
    .find(item => item.id === (storageRef.projectId || state.currentProjectId));
  return {
    id: options.id || uid('factory_registration'),
    productName: productName || '등록 상품',
    productNo,
    registeredAt: options.registeredAt || Date.now(),
    target: settings.target,
    targetLabel: settings.targetLabel,
    cafe24Display: settings.display,
    cafe24DisplayLabel: settings.displayLabel,
    cafe24Selling: settings.selling,
    cafe24SellingLabel: settings.sellingLabel,
    openMarketStatus: settings.includeOpenMarket ? '오픈마켓 흐름 시작' : '오픈마켓 진행 안 함',
    openMarketChannels: channels.map(channel => channel.label || channel.id).filter(Boolean),
    finalStatus: options.finalStatus || sync.finalRegistrationStatus || '',
    projectId: storageRef.projectId || state.currentProjectId || '',
    projectName: project?.name || state.currentProjectName || deriveProjectName(),
    storageLabel: storageRef.label,
    storageRef,
    heroImage: factoryRegistrationHeroImageRef(factory),
    detailImages: factoryRegistrationDetailImageRefs(factory),
    detailSectionCount: detailModel.generated,
    detailAssetCount: detailModel.detailAssets,
    savedProjectUpdatedAt: project?.updatedAt || null,
    registrationReceipt: factory.product?.cafe24RegistrationReceipt || null,
    source: options.source || 'final-registration',
  };
}

async function factoryRecordFinalRegistrationHistory(options = {}) {
  const record = factoryBuildRegistrationHistoryRecord(options);
  const publicationReceipt = factoryApplyCafe24PublicationReceipt(
    options.factory || factoryRuntimeReadFactory(),
    record,
  );
  const saved = await prependFactoryRegistrationHistoryRecord({
    ...record,
    sourceWorkfileName: publicationReceipt.sourceWorkfileName,
    publicationReceipt,
  }, { render: options.render !== false });
  if (typeof factoryLog === 'function' && saved) {
    factoryLog(`등록 이력 저장 완료: ${saved.productName}${saved.productNo ? ` #${saved.productNo}` : ''}`, 'ok', options.factory);
  }
  return saved;
}

async function factoryResumeLatestExactCafe24Product(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/cafe24:resume-exact-product',
      'cafe24',
      draft => factoryResumeLatestExactCafe24Product({ ...options, factory: draft, render: false }),
    );
    await saveLastWorkNow({ sync: false, factory: receipt.snapshot.factory });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  if (typeof window.ensureCafe24Modules === 'function') await window.ensureCafe24Modules();
  const factory = options.factory;
  const basicInfo = factoryFinalRegistrationBasicInfoModel(factory);
  const productName = String(basicInfo.productName || '').trim();
  if (!productName) {
    factoryOpenMarketLog('동일명 Cafe24 상품 조회 중단: 상품명이 비어 있습니다.', 'error', factory);
    return null;
  }
  factory.product.cafe24ApiStatus = `동일명 최신 Cafe24 상품 조회 중: ${productName}`;
  factoryOpenMarketLog(factory.product.cafe24ApiStatus, 'info', factory);
  try {
    const product = await factoryFindLiveCafe24ProductByExactName(productName, CAFE24_CONTROL_API.defaultMallId);
    const attached = factoryAttachCafe24ProductAsCurrentTarget(product, `final-resume:${productName}`, factory);
    if (!attached?.productNo) throw new Error(`${productName} 상품을 Cafe24에서 찾지 못했습니다.`);
    const sync = factoryEnsureOpenMarketSync(factory);
    sync.cafe24RegistrationMode = 'update';
    sync.cafe24RegistrationModeUserTouched = true;
    factory.product.cafe24ApiStatus = `동일명 최신 Cafe24 상품 이어서 수정: #${attached.productNo} ${attached.productName || productName}`;
    factoryOpenMarketLog(factory.product.cafe24ApiStatus, 'ok', factory);
    return attached;
  } catch (error) {
    factory.product.cafe24ApiStatus = `동일명 최신 Cafe24 상품 조회 실패: ${error.message || error}`;
    factoryOpenMarketLog(factory.product.cafe24ApiStatus, 'error', factory);
    return null;
  }
}

function factoryCafe24BuildRegistrationReceiptPreflight(factory = factoryRuntimeReadFactory(), options = {}) {
  const basicInfo = options.basicInfo || factoryFinalRegistrationBasicInfoModel(factory);
  const settings = options.settings || factoryFinalRegistrationSettings(factory);
  const optionPlan = typeof factoryBuildCafe24OptionSyncPlan === 'function'
    ? factoryBuildCafe24OptionSyncPlan(factory, factory.product?.finalDb || {}, null, {
      forceInventory: true,
      forceInventoryQuantity: options.forceInventoryQuantity || '',
    })
    : { optionName: '', optionValues: [] };
  const optionValues = Array.isArray(optionPlan.optionValues) ? optionPlan.optionValues.map(value => String(value || '').trim()).filter(Boolean) : [];
  const variants = typeof factoryCafe24VariantRows === 'function' ? factoryCafe24VariantRows(factory, optionValues) : [];
  const inventoryByOption = {};
  variants.forEach((row, index) => {
    const key = String(typeof factoryCafe24VariantNormalizedOptionKey === 'function'
      ? factoryCafe24VariantNormalizedOptionKey(row)
      : (row?.option_value || row?.option_text || index + 1)).trim() || String(index + 1);
    const inventory = typeof factoryCafe24InventoryPayload === 'function' ? factoryCafe24InventoryPayload(row) : row;
    inventoryByOption[key] = Object.freeze({
      quantity: String(options.forceInventoryQuantity || inventory?.quantity || '').trim(),
      useInventory: String(inventory?.use_inventory ?? row?.use_inventory ?? '').trim().toUpperCase(),
    });
  });
  const review = typeof factoryAutomationReviewSummary === 'function'
    ? factoryAutomationReviewSummary(factory, typeof factoryAutomationCounts === 'function' ? factoryAutomationCounts(factory) : {})
    : { fields: [] };
  const requiredValues = Object.fromEntries((review.fields || [])
    .filter(field => field?.required)
    .map(field => [String(field.id || field.label || '').trim(), String(field.value ?? '').trim()]));
  const imagePayload = typeof factoryCafe24ImagePayload === 'function' ? factoryCafe24ImagePayload(factory) : {};
  const imageSlots = typeof FACTORY_CAFE24_IMAGE_SLOTS !== 'undefined' && Array.isArray(FACTORY_CAFE24_IMAGE_SLOTS)
    ? FACTORY_CAFE24_IMAGE_SLOTS
    : [];
  const detailHtml = String(options.detailHtml || '').trim();
  return Object.freeze({
    schema: 'kuasangse.cafe24-registration-receipt',
    version: 1,
    status: 'preflight',
    capturedAt: Date.now(),
    mode: String(options.mode || settings.cafe24RegistrationMode || '').trim(),
    productNo: String(options.productNo || '').trim(),
    productName: String(basicInfo.productName || '').trim(),
    price: String(basicInfo.salePrice || '').trim(),
    retailPrice: String(basicInfo.consumerPrice || '').trim(),
    supplyPrice: String(basicInfo.supplyPrice || '').trim(),
    display: String(settings.display || '').trim().toUpperCase(),
    selling: String(settings.selling || '').trim().toUpperCase(),
    representativeImageCount: Number.isFinite(Number(options.representativeImageCount))
      ? Number(options.representativeImageCount)
      : imageSlots.filter(slot => imagePayload?.[slot.key]).length,
    detailImageCount: Number.isFinite(Number(options.detailImageCount))
      ? Number(options.detailImageCount)
      : typeof factoryCafe24DetailImageSrcValues === 'function'
        ? factoryCafe24DetailImageSrcValues(detailHtml).length
        : (detailHtml.match(/<img\b[^>]*\bsrc\s*=/gi) || []).length,
    optionName: String(optionPlan.optionName || '').trim(),
    optionValues: Object.freeze(optionValues),
    variantCount: variants.length,
    inventoryByOption: Object.freeze(inventoryByOption),
    requiredValues: Object.freeze(requiredValues),
  });
}

function factoryCafe24CompareRegistrationReadback(preflight = {}, detail = null, saveVerification = null) {
  const raw = typeof parseCafe24Raw === 'function' ? (parseCafe24Raw(detail) || detail?.raw || detail || {}) : (detail?.raw || detail || {});
  const optionSummary = typeof factoryOpenMarketOptionSummary === 'function'
    ? factoryOpenMarketOptionSummary(null, raw)
    : { values: [], variants: Array.isArray(raw.variants) ? raw.variants : [] };
  const actualOptionValues = Array.isArray(optionSummary.values) ? optionSummary.values.map(value => String(value || '').trim()).filter(Boolean) : [];
  const actualVariants = Array.isArray(optionSummary.variants) ? optionSummary.variants : [];
  const actualInventory = {};
  actualVariants.forEach((row, index) => {
    const key = String(typeof factoryCafe24VariantNormalizedOptionKey === 'function'
      ? factoryCafe24VariantNormalizedOptionKey(row)
      : (row?.option_value || row?.option_text || index + 1)).trim() || String(index + 1);
    const inventory = typeof factoryCafe24InventoryPayload === 'function' ? factoryCafe24InventoryPayload(row) : row;
    actualInventory[key] = Object.freeze({
      quantity: String(inventory?.quantity ?? row?.quantity ?? '').trim(),
      useInventory: String(inventory?.use_inventory ?? row?.use_inventory ?? '').trim().toUpperCase(),
    });
  });
  const roughlyEqual = (left, right) => typeof factoryCafe24ValuesRoughlyEqual === 'function'
    ? factoryCafe24ValuesRoughlyEqual(left, right)
    : String(left ?? '').trim() === String(right ?? '').trim();
  const dimensionTokens = value => [...String(value ?? '').matchAll(/(\d+(?:\.\d+)?)\s*(mm|cm|㎜|㎝)?/gi)]
    .map(match => {
      const unit = String(match[2] || '').toLowerCase().replace('㎜', 'mm').replace('㎝', 'cm');
      return String(Number((Number(match[1]) * (unit === 'cm' ? 10 : 1)).toFixed(6)));
    });
  const dimensionsEqual = (left, right) => {
    const expected = dimensionTokens(left);
    const actual = dimensionTokens(right);
    if (!expected.length || !actual.length) return roughlyEqual(left, right);
    return expected.length === actual.length && expected.every((value, index) => value === actual[index]);
  };
  const expectedOptionValues = Array.isArray(preflight.optionValues) ? preflight.optionValues : [];
  const expectedInventory = preflight.inventoryByOption && typeof preflight.inventoryByOption === 'object'
    ? preflight.inventoryByOption
    : {};
  const expectedRequiredValues = preflight.requiredValues && typeof preflight.requiredValues === 'object'
    ? preflight.requiredValues
    : {};
  const additionalInformation = typeof factoryCafe24AdditionalInformationPayload === 'function'
    ? factoryCafe24AdditionalInformationPayload(raw.additional_information)
    : (Array.isArray(raw.additional_information) ? raw.additional_information : []);
  const actualSize = String(additionalInformation.find(row => /^(사이즈|규격|크기)$/i.test(String(row?.name || '').trim()))?.value
    || raw.size || raw.dimensions || raw.product_size || '').trim();
  const actualSizeTokens = dimensionTokens(actualSize);
  const actualMaterial = String(raw.product_material || raw.material || raw.cloth_fabric || '').trim();
  const requiredValuesMatched = [
    !expectedRequiredValues.size || dimensionsEqual(expectedRequiredValues.size, actualSize),
    !expectedRequiredValues.width_mm || dimensionsEqual(expectedRequiredValues.width_mm, actualSizeTokens[0] || ''),
    !expectedRequiredValues.depth_mm || dimensionsEqual(expectedRequiredValues.depth_mm, actualSizeTokens[1] || ''),
    !expectedRequiredValues.material || roughlyEqual(expectedRequiredValues.material, actualMaterial),
  ].every(Boolean);
  const actualRepresentativeImageCount = [raw.detail_image, raw.list_image, raw.small_image, raw.tiny_image]
    .filter(value => String(value || '').trim()).length;
  const actualDetailHtml = String(raw.description || raw.mobile_description || '').trim();
  const actualDetailImageCount = typeof factoryCafe24DetailImageSrcValues === 'function'
    ? factoryCafe24DetailImageSrcValues(actualDetailHtml).length
    : (actualDetailHtml.match(/<img\b[^>]*\bsrc\s*=/gi) || []).length;
  const inventoryMatched = Object.entries(expectedInventory).every(([key, expected]) => {
    const actual = actualInventory[key];
    return !!actual
      && (!expected.quantity || roughlyEqual(expected.quantity, actual.quantity))
      && (!expected.useInventory || expected.useInventory === actual.useInventory);
  });
  const checks = [
    ['상품명', roughlyEqual(preflight.productName, raw.product_name)],
    ['판매가', roughlyEqual(preflight.price, raw.price)],
    ['소비자가', !preflight.retailPrice || roughlyEqual(preflight.retailPrice, raw.retail_price)],
    ['공급가', !preflight.supplyPrice || roughlyEqual(preflight.supplyPrice, raw.supply_price)],
    ['진열 상태', !preflight.display || preflight.display === String(raw.display || '').trim().toUpperCase()],
    ['판매 상태', !preflight.selling || preflight.selling === String(raw.selling || '').trim().toUpperCase()],
    ['대표이미지', !Number(preflight.representativeImageCount || 0) || actualRepresentativeImageCount > 0],
    ['상세이미지', !Number(preflight.detailImageCount || 0) || actualDetailImageCount >= Number(preflight.detailImageCount || 0)],
    ['옵션값', expectedOptionValues.length === actualOptionValues.length && expectedOptionValues.every((value, index) => value === actualOptionValues[index])],
    ['품목 수', Number(preflight.variantCount || 0) === actualVariants.length],
    ['옵션별 재고', inventoryMatched],
    ['필수값/사이즈', requiredValuesMatched],
    ['기본/필수값 payload', !saveVerification || (saveVerification.ok === true && (!saveVerification.productNo || String(saveVerification.productNo) === String(raw.product_no || '')))],
  ].map(([label, matched]) => Object.freeze({ label, matched: !!matched }));
  const mismatches = checks.filter(check => !check.matched).map(check => check.label);
  return Object.freeze({
    productNo: String(raw.product_no || '').trim(),
    checkedAt: Date.now(),
    allMatched: mismatches.length === 0,
    mismatches: Object.freeze(mismatches),
    checks: Object.freeze(checks),
    readback: Object.freeze({
      productName: String(raw.product_name || '').trim(),
      price: String(raw.price || '').trim(),
      retailPrice: String(raw.retail_price || '').trim(),
      supplyPrice: String(raw.supply_price || '').trim(),
      display: String(raw.display || '').trim().toUpperCase(),
      selling: String(raw.selling || '').trim().toUpperCase(),
      representativeImageCount: actualRepresentativeImageCount,
      detailImageCount: actualDetailImageCount,
      optionValues: Object.freeze(actualOptionValues),
      variantCount: actualVariants.length,
      inventoryByOption: Object.freeze(actualInventory),
      requiredValues: Object.freeze({
        size: actualSize,
        width_mm: actualSizeTokens[0] || '',
        depth_mm: actualSizeTokens[1] || '',
        material: actualMaterial,
      }),
    }),
  });
}

// Cafe24 가 등록 직후에는 아직 채우지 않는 값들. 이 항목만 어긋나 있으면 잠시 뒤 다시 읽는다.
const CAFE24_READBACK_SETTLING_LABELS = new Set([
  '옵션별 재고', '대표이미지', '상세이미지',
  // 저장 에코도 같은 이유로 늦게 채워진다. 이 항목만 목록에서 빠져 있으면 다른 항목이
  // 아직 반영 중이어도 재시도가 한 번도 돌지 않고 즉시 실패로 끝난다. 실측: 방울수저집
  // #3021 은 스토어에 분류·옵션·이미지가 모두 정상인데 이 한 줄 때문에 실패로 기록됐다.
  '기본/필수값 payload',
]);
// 저장 에코를 기다릴 때와 같은 폭(약 30초)으로 본다. 8초로는 이미지 반영을 못 기다린다.
const CAFE24_READBACK_SETTLE_ATTEMPTS = 20;
const CAFE24_READBACK_SETTLE_DELAY_MS = 1500;

// factory 는 반드시 소유한 draft 여야 한다. 커밋된 스냅샷은 깊게 동결돼 있고
// app-core-05 는 non-strict 라, 셀렉터 기본값을 쓰면 아래 영수증 대입이
// 예외 없이 조용히 버려진다.
function factoryCafe24RefreshSaveVerificationFromDetail(record, detail, productNo) {
  // 보낸 payload 를 남겨 둔 기록만 다시 대조할 수 있다. 없으면 원래 기록을 그대로 쓴다.
  if (!record || typeof record !== 'object') return record;
  if (String(record.productNo || '') !== String(productNo || '')) return record;
  const sent = record.sentPayload && typeof record.sentPayload === 'object' ? record.sentPayload : null;
  if (!sent || !Object.keys(sent).length) return record;
  if (typeof factoryVerifyCafe24ProductEcho !== 'function'
    || typeof factoryCafe24SaveVerificationRecord !== 'function') return record;
  const raw = typeof parseCafe24Raw === 'function'
    ? (parseCafe24Raw(detail) || detail?.raw || detail)
    : (detail?.raw || detail);
  if (!raw) return record;
  return factoryCafe24SaveVerificationRecord({
    type: record.type || 'update',
    productNo,
    product: sent,
    verification: factoryVerifyCafe24ProductEcho(sent, raw),
    rollback: record.rollback || null,
  });
}

async function factoryCafe24FinalizeRegistrationReceipt(factory, options = {}) {
  const preflight = options.preflight || factory.product?.cafe24RegistrationReceipt;
  if (!preflight) return null;
  const target = typeof factoryCafe24TargetInfo === 'function' ? factoryCafe24TargetInfo(factory) : {};
  const productNo = String(options.productNo || target?.productNo || preflight.productNo || factory.product?.finalDb?.product_no || '').trim();
  if (!productNo) throw new Error('Cafe24 등록 후 read-back 검증 실패: 상품번호가 없습니다.');
  const mallId = target?.mallId || CAFE24_CONTROL_API.defaultMallId;
  let detail = null;
  let comparison = null;
  for (let attempt = 0; attempt < CAFE24_READBACK_SETTLE_ATTEMPTS; attempt += 1) {
    detail = await fetchCafe24ProductFullByNo(productNo, mallId);
    if (typeof factoryAttachCafe24InventoryEchoes === 'function') detail = await factoryAttachCafe24InventoryEchoes(detail, mallId);
    // 저장 직후 찍은 에코는 Cafe24 가 나중에 채우는 분류·옵션을 불일치로 남긴다. 방금 읽은
    // 상세로 다시 대조해야, 이미 반영된 값을 옛 스냅샷 때문에 실패로 적지 않는다.
    const refreshedSaveVerification = factoryCafe24RefreshSaveVerificationFromDetail(
      factory.product?.cafe24LastSaveVerification || null,
      detail,
      productNo,
    );
    if (refreshedSaveVerification) factory.product.cafe24LastSaveVerification = refreshedSaveVerification;
    comparison = factoryCafe24CompareRegistrationReadback(preflight, detail, refreshedSaveVerification);
    // Cafe24 는 등록 직후 이미지와 재고를 아직 채우지 않은 채로 응답한다. 실측: 02:51 등록
    // 시점에는 detail/list/small/tiny 가 모두 비어 대표이미지가 불일치였고, 같은 상품을
    // 나중에 다시 읽으니 네 칸 모두 채워져 전부 일치했다. 재고에만 재시도를 걸어 두면
    // 이미지 불일치는 영영 풀리지 않고, 실제로는 올라간 상품이 실패로 기록된다.
    const settlingPending = !comparison.allMatched
      && comparison.mismatches.length > 0
      && comparison.mismatches.every(label => CAFE24_READBACK_SETTLING_LABELS.has(label));
    if (!settlingPending || attempt === CAFE24_READBACK_SETTLE_ATTEMPTS - 1) break;
    await factoryCafe24Delay(CAFE24_READBACK_SETTLE_DELAY_MS);
  }
  const receipt = Object.freeze({
    ...preflight,
    status: comparison.allMatched ? 'verified' : 'mismatch',
    productNo: comparison.productNo || productNo,
    verifiedAt: comparison.checkedAt,
    comparisons: comparison.checks,
    mismatches: comparison.mismatches,
    readback: comparison.readback,
  });
  factory.product.cafe24RegistrationReceipt = receipt;
  if (!comparison.allMatched) throw new Error(`Cafe24 등록 후 A+B read-back 불일치: ${comparison.mismatches.join(', ')}`);
  return receipt;
}

function renderFactoryCafe24RegistrationReceipt(factory = factoryRuntimeReadFactory()) {
  const storedReceipt = factory.product?.cafe24RegistrationReceipt;
  const currentDetail = !storedReceipt && typeof factoryCafe24CurrentScopedDetailHtml === 'function'
    ? factoryCafe24CurrentScopedDetailHtml(factory)
    : null;
  const receipt = storedReceipt || factoryCafe24BuildRegistrationReceiptPreflight(factory, {
    mode: factoryFinalRegistrationSettings(factory).cafe24RegistrationMode,
    productNo: factoryCafe24TargetInfo(factory)?.productNo || '',
    detailHtml: currentDetail?.html || '',
    representativeImageCount: typeof factoryRegistrationHeroImageRef === 'function' && factoryRegistrationHeroImageRef(factory) ? 1 : 0,
    detailImageCount: factoryFinalRegistrationDetailModel(factory).generated || 0,
  });
  const verified = receipt.status === 'verified';
  const failed = receipt.status === 'mismatch' || receipt.status === 'failed';
  const tone = verified ? 'var(--ok)' : failed ? 'var(--danger)' : 'var(--warn)';
  const label = verified ? 'Cafe24 read-back 일치' : failed ? 'Cafe24 read-back 확인 필요' : storedReceipt ? 'Cafe24 전송 전 A 영수증 고정' : 'Cafe24 등록 전 A 영수증 준비';
  const mismatchText = Array.isArray(receipt.mismatches) && receipt.mismatches.length
    ? ` · 불일치 ${receipt.mismatches.join(', ')}`
    : '';
  return `<div data-factory-cafe24-registration-receipt style="margin-top:10px;border:1px solid color-mix(in srgb,${tone} 42%,transparent);background:rgba(15,23,42,.34);border-radius:9px;padding:9px">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
      <div class="factory-small" style="color:${tone};font-weight:950">${escapeHtml(label)}${receipt.productNo ? ` · #${escapeHtml(receipt.productNo)}` : ''}</div>
      <span class="api-badge">${escapeHtml(receipt.mode || '등록')} · ${escapeHtml(receipt.productName || '상품명 없음')}</span>
    </div>
    <div class="factory-small" style="margin-top:6px;color:var(--text-m);line-height:1.55">판매가 ${escapeHtml(receipt.price || '-')} · 대표 ${Number(receipt.representativeImageCount || 0)} · 상세 ${Number(receipt.detailImageCount || 0)} · 옵션 ${Number(receipt.optionValues?.length || 0)} · 품목/재고 ${Number(receipt.variantCount || 0)} · 필수값 ${Object.keys(receipt.requiredValues || {}).length}${escapeHtml(mismatchText)}</div>
  </div>`;
}

function renderFactoryFinalRegistrationPanel(factory, baseDraft = {}, options = {}) {
  const sync = factoryEnsureOpenMarketSync(factory);
  const settings = factoryFinalRegistrationSettings(factory);
  const renderCache = options.renderCache || null;
  const cafe24Model = options.cafe24Model || (renderCache
    ? factoryRenderCacheFinalCafe24Model(factory, renderCache)
    : factoryFinalRegistrationCafe24Model(factory, options));
  const detailModel = options.detailModel || (renderCache
    ? factoryRenderCacheFinalDetailModel(factory, renderCache)
    : factoryFinalRegistrationDetailModel(factory));
  const selectedChannels = factoryOpenMarketSelectedChannels(factory);
  const channelLabelText = factoryOpenMarketChannelLabelList(selectedChannels);
  const marketRouteLabel = sync.mode === 'direct_api' ? '오픈마켓 직접 API' : 'Cafe24 마켓플러스';
  const openMarketText = settings.includeOpenMarket
    ? `${marketRouteLabel} · ${channelLabelText || '선택 채널 없음'}`
    : '오픈마켓 진행 안 함';
  const openMarketReady = !settings.includeOpenMarket || selectedChannels.length > 0;
  const detailWarning = detailModel.warning || '';
  const canRun = detailModel.canProceed && cafe24Model.canRun && openMarketReady && !sync.finalRegistrationRunning;
  const disabledReason = (!detailModel.canProceed ? detailModel.reason : '') || cafe24Model.reason || (!openMarketReady ? '오픈마켓까지 진행하려면 보낼 마켓을 1개 이상 선택해주세요.' : '') || (sync.finalRegistrationRunning ? '최종 등록이 이미 진행 중입니다.' : '');
  const runTitle = disabledReason || detailWarning || '선택한 범위로 Cafe24 등록/저장 후 필요한 경우 오픈마켓 흐름까지 이어갑니다.';
  const progress = Math.max(0, Math.min(100, Number(sync.finalRegistrationProgress || 0)));
  const staleCompletedStatus = !!(sync.finalRegistrationStatus && !sync.finalRegistrationRunning && !canRun && progress >= 100);
  const rawShownStatus = staleCompletedStatus
    ? `이전 실행 결과: ${sync.finalRegistrationStatus}`
    : sync.finalRegistrationStatus;
  const shownStatus = rawShownStatus ? formatAppErrorMessage(rawShownStatus) : '';
  const recoveryActionsHtml = !detailModel.canProceed
    ? `<button class="btn-sm" type="button" data-factory-guide-action="open-preview"><span class="material-icons-outlined" style="font-size:14px">visibility</span>미리보기 확인</button>
       <button class="btn-sm" type="button" data-factory-guide-action="go-tab:sections"><span class="material-icons-outlined" style="font-size:14px">view_list</span>섹션 설정으로 이동</button>
       <button class="btn-sm" type="button" data-factory-run-stage="detail"><span class="material-icons-outlined" style="font-size:14px">auto_mode</span>상세페이지 다시 만들기</button>`
    : `<button class="btn-sm" type="button" data-factory-guide-action="focus-materials"><span class="material-icons-outlined" style="font-size:14px">fact_check</span>DB/Cafe24 입력판 확인</button>
       <button class="btn-sm" type="button" data-factory-guide-action="go-tab:publish"><span class="material-icons-outlined" style="font-size:14px">send</span>전송 설정 다시 보기</button>`;
  const recoveryHelpText = !detailModel.canProceed
    ? '현재 작업물을 잃지 않도록 먼저 미리보기/섹션 상태를 확인한 뒤 다시 등록할 수 있습니다.'
    : '현재 작업물을 잃지 않도록 DB/Cafe24 기준값과 전송 범위를 확인한 뒤 다시 등록할 수 있습니다.';
  const detailRecoveryHtml = disabledReason && !sync.finalRegistrationRunning
    ? `<div class="factory-guide-note" style="margin-top:10px;border-color:rgba(245,158,11,.45);background:rgba(245,158,11,.09)">
        <div style="font-size:12px;color:var(--warn);font-weight:950;line-height:1.6">${escapeHtml(disabledReason)}</div>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m);line-height:1.55">${escapeHtml(recoveryHelpText)}</div>
        <div class="factory-stage-actions" style="margin-top:8px;justify-content:flex-start;flex-wrap:wrap">
          ${recoveryActionsHtml}
        </div>
      </div>`
    : '';
  const cafe24OptionEditorHtml = typeof renderFactoryCafe24OptionEditor === 'function'
    ? renderFactoryCafe24OptionEditor(factory, factoryCafe24OptionEditorModel(factory))
    : '';
  return `<div id="factoryFinalRegistrationPanel" data-factory-final-registration="1" style="border:1px solid rgba(99,102,241,.38);background:rgba(99,102,241,.075);border-radius:12px;padding:12px;margin-top:12px">
    <div style="display:flex;gap:10px;align-items:flex-start;justify-content:space-between;flex-wrap:wrap">
      <div style="min-width:0">
        <div style="font-size:13px;color:var(--text);font-weight:950">최종 등록 선택</div>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m);line-height:1.55">
          실행 직전 선택값입니다. Cafe24 전송 payload에는 아래 진열/판매 상태가 우선 반영됩니다.
        </div>
      </div>
      <div class="factory-stage-actions" style="justify-content:flex-end">
        <button class="btn-sm" type="button" data-factory-resume-exact-cafe24-product="1" data-factory-guide-action="resume-exact-cafe24-product" onclick="return window.factoryResumeExactCafe24ButtonInline(this,event)" ${disabledAttr(sync.finalRegistrationRunning, '최종 등록이 끝난 뒤 다시 선택할 수 있습니다.')} title="현재 상품명과 정확히 같은 최신 Cafe24 상품을 찾아 기존 상품 수정 대상으로 선택합니다.">
          <span class="material-icons-outlined" style="font-size:14px">manage_search</span>동일명 최신 Cafe24 상품 이어서 수정
        </button>
        <button class="btn-primary" type="button" id="factoryRunFinalRegistration" data-factory-guide-action="run-final-registration" onclick="return window.factoryRunFinalRegistrationButtonInline(this,event)" ${disabledAttr(!canRun, disabledReason || '최종 등록 조건을 확인해주세요.')} title="${escAttr(runTitle)}">
          <span class="material-icons-outlined" style="font-size:16px">${sync.finalRegistrationRunning ? 'hourglass_empty' : 'rocket_launch'}</span>${sync.finalRegistrationRunning ? 'Cafe24 최종 등록 중' : 'Cafe24 최종 등록'}
        </button>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;margin-top:10px">
      <label style="display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-m);font-weight:850">
        등록 범위
        <select class="input" id="factoryFinalRegistrationTarget">
          <option value="cafe24_only" ${settings.target === 'cafe24_only' ? 'selected' : ''}>카페24만 등록</option>
          <option value="cafe24_openmarket" ${settings.target === 'cafe24_openmarket' ? 'selected' : ''}>카페24 + 오픈마켓까지</option>
        </select>
      </label>
      <label style="display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-m);font-weight:850">
        Cafe24 등록 방식
        <select class="input" id="factoryFinalCafe24RegistrationMode">
          <option value="create" ${settings.cafe24RegistrationMode === 'create' ? 'selected' : ''}>새 상품으로 등록</option>
          <option value="update" ${settings.cafe24RegistrationMode === 'update' ? 'selected' : ''}>기존 상품 수정</option>
        </select>
      </label>
      <label style="display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-m);font-weight:850">
        Cafe24 진열 상태
        <select class="input" id="factoryFinalCafe24Display">
          ${renderFactoryCafe24FinalFlagOptions('display', settings.display)}
        </select>
      </label>
      <label style="display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-m);font-weight:850">
        Cafe24 판매 상태
        <select class="input" id="factoryFinalCafe24Selling">
          ${renderFactoryCafe24FinalFlagOptions('selling', settings.selling)}
        </select>
      </label>
    </div>
    ${renderFactoryFinalRegistrationBasicInfoPanel(factory, {
      renderCache,
      createModel: options.createModel,
      model: options.basicInfoModel,
    })}
    ${cafe24OptionEditorHtml}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:7px;margin-top:10px">
      <div class="api-badge" style="justify-content:flex-start">상세페이지 ${escapeHtml(detailModel.label)}</div>
      <div class="api-badge" style="justify-content:flex-start">Cafe24 ${escapeHtml(cafe24Model.label)}</div>
      <div class="api-badge" style="justify-content:flex-start">방식 ${escapeHtml(settings.cafe24RegistrationLabel)}</div>
      <div class="api-badge" style="justify-content:flex-start">진열 ${escapeHtml(settings.displayLabel)}</div>
      <div class="api-badge" style="justify-content:flex-start">판매 ${escapeHtml(settings.sellingLabel)}</div>
      <div class="api-badge" style="justify-content:flex-start">이후 ${escapeHtml(openMarketText)}</div>
    </div>
    ${detailWarning && !sync.finalRegistrationRunning ? `<div class="factory-small" style="margin-top:8px;color:var(--warn);font-weight:900">${escapeHtml(detailWarning)}. 실행하면 확인창에서 계속 진행할지 묻습니다.</div>` : ''}
    ${detailRecoveryHtml}
    <div data-final-registration-status-box style="display:${shownStatus ? 'block' : 'none'};margin-top:10px;border:1px solid ${staleCompletedStatus ? 'rgba(245,158,11,.34)' : 'rgba(148,163,184,.20)'};background:${staleCompletedStatus ? 'rgba(245,158,11,.07)' : 'rgba(15,23,42,.34)'};border-radius:9px;padding:8px">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
        <div class="factory-small" data-final-registration-status style="color:${staleCompletedStatus ? 'var(--warn)' : (sync.finalRegistrationRunning ? 'var(--primary-h)' : 'var(--text)')};font-weight:950">${escapeHtml(shownStatus)}</div>
        <span class="api-badge" data-final-registration-progress-label>${progress}%</span>
      </div>
      ${staleCompletedStatus ? `<div class="factory-small" style="margin-top:5px;color:var(--text-m);line-height:1.5">현재 조건이 바뀌어서 위 완료 상태는 과거 실행 결과입니다. 지금 등록하려면 위 안내 버튼으로 상세페이지 상태를 먼저 복구해주세요.</div>` : ''}
      <div class="progress-outer" style="max-width:none;height:10px;margin-top:7px">
        <div class="progress-inner" data-final-registration-progress-bar style="width:${progress}%;min-width:0;font-size:0"></div>
      </div>
    </div>
    ${renderFactoryCafe24RegistrationReceipt(factory)}
  </div>`;
}

function factoryPatchFinalRegistrationStatusInPlace(sync = factoryEnsureOpenMarketSync(factoryRuntimeReadFactory())) {
  const panel = document.getElementById('factoryFinalRegistrationPanel');
  if (!panel) return false;
  const statusBox = panel.querySelector('[data-final-registration-status-box]');
  const statusEl = panel.querySelector('[data-final-registration-status]');
  const progressLabel = panel.querySelector('[data-final-registration-progress-label]');
  const progressBar = panel.querySelector('[data-final-registration-progress-bar]');
  if (!statusBox || !statusEl || !progressLabel || !progressBar) return false;
  const progress = Math.max(0, Math.min(100, Number(sync.finalRegistrationProgress || 0)));
  statusBox.style.display = 'block';
  statusEl.textContent = formatAppErrorMessage(sync.finalRegistrationStatus || '');
  statusEl.style.color = sync.finalRegistrationRunning ? 'var(--primary-h)' : 'var(--text)';
  progressLabel.textContent = `${progress}%`;
  progressBar.style.width = `${progress}%`;
  const runBtn = document.getElementById('factoryRunFinalRegistration');
  if (runBtn && sync.finalRegistrationRunning) {
    runBtn.disabled = true;
    runBtn.innerHTML = '<span class="material-icons-outlined" style="font-size:16px">hourglass_empty</span>Cafe24 최종 등록 중';
  }
  return true;
}

function factoryUpdateFinalRegistrationStatus(message, progress = 0, type = 'info', options = {}) {
  if (!options.factory) {
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/final-registration:update-status',
      'cafe24',
      draft => factoryUpdateFinalRegistrationStatus(message, progress, type, {
        ...options,
        factory: draft,
        render: false,
      }),
    );
    const sync = factoryEnsureOpenMarketSync(factoryRuntimeReadFactory());
    if (sync.finalRegistrationRunning && factoryPatchFinalRegistrationStatusInPlace(sync)) {
      scheduleLastWorkSave(700);
    } else {
      saveLastWorkNow({ sync: false });
      if (options.render !== false) renderPreservingMainScroll();
    }
    return receipt.result;
  }
  const factory = options.factory;
  const sync = factoryEnsureOpenMarketSync(factory);
  sync.finalRegistrationStatus = String(message || '');
  sync.finalRegistrationProgress = Math.max(0, Math.min(100, Number(progress || 0)));
  sync.finalRegistrationUpdatedAt = Date.now();
  factoryOpenMarketLog(sync.finalRegistrationStatus, type, factory);
}

function factoryFinalRegistrationErrorMessage(error) {
  const raw = error && typeof error === 'object'
    ? (error.message || error.error || JSON.stringify(error))
    : String(error || '');
  const formatted = typeof formatAppErrorMessage === 'function'
    ? formatAppErrorMessage(raw)
    : raw;
  const compact = String(formatted || '')
    .replace(/\s+/g, ' ')
    .replace(/(\{["'][\s\S]{180,})$/g, 'Cafe24 응답 원문이 너무 길어 화면에서는 접었습니다. 실행 로그와 Control Tower에서 상세 원문을 확인해주세요.')
    .trim();
  if (compact.length <= 520) return compact;
  return `${compact.slice(0, 520)}... (긴 응답은 접었습니다)`;
}

function factoryClearFinalRegistrationStaleResult(factory, options = {}) {
  const product = factory.product || (factory.product = {});
  const sync = factoryEnsureOpenMarketSync(factory);
  let changed = false;
  if (product.cafe24LastSaveVerification) {
    product.cafe24LastSaveVerification = null;
    changed = true;
  }
  const apiStatus = String(product.cafe24ApiStatus || '').trim();
  const looksLikePreviousSuccess = /Cafe24 (새 상품 등록 완료|새 상품 등록 후|상품 기본정보 반영완료|상세페이지 HTML 저장 완료|이미지 업로드 완료|추가 이미지 .* 완료|옵션\/품목 반영완료|카테고리 연결 완료|SEO 저장 완료|태그 동기화 완료)|동일 상품명 Cafe24 상품 확인|최종 등록 완료/.test(apiStatus);
  if (options.clearApiStatus !== false && looksLikePreviousSuccess) {
    product.cafe24ApiStatus = '';
    changed = true;
  }
  const finalStatus = String(sync.finalRegistrationStatus || '').trim();
  if (options.clearFinalStatus !== false && /최종 등록 완료/.test(finalStatus)) {
    sync.finalRegistrationStatus = '';
    sync.finalRegistrationProgress = 0;
    sync.finalRegistrationUpdatedAt = Date.now();
    changed = true;
  }
  return changed;
}

async function factoryPrepareFinalRegistrationLocalAssets(options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/final-registration:prepare-assets',
      'cafe24',
      draft => factoryPrepareFinalRegistrationLocalAssets({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    saveLastWorkNow({ sync: false });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  const emit = (message, progress, type = 'info') => {
    if (typeof options.onProgress === 'function') {
      try { options.onProgress(message, progress, type); } catch(_) {}
      return;
    }
    factoryUpdateFinalRegistrationStatus(message, progress, type, { factory, render: false });
  };
  if (typeof factoryRefreshLocalArchiveAssets !== 'function') return { ok: false, reason: 'no-refresh' };
  emit('최종 등록 전 로컬 보관 이미지를 다시 확인합니다.', 3, 'info');
  try {
    await factoryRefreshLocalArchiveAssets({ auto: false, limit: 240, stageRefresh: true, factory, render: false });
  } catch(e) {
    emit(`로컬 보관 이미지 확인 실패: ${e.message || e}`, 4, 'error');
    return { ok: false, reason: e.message || String(e) };
  }

  const previewStatus = typeof factoryCurrentPreviewSectionStatus === 'function'
    ? factoryCurrentPreviewSectionStatus(state)
    : null;
  const currentDetailImageCount = typeof factoryRegistrationDetailImageRefs === 'function'
    ? factoryRegistrationDetailImageRefs(factory, { includeTransferSrc: true }).length
    : 0;
  if (previewStatus?.generated > currentDetailImageCount
    && typeof factoryRecoverPreviewSectionsFromLocalArchive === 'function') {
    const recovery = await factoryRecoverPreviewSectionsFromLocalArchive({ render: false, persist: false });
    if (recovery?.restored) {
      emit(`현재 상세 이미지 로컬 보관본 복구 완료: ${recovery.restored}/${recovery.total || recovery.restored}개`, 5, 'ok');
    }
  }

  let restored = { ok: false, restored: 0, total: 0 };
  if (options.restoreCurrentWork === true && typeof factoryRestoreLocalArchiveToCurrentWork === 'function') {
    const targets = typeof factoryLocalArchiveRestoreTargets === 'function'
      ? factoryLocalArchiveRestoreTargets(factory)
      : [];
    if (targets.length) {
      emit(`로컬 보관 이미지를 현재 작업에 복원합니다: ${targets.length}개`, 5, 'info');
      restored = await factoryRestoreLocalArchiveToCurrentWork({
        limit: Number(options.restoreLimit || 24),
        factory,
        silent: true,
        render: false,
      });
      emit(`로컬 보관 이미지 복원 완료: ${restored.restored || 0}/${restored.total || targets.length}개`, 7, restored.restored ? 'ok' : 'warn');
    } else {
      emit('현재 작업에 이미 연결된 로컬 보관 이미지가 있는지 확인했습니다.', 6, 'info');
    }
  } else {
    emit('최종등록에는 필요한 대표이미지 원본만 연결하고, 보관함 전체 후보 복원은 건너뜁니다.', 6, 'info');
  }

  let hydrated = { ok: false, hydrated: 0 };
  if (typeof factoryHydrateCafe24ImagesFromLocalArchive === 'function') {
    hydrated = await factoryHydrateCafe24ImagesFromLocalArchive({
      stages: ['hero'],
      progress: 8,
      doneProgress: 10,
      onProgress: emit,
      factory,
      render: false,
    });
  }
  return {
    ok: !!(restored.ok || hydrated.ok),
    restored: restored.restored || 0,
    hydrated: hydrated.hydrated || 0,
    alreadyReady: !!hydrated.alreadyReady,
  };
}

function factoryPromptFinalRegistrationConfirmation(lines = []) {
  return new Promise(resolve => {
    document.getElementById('factoryFinalRegistrationConfirmDialog')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'factoryFinalRegistrationConfirmDialog';
    overlay.className = 'factory-asset-preview-overlay';
    overlay.innerHTML = `
      <div class="factory-asset-preview-modal" role="dialog" aria-modal="true" aria-labelledby="factoryFinalRegistrationConfirmTitle" style="width:min(560px,96vw);grid-template-rows:auto minmax(0,1fr) auto">
        <div class="factory-asset-preview-head">
          <div class="factory-asset-preview-title" id="factoryFinalRegistrationConfirmTitle">Cafe24 최종 등록 확인</div>
        </div>
        <div class="factory-asset-preview-body" style="display:block;color:var(--text-d);font-size:13px;line-height:1.65;white-space:pre-wrap;word-break:keep-all;overflow-wrap:anywhere">${escapeHtml((Array.isArray(lines) ? lines : [lines]).join('\n'))}</div>
        <div class="factory-stage-actions" style="justify-content:flex-end;padding:12px 14px;border-top:1px solid var(--border);flex-wrap:wrap">
          <button class="btn-sm" type="button" data-factory-final-registration-confirm="cancel">취소</button>
          <button class="btn-sm primary" type="button" data-factory-final-registration-confirm="confirm">확인하고 등록 실행</button>
        </div>
      </div>`;
    const finish = confirmed => {
      overlay.remove();
      resolve(confirmed);
    };
    overlay.addEventListener('click', event => {
      if (event.target === overlay) finish(false);
    });
    overlay.addEventListener('keydown', event => {
      if (event.key === 'Escape') finish(false);
    });
    overlay.querySelector('[data-factory-final-registration-confirm="cancel"]')?.addEventListener('click', () => finish(false));
    const confirmButton = overlay.querySelector('[data-factory-final-registration-confirm="confirm"]');
    confirmButton?.addEventListener('click', () => finish(true));
    document.body.appendChild(overlay);
    confirmButton?.focus();
  });
}

async function factoryRunFinalRegistration(options = {}) {
  if (!options.factory && options.operationLeaseHeld !== true) {
    return factoryRuntimeWithOperationLease(
      'factory/final-registration:run',
      { operationToken: options.operationToken },
      operation => factoryRunFinalRegistration({
        ...options,
        operationToken: operation.operationToken,
        operationLeaseHeld: true,
      }),
    );
  }
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/final-registration:run',
      'cafe24',
      draft => factoryRunFinalRegistration({
        ...options,
        factory: draft,
        render: false,
      }),
    );
    await saveLastWorkNow({ sync: false, factory: receipt.snapshot.factory });
    if (options.render !== false) renderPreservingMainScroll();
    return receipt.result;
  }
  const factory = options.factory;
  // Cafe24 heavy modules may still be staging-in; wait without changing registration logic.
  if (typeof window.ensureCafe24Modules === 'function') {
    try {
      await window.ensureCafe24Modules();
    } catch (e) {
      if (typeof factoryLog === 'function') factoryLog(String(e && e.message ? e.message : e), 'error');
      throw e;
    }
  }
  // 배치(조립공장 워커)에는 등록 화면이 없다. 그때 DOM 입력을 읽으면 관제탑이 넣어 둔
  // 분류·판매가·진열 값이 빈 값으로 덮여 등록이 조용히 어긋난다. 화면이 있을 때만 읽는다.
  if (options.headless !== true) {
    factoryUpdateFromInputs(factory);
    factoryApplyFinalRegistrationBasicInfoInputs({
      silent: true,
      render: false,
      container: options.container,
      factory,
    });
  }
  let sync = factoryEnsureOpenMarketSync(factory);
  if (sync.finalRegistrationRunning) {
    factoryOpenMarketLog('최종 등록이 이미 진행 중입니다. 현재 작업이 끝난 뒤 다시 실행해주세요.', 'error', factory);
    return false;
  }
  factoryClearFinalRegistrationStaleResult(factory);
  factoryApplyFinalCafe24StatusToDb(factory);
  if (typeof factoryUpdateFinalDbFromFields === 'function') factoryUpdateFinalDbFromFields(factory);
  if (options.skipLocalAssetPrepare !== true) {
    await factoryPrepareFinalRegistrationLocalAssets({ factory, render: false, restoreCurrentWork: true });
    sync = factoryEnsureOpenMarketSync(factory);
    factoryApplyFinalCafe24StatusToDb(factory);
    if (typeof factoryUpdateFinalDbFromFields === 'function') factoryUpdateFinalDbFromFields(factory);
  }
  const settings = factoryFinalRegistrationSettings(factory);
  const detailModel = factoryFinalRegistrationDetailModel(factory);
  const cafe24Model = factoryFinalRegistrationCafe24Model(factory);
  const basicInfo = factoryFinalRegistrationBasicInfoModel(factory);
  const inventoryQuantityInput = String(options.forceInventoryQuantity ?? '').trim();
  // 새 상품의 초기 옵션 재고는 DB 수량이 정본이다. 이 값을 실어 주지 않으면 옵션 재고를
  // 다른 Cafe24 상품의 후보 캐시에서 seed 하는데, 갓 만든 상품의 캐시본은 재고가 0이라
  // 그 0 이 그대로 실린다. 실측: #3011 은 스토어에 9색 전부 99 인데 캐시본은 0 이었고,
  // 그 탓에 새로 올린 #3021 이 9색 전부 0(품절)으로 등록됐다.
  // 부르는 쪽이 수량을 못박았으면 그 값이 우선이다. 기존 상품 수정 경로는 이 값을 받지
  // 않으므로, 스토어에 이미 있는 재고를 이 기본값이 덮어쓰지 않는다.
  const dbInventoryQuantity = String(factory.product?.finalDb?.quantity ?? '').trim();
  const forceInventoryQuantity = /^\d+$/.test(inventoryQuantityInput)
    ? inventoryQuantityInput
    : (/^\d+$/.test(dbInventoryQuantity) ? dbInventoryQuantity : '');
  if (!detailModel.canProceed) {
    factoryUpdateFinalRegistrationStatus(detailModel.reason || '상세페이지 조각이 아직 없습니다.', 0, 'error', { factory, render: false });
    return false;
  }
  if (!cafe24Model.canRun) {
    factoryUpdateFinalRegistrationStatus(cafe24Model.reason || '최종 등록 조건이 아직 준비되지 않았습니다.', 0, 'error', { factory, render: false });
    return false;
  }
  const selectedChannels = factoryOpenMarketSelectedChannels(factory);
  const marketRouteLabel = sync.mode === 'direct_api' ? '오픈마켓 직접 API' : 'Cafe24 마켓플러스';
  const openMarketSummary = settings.includeOpenMarket
    ? `${marketRouteLabel} · ${factoryOpenMarketChannelLabelList(selectedChannels) || '선택 채널 없음'}`
    : '오픈마켓 진행 안 함';
  if (settings.includeOpenMarket && !selectedChannels.length) {
    factoryOpenMarketLog('최종 등록 중단: 오픈마켓까지 진행하려면 보낼 마켓을 1개 이상 선택해주세요.', 'error', factory);
    return false;
  }
  const confirmLines = [
    ...(detailModel.ok ? [] : [
      '상세페이지 섹션이 남아있습니다.',
      `${detailModel.label} 상태입니다. 그래도 진행하시겠습니까?`,
      '',
    ]),
    '최종 등록을 실행합니다.',
    '',
    `범위: ${settings.targetLabel}`,
    `상품명: ${basicInfo.productName || '미입력'}`,
    `판매가: ${basicInfo.salePrice || '미입력'}`,
    `Cafe24 작업: ${settings.cafe24RegistrationLabel} / ${cafe24Model.label}`,
    `Cafe24 진열: ${settings.displayLabel}`,
    `Cafe24 판매: ${settings.sellingLabel}`,
    `오픈마켓: ${openMarketSummary}`,
    '',
    '외부 Cafe24/오픈마켓 데이터가 실제로 변경될 수 있습니다. 계속할까요?',
  ];
  const ok = options.skipConfirm === true || await factoryPromptFinalRegistrationConfirmation(confirmLines);
  if (!ok) return false;
  if (!detailModel.ok) {
    factoryOpenMarketLog(`상세페이지 일부 섹션 미완성 상태로 최종 등록을 계속합니다: ${detailModel.label}`, 'warn', factory);
  }
  if (cafe24Model.mode === 'create') {
    const referenceNo = String(factoryCafe24TargetInfo(factory)?.productNo || '').trim();
    factoryOpenMarketLog(referenceNo
      ? `Cafe24 새 상품 등록 모드: 기존 #${referenceNo}는 원본 참고만 하고, Cafe24에는 새 상품번호로 별도 생성합니다.`
      : 'Cafe24 새 상품 등록 모드: 기존 상품 수정 없이 새 상품을 생성합니다.', 'info', factory);
    if (typeof factoryHydrateCafe24ImagesFromLocalArchive === 'function') {
      await factoryHydrateCafe24ImagesFromLocalArchive({
        stages: ['hero'],
        progress: 8,
        doneProgress: 10,
        onProgress: (message, progress, type = 'info') => factoryUpdateFinalRegistrationStatus(message, progress, type, { factory, render: false }),
        factory,
        render: false,
      });
    }
    const cafe24ImagePayload = typeof factoryCafe24ImagePayload === 'function'
      ? factoryCafe24ImagePayload(factory)
      : {};
    const cafe24ImageSlots = typeof FACTORY_CAFE24_IMAGE_SLOTS !== 'undefined' && Array.isArray(FACTORY_CAFE24_IMAGE_SLOTS)
      ? FACTORY_CAFE24_IMAGE_SLOTS
      : [];
    const cafe24ImageSlotCount = cafe24ImageSlots.filter(slot => cafe24ImagePayload?.[slot.key]).length;
    if (!cafe24ImageSlotCount) {
      factoryUpdateFinalRegistrationStatus('최종 등록 중단: Cafe24 새 상품에 올릴 대표이미지 파일을 찾지 못했습니다. 대표이미지 후보를 선택하거나 이미지 입력판을 확인해주세요.', 0, 'error', { factory, render: false });
      return false;
    }
    factoryOpenMarketLog(`Cafe24 대표이미지 업로드 준비 확인: ${cafe24ImageSlotCount}개 슬롯`, 'ok', factory);
  } else {
    factoryOpenMarketLog(`Cafe24 기존 상품 수정 모드: #${cafe24Model.productNo || '-'} 상품을 업데이트합니다.`, 'warn', factory);
  }
  const preservedDetail = factoryEnsureCurrentDetailHtmlAsset(factory);
  const preservedDetailHtml = String(preservedDetail?.html || '').trim();
  const preservedDetailSource = String(preservedDetail?.source || preservedDetail?.asset?.metadata?.source || '').trim();
  if (!preservedDetailHtml) {
    factoryUpdateFinalRegistrationStatus('최종 등록 중단: 현재 미리보기 상세페이지 HTML을 확보하지 못했습니다. 상세페이지를 다시 확인한 뒤 전송해주세요.', 0, 'error', { factory, render: false });
    return false;
  }
  const expectedDetailImageCount = Math.max(0, Number(preservedDetail?.sectionCount || detailModel.generated || 0));
  const preservedDetailImageCount = typeof factoryCafe24DetailImageSrcValues === 'function'
    ? factoryCafe24DetailImageSrcValues(preservedDetailHtml).length
    : (preservedDetailHtml.match(/<img\b[^>]*\bsrc\s*=/gi) || []).length;
  if (expectedDetailImageCount && preservedDetailImageCount < expectedDetailImageCount) {
    const message = `최종 등록 중단: 상세 이미지 ${preservedDetailImageCount}/${expectedDetailImageCount}장만 전송 HTML에 연결됐습니다. Cafe24에는 전송하지 않습니다.`;
    factoryUpdateFinalRegistrationStatus(message, 0, 'error', { factory, render: false });
    factoryOpenMarketLog(message, 'error', factory);
    return false;
  }
  if (preservedDetail?.partialFallback) {
    factoryOpenMarketLog(`부분 상세페이지 ${preservedDetail.sectionCount || detailModel.generated}/${detailModel.total || 0} 상태라 상품 기준 안전 상세설명을 등록 전 보존했습니다.`, 'warn', factory);
  } else if (preservedDetail?.stored) {
    factoryOpenMarketLog(`현재 미리보기 상세페이지 HTML을 등록 전 자산으로 보존했습니다: ${preservedDetail.sectionCount || detailModel.generated}개 섹션`, 'ok', factory);
  } else if (preservedDetail?.reused) {
    factoryOpenMarketLog('현재 미리보기 상세페이지 HTML은 이미 보존된 자산을 다시 사용합니다.', 'info', factory);
  }

  const registrationPreflight = factoryCafe24BuildRegistrationReceiptPreflight(factory, {
    mode: cafe24Model.mode,
    productNo: cafe24Model.productNo,
    basicInfo,
    settings,
    detailHtml: preservedDetailHtml,
    forceInventoryQuantity,
  });
  factory.product.cafe24RegistrationReceipt = registrationPreflight;

  sync.finalRegistrationRunning = true;
  sync.finalRegistrationProgress = 5;
  sync.finalRegistrationStatus = '최종 등록 준비 중입니다.';
  sync.finalRegistrationUpdatedAt = Date.now();
  sync.finalRegistrationSessionId = FACTORY_PAGE_SESSION_ID;
  factoryOpenMarketLog(sync.finalRegistrationStatus, 'info', factory);
  factoryPatchFinalRegistrationStatusInPlace(sync);
  await new Promise(resolve => setTimeout(resolve, 0));

  try {
    factoryUpdateFinalRegistrationStatus(`Cafe24 ${cafe24Model.mode === 'update' ? '기존 상품 저장' : '새 상품 등록'} 시작: 진열 ${settings.displayLabel}, 판매 ${settings.sellingLabel}`, 20, 'info', { factory, render: false });
    const reportCafe24Progress = (message, progress, type = 'info') => {
      factoryUpdateFinalRegistrationStatus(message, progress, type, { factory, render: false });
      factoryPatchFinalRegistrationStatusInPlace(sync);
    };
    const cafe24Result = cafe24Model.mode === 'update'
      ? await factorySaveCafe24ProductFromFinalDb({ skipConfirm: true, applyFinalRegistrationSettings: true, deferInitialSave: true, forceName: basicInfo.productName, forceSalePrice: basicInfo.salePrice, detailHtml: preservedDetailHtml, detailSource: preservedDetailSource, onProgress: reportCafe24Progress, factory, render: false })
      : await factoryCreateCafe24ProductFromFinalDb({ skipConfirm: true, applyFinalRegistrationSettings: true, allowSelectedSource: true, forceName: basicInfo.productName, forceSalePrice: basicInfo.salePrice, forceInventoryQuantity, detailHtml: preservedDetailHtml, detailSource: preservedDetailSource, onProgress: reportCafe24Progress, factory, render: false });
    if (cafe24Result === false) {
      const apiStatus = String(factory.product?.cafe24ApiStatus || '').trim();
      const verificationError = String(factory.product?.cafe24LastSaveVerification?.error || '').trim();
      const detailedReason = [apiStatus, verificationError].filter(Boolean).join(' · ');
      throw new Error(detailedReason || 'Cafe24 등록/저장 단계가 실패했거나 중단되었습니다.');
    }
    if (cafe24Model.mode === 'update') {
      const productNo = String(cafe24Model.productNo || '').trim();
      if (!productNo) throw new Error('Cafe24 기존 상품 후속 등록 중단: 상품번호가 없습니다.');
      reportCafe24Progress(`Cafe24 기존 상품 상세페이지 후속 저장 중: #${productNo}`, 92, 'info');
      await factoryPublishCafe24ScopedDetailHtml(productNo, {
        mallId: factoryCafe24TargetInfo(factory)?.mallId || CAFE24_CONTROL_API.defaultMallId,
        html: preservedDetailHtml,
        source: preservedDetailSource || 'final-registration-preserved',
        progressStart: 92,
        progressMid: 95,
        progressEnd: 97,
        onProgress: reportCafe24Progress,
        factory,
        render: false,
      });
      const forceInventory = Boolean(forceInventoryQuantity);
      const presentationPlan = typeof factoryCafe24CreatePostSyncPlan === 'function'
        ? factoryCafe24CreatePostSyncPlan(factory, { forceInventory, forceInventoryQuantity })
        : { imageSlotCount: 0, readyActions: [] };
      const requiredPresentationKeys = forceInventory
        ? ['images', 'category', 'options']
        : ['images', 'category'];
      const requiredPresentationActions = (presentationPlan.readyActions || [])
        .filter(action => requiredPresentationKeys.includes(action?.key));
      if (forceInventory && !requiredPresentationActions.some(action => action?.key === 'options')) {
        throw new Error('Cafe24 기존 상품 재고 99 동기화 준비가 되지 않았습니다.');
      }
      if (requiredPresentationActions.length) {
        const presentationOk = await factoryRunCafe24PostCreateSync(requiredPresentationActions, {
          productNo,
          mallId: factoryCafe24TargetInfo(factory)?.mallId || CAFE24_CONTROL_API.defaultMallId,
          progressStart: 97,
          progressEnd: 99,
          onProgress: reportCafe24Progress,
          requiredKeys: requiredPresentationKeys,
          forceInventory,
          forceInventoryQuantity,
          factory,
          render: false,
        });
        if (presentationOk === false) throw new Error('Cafe24 기존 상품 이미지/카테고리 후속 동기화가 실패했습니다.');
      }
      const finalDetail = await fetchCafe24ProductFullByNo(productNo, factoryCafe24TargetInfo(factory)?.mallId || CAFE24_CONTROL_API.defaultMallId);
      const finalRaw = parseCafe24Raw(finalDetail) || finalDetail?.raw || finalDetail || {};
      const finalHtml = String(finalRaw.description || finalRaw.mobile_description || '').trim();
      const finalHasImage = [finalRaw.detail_image, finalRaw.list_image, finalRaw.small_image, finalRaw.tiny_image]
        .some(value => String(value || '').trim());
      const finalIssues = [
        !finalHtml ? '상세페이지 HTML 비어 있음' : '',
        Number(presentationPlan.imageSlotCount || 0) > 0 && !finalHasImage ? '대표/목록 이미지 비어 있음' : '',
      ].filter(Boolean);
      if (finalIssues.length) throw new Error(`Cafe24 기존 상품 후속 등록 검증 실패: #${productNo} ${finalIssues.join(' · ')}`);
      factoryOpenMarketLog(`Cafe24 기존 상품 후속 등록 검증 완료: #${productNo} 상세페이지/대표이미지 반영 확인`, 'ok', factory);
      reportCafe24Progress(`Cafe24 기존 상품 후속 등록 검증 완료: #${productNo}`, 99, 'ok');
    }
    await factoryCafe24FinalizeRegistrationReceipt(factory, { preflight: registrationPreflight });
    sync = factoryEnsureOpenMarketSync(factory);
    if (!settings.includeOpenMarket) {
      sync.finalRegistrationRunning = false;
      sync.finalRegistrationProgress = 100;
      sync.finalRegistrationStatus = '최종 등록 완료: Cafe24까지만 처리했습니다.';
      sync.finalRegistrationUpdatedAt = Date.now();
      sync.finalRegistrationSessionId = '';
      factoryOpenMarketLog(sync.finalRegistrationStatus, 'ok', factory);
      await factoryRecordFinalRegistrationHistory({
        settings,
        finalStatus: sync.finalRegistrationStatus,
        source: options.historySource || 'final-registration',
        render: false,
        factory,
      }).catch(err => factoryOpenMarketLog(`등록 이력 저장 실패: ${formatAppErrorMessage(err.message || String(err))}`, 'warn', factory));
      return true;
    }

    factoryUpdateFinalRegistrationStatus(`Cafe24 완료, ${marketRouteLabel} 단계로 이어가는 중입니다.`, 70, 'info', { factory, render: false });
    if (sync.mode === 'direct_api') {
      factoryBuildOpenMarketDrafts('', { factory, render: false });
      const channels = factoryOpenMarketSelectedChannels(factory);
      for (const channel of channels) {
        factoryUpdateFinalRegistrationStatus(`${channel.label} 오픈마켓 직접 전송 중입니다.`, 75, 'info', { factory, render: false });
        await factorySendOpenMarketDraft(channel.id, { factory, render: false });
      }
    } else {
      const started = await factoryStartMarketPlusSendFlow('', { factory, render: false });
      if (started === false) throw new Error('마켓플러스 상품 보내기 절차를 시작하지 못했습니다.');
    }

    const doneSync = factoryEnsureOpenMarketSync(factory);
    doneSync.finalRegistrationRunning = false;
    doneSync.finalRegistrationProgress = 100;
    doneSync.finalRegistrationStatus = settings.includeOpenMarket
      ? `최종 등록 완료: Cafe24 처리 후 ${marketRouteLabel} 흐름까지 시작했습니다.`
      : '최종 등록 완료: Cafe24까지만 처리했습니다.';
    doneSync.finalRegistrationUpdatedAt = Date.now();
    doneSync.finalRegistrationSessionId = '';
    factoryOpenMarketLog(doneSync.finalRegistrationStatus, 'ok', factory);
    await factoryRecordFinalRegistrationHistory({
      settings,
      finalStatus: doneSync.finalRegistrationStatus,
      source: options.historySource || 'final-registration',
      render: false,
      factory,
    }).catch(err => factoryOpenMarketLog(`등록 이력 저장 실패: ${formatAppErrorMessage(err.message || String(err))}`, 'warn', factory));
    return true;
  } catch(e) {
    const preflight = factory.product?.cafe24RegistrationReceipt;
    if (preflight) {
      factory.product.cafe24RegistrationReceipt = Object.freeze({
        ...preflight,
        status: preflight.status === 'mismatch' ? 'mismatch' : 'failed',
        error: factoryFinalRegistrationErrorMessage(e),
      });
    }
    const failedSync = factoryEnsureOpenMarketSync(factory);
    failedSync.finalRegistrationRunning = false;
    failedSync.finalRegistrationProgress = Math.max(10, Math.min(95, Number(failedSync.finalRegistrationProgress || 0)));
    failedSync.finalRegistrationStatus = `최종 등록 실패: ${factoryFinalRegistrationErrorMessage(e)}`;
    failedSync.finalRegistrationUpdatedAt = Date.now();
    failedSync.finalRegistrationSessionId = '';
    factoryOpenMarketLog(failedSync.finalRegistrationStatus, 'error', factory);
    return false;
  }
}

function renderFactoryOpenMarketSalesPanel(factory, options = {}) {
  const sync = factoryEnsureOpenMarketSync(factory);
  const renderCache = options.renderCache || null;
  const baseDraft = options.baseDraft || (renderCache
    ? factoryRenderCacheBaseDraft(factory, renderCache)
    : factoryOpenMarketBuildBaseDraft(factory, options));
  const showFinalRegistration = options.finalRegistration !== false;
  const selected = new Set(sync.selectedChannels || []);
  const allChannels = factoryOpenMarketChannels(factory);
  const selectedChannels = allChannels.filter(channel => selected.has(channel.id));
  const selectedChannelLabels = factoryOpenMarketChannelLabelList(selectedChannels);
  const marketPlus = factoryMarketPlusReadySummary(baseDraft);
  const directMode = sync.mode === 'direct_api';
  const readyCount = directMode ? baseDraft.checklist.filter(item => item.ok).length : marketPlus.ready;
  const readyTotal = directMode ? baseDraft.checklist.length : marketPlus.total;
  const hasMissing = readyCount < readyTotal;
  const saveVerify = baseDraft.cafe24Verification || null;
  const lastChecked = factoryOpenMarketFormatTs(sync.lastCheckedAt);
  const lastDrafted = factoryOpenMarketFormatTs(sync.lastDraftedAt);
  const lastDryRun = factoryOpenMarketFormatTs(sync.lastDryRunAt);
  const testProductName = sync.testProductName || FACTORY_OPEN_MARKET_TEST_PRODUCT_NAME;
  const testProductNo = sync.testProductNo || FACTORY_OPEN_MARKET_TEST_PRODUCT_NO;
  const currentProductName = String(baseDraft.productName || '').trim();
  const isTestProduct = currentProductName === testProductName || String(baseDraft.productNo || '') === String(testProductNo);
  const logItems = (sync.logs || []).slice(0, 5);
  return `<div class="factory-source-panel" data-factory-open-market-panel="1" style="margin-top:14px;border-color:rgba(34,197,94,.35);background:rgba(6,78,59,.12)">
    <div class="factory-cafe24-save-head" style="align-items:flex-start;gap:12px">
      <div>
        <div class="factory-cafe24-save-title">Cafe24 마켓플러스 연동 준비</div>
        <div class="factory-cafe24-save-sub">
          기본 경로는 Cafe24 상품을 완성한 뒤 마켓플러스에서 ${escapeHtml(selectedChannelLabels || '선택 마켓')}로 관리하는 방식입니다.
          직접 오픈마켓 API는 인증값과 전용 상품 등록 API가 준비된 경우에만 보조로 씁니다.
        </div>
      </div>
      <div class="factory-stage-actions" style="margin-left:auto;justify-content:flex-end">
        <select class="input" id="factoryMarketSyncMode" style="width:auto;min-width:190px;padding:7px 9px" title="마켓 연동 기준을 선택합니다. 권장은 Cafe24 상품 저장 후 마켓플러스 관리입니다.">
          <option value="cafe24_marketplus" ${sync.mode === 'cafe24_marketplus' ? 'selected' : ''}>권장: Cafe24 마켓플러스</option>
          <option value="direct_api" ${sync.mode === 'direct_api' ? 'selected' : ''}>고급: 오픈마켓 직접 API</option>
        </select>
        <button class="btn-sm" id="factoryOpenMarketRefresh" ${disabledAttr(sync.loading, '연동 상태를 확인 중입니다.')} title="Cafe24 Control Tower와 API Hub의 직접 오픈마켓 커넥터 상태를 다시 확인합니다.">
          <span class="material-icons-outlined" style="font-size:14px">${sync.loading ? 'hourglass_empty' : 'sync'}</span>연동 상태 새로고침
        </button>
        <button class="btn-sm primary" id="factoryOpenMarketBuildDrafts" title="현재 Cafe24 입력판/신화사DB/생성 자산을 읽어 마켓플러스 상품 보내기 전 체크용 준비값을 만듭니다.">
          <span class="material-icons-outlined" style="font-size:14px">inventory</span>마켓플러스 준비값 만들기
        </button>
        <button class="btn-sm" id="factoryOpenMarketDryRunAll" title="보조/비상용 직접 API 검증 라우트에 dry-run으로 보내 payload와 누락 사유를 확인합니다. 주 경로는 Cafe24 마켓플러스 상품 보내기입니다. 실제 판매 등록은 하지 않습니다.">
          <span class="material-icons-outlined" style="font-size:14px">rule</span>보조 직접 API dry-run
        </button>
        <button class="btn-sm" id="factoryUseCafe24TestProduct" title="Cafe24에서 방울수저집test 상품을 live 조회해 현재 검증 기준 상품으로 불러옵니다.">
          <span class="material-icons-outlined" style="font-size:14px">science</span>${escapeHtml(testProductName)} 불러오기
        </button>
        <button class="btn-sm" id="factoryCafe24MarketSyncEnable" ${disabledAttr(!baseDraft.productNo || baseDraft.marketSync === 'T', baseDraft.marketSync === 'T' ? '이미 Cafe24 market_sync가 켜져 있습니다.' : '먼저 Cafe24 상품을 확정하거나 방울수저집test를 불러오세요.')} title="현재 선택된 Cafe24 상품의 market_sync 값을 T로 저장 시도한 뒤 재조회로만 성공 판정합니다. Cafe24 API가 이 필드 쓰기를 무시하면 관리자/마켓플러스에서 직접 켜야 합니다. 진열/판매 상태는 바꾸지 않습니다.">
          <span class="material-icons-outlined" style="font-size:14px">hub</span>마켓연동값 반영 시도
        </button>
      </div>
    </div>
    <div style="border:1px solid ${isTestProduct ? 'rgba(34,197,94,.34)' : 'rgba(245,158,11,.34)'};background:${isTestProduct ? 'rgba(34,197,94,.07)' : 'rgba(245,158,11,.07)'};border-radius:10px;padding:9px 10px;margin-top:10px">
      <div style="font-size:12px;color:${isTestProduct ? 'var(--ok)' : 'var(--warn)'};font-weight:950">현재 검증 기준 상품</div>
      <div class="factory-small" style="margin-top:4px;color:var(--text);line-height:1.6">
        ${isTestProduct
          ? `테스트 상품 <b>${escapeHtml(testProductName)}</b>${baseDraft.productNo ? ` (#${escapeHtml(baseDraft.productNo)})` : ''} 기준으로 검증 중입니다.`
          : `현재 상품은 <b>${escapeHtml(currentProductName || '선택 없음')}</b>입니다. 이 단계 검증은 기본적으로 <b>${escapeHtml(testProductName)}</b>을 기준으로 진행하세요.`}
        ${baseDraft.productNo ? `Cafe24 상품번호: #${escapeHtml(baseDraft.productNo)}.` : 'Cafe24 상품번호가 아직 없습니다.'}
      </div>
    </div>
    <div style="border:1px solid rgba(34,197,94,.24);background:rgba(34,197,94,.055);border-radius:10px;padding:9px 10px;margin-top:10px">
      <div style="font-size:12px;color:var(--ok);font-weight:950">권장 운영 흐름</div>
      <div class="factory-small" style="margin-top:4px;color:var(--text);line-height:1.6">
        1) 이 화면에서 Cafe24 상품값을 완성하고 저장합니다. 2) Cafe24 관리자/마켓플러스에서 각 마켓 상품 보내기를 관리합니다.
        마켓플러스 공개 상품 보내기 API가 확인되지 않은 단계에서는 관리자 화면을 열고 실제 상품 보내기 흐름을 따라가며 결과를 기록합니다.
        선택 마켓 dry-run은 API Hub 보조 판매자 API payload 검증이며, Cafe24 마켓플러스 실제 상품 보내기가 아닙니다.
      </div>
    </div>
    <div class="factory-small" style="margin-top:8px">
      마지막 연동 확인: ${escapeHtml(lastChecked)} · 마지막 준비값 생성: ${escapeHtml(lastDrafted)} · 마지막 dry-run: ${escapeHtml(lastDryRun)} · 준비 항목 ${readyCount}/${readyTotal}
      ${hasMissing ? '<span style="color:var(--warn);font-weight:900"> · 누락 항목은 마켓 전송 전 보강 필요</span>' : '<span style="color:var(--ok);font-weight:900"> · 기본 등록값 준비됨</span>'}
    </div>
    ${saveVerify ? `<div class="factory-small" style="margin-top:6px;color:${saveVerify.ok ? 'var(--ok)' : 'var(--warn)'};font-weight:900">
      Cafe24 저장검증: ${escapeHtml(saveVerify.value || (saveVerify.ok ? '반영완료' : '확인 필요'))}${saveVerify.detail ? ` · ${escapeHtml(saveVerify.detail)}` : ''}
    </div>` : ''}
    ${sync.status ? `<div class="factory-small" style="margin-top:6px;color:var(--text-m)">${escapeHtml(sync.status)}</div>` : ''}
    ${renderFactoryOpenMarketOriginSummary(baseDraft)}
    ${showFinalRegistration ? renderFactoryFinalRegistrationPanel(factory, baseDraft, {
      renderCache,
      createModel: options.createModel,
      cafe24Model: options.cafe24Model,
      detailModel: options.detailModel,
      basicInfoModel: options.basicInfoModel,
    }) : ''}
    ${renderFactoryMarketPlusChannelProfileSummary(sync)}
    ${renderFactoryMarketPlusActionStatus(sync, baseDraft)}
    ${renderFactoryOpenMarketChecklist(directMode ? baseDraft.checklist : marketPlus.checklist)}
    ${directMode ? `<div class="factory-cafe24-save-note" style="margin-top:10px">고급 직접 API 모드입니다. 이 경로는 마켓별 판매자 인증값, 카테고리/배송/반품/옵션 변환이 모두 확인된 경우에만 실제 전송할 수 있습니다.</div>` : ''}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;margin-top:12px">
      ${factoryOpenMarketChannels(factory).map(channel => {
        const channelStatus = sync.channelStatus?.[channel.id] || {};
        const draft = sync.drafts?.[channel.id] || null;
        const dryRun = sync.dryRuns?.[channel.id] || null;
        const connected = !!channelStatus.connected;
        const endpointReady = !!channelStatus.createEndpointId;
        const credentialReady = !!channelStatus.credentialReady;
        const validationReady = !!channelStatus.validationAdapterReady || !!channelStatus.directRegisterRoute || !!channelStatus.createEndpointId;
        const liveReady = !!channelStatus.liveAdapterReady;
        const liveBlockReason = factoryOpenMarketLiveBlockReason(channelStatus, dryRun);
        const statusColor = directMode ? (!connected ? 'var(--warn)' : (credentialReady && liveReady ? 'var(--ok)' : 'var(--warn)')) : 'var(--ok)';
        const borderColor = directMode
          ? (connected ? (credentialReady && liveReady ? 'rgba(34,197,94,.32)' : 'rgba(245,158,11,.35)') : 'rgba(148,163,184,.22)')
          : 'rgba(34,197,94,.24)';
        const canDryRun = !!draft && (validationReady || endpointReady || channelStatus.directRegisterRoute);
        const canSend = directMode && !!draft && connected && endpointReady && credentialReady && liveReady;
        const canMarketPlusStart = !directMode && selected.has(channel.id) && !!baseDraft.productNo;
        return `<div style="border:1px solid ${borderColor};background:${selected.has(channel.id) ? 'rgba(99,102,241,.09)' : 'rgba(2,6,23,.35)'};border-radius:12px;padding:11px;min-width:0">
          <label style="display:flex;align-items:center;gap:8px;font-weight:900;color:var(--text);font-size:13px">
            <input type="checkbox" data-open-market-toggle="${escAttr(channel.id)}" ${selected.has(channel.id) ? 'checked' : ''}>
            ${escapeHtml(channel.label)}
          </label>
          <div class="factory-small" style="margin-top:6px;color:${statusColor}">
            ${directMode
              ? (connected ? `직접 API 상태: ${escapeHtml(channelStatus.connectorName || channelStatus.adapterLabel || channelStatus.connectorId || '')}` : '직접 API 상태 없음')
              : 'Cafe24 마켓플러스에서 이 마켓 상품 보내기 관리'}
          </div>
          <div class="factory-small" style="margin-top:4px;color:${directMode && credentialReady && liveReady ? 'var(--ok)' : 'var(--text-m)'}">${escapeHtml(directMode ? (channelStatus.credentialNote || channel.note) : 'Cafe24 상품 데이터가 정확하면 마켓플러스 쪽에서 마켓별 노출/판매/연동을 이어갈 수 있습니다.')}</div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
            <span class="api-badge">상품명 ${baseDraft.productName ? '준비' : '누락'}</span>
            <span class="api-badge">옵션 ${baseDraft.optionCount}개</span>
            <span class="api-badge">상세 ${baseDraft.hasDetailPage ? '준비' : '확인'}</span>
            ${directMode && connected ? `<span class="api-badge">검증 ${validationReady ? '가능' : '필요'}</span><span class="api-badge">인증 ${credentialReady ? '확인' : '필요'}</span><span class="api-badge">live ${liveReady ? '가능' : '차단'}</span>` : '<span class="api-badge">Cafe24 기준</span>'}
          </div>
          ${draft ? `<div class="factory-small" style="margin-top:7px;color:var(--text)">준비값: ${escapeHtml(draft.productName || '상품명 없음')} · ${escapeHtml(draft.price || '가격 없음')}원</div>` : `<div class="factory-small" style="margin-top:7px;color:var(--text-m)">아직 이 마켓용 준비값이 없습니다.</div>`}
          ${dryRun ? `<div class="factory-small" style="margin-top:5px;color:${dryRun.ok ? 'var(--ok)' : 'var(--warn)'}">dry-run: ${escapeHtml(dryRun.message || (dryRun.ok ? '검증 완료' : '확인 필요'))}</div>
            ${Array.isArray(dryRun.missingSecrets) && dryRun.missingSecrets.length ? `<div class="factory-small" style="margin-top:3px;color:var(--warn)">인증 누락 ${dryRun.missingSecrets.length}개</div>` : ''}
            ${Array.isArray(dryRun.warnings) && dryRun.warnings.length ? `<div class="factory-small" style="margin-top:3px;color:var(--text-m)">검증 경고: ${escapeHtml(dryRun.warnings.slice(0, 2).join(' · '))}${dryRun.warnings.length > 2 ? ` 외 ${dryRun.warnings.length - 2}개` : ''}</div>` : ''}` : ''}
          <div class="factory-stage-actions" style="margin-top:9px">
            <button class="btn-sm" data-open-market-build="${escAttr(channel.id)}" title="${escAttr(channel.label)} 기준 마켓플러스 준비값을 다시 만듭니다.">준비값 만들기</button>
            <button class="btn-sm" data-open-market-dryrun="${escAttr(channel.id)}" ${disabledAttr(!canDryRun, !draft ? '먼저 준비값을 만들어주세요.' : 'API Hub 검증 경로가 확인되지 않았습니다.')} title="실제 판매 등록 없이 API Hub의 채널별 payload 변환/필수값 검증만 실행합니다.">dry-run 검증</button>
            <button class="btn-sm ${directMode ? (canSend ? 'primary' : '') : (canMarketPlusStart ? 'primary' : '')}" data-open-market-send="${escAttr(channel.id)}" ${disabledAttr(directMode ? !canSend : !canMarketPlusStart, directMode ? (!draft ? '먼저 등록 초안을 만들어주세요.' : (!connected ? 'API Hub에 이 마켓의 판매자 등록 경로가 없습니다.' : (!endpointReady ? '판매 등록 endpoint가 확인되지 않았습니다.' : (!credentialReady ? '판매자 API 인증값/상태 확인이 필요합니다.' : '실전송 어댑터가 아직 live 가능 상태가 아닙니다.')))) : (!selected.has(channel.id) ? '이 채널을 먼저 선택해주세요.' : '먼저 Cafe24 상품번호가 필요합니다. 방울수저집test를 불러오거나 Cafe24 상품을 등록/확정하세요.'))} title="${directMode ? '판매자 API 인증값과 live 전송 어댑터가 모두 확인된 경우에만 실제 전송합니다.' : 'Cafe24 마켓플러스 상품 보내기 준비값을 고정하고 관리자 화면으로 넘어갑니다. 실제 마켓 상품 생성 성공 여부는 마켓플러스 결과로 확인해야 합니다.'}">${directMode ? '직접 전송' : '상품 보내기 절차 시작'}</button>
          </div>
          <div class="factory-small" style="margin-top:5px;color:${directMode ? (credentialReady && liveReady ? 'var(--ok)' : 'var(--warn)') : 'var(--text-m)'}">
            ${directMode
              ? (credentialReady && liveReady ? '실전송 조건 확인' : `실전송 차단: ${escapeHtml(liveBlockReason)}`)
              : '권장 경로: Cafe24 저장 후 마켓플러스 관리자에서 상품 보내기'}
          </div>
        </div>`;
      }).join('')}
    </div>
    ${logItems.length ? `<div style="border-top:1px solid var(--line);margin-top:12px;padding-top:10px">
      <div class="factory-small" style="font-weight:900;color:var(--text)">마켓 연동 로그</div>
      ${logItems.map(log => `<div class="factory-small" style="margin-top:4px;color:${log.type === 'error' ? 'var(--err)' : (log.type === 'ok' ? 'var(--ok)' : 'var(--text-m)')}">${escapeHtml(log.time)} · ${escapeHtml(log.message)}</div>`).join('')}
    </div>` : ''}
  </div>`;
}

function factoryStageRunBlockReason(def, factory, selectedInputs = [], assets = []) {
  const stage = factory.stages[def.id] || {};
  if (stage.status === 'running') return '현재 단계가 이미 실행 중입니다.';
  const productTerm = cleanDbSearchTerm(
    factory.product?.productName ||
    state.productName ||
    factory.product?.naturalHint ||
    ''
  );
  const productPreview = factoryProductPreview(factory);
  const hasProductImage = !!productPreview || !!state.imagePreview || (state.analysisImages || []).some(item => item?.dataUrl || item?.image);
  const hasSelectedInput = selectedInputs.some(asset => factoryAssetDisplayImage(asset));
  const hasUsedStageAsset = assets.some(asset => asset?.used && (factoryAssetDisplayImage(asset) || asset.html));

  if (def.id === 'db' && !productTerm) {
    return '제품명을 먼저 입력해주세요. 이미지 단독 판독은 AI 분석에서 먼저 실행할 수 있습니다.';
  }
  if (['hero', 'cuts'].includes(def.id) && !hasProductImage && !hasSelectedInput) {
    return '입력 슬롯에 이미지가 없고 제품 사진도 없습니다.';
  }
  if (def.id === 'size') {
    if (!hasProductImage && !hasSelectedInput) return '사이즈컷에 사용할 제품 이미지가 필요합니다.';
    if (typeof factoryHasSizeFacts === 'function' && !factoryHasSizeFacts()) {
      return '확정 DB의 실제 사이즈가 없어서 자동 생성할 수 없습니다.';
    }
  }
  if (def.id === 'detail' && !factory.assets.some(asset => asset.used && factoryAssetHasCurrentProductPayload(asset, factory, { allowHtml: true }))) {
    return '상세페이지에 넣을 사용 선택 자산이 아직 없습니다.';
  }
  if (def.id === 'export' && !hasUsedStageAsset && !factory.assets.some(asset => factoryAssetHasCurrentProductPayload(asset, factory, { allowHtml: true }))) {
    return '저장할 생성 자산이 아직 없습니다.';
  }
  return '';
}

function renderFactoryStageDbSizeHint(def, factory) {
  if (def.id !== 'size') return '';
  const items = typeof factoryCollectDbSizeFieldModels === 'function'
    ? factoryCollectDbSizeFieldModels(factory)
    : [];
  const drafts = typeof factoryDbSizeDrafts === 'function' ? factoryDbSizeDrafts(factory) : {};
  const filled = items.filter(item => item.value).length;
  const hasMissingRequired = items.some(item => item.required && !item.value);
  return `<div style="border:1px solid ${hasMissingRequired ? 'rgba(239,68,68,.45)' : filled ? 'rgba(34,197,94,.35)' : 'rgba(245,158,11,.35)'};background:${hasMissingRequired ? 'rgba(239,68,68,.08)' : filled ? 'rgba(34,197,94,.08)' : 'rgba(245,158,11,.08)'};border-radius:10px;padding:10px 12px;margin:10px 0">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px">
      <div style="font-size:12px;font-weight:900;color:${hasMissingRequired ? 'var(--danger)' : filled ? 'var(--ok)' : 'var(--warn)'}">0단계 DB에서 공급되는 사이즈</div>
      <div style="font-size:11px;color:var(--text-dim)">${filled ? `${filled}/${items.length}개 확인` : '사이즈 값 대기'}</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px">
      ${items.map(item => {
        const draftValue = drafts?.[item.fieldId] ? String(drafts[item.fieldId].value || '') : '';
        return item.value
        ? `<div style="border:1px solid rgba(34,197,94,.28);background:rgba(15,23,42,.36);border-radius:8px;padding:8px;min-width:0">
            <div style="font-size:11px;color:var(--text-m);font-weight:800">${escapeHtml(item.label)}</div>
            <div style="font-size:15px;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(item.value)}</div>
            <div style="font-size:10px;color:var(--ok);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">출처: ${escapeHtml(item.source || 'DB')}</div>
          </div>`
        : `<div style="display:block;border:1px solid ${item.required ? 'rgba(239,68,68,.55)' : 'rgba(245,158,11,.35)'};background:${item.required ? 'rgba(127,29,29,.18)' : 'rgba(245,158,11,.08)'};border-radius:8px;padding:8px;min-width:0">
            <span style="display:block;font-size:11px;color:${item.required ? 'var(--danger)' : 'var(--warn)'};font-weight:900;margin-bottom:5px">${escapeHtml(item.label)} ${item.required ? '필수 입력' : '값 없음'}</span>
            <input class="input" data-factory-size-manual="${escAttr(item.fieldId)}" value="${escAttr(draftValue)}" placeholder="${escAttr(item.placeholder)}" style="min-height:34px">
            <button class="btn-sm success" type="button" data-factory-size-manual-commit="${escAttr(item.fieldId)}" style="margin-top:6px;width:100%">이 값 확인</button>
            <div class="factory-small" style="margin-top:4px">입력 중에는 칸을 유지하고, 확인을 눌러야 필수값 완료로 처리됩니다.</div>
          </div>`;
      }).join('')}
    </div>
    ${hasMissingRequired
      ? `<div style="font-size:11px;color:var(--danger);font-weight:800;margin-top:8px">가로/세로가 없으면 사이즈컷 자동 생성은 수동 입력 대기 상태로 멈춥니다. 입력한 뒤 각 칸의 확인 버튼을 눌러야 완성 DB와 저장 상태에 반영됩니다.</div>`
      : ''}
  </div>`;
}

function factoryStageMessageForCurrentProduct(stage = {}, factory = factoryRuntimeReadFactory()) {
  const message = String(stage.message || '').trim();
  if (!message) return '';
  const explicitKey = factoryNormalizeIdentityText(factoryExplicitIdentityFromText(message));
  const identityKey = factoryIdentityKey(factory) || factoryNormalizeIdentityText(factory?.product?.productName || state.productName || '');
  if (explicitKey && identityKey && !factoryIdentityKeysCompatible(explicitKey, identityKey)) return '';
  return message;
}

function factoryOptionColorImagesDisabled() {
  return typeof optionSorterColorImagesDisabled === 'function'
    ? optionSorterColorImagesDisabled(state.optionSorter)
    : (state?.optionSorter?.optionColorImageUsage || 'use') === 'none';
}

function renderFactoryOptionColorControls(factory = factoryRuntimeReadFactory(), options = {}) {
  const disabled = factoryOptionColorImagesDisabled();
  const optionAssets = typeof factoryUsableAssetsForStage === 'function'
    ? factoryUsableAssetsForStage('options', factory)
    : factoryAssetsForStage('options', factory);
  const selectedCount = optionAssets.filter(asset => asset.used).length;
  const compact = options.compact === true;
  const context = options.context || (compact ? 'automation' : 'stage');
  const title = compact ? '색상이미지 처리' : '색상이미지 진행 방식';
  const statusText = disabled
    ? '색상이미지 없이 진행 중입니다. 색상옵션 섹션은 섹션설정과 상세페이지 배치에서 빠집니다.'
    : (selectedCount
      ? `직접 넣거나 가져온 색상이미지 ${selectedCount}개가 사용 선택되어 있습니다.`
      : '색상이미지를 직접 넣거나 옵션분류기 결과를 가져와 사용할 수 있습니다.');
  return `<div data-factory-option-color-panel="${escAttr(context)}" style="border:1px solid ${disabled ? 'rgba(245,158,11,.45)' : 'rgba(99,102,241,.30)'};background:${disabled ? 'rgba(245,158,11,.07)' : 'rgba(99,102,241,.055)'};border-radius:10px;padding:10px 12px;margin:${compact ? '0 0 8px' : '10px 0 12px'}">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap">
      <div style="min-width:0">
        <div style="font-size:13px;font-weight:950;color:${disabled ? 'var(--warn)' : 'var(--primary-h)'}">${escapeHtml(title)}</div>
        <div class="factory-small" style="margin-top:4px;color:var(--text);line-height:1.55">${escapeHtml(statusText)}</div>
      </div>
      <div class="factory-automation-actions" style="margin:0;justify-content:flex-end">
        <button class="btn-sm ${!disabled ? 'success' : ''}" type="button" data-factory-color-image-usage="use" title="색상이미지를 상세페이지 색상옵션 섹션에 사용할 수 있게 합니다.">색상이미지 사용</button>
        <button class="btn-sm ${disabled ? 'danger' : ''}" type="button" data-factory-color-image-usage="none" title="색상옵션 섹션과 기존 색상이미지 배치를 상세페이지 구성에서 제외합니다.">색상이미지 없이 진행</button>
        <button class="btn-sm" type="button" data-factory-sync-db-options title="확정 DB의 색상/옵션 정보를 옵션분류기 입력으로 보냅니다.">DB 옵션 가져오기</button>
        <button class="btn-sm" type="button" data-factory-sync-option-results title="옵션분류기에서 완성한 색상이미지를 현재 작업으로 가져옵니다.">옵션 결과 가져오기</button>
        <button class="btn-sm primary" type="button" data-factory-option-color-upload title="완성된 색상이미지/옵션표 파일을 직접 넣고 사용 선택합니다.">색상이미지 직접넣기</button>
        <input type="file" data-factory-option-color-file accept="image/*" multiple style="display:none">
      </div>
    </div>
    ${typeof renderOptionGroupShotPanel === 'function'
      ? renderOptionGroupShotPanel(state.optionSorter, { context: 'factory', compact: true })
      : ''}
  </div>`;
}

function factoryStagePromptCurrentScope(factory = factoryRuntimeReadFactory(), stageId = '') {
  const normalizedStage = typeof factoryNormalizeStageScope === 'function'
    ? (factoryNormalizeStageScope(stageId) || String(stageId || '').trim())
    : String(stageId || '').trim();
  const currentRunId = String(
    (typeof factoryCurrentWorkflowRunId === 'function' ? factoryCurrentWorkflowRunId(factory) : '') ||
    factory?.product?.currentRunId ||
    factory?.product?.generationRunId ||
    ''
  ).trim();
  const productKey = typeof factoryCurrentProductKey === 'function'
    ? factoryCurrentProductKey(factory)
    : factoryNormalizeIdentityText(factory?.product?.productName || state.productName || '');
  const inputImageFingerprint = String(
    typeof factoryCurrentInputImageFingerprint === 'function'
      ? factoryCurrentInputImageFingerprint(factory)
      : ''
  ).trim();
  return {
    currentRunId,
    productKey,
    inputImageFingerprint,
    stageId: normalizedStage,
    scopeKey: [
      currentRunId || 'no-run',
      productKey || 'no-product',
      inputImageFingerprint || 'no-image',
      normalizedStage || 'stage',
    ].join('::'),
  };
}

function factoryStagePromptSavedScope(stage = {}) {
  const saved = stage?.promptScope && typeof stage.promptScope === 'object' ? stage.promptScope : {};
  const stageId = typeof factoryNormalizeStageScope === 'function'
    ? (factoryNormalizeStageScope(saved.stageId || stage.promptStageId || '') || String(saved.stageId || stage.promptStageId || '').trim())
    : String(saved.stageId || stage.promptStageId || '').trim();
  return {
    currentRunId: String(saved.currentRunId || stage.promptCurrentRunId || '').trim(),
    productKey: String(saved.productKey || stage.promptProductKey || '').trim(),
    inputImageFingerprint: String(saved.inputImageFingerprint || stage.promptInputImageFingerprint || '').trim(),
    stageId,
    scopeKey: String(saved.scopeKey || stage.promptScopeKey || '').trim(),
  };
}

function factoryStagePromptMatchesCurrentWork(factory = factoryRuntimeReadFactory(), stageId = '', stage = null) {
  const targetStage = stage || factory?.stages?.[stageId] || {};
  const prompt = String(targetStage?.prompt || '');
  if (!prompt.trim()) return true;
  const current = factoryStagePromptCurrentScope(factory, stageId);
  const saved = factoryStagePromptSavedScope(targetStage);
  const hasCurrentWork = !!(current.currentRunId || current.productKey || current.inputImageFingerprint);
  const hasSavedScope = !!(saved.scopeKey || saved.currentRunId || saved.productKey || saved.inputImageFingerprint || saved.stageId);
  if (hasCurrentWork && !hasSavedScope) return false;
  if (saved.scopeKey && saved.scopeKey !== current.scopeKey) return false;
  if (current.currentRunId && (!saved.currentRunId || saved.currentRunId !== current.currentRunId)) return false;
  if (current.productKey && (!saved.productKey || saved.productKey !== current.productKey)) return false;
  if (current.inputImageFingerprint && (!saved.inputImageFingerprint || saved.inputImageFingerprint !== current.inputImageFingerprint)) return false;
  if (current.stageId && (!saved.stageId || saved.stageId !== current.stageId)) return false;
  return true;
}

function factoryStagePromptForCurrentWork(factory = factoryRuntimeReadFactory(), stageId = '') {
  const stage = factory?.stages?.[stageId] || {};
  return factoryStagePromptMatchesCurrentWork(factory, stageId, stage) ? String(stage.prompt || '') : '';
}

function factoryStagePromptExcludedForCurrentWork(factory = factoryRuntimeReadFactory(), stageId = '') {
  const stage = factory?.stages?.[stageId] || {};
  return !!String(stage.prompt || '').trim() && !factoryStagePromptMatchesCurrentWork(factory, stageId, stage);
}

function factorySetStagePromptForCurrentWork(factory, stageId = '', value = '') {
  if (!factory || typeof factory !== 'object') return '';
  factory.stages = factory.stages && typeof factory.stages === 'object' ? factory.stages : {};
  factory.stages[stageId] = factory.stages[stageId] && typeof factory.stages[stageId] === 'object' ? factory.stages[stageId] : {};
  const stage = factory.stages[stageId];
  const text = String(value || '');
  stage.prompt = text;
  if (text.trim()) {
    const scope = factoryStagePromptCurrentScope(factory, stageId);
    stage.promptScope = scope;
    stage.promptCurrentRunId = scope.currentRunId;
    stage.promptProductKey = scope.productKey;
    stage.promptInputImageFingerprint = scope.inputImageFingerprint;
    stage.promptStageId = scope.stageId;
    stage.promptScopeKey = scope.scopeKey;
  } else {
    delete stage.promptScope;
    delete stage.promptCurrentRunId;
    delete stage.promptProductKey;
    delete stage.promptInputImageFingerprint;
    delete stage.promptStageId;
    delete stage.promptScopeKey;
  }
  return text;
}

function factoryPreviewOnlySizeAssets(factory = factoryRuntimeReadFactory()) {
  const currentProductKey = String(typeof factoryCurrentProductKey === 'function'
    ? factoryCurrentProductKey(factory)
    : '').trim();
  const currentSourceKey = String(typeof cutsCurrentSourceImageKey === 'function'
    ? cutsCurrentSourceImageKey('size')
    : '').trim();
  if (!currentProductKey || !currentSourceKey) return [];
  return (state.cuts?.sizePrompts || []).map((cut, index) => {
    const assetId = String(cut?.assetId || cut?.resultAssetId || cut?.metadata?.assetId || cut?.metadata?.resultAssetId || '').trim();
    const sourceKey = String(typeof cutPromptSourceImageKey === 'function' ? cutPromptSourceImageKey(cut) : '').trim();
    if (!assetId || !sourceKey || sourceKey !== currentSourceKey || !factoryCutPromptMatchesStage(cut, 'size')) return null;
    const promptProductKey = String(typeof cutPromptProductKey === 'function' ? cutPromptProductKey(cut) : '').trim();
    if (!promptProductKey) return null;
    const productMatches = (
      typeof factoryJobProductKeysCompatible === 'function'
        ? factoryJobProductKeysCompatible(promptProductKey, currentProductKey)
        : promptProductKey === currentProductKey
    );
    if (!productMatches) return null;
    const image = factoryCutPromptResultDisplaySrc(cut, 'size', {
      requireCurrent: true,
      requireJob: false,
      factory,
    });
    if (!image) return null;
    return {
      id: assetId,
      stageId: 'size',
      title: cut.label || `사이즈컷 ${index + 1}`,
      prompt: cut.prompt || '',
      image,
      type: 'image',
      archived: true,
      previewOnly: true,
      metadata: { source: '보관된 사이즈컷', previewOnly: true },
    };
  }).filter(Boolean);
}

function renderFactoryStageCard(def, factory) {
  const stage = factory.stages[def.id] || {};
  const promptValue = factoryStagePromptForCurrentWork(factory, def.id);
  const promptExcluded = factoryStagePromptExcludedForCurrentWork(factory, def.id);
  const rawAssets = factoryAssetsForStage(def.id, factory);
  const currentAssets = ['hero', 'size', 'options', 'cuts'].includes(def.id)
    ? factoryUsableAssetsForStage(def.id, factory)
    : rawAssets.filter(asset => factoryAssetHasCurrentProductPayload(asset, factory, { allowHtml: true }));
  const previewOnlyAssets = def.id === 'size'
    ? factoryPreviewOnlySizeAssets(factory).filter(candidate => !currentAssets.some(asset => asset.id === candidate.id))
    : [];
  const assets = [...currentAssets, ...previewOnlyAssets];
  const missingAssetCount = rawAssets.length - currentAssets.length;
  const used = assets.filter(asset => asset.used).length;
  const resultStage = ['hero', 'size', 'options', 'cuts', 'detail'].includes(def.id);
  const doneWithoutSelectableAsset = resultStage && stage.status === 'done' && assets.length === 0;
  const effectiveStatus = doneWithoutSelectableAsset ? 'blocked' : stage.status;
  const statusClass = factoryStageStatusClass(effectiveStatus);
  const statusLabel = doneWithoutSelectableAsset
    ? (rawAssets.length ? '원본 없음' : '선택 대기')
    : (FACTORY_STAGE_STATUS_LABELS[stage.status] || '대기');
  const isActive = factory.activeStage === def.id;
  const selectedInputs = (stage.inputAssetIds || [])
    .map(id => factory.assets.find(asset => asset.id === id))
    .filter(Boolean);
  const automationCutsSummary = def.id === 'cuts' && typeof factoryAutomationCustomCutPromptSummary === 'function'
    ? factoryAutomationCustomCutPromptSummary()
    : null;
  const displayTargetCount = automationCutsSummary?.count || stage.targetCount || 1;
  const stageMessage = doneWithoutSelectableAsset
    ? (rawAssets.length
      ? `완료 기록 ${rawAssets.length}개는 있지만 현재 제품에서 고를 이미지 원본이 없습니다. 재생성하거나 직접 이미지를 넣어주세요.`
      : '완료로 볼 선택 이미지가 아직 없습니다. 현재 단계 생성을 실행해주세요.')
    : factoryStageMessageForCurrentProduct(stage, factory);
  const extraControls = ['hero', 'size', 'options', 'cuts'].includes(def.id)
    ? `<div class="factory-input-row">
        <div>
          <label class="label">목표 생성 수</label>
          <input class="input" type="number" min="1" max="30" data-factory-stage-target="${escAttr(def.id)}" value="${displayTargetCount}">
        </div>
        <div>
          <label class="label">프리셋/추가 지시</label>
          <textarea class="textarea" data-factory-stage-prompt="${escAttr(def.id)}" rows="3" placeholder="${def.id === 'options' ? '옵션표는 기존 옵션 분류기 설정을 우선 사용합니다.' : '비워두면 기본 프리셋을 사용합니다.'}">${escapeHtml(promptValue)}</textarea>
          ${promptExcluded ? '<div class="factory-small" style="margin-top:6px;color:var(--warn);line-height:1.45">이전 작업 프롬프트는 현재 작업 기준과 달라 생성 기본값에서 제외했습니다.</div>' : ''}
        </div>
      </div>`
    : '';
  const optionColorControls = def.id === 'options' ? renderFactoryOptionColorControls(factory) : '';
  const drop = ['hero', 'size', 'cuts', 'detail'].includes(def.id)
    ? renderFactoryDrop(def.id, `${def.shortLabel} 입력 슬롯`, '대표/생성 자산을 끌어오거나 아래 버튼으로 보낼 수 있습니다.', selectedInputs)
    : '';
  const runBlockReason = factoryStageRunBlockReason(def, factory, selectedInputs, assets);
  return `<article class="factory-stage-card ${isActive ? 'active' : ''} ${statusClass}" id="factoryStageCard_${escAttr(def.id)}">
    <div class="factory-stage-head">
      <span class="factory-stage-no">${Number(def.no) + 1}</span>
      <div>
        <div class="factory-stage-title">${escapeHtml(def.label)} ${renderFactoryApiBadges(def.apiKeys)}</div>
        <div class="factory-stage-desc">${escapeHtml(def.desc)}</div>
      </div>
      <span class="factory-stage-status ${statusClass}">${escapeHtml(statusLabel)}</span>
    </div>
    <div class="factory-stage-body">
      <div class="factory-stage-counts">
        <div class="factory-count">목표<strong>${displayTargetCount}</strong></div>
        <div class="factory-count">생성/확보<strong>${assets.length}</strong></div>
        <div class="factory-count">사용 선택<strong>${used}</strong></div>
      </div>
      ${renderFactoryStageDbSizeHint(def, factory)}
      ${optionColorControls}
      ${drop}
      ${extraControls}
      ${renderFactoryStageResults(def, factory, assets, missingAssetCount)}
      ${renderFactoryStageBridgeInfo(def, stage)}
      ${stageMessage ? `<div class="factory-small">${escapeHtml(stageMessage)}</div>` : ''}
    </div>
    <div class="factory-stage-actions">
      <button class="btn-sm" type="button" data-factory-run-stage="${escAttr(def.id)}" onclick="return factoryRunStageButtonInline(this,event)" ${disabledAttr(!!runBlockReason, runBlockReason)}><span class="material-icons-outlined" style="font-size:14px">play_arrow</span>현재 단계 생성</button>
      <button class="btn-sm" data-factory-next-stage="${escAttr(def.id)}"><span class="material-icons-outlined" style="font-size:14px">east</span>선택 결과로 다음 단계</button>
      ${renderFactoryStageBridgeActions(def)}
    </div>
  </article>`;
}

function renderFactoryStageResults(def, factory, assets = [], missingAssetCount = 0) {
  if (!['hero', 'size', 'options', 'cuts', 'detail'].includes(def.id)) return '';
  const visibleAssets = assets.slice(0, 8);
  if (!visibleAssets.length) {
    return `<div class="factory-stage-results empty">
      <div class="factory-small">${missingAssetCount
        ? `이전 기록 ${missingAssetCount}개는 현재 제품과 맞지 않거나 이미지 원본이 없어 기본 후보와 분리했습니다. 필요한 컷은 다시 생성하거나 직접 이미지를 넣어주세요.`
        : '아직 이 단계 결과가 없습니다. 원래 메뉴에서 만든 결과를 가져오거나 현재 단계 생성을 실행하면 여기에 썸네일로 표시됩니다.'}</div>
    </div>`;
  }
  const previewOnly = visibleAssets.every(asset => asset.previewOnly === true);
  return `<div class="factory-stage-results">
    <div class="factory-stage-results-head">
      <b>결과 전광판</b>
      <span>${visibleAssets.length}${assets.length > visibleAssets.length ? ` / ${assets.length}` : ''}개 · ${previewOnly ? '보관 원본은 크게 보기만 가능합니다.' : '드래그해서 다른 입력 슬롯으로 보낼 수 있습니다.'}</span>
    </div>
    <div class="factory-stage-result-grid">
      ${visibleAssets.map((asset, index) => {
        const meta = asset.metadata || {};
        const title = factoryVisibleAssetTitle(asset.title || `${def.label} 결과`);
        const assetImage = factoryAssetDisplayImage(asset);
        const priorityAttr = index < FACTORY_LIGHT_IMAGE_PRIORITY_LIMIT ? 'data-factory-light-priority="1" ' : '';
        const promptRaw = String(asset.prompt || meta.prompt || meta.promptText || '').trim();
        const promptLine = promptRaw
          ? promptRaw.split(/\r?\n/).map(v => v.trim()).filter(Boolean)[0]
          : '';
        const promptPreview = promptLine || '프롬프트 미기입';
        return `<article class="factory-stage-result-card ${asset.used ? 'used' : ''}" draggable="${asset.previewOnly ? 'false' : 'true'}" data-factory-asset-id="${escAttr(asset.id)}">
          <button class="factory-stage-result-thumb" type="button" data-factory-preview-asset="${escAttr(asset.id)}" title="크게 보기">
            ${assetImage ? renderFactoryLightImage(assetImage, title, `${priorityAttr}data-factory-asset-img="${escAttr(asset.id)}"`) : `<span>${escapeHtml(asset.type === 'html' ? 'HTML 상세' : '이미지 없음')}</span>`}
          </button>
          <div class="factory-stage-result-info">
            <div class="factory-stage-result-title">${escapeHtml(title)}</div>
            <div class="factory-stage-result-prompt" title="${escAttr(promptPreview)}">${escapeHtml(promptPreview)}</div>
            <div class="factory-stage-result-meta">${escapeHtml([meta.presetLabel, meta.modelLabel || meta.model, asset.archived ? '저장됨' : ''].filter(Boolean).join(' · ') || '생성 결과')}</div>
          </div>
          <div class="factory-stage-result-actions">
            ${asset.previewOnly
              ? '<button class="btn-sm" type="button" disabled title="현재 단계 작업키와 분리된 보관 원본입니다.">보기 전용</button>'
              : `<button class="btn-sm ${asset.used ? 'success' : ''}" type="button" data-factory-asset-use="${escAttr(asset.id)}">${asset.used ? '선택됨' : '사용'}</button>`}
            <button class="btn-sm" type="button" data-factory-preview-asset="${escAttr(asset.id)}">크게</button>
          </div>
        </article>`;
      }).join('')}
    </div>
    ${assets.length > visibleAssets.length ? `<div class="factory-small">나머지 ${assets.length - visibleAssets.length}개는 아래 생성 자산 보관함에서 볼 수 있습니다.</div>` : ''}
    ${missingAssetCount ? `<div class="factory-small" style="color:var(--warn)">이전 기록 ${missingAssetCount}개는 현재 제품과 맞지 않거나 이미지 원본이 없어 기본 후보와 분리했습니다.</div>` : ''}
  </div>`;
}

function renderFactoryAssetCard(asset) {
  const def = factoryStageDef(asset.stageId);
  const meta = asset.metadata || {};
  const assetImage = factoryAssetDisplayImage(asset);
  const canPlaceInDetail = typeof factoryAssetCanPlaceInDetailSection === 'function'
    ? factoryAssetCanPlaceInDetailSection(asset)
    : asset.stageId !== 'hero';
  const metaLine = [
    def.label,
    meta.modelLabel || meta.model || '',
    meta.presetLabel || '',
    asset.archived ? '폴더 저장됨' : '',
  ].filter(Boolean).join(' · ');
  return `<article class="factory-asset-card ${asset.used ? 'used' : ''} ${asset.rejected ? 'rejected' : ''}" draggable="true" data-factory-asset-id="${escAttr(asset.id)}">
    <div class="factory-asset-thumb">
      ${assetImage ? renderFactoryLightImage(assetImage, asset.title, `data-factory-asset-img="${escAttr(asset.id)}"`) : `<code>${escapeHtml(asset.type === 'html' ? 'HTML 상세페이지' : '이미지 없음')}</code>`}
    </div>
    <div>
      <div class="factory-asset-title">${escapeHtml(asset.title)}</div>
      <div class="factory-asset-meta">${escapeHtml(metaLine || '생성 기록 없음')}</div>
    </div>
    <div class="factory-asset-actions">
      <button class="btn-sm" data-factory-asset-use="${escAttr(asset.id)}">${asset.used ? '사용 해제' : '사용'}</button>
      <button class="btn-sm" data-factory-asset-reject="${escAttr(asset.id)}">${asset.rejected ? '복구' : '폐기'}</button>
      <button class="btn-sm" data-factory-send="${escAttr(asset.id)}:hero">대표 입력</button>
      <button class="btn-sm" data-factory-send="${escAttr(asset.id)}:size">사이즈 입력</button>
      <button class="btn-sm" data-factory-send="${escAttr(asset.id)}:cuts">이미지컷 입력</button>
      ${canPlaceInDetail ? `<button class="btn-sm" data-factory-place="${escAttr(asset.id)}">상세 배치</button>` : '<span class="factory-small" style="align-self:center;color:var(--text-m)">상품 메인/썸네일용</span>'}
      <button class="btn-sm" data-factory-archive-asset="${escAttr(asset.id)}">폴더 저장</button>
    </div>
  </article>`;
}

function renderFactoryAssets(factory) {
  const rawAssets = (factory.assets || []).filter(asset => !asset.rejected);
  const stageUsableIds = new Map();
  const isStageUsableAsset = asset => {
    if (!['hero', 'size', 'options', 'cuts'].includes(asset?.stageId)) {
      return factoryAssetHasCurrentProductPayload(asset, factory, { allowHtml: true });
    }
    if (!stageUsableIds.has(asset.stageId)) {
      stageUsableIds.set(asset.stageId, new Set(factoryUsableAssetsForStage(asset.stageId, factory).map(item => item.id)));
    }
    return stageUsableIds.get(asset.stageId).has(asset.id);
  };
  const assets = rawAssets.filter(isStageUsableAsset);
  const missingAssetCount = rawAssets.length - assets.length;
  const expanded = !!factory.assetListExpanded;
  const perStageLimit = expanded ? Number.POSITIVE_INFINITY : 6;
  if (!assets.length) {
    return `<div class="factory-card"><div class="factory-small">${missingAssetCount
      ? `이전 생성 기록 ${missingAssetCount}개는 현재 제품과 맞지 않거나 이미지 원본이 없어 기본 보관함과 분리했습니다. 필요한 이미지는 다시 생성하거나 직접 넣어주세요.`
      : '아직 생성 자산이 없습니다. 위 공정에서 생성하면 여기에 카드로 쌓이고, 드래그해서 다른 공정 입력으로 보낼 수 있습니다.'}</div></div>`;
  }
  const stageDefs = FACTORY_STAGE_DEFS.filter(def => assets.some(asset => asset.stageId === def.id));
  const totalVisible = stageDefs.reduce((sum, def) => sum + Math.min(perStageLimit, assets.filter(asset => asset.stageId === def.id).length), 0);
  return `<div class="factory-card" style="margin-bottom:10px">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
      <div class="factory-small">보관함 ${assets.length}개 중 ${totalVisible}개 표시${missingAssetCount ? ` · 분리 ${missingAssetCount}개` : ''}</div>
      <button class="btn-sm" data-factory-toggle-assets type="button">${expanded ? '보관함 접기' : '보관함 전체 펼치기'}</button>
    </div>
  </div>
  ${stageDefs
    .map(def => {
      const stageAssets = assets.filter(asset => asset.stageId === def.id);
      const visibleAssets = stageAssets.slice(0, perStageLimit);
      return `<div class="factory-card">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px">
        <h4 style="margin:0">${escapeHtml(def.label)}</h4>
        <span class="factory-pill">${visibleAssets.length}${stageAssets.length > visibleAssets.length ? ` / ${stageAssets.length}` : ''}개</span>
      </div>
      <div class="factory-assets">${visibleAssets.map(renderFactoryAssetCard).join('')}</div>
      ${stageAssets.length > visibleAssets.length ? `<div class="factory-small" style="margin-top:8px">나머지 ${stageAssets.length - visibleAssets.length}개는 보관함 전체 펼치기를 누르면 표시됩니다.</div>` : ''}
    </div>`;
    }).join('')}`;
}

function renderFactoryGoalControls(factory) {
  const goal = factory.goalRun || {};
  const p = Math.max(0, Math.min(100, Number(goal.progress) || 0));
  const failed = factoryGoalRunHasFailure(goal, goal.currentStage || '');
  return `<section class="factory-section">
    <div class="factory-section-head">
      <div>
        <h3>goal 루프</h3>
        <p>목표 수량이 찰 때까지 부족한 공정을 반복합니다. 사이즈 DB 누락, API 실패, 색상 충돌 미확정은 자동으로 넘기지 않습니다.</p>
      </div>
      <div class="factory-toolbar">
        <button class="btn-sm" id="factoryStopGoal" ${disabledAttr(!goal.running, '실행 중인 goal 루프가 없습니다.')}>중단하고 검수</button>
        <button class="btn-primary" id="factoryRunGoal"><span class="material-icons-outlined" style="font-size:18px">loop</span>goal 루프 시작</button>
      </div>
    </div>
    <div class="factory-input-row">
      ${['hero','size','options','cuts','detail'].map(key => `<div>
        <label class="label">${escapeHtml(factoryStageLabel(key))} 목표</label>
        <input class="input" type="number" min="0" max="30" data-factory-goal-target="${key}" value="${Number(goal.targets?.[key] ?? 1)}">
      </div>`).join('')}
      <div>
        <label class="label">최대 반복</label>
        <input class="input" type="number" min="1" max="20" id="factoryGoalMaxLoops" value="${goal.maxLoops || 3}">
      </div>
      <div>
        <label class="label">루프 방식</label>
        <select class="input" id="factoryGoalMode">
          <option value="review" ${goal.mode !== 'auto' ? 'selected' : ''}>검수 후 다음 단계 진행</option>
          <option value="auto" ${goal.mode === 'auto' ? 'selected' : ''}>전체 자동 실행</option>
        </select>
      </div>
    </div>
    <div style="margin-top:12px" class="factory-progress ${failed ? 'failed' : ''}"><span style="--p:${p}%"></span></div>
    <div class="factory-small" style="margin-top:8px;color:${failed ? 'var(--danger)' : 'var(--text-m)'}">현재 단계: ${escapeHtml(goal.currentStage || '대기')} · ${failed ? `실패 ${p}% · ` : ''}반복 ${goal.loopCount || 0}/${goal.maxLoops || 3}${goal.failureReason ? ` · ${escapeHtml(goal.failureReason)}` : ''}</div>
  </section>`;
}


function factoryProjectHasFactory(project = {}) {
  if (project.factorySummary && typeof project.factorySummary === 'object') {
    return !!project.factorySummary.hasFactory;
  }
  const payload = project.payload || {};
  const factory = payload.factory || {};
  const product = factory.product || {};
  return payload.step === 'factory' ||
    !!product.productName ||
    !!product.imageBase64 ||
    !!(product.confirmedDb && Object.keys(product.confirmedDb || {}).length) ||
    !!(product.cafe24Candidates && product.cafe24Candidates.length) ||
    !!(factory.assets && factory.assets.length);
}

function factorySavedProjects() {
  const projects = Array.isArray(state.projects) ? state.projects : [];
  return projects.filter(factoryProjectHasFactory)
    .sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0));
}

function factoryCurrentWorkfileFallback() {
  const factory = state.factory && typeof state.factory === 'object' ? state.factory : {};
  const product = factory.product && typeof factory.product === 'object' ? factory.product : {};
  const locationLabel = typeof factoryProjectFileLocationLabel === 'function'
    ? String(factoryProjectFileLocationLabel() || '').trim()
    : '';
  const fileName = locationLabel || '';
  const fileBaseName = fileName.replace(/\.kuasangse$/i, '').trim();
  const name = String(
    state.currentProjectName ||
    product.productName ||
    state.productName ||
    fileBaseName ||
    '',
  ).trim();
  const projectId = String(state.currentProjectId || factory.workspace?.id || '').trim();
  const savedAt = Number(state.workfileLastSavedAt || factory.lastSavedAt || factory.workspace?.updatedAt || 0) || 0;
  const hasFactoryWork = !!(
    name ||
    fileName ||
    projectId ||
    savedAt ||
    product.imagePreview ||
    product.imageBase64 ||
    product.confirmedDb ||
    (Array.isArray(factory.assets) && factory.assets.length)
  );
  if (!hasFactoryWork) return null;

  let thumb = '';
  try {
    thumb = displayableImageSrc(factoryProductPreview(factory)) || '';
  } catch (_) {}
  let selectedCafe24 = {};
  try {
    selectedCafe24 = typeof factoryCafe24TargetCandidate === 'function'
      ? (factoryCafe24TargetCandidate(factory, { allowFallback: false }) || {})
      : {};
  } catch (_) {}
  const sectionContents = state.sectionContents && typeof state.sectionContents === 'object'
    ? state.sectionContents
    : {};
  const sectionImages = state.sectionImages && typeof state.sectionImages === 'object'
    ? state.sectionImages
    : {};
  const sectionIds = new Set([...Object.keys(sectionContents), ...Object.keys(sectionImages)]);
  const sectionOrder = Array.isArray(state.sectionOrder) ? state.sectionOrder.filter(Boolean) : [];
  const sectionTotal = sectionOrder.length || sectionIds.size;
  const sectionGenerated = Object.keys(sectionContents).filter(id => String(sectionContents[id] || '').trim()).length;
  const confirmedDb = product.confirmedDb && typeof product.confirmedDb === 'object' ? product.confirmedDb : {};
  const sync = factory.openMarketSync && typeof factory.openMarketSync === 'object' ? factory.openMarketSync : {};
  return {
    id: projectId || '__current-workfile__',
    name: name || '현재 작업파일',
    updatedAt: savedAt || null,
    source: 'current-workfile',
    fileName,
    factorySummary: {
      thumb,
      product: {
        productName: name || '현재 작업파일',
        hasImage: !!(thumb || product.imagePreview || product.imageBase64),
        imagePreview: thumb,
      },
      dbName: confirmedDb.product_name || confirmedDb.jname || confirmedDb.name || '',
      cafe24Name: factoryCandidateName(selectedCafe24, 'cafe24'),
      assetCount: Array.isArray(factory.assets) ? factory.assets.length : 0,
      sectionGenerated,
      sectionTotal,
      finalTarget: sync.finalTarget === 'cafe24_only' ? 'cafe24_only' : 'cafe24_openmarket',
    },
  };
}

function factoryRecentWorkfileProjects(limit = 4) {
  const count = Number.isFinite(Number(limit)) ? Math.max(0, Math.floor(Number(limit))) : 4;
  const projects = factorySavedProjects();
  if (projects.length) return projects.slice(0, count);
  const currentWorkfile = factoryCurrentWorkfileFallback();
  return currentWorkfile ? [currentWorkfile].slice(0, count) : [];
}

function factorySavedProjectProduct(project = {}) {
  return project.factorySummary?.product || project.payload?.factory?.product || {};
}

function factorySavedProjectThumb(project = {}) {
  if (project.factorySummary?.thumb) return project.factorySummary.thumb;
  const payload = project.payload || {};
  const product = factorySavedProjectProduct(project);
  if (product.imagePreview && product.imagePreview !== '__stored_in_indexeddb__') return product.imagePreview;
  if (product.imageBase64) return `data:${product.imageMime || 'image/png'};base64,${product.imageBase64}`;
  if (payload.imagePreview && payload.imagePreview !== '__stored_in_indexeddb__') return payload.imagePreview;
  if (payload.imageBase64) return `data:${payload.imageMime || 'image/png'};base64,${payload.imageBase64}`;
  return '';
}

function factorySavedProjectTitle(project = {}) {
  const payload = project.payload || {};
  const product = factorySavedProjectProduct(project);
  return project.name || payload.name || product.productName || payload.productName || '조립공장 작업';
}

function factorySavedProjectMeta(project = {}) {
  const summary = project.factorySummary || null;
  if (summary) {
    const updated = project.updatedAt ? new Date(project.updatedAt).toLocaleString('ko-KR') : '';
    return [
      summary.dbName ? `신화사 ${summary.dbName}` : '',
      summary.cafe24Name ? `Cafe24 ${summary.cafe24Name}` : '',
      Number(summary.assetCount || 0) ? `생성컷 ${summary.assetCount}개` : '',
      project.snapshotCount ? `버전 ${project.snapshotCount}개` : '',
      updated,
    ].filter(Boolean).join(' · ');
  }
  const payload = project.payload || {};
  const factory = payload.factory || {};
  const product = factory.product || {};
  const confirmedDb = product.confirmedDb || {};
  const selectedCafe24 = factory.product ? (factoryCafe24TargetCandidate(factory, { allowFallback: false }) || {}) : {};
  const dbName = confirmedDb.product_name || confirmedDb.jname || confirmedDb.name || '';
  const cafe24Name = factoryCandidateName(selectedCafe24, 'cafe24');
  const updated = project.updatedAt ? new Date(project.updatedAt).toLocaleString('ko-KR') : '';
  return [
    dbName ? `신화사 ${dbName}` : '',
    selectedCafe24 && Object.keys(selectedCafe24).length ? `Cafe24 ${cafe24Name}` : '',
    project.snapshotCount ? `버전 ${project.snapshotCount}개` : '',
    updated,
  ].filter(Boolean).join(' · ');
}

function factorySavedProjectSectionText(project = {}) {
  const summary = project.factorySummary || {};
  const generated = Number(summary.sectionGenerated || 0);
  const total = Number(summary.sectionTotal || 0);
  if (total) return `${generated}/${total}섹션`;
  return generated ? `${generated}섹션` : '섹션 없음';
}

function factorySavedProjectTargetText(project = {}) {
  const summary = project.factorySummary || {};
  return summary.finalTarget === 'cafe24_only' ? '카페24만' : '카페24+오픈마켓';
}

function factorySavedProjectBatchText(project = {}) {
  const status = project.batchStatus || {};
  if (!status.status) return '';
  const label = status.status === 'success' ? '일괄 성공' : status.status === 'running' ? '일괄 진행중' : '일괄 실패';
  const message = status.message ? ` · ${status.message}` : '';
  return `${label}${message}`;
}

function renderFactorySavedProjectCard(project = {}) {
  const thumb = factorySavedProjectThumb(project);
  const current = project.id && project.id === state.currentProjectId;
  const selectedIds = new Set(Array.isArray(state.factoryBatchSelectedIds) ? state.factoryBatchSelectedIds : []);
  const checked = selectedIds.has(project.id);
  const batchText = factorySavedProjectBatchText(project);
  const batchTone = project.batchStatus?.status === 'success'
    ? 'var(--ok)'
    : project.batchStatus?.status === 'failed'
      ? 'var(--err)'
      : 'var(--warn)';
  return `<article class="factory-saved-card ${current ? 'current' : ''}">
    <label style="display:flex;align-items:center;justify-content:center;min-width:22px" title="일괄등록 대상으로 선택">
      <input type="checkbox" data-factory-batch-project="${escAttr(project.id)}" ${checked ? 'checked' : ''} ${state.factoryBatchRunning ? 'disabled' : ''}>
    </label>
    <div class="factory-saved-thumb">
      ${thumb ? renderFactoryLightImage(thumb, factorySavedProjectTitle(project)) : '<span class="material-icons-outlined">inventory_2</span>'}
    </div>
    <div>
      <div class="factory-saved-title">${escapeHtml(factorySavedProjectTitle(project))}</div>
      <div class="factory-saved-meta">${escapeHtml(factorySavedProjectMeta(project) || '저장 정보 없음')}</div>
      <div class="factory-saved-meta" style="margin-top:4px">
        ${escapeHtml(factorySavedProjectSectionText(project))} · ${escapeHtml(factorySavedProjectTargetText(project))}
        ${project.factorySummary?.selectedChannelCount ? ` · 마켓 ${escapeHtml(project.factorySummary.selectedChannelCount)}개` : ''}
      </div>
      ${project.factorySummary?.finalRegistrationStatus ? `<div class="factory-saved-meta" style="margin-top:4px;color:var(--text)">최근 최종등록: ${escapeHtml(project.factorySummary.finalRegistrationStatus)}</div>` : ''}
      ${batchText ? `<div class="factory-saved-meta" style="margin-top:4px;color:${batchTone};font-weight:900">${escapeHtml(batchText)}</div>` : ''}
      <div class="factory-saved-meta" style="margin-top:8px;color:${current ? 'var(--primary-h)' : 'var(--text-m)'}">${current ? '현재 작업파일 · 개별 열기는 맨 위 작업파일 버튼 사용' : '일괄등록 대상으로만 선택 가능'}</div>
    </div>
  </article>`;
}

function renderFactoryRecentWorkfileCard(project = {}) {
  const thumb = factorySavedProjectThumb(project);
  const current = project.id && project.id === state.currentProjectId;
  const title = factorySavedProjectTitle(project);
  const isCurrentWorkfileFallback = project.source === 'current-workfile';
  return `<article class="factory-recent-workfile-card ${current ? 'current' : ''}" data-factory-recent-workfile-card data-project-id="${escAttr(project.id || '')}">
    <div class="factory-recent-workfile-thumb">
      ${thumb ? renderFactoryLightImage(thumb, title) : '<span class="material-icons-outlined">inventory_2</span>'}
    </div>
    <div class="factory-recent-workfile-body">
      <div class="factory-recent-workfile-title">${escapeHtml(title)}</div>
      <div class="factory-recent-workfile-meta">${escapeHtml(factorySavedProjectMeta(project) || '저장 정보 없음')}</div>
      <div class="factory-recent-workfile-meta">${escapeHtml(factorySavedProjectSectionText(project))} · ${escapeHtml(factorySavedProjectTargetText(project))}</div>
      ${isCurrentWorkfileFallback && project.fileName ? `<div class="factory-recent-workfile-meta">로컬 파일 · ${escapeHtml(project.fileName)}</div>` : ''}
      ${current ? '<span class="factory-recent-workfile-current">현재 작업파일</span>' : ''}
    </div>
    ${isCurrentWorkfileFallback
      ? (project.fileName
        ? `<button class="btn-sm factory-recent-workfile-open" type="button" data-factory-recent-open-file="1" aria-label="${escAttr(`${title} 작업파일 다시 열기`)}">파일 다시 열기</button>`
        : '<span class="factory-recent-workfile-current">현재 열림</span>')
      : `<button class="btn-sm factory-recent-workfile-open" type="button" data-factory-recent-load-project="${escAttr(project.id || '')}" aria-label="${escAttr(`${title} 작업파일 열기`)}">열기</button>`}
  </article>`;
}

function factoryRegistrationDateText(value) {
  return value ? new Date(value).toLocaleString('ko-KR') : '날짜 없음';
}

function factoryRegistrationTargetText(item = {}) {
  if (item.targetLabel) return item.targetLabel;
  return item.target === 'cafe24_only' ? '카페24만 등록' : '카페24 + 오픈마켓';
}

function factoryRegistrationImageThumb(ref = {}, alt = '이미지') {
  const label = ref?.label || alt;
  const placeholder = ref?.storedLarge && typeof factoryLightImagePlaceholder === 'function'
    ? factoryLightImagePlaceholder(label || '이미지 보관됨')
    : '';
  const src = ref?.src || placeholder;
  if (src) {
    return renderFactoryLightImage(src, label, 'style="width:100%;height:100%;object-fit:cover;border-radius:8px;background:#fff"');
  }
  return `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;border-radius:8px;border:1px dashed rgba(148,163,184,.22);color:var(--text-m);font-size:10px;text-align:center;padding:6px">이미지 보관됨</div>`;
}

function renderFactoryRegisteredProductDetail(item = {}) {
  const detailImages = Array.isArray(item.detailImages) ? item.detailImages : [];
  const channels = Array.isArray(item.openMarketChannels) && item.openMarketChannels.length
    ? item.openMarketChannels.join(', ')
    : item.openMarketStatus || '오픈마켓 진행 안 함';
  const storageLabel = item.storageLabel || item.storageRef?.label || '로컬 저장소';
  return `<div style="grid-column:1 / -1;border-top:1px solid rgba(148,163,184,.14);margin-top:9px;padding-top:9px">
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px">
      <div style="border:1px solid rgba(148,163,184,.14);border-radius:9px;padding:8px;background:rgba(15,23,42,.30)">
        <div class="factory-small" style="color:var(--text-m);font-weight:850">등록 날짜</div>
        <div style="font-size:12px;color:var(--text);font-weight:900;margin-top:3px">${escapeHtml(factoryRegistrationDateText(item.registeredAt))}</div>
      </div>
      <div style="border:1px solid rgba(148,163,184,.14);border-radius:9px;padding:8px;background:rgba(15,23,42,.30)">
        <div class="factory-small" style="color:var(--text-m);font-weight:850">사용한 저장본</div>
        <div style="font-size:12px;color:var(--text);font-weight:900;margin-top:3px">${escapeHtml(item.projectName || '현재 마지막 작업')}</div>
        <div class="factory-small" style="margin-top:3px;color:var(--text-m);word-break:break-all">${escapeHtml(item.projectId || '저장본 ID 없음')}</div>
      </div>
      <div style="border:1px solid rgba(148,163,184,.14);border-radius:9px;padding:8px;background:rgba(15,23,42,.30)">
        <div class="factory-small" style="color:var(--text-m);font-weight:850">보관 위치</div>
        <div class="factory-small" style="margin-top:3px;color:var(--text);word-break:break-all">${escapeHtml(storageLabel)}</div>
        ${item.projectId ? `<button class="btn-sm" style="margin-top:7px" type="button" data-factory-load-project="${escAttr(item.projectId)}">보관 저장본 열기</button>` : ''}
      </div>
    </div>
    <div style="display:grid;grid-template-columns:140px minmax(0,1fr);gap:10px;margin-top:10px">
      <div>
        <div class="factory-small" style="color:var(--text-m);font-weight:900;margin-bottom:5px">사용 대표이미지</div>
        <div style="width:120px;height:90px;border:1px solid rgba(148,163,184,.18);border-radius:9px;overflow:hidden;background:rgba(2,6,23,.30)">
          ${factoryRegistrationImageThumb(item.heroImage, '사용 대표이미지')}
        </div>
      </div>
      <div>
        <div class="factory-small" style="color:var(--text-m);font-weight:900;margin-bottom:5px">상세이미지 ${detailImages.length}장 · 섹션 ${escapeHtml(String(item.detailSectionCount || 0))}개</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(78px,92px));gap:7px">
          ${detailImages.length
            ? detailImages.map((img, index) => `<div title="${escAttr(img.label || `상세이미지 ${index + 1}`)}" style="height:66px;border:1px solid rgba(148,163,184,.18);border-radius:9px;overflow:hidden;background:rgba(2,6,23,.30)">${factoryRegistrationImageThumb(img, img.label || `상세이미지 ${index + 1}`)}</div>`).join('')
            : `<div class="factory-small" style="color:var(--text-m)">표시할 상세이미지 썸네일이 없습니다. 저장본을 열면 전체 작업물을 볼 수 있습니다.</div>`}
        </div>
      </div>
    </div>
    <div class="factory-small" style="margin-top:9px;color:var(--text-m);line-height:1.5">
      오픈마켓: ${escapeHtml(channels)} · 최종 로그: ${escapeHtml(item.finalStatus || '기록 없음')}
    </div>
  </div>`;
}

function renderFactoryRegisteredProductCard(item = {}) {
  const expanded = new Set(Array.isArray(state.expandedFactoryRegistrationIds) ? state.expandedFactoryRegistrationIds : []);
  const isOpen = expanded.has(item.id);
  const hero = item.heroImage || {};
  const channelsText = Array.isArray(item.openMarketChannels) && item.openMarketChannels.length
    ? `마켓 ${item.openMarketChannels.length}개`
    : (item.target === 'cafe24_only' ? '오픈마켓 안 함' : '마켓 흐름 시작');
  return `<article style="border:1px solid rgba(148,163,184,.16);border-radius:10px;background:rgba(0,0,0,.16);padding:10px;display:grid;grid-template-columns:64px minmax(0,1fr) auto;gap:10px;align-items:start">
    <div style="width:64px;height:64px;border:1px solid rgba(148,163,184,.18);border-radius:9px;overflow:hidden;background:rgba(15,23,42,.72)">
      ${factoryRegistrationImageThumb(hero, item.productName || '등록 상품')}
    </div>
    <div style="min-width:0">
      <div style="font-size:13px;font-weight:950;color:var(--text);line-height:1.35;word-break:keep-all;overflow-wrap:anywhere">${escapeHtml(item.productName || '등록 상품')}</div>
      <div class="factory-saved-meta" style="margin-top:3px">
        ${item.productNo ? `Cafe24 #${escapeHtml(item.productNo)} · ` : ''}${escapeHtml(factoryRegistrationDateText(item.registeredAt))}
      </div>
      <div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:6px">
        <span class="factory-pill">${escapeHtml(factoryRegistrationTargetText(item))}</span>
        <span class="factory-pill">진열 ${escapeHtml(item.cafe24DisplayLabel || factoryCafe24FinalFlagLabel('display', item.cafe24Display))}</span>
        <span class="factory-pill">판매 ${escapeHtml(item.cafe24SellingLabel || factoryCafe24FinalFlagLabel('selling', item.cafe24Selling))}</span>
        <span class="factory-pill">${escapeHtml(channelsText)}</span>
      </div>
      ${item.finalStatus ? `<div class="factory-saved-meta" style="margin-top:6px;color:var(--text)">상태: ${escapeHtml(item.finalStatus)}</div>` : ''}
    </div>
    <button class="btn-sm" type="button" data-factory-registration-toggle="${escAttr(item.id)}">${isOpen ? '접기' : '펼쳐보기'}</button>
    ${isOpen ? renderFactoryRegisteredProductDetail(item) : ''}
  </article>`;
}

function renderFactoryRegisteredProductsPanel(factory = factoryRuntimeReadFactory()) {
  const items = Array.isArray(state.factoryRegistrationHistory) ? state.factoryRegistrationHistory : [];
  const sync = factoryEnsureOpenMarketSync(factory);
  const canRecordCurrent = !sync.finalRegistrationRunning && /최종 등록 완료/.test(String(sync.finalRegistrationStatus || ''));
  return `<div class="factory-card" style="margin-top:12px">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      <div>
        <h4 style="margin:0">등록한 제품 리스트</h4>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m)">Cafe24 등록 여부, 오픈마켓 진행 여부, 진열/판매 상태, 사용 이미지와 보관 저장본을 확인합니다.</div>
      </div>
      <div class="factory-workspace-actions" style="justify-content:flex-end;margin:0">
        <span class="factory-pill">${state.factoryRegistrationHistoryLoaded ? `${items.length}개` : '불러오는 중'}</span>
        <button class="btn-sm" id="factoryRefreshRegistrationHistory" type="button">등록 이력 새로고침</button>
        <button class="btn-sm primary" id="factoryRecordCurrentRegistrationHistory" type="button" ${disabledAttr(!canRecordCurrent, '최종 등록 완료 상태일 때 현재 결과를 이력에 저장할 수 있습니다.')}>현재 완료 등록 이력 저장</button>
      </div>
    </div>
    <div style="display:grid;gap:8px;overflow:visible;padding-right:2px">
      ${items.length
        ? items.map(renderFactoryRegisteredProductCard).join('')
        : `<div class="factory-small" style="border:1px dashed rgba(148,163,184,.24);border-radius:10px;padding:14px;color:var(--text-m)">
          아직 등록 이력이 없습니다. 앞으로 최종등록이 성공하면 자동으로 여기에 쌓입니다.
        </div>`}
    </div>
  </div>`;
}

function factoryLocalArchiveShort(value = '', len = 12) {
  const text = String(value || '').trim();
  if (!text) return '';
  return text.length > len ? `${text.slice(0, len)}...` : text;
}

function factoryLocalArchiveImageUrl(item = {}) {
  const raw = String(item.imageUrl || item.thumbnailUrl || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw) || /^data:image\//i.test(raw)) return raw;
  const base = (typeof factoryBackendBaseUrl === 'function'
    ? factoryBackendBaseUrl()
    : (state.backendBaseUrl || 'http://127.0.0.1:5050')).replace(/\/+$/, '');
  return `${base}${raw.startsWith('/') ? raw : `/${raw}`}`;
}

function factoryLocalArchiveCategoryLabel(item = {}) {
  if (item.categoryLabel) return String(item.categoryLabel);
  const info = typeof factoryLocalArchiveStageInfo === 'function'
    ? factoryLocalArchiveStageInfo(item.stageId || '', item)
    : null;
  return info?.categoryLabel || '기타 보관 파일';
}

function factoryLocalArchiveKindRank(label = '') {
  const text = String(label || '');
  if (text.includes('제품 원본')) return 0;
  if (text.includes('대표')) return 1;
  if (text.includes('사이즈')) return 2;
  if (text.includes('색상')) return 3;
  if (text.includes('이미지컷')) return 4;
  if (text.includes('섹션')) return 5;
  if (text.includes('상세')) return 6;
  return 9;
}

function factoryLocalArchiveMatchesCurrentProductInput(item = {}, factory = factoryRuntimeReadFactory()) {
  const currentName = factoryCurrentProductIdentityMeta().productName || factory.product?.productName || state.productName || '';
  const currentKey = typeof factoryCurrentProductKey === 'function'
    ? factoryCurrentProductKey(factory)
    : factoryNormalizeIdentityText(currentName);
  const rawCurrentFingerprint = typeof factoryCurrentInputImageFingerprint === 'function'
    ? factoryCurrentInputImageFingerprint(factory)
    : '';
  const currentFingerprint = typeof factoryImageFingerprintLooksUsable === 'function'
    ? (factoryImageFingerprintLooksUsable(rawCurrentFingerprint) ? rawCurrentFingerprint : '')
    : rawCurrentFingerprint;
  const itemKey = item.productKey || factoryNormalizeIdentityText(item.productName || '');
  const rawItemFingerprint = String(item.inputImageFingerprint || '').trim();
  const itemFingerprint = typeof factoryImageFingerprintLooksUsable === 'function'
    ? (factoryImageFingerprintLooksUsable(rawItemFingerprint) ? rawItemFingerprint : '')
    : rawItemFingerprint;
  if (!currentFingerprint || !itemFingerprint) return false;
  if (currentFingerprint === itemFingerprint) return true;
  if (!currentKey || !itemKey) return false;
  const normalizeKey = typeof factoryNormalizeIdentityText === 'function'
    ? factoryNormalizeIdentityText
    : (value => String(value || '').trim().replace(/\s+/g, '').toLowerCase());
  return normalizeKey(currentKey) === normalizeKey(itemKey) && currentFingerprint === itemFingerprint;
}

function factoryLocalArchiveCanRecoverLegacyDraftInput(item = {}, factory = factoryRuntimeReadFactory()) {
  const itemWorkspaceId = String(
    item.workspaceId ||
    item.currentProjectId ||
    item.projectId ||
    item.metadata?.workspaceId ||
    item.sourceMap?.workspaceId ||
    ''
  ).trim();
  if (!/^draft:lastwork_/i.test(itemWorkspaceId)) return false;
  return factoryLocalArchiveMatchesCurrentProductInput(item, factory);
}

function factoryLocalArchiveMatchesCurrentInput(item = {}, factory = factoryRuntimeReadFactory()) {
  const currentWorkspaceId = String(
    (typeof factoryCurrentWorkspaceId === 'function' ? factoryCurrentWorkspaceId(factory) : '') ||
    state.currentProjectId ||
    factory?.workspace?.id ||
    factory?.currentProjectId ||
    ''
  ).trim();
  const itemWorkspaceId = String(
    item.workspaceId ||
    item.currentProjectId ||
    item.projectId ||
    item.metadata?.workspaceId ||
    item.sourceMap?.workspaceId ||
    ''
  ).trim();
  if (currentWorkspaceId && itemWorkspaceId && currentWorkspaceId === itemWorkspaceId) {
    return factoryLocalArchiveMatchesCurrentProductInput(item, factory);
  }
  const archiveId = String(item.archiveId || item.id || '').trim();
  const linkedLegacyAssetIds = Array.isArray(factory?.archive?.linkedLegacyAssetIds)
    ? factory.archive.linkedLegacyAssetIds
    : [];
  if (!archiveId || !linkedLegacyAssetIds.includes(archiveId)) return false;
  return factoryLocalArchiveCanRecoverLegacyDraftInput(item, factory);
}

function factoryLocalArchiveMatchesCurrentWork(item = {}, factory = factoryRuntimeReadFactory()) {
  if (!factoryLocalArchiveMatchesCurrentInput(item, factory)) return false;
  const rawStageId = String(
    item.stageId ||
    item.metadata?.stageId ||
    item.sourceMap?.stageId ||
    ''
  ).trim();
  if (!rawStageId) return false;
  const currentRunId = String(
    (typeof factoryCurrentStageRunId === 'function' ? factoryCurrentStageRunId(rawStageId, factory) : '') ||
    factory?.product?.currentRunId ||
    factory?.automation?.currentRunId ||
    factory?.goalRun?.currentRunId ||
    (typeof factoryCurrentWorkflowRunId === 'function' ? factoryCurrentWorkflowRunId(factory) : '') ||
    ''
  ).trim();
  const itemRunId = String(
    item.currentRunId ||
    item.generationRunId ||
    item.metadata?.currentRunId ||
    item.metadata?.generationRunId ||
    ''
  ).trim();
  return !!currentRunId && !!itemRunId && itemRunId === currentRunId;
}

function renderFactoryLocalArchiveCard(item = {}) {
  const imageUrl = factoryLocalArchiveImageUrl(item);
  const label = factoryLocalArchiveCategoryLabel(item);
  const files = item.files && typeof item.files === 'object' ? item.files : {};
  const sourceFiles = item.sourceFiles && typeof item.sourceFiles === 'object' ? item.sourceFiles : {};
  const archiveId = item.archiveId || item.id || '';
  const title = item.title || item.assetId || '로컬 보관 이미지';
  const sectionText = item.sectionId ? `섹션 ${item.sectionId}` : (item.stageId || '단계 없음');
  const runText = factoryLocalArchiveShort(item.currentRunId, 14) || 'run 없음';
  const stageText = String(item.stageId || item.metadata?.stageId || item.sourceMap?.stageId || '').trim() || 'stageId 없음';
  const productKeyText = String(
    item.productKey ||
    item.productIdentityKey ||
    item.metadata?.productKey ||
    item.sourceMap?.productKey ||
    (item.productName ? factoryNormalizeIdentityText(item.productName) : '') ||
    ''
  ).trim() || 'productKey 없음';
  const fpText = factoryLocalArchiveShort(item.inputImageFingerprint, 14) || '원본지문 없음';
  const savedPath = files.imagePath || files.htmlPath || item.folder || '';
  const sourceText = item.sourceLabel || item.origin || item.reason || sourceFiles.imagePath || item.sourceArchiveId || '생성 원본 기록';
  const sourcePath = sourceFiles.imagePath || sourceFiles.originalPath || sourceFiles.filePath || item.sourceArchiveId || '';
  const copyPath = savedPath || item.folder || '';
  const workspaceId = String(
    item.workspaceId ||
    item.currentProjectId ||
    item.metadata?.workspaceId ||
    item.sourceMap?.workspaceId ||
    ''
  ).trim();
  const isCurrentInput = factoryLocalArchiveMatchesCurrentInput(item, factoryRuntimeReadFactory());
  return `<article class="factory-local-archive-card">
    <button class="factory-local-archive-thumb" type="button" data-factory-local-archive-preview="${escAttr(archiveId)}" title="크게 보기">
      ${imageUrl ? renderFactoryLightImage(imageUrl, title, 'data-factory-light-priority="1"', label) : '<span class="material-icons-outlined">insert_photo</span>'}
    </button>
    <div class="factory-local-archive-body">
      <div class="factory-local-archive-title">
        ${escapeHtml(title)}
        <span class="factory-pill" style="margin-left:6px;color:var(--ok);border-color:color-mix(in srgb, var(--ok) 55%, transparent)">로컬</span>
      </div>
      <div class="factory-local-archive-meta">
        <span>${escapeHtml(label)}</span>
        <span>${escapeHtml(sectionText)}</span>
        <span>${escapeHtml(item.productName || '상품명 없음')}</span>
      </div>
      <div class="factory-local-archive-path" title="${escAttr(copyPath)}">${escapeHtml(copyPath || '저장 경로 없음')}</div>
      <div class="factory-local-archive-meta">
        <span title="${escAttr(stageText)}">stageId ${escapeHtml(factoryLocalArchiveShort(stageText, 16))}</span>
        <span title="${escAttr(productKeyText)}">productKey ${escapeHtml(factoryLocalArchiveShort(productKeyText, 18))}</span>
        <span title="${escAttr(workspaceId)}">작업파일 ${escapeHtml(factoryLocalArchiveShort(workspaceId, 18) || 'ID 없음')}</span>
        <span title="${escAttr(item.currentRunId || '')}">runId ${escapeHtml(runText)}</span>
        <span title="${escAttr(item.inputImageFingerprint || '')}">원본 ${escapeHtml(fpText)}</span>
      </div>
      <div class="factory-local-archive-source" title="${escAttr(sourcePath || sourceText)}">원본 연결: ${escapeHtml(sourceText)}</div>
      <div class="factory-local-archive-actions">
        <button class="btn-sm" type="button" data-factory-local-archive-preview="${escAttr(archiveId)}">크게</button>
        <button class="btn-sm primary" type="button" data-factory-local-archive-load="${escAttr(archiveId)}" data-factory-local-archive-action="load" onclick="return window.factoryLocalArchiveActionButtonInline(this,event)" ${disabledAttr(!isCurrentInput, '다른 작업파일 또는 다른 입력 원본의 결과입니다. 해당 작업을 연 뒤 가져올 수 있습니다.')}>가져오기</button>
        <button class="btn-sm" type="button" data-factory-open-local-archive-folder="asset" data-factory-local-archive-id="${escAttr(archiveId)}" ${disabledAttr(!archiveId, '열 로컬 보관 자산이 없습니다.')}>
          <span class="material-icons-outlined" style="font-size:14px">folder_open</span>폴더 열기
        </button>
        <button class="btn-sm" type="button" data-factory-copy-archive-path="${escAttr(copyPath)}" ${disabledAttr(!copyPath, '복사할 저장 경로가 없습니다.')}>경로 복사</button>
      </div>
    </div>
  </article>`;
}

function renderFactoryLocalArchiveMiniPanel(factory = factoryRuntimeReadFactory()) {
  if (typeof factoryScheduleLocalArchiveAutoRefresh === 'function') {
    factoryScheduleLocalArchiveAutoRefresh(factory);
  }
  const archive = factory.archive || {};
  const assets = Array.isArray(archive.localAssets) ? archive.localAssets : [];
  const showAll = !!archive.localShowAll;
  const currentAssets = assets.filter(item => factoryLocalArchiveMatchesCurrentWork(item, factory));
  const currentInputAssets = assets.filter(item => factoryLocalArchiveMatchesCurrentInput(item, factory));
  const restoreTargets = typeof factoryLocalArchiveRestoreTargets === 'function'
    ? factoryLocalArchiveRestoreTargets(factory)
    : currentInputAssets;
  const restoreReady = restoreTargets.length > 0 && !archive.localAssetsLoading;
  const restoreDisabledReason = archive.localAssetsLoading
    ? '로컬 보관 목록을 불러오는 중입니다.'
    : '현재 작업에 연결할 새 로컬 보관 이미지가 없습니다. 이미 복원된 이미지는 그대로 유지됩니다.';
  const scopedAssets = showAll ? assets : currentInputAssets;
  const groups = new Map();
  scopedAssets.forEach(item => {
    const label = factoryLocalArchiveCategoryLabel(item);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(item);
  });
  const perGroupLimit = showAll ? 24 : 4;
  const maxVisibleTotal = showAll ? 96 : 24;
  let visibleTotal = 0;
  const orderedGroups = [...groups.entries()]
    .sort((a, b) => factoryLocalArchiveKindRank(a[0]) - factoryLocalArchiveKindRank(b[0]) || a[0].localeCompare(b[0], 'ko-KR'))
    .map(([label, items]) => {
      const remaining = Math.max(0, maxVisibleTotal - visibleTotal);
      const visibleItems = items.slice(0, Math.min(perGroupLimit, remaining));
      visibleTotal += visibleItems.length;
      return [label, visibleItems, items.length];
    })
    .filter(([, items, total]) => items.length || total);
  const displayCount = orderedGroups.reduce((sum, group) => sum + group[1].length, 0);
  const hiddenCount = Math.max(0, scopedAssets.length - displayCount);
  const currentFingerprint = typeof factoryCurrentInputImageFingerprint === 'function' ? factoryCurrentInputImageFingerprint(factory) : '';
  return `<div class="factory-card factory-local-archive-panel" style="margin-top:12px">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      <div>
        <h4 style="margin:0">이미지 모음 / 로컬 보관함</h4>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m)">
          앞으로 생성되는 이미지는 대표컷·사이즈컷·이미지컷·섹션이미지로 분류되어 바로 저장됩니다. 기본은 현재 작업 기준이며, 같은 상품의 다른 작업파일 결과도 분리해 볼 수 있습니다.
        </div>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m)">
          위치: ${escapeHtml(archive.localRoot || 'output/local-archive')}
        </div>
        <div class="factory-small" style="margin-top:4px;color:var(--text-m)">
          현재 기준: ${escapeHtml(factoryCurrentProductIdentityMeta().productName || '제품명 없음')} · 원본 ${escapeHtml(factoryLocalArchiveShort(currentFingerprint, 18) || '지문 없음')}
        </div>
      </div>
      <div class="factory-workspace-actions" style="justify-content:flex-end;margin:0">
        <span class="factory-pill">${archive.localAssetsLoading ? '불러오는 중' : `현재 ${currentAssets.length}개 / 전체 ${assets.length}개`}</span>
        <span class="factory-pill">현재 입력 원본 ${currentInputAssets.length}개</span>
        <label class="factory-pill"><input type="checkbox" id="factoryLocalArchiveShowAll" ${showAll ? 'checked' : ''}> 같은 상품 전체 작업파일</label>
        <button class="btn-sm" type="button" data-factory-open-local-archive-folder="work" data-factory-local-archive-scope="work">
          <span class="material-icons-outlined" style="font-size:14px">folder_open</span>현재 작업 폴더
        </button>
        <button class="btn-sm primary" id="factoryRestoreLocalArchiveToCurrentWork" type="button" data-factory-local-archive-action="restore" onclick="return window.factoryLocalArchiveActionButtonInline(this,event)" ${disabledAttr(!restoreReady, restoreDisabledReason)}>
          <span class="material-icons-outlined" style="font-size:14px">settings_backup_restore</span>${restoreTargets.length ? '현재 작업 후보로 복원' : '이미 복원됨'}
        </button>
        <button class="btn-sm" id="factoryRefreshLocalArchiveAssets" type="button" data-factory-local-archive-action="refresh" onclick="return window.factoryLocalArchiveActionButtonInline(this,event)">
          <span class="material-icons-outlined" style="font-size:14px">refresh</span>로컬 목록 새로고침
        </button>
      </div>
    </div>
    ${archive.localAssetsError ? `<div class="factory-small" style="border:1px solid rgba(239,68,68,.28);background:rgba(239,68,68,.08);border-radius:10px;padding:10px;color:var(--err);margin-bottom:10px">${escapeHtml(archive.localAssetsError)}</div>` : ''}
    <div class="factory-local-archive-summary">
      <span>표시 ${displayCount}개</span>
      <span>현재 작업 ${currentAssets.length}개</span>
      <span>현재 입력 원본 ${currentInputAssets.length}개</span>
      <span>전체 보관 ${assets.length}개</span>
      ${hiddenCount ? `<span>나머지 ${hiddenCount}개는 같은 기준으로 보관됨</span>` : ''}
    </div>
    <div class="factory-local-archive-gallery">
      ${orderedGroups.length ? orderedGroups.map(([label, items, total]) => `<section class="factory-local-archive-group">
        <div class="factory-local-archive-group-head">
          <b>${escapeHtml(label)}</b>
          <span>${items.length}${total > items.length ? `/${total}` : ''}개</span>
        </div>
        <div class="factory-local-archive-grid">
          ${items.map(renderFactoryLocalArchiveCard).join('')}
        </div>
      </section>`).join('') : `<div class="factory-small" style="border:1px dashed rgba(148,163,184,.24);border-radius:10px;padding:12px;color:var(--text-m)">
        ${assets.length ? '현재 작업 기준으로 볼 이미지가 없습니다. 전체 보기를 켜면 다른 작업 보관 파일도 확인할 수 있습니다.' : '아직 로컬 보관 목록이 비어 있습니다. 앞으로 생성되는 이미지는 여기에 분류되어 쌓입니다.'}
      </div>`}
    </div>
  </div>`;
}

function renderGlobalWorkfileBar() {
  const projects = typeof factoryRecentWorkfileProjects === 'function'
    ? factoryRecentWorkfileProjects(4)
    : (Array.isArray(state.projects) ? state.projects : []);
  const projectName = state.currentProjectName || state.factory?.product?.productName || state.productName || deriveProjectName();
  const cleanProjectName = String(projectName || '새 작업').replace(/\.kuasangse$/i, '').trim() || '새 작업';
  const fileDisplayName = `${cleanProjectName}.kuasangse`;
  const currentStatus = typeof workspaceDocumentStatusLabel === 'function'
    ? workspaceDocumentStatusLabel()
    : (state.currentProjectId ? '저장됨' : '초안');
  const activeStepLabel = typeof getCurrentStepLabel === 'function' ? getCurrentStepLabel() : '작업 화면';
  const syncInfo = typeof latestDbSyncInfo === 'function' ? latestDbSyncInfo() : null;
  const dbSyncLabel = syncInfo?.syncedAt && typeof formatLatestDbSyncTime === 'function'
    ? `DB 동기화 ${formatLatestDbSyncTime(syncInfo.syncedAt)}`
    : 'DB 동기화 기록 없음';
  const selectedProjectId = projects.some(project => project.id === state.currentProjectId) ? state.currentProjectId : '';
  const projectOptions = projects.map(project => `
    <option value="${escAttr(project.id)}" ${project.id === selectedProjectId ? 'selected' : ''}>
      ${escapeHtml(project.name || project.id)}${project.snapshotCount ? ` · 버전 ${project.snapshotCount}` : ''}
    </option>
  `).join('');
  return `<section class="global-workfile-bar" aria-label="작업파일 저장과 불러오기">
    <div class="global-workfile-doc">
      <span class="material-icons-outlined" aria-hidden="true">description</span>
      <div>
        <div class="global-workfile-kicker">현재 작업파일</div>
        <h2 title="${escAttr(fileDisplayName)}">${escapeHtml(fileDisplayName)}</h2>
        <div class="global-workfile-meta">
          <span class="${state.workspaceDocumentDirty ? 'dirty' : ''}">${escapeHtml(currentStatus)}</span>
          <span>${escapeHtml(dbSyncLabel)}</span>
          <span>화면 ${escapeHtml(activeStepLabel)}</span>
        </div>
      </div>
    </div>
    <div class="global-workfile-main">
      <label class="label" for="workspaceProjectName">파일 이름</label>
      <input class="input" id="workspaceProjectName" value="${escAttr(state.currentProjectName || projectName)}" placeholder="예: 띠수네모동전지갑 작업파일">
      <div class="global-workfile-actions">
        <button class="btn-sm primary" id="saveProjectBtn" type="button">${state.projectBusy ? '저장 중...' : '저장'}</button>
        <button class="btn-sm" id="newProjectBtn" type="button" title="현재 내용은 유지하고 새 저장본 이름으로 분리합니다.">다른 이름</button>
        <button class="btn-sm" id="exportProjectFileBtn" type="button" title=".kuasangse 작업파일로 내려받습니다.">파일로 저장</button>
        <button class="btn-sm" id="importProjectFileBtn" type="button" title=".kuasangse 작업파일을 엽니다.">파일 불러오기</button>
        <button class="btn-sm" id="blankWorkBtn" type="button" title="미저장 시 저장 여부를 묻고, 화면을 완전히 비워 새 파일을 시작합니다.">새 파일</button>
        <button class="btn-sm" id="saveSnapshotBtn" type="button" ${disabledAttr(!state.currentProjectId, '먼저 저장해주세요.')}>버전 저장</button>
      </div>
    </div>
    <div class="global-workfile-load">
      <label class="label" for="workspaceProjectSelect">최근 작업파일 불러오기</label>
      <select class="input" id="workspaceProjectSelect" ${disabledAttr(!state.projectsLoaded || !projects.length, state.projectsLoaded ? '저장된 작업이 없습니다.' : '저장 목록을 불러오는 중입니다.')}>
        <option value="">최근 작업파일 선택</option>
        ${projectOptions}
      </select>
      <div class="global-workfile-status">
        <button class="btn-sm" id="loadProjectBtn" type="button" ${disabledAttr(!projects.length, '저장된 작업이 없습니다.')}>불러오기</button>
        <span class="factory-pill">최근 ${projects.length}개</span>
        ${state.currentProjectId ? `<span class="factory-pill">ID ${escapeHtml(state.currentProjectId)}</span>` : ''}
      </div>
    </div>
  </section>`;
}

