function getInferredProductName() {
  const a = analysisMatchesCurrentImageInput(state.analysis) ? (state.analysis || {}) : {};
  return String(a.product_name || a.productName || a.product_name_ko || a.product_name_en || '').trim();
}

function getDbConfirmedProductName(db = getDbContextSummary()) {
  const match = db?.match || {};
  return String(match.product_name || match.jname || match.name || '').trim();
}

function getProductContextSummary() {
  const analysis = analysisMatchesCurrentImageInput(state.analysis) ? (state.analysis || {}) : {};
  const image = state.imagePreview
    || analysisImageSrc(state.analysisImages?.[0])
    || (state.imageBase64 ? `data:${state.imageMime || 'image/png'};base64,${state.imageBase64}` : null);
  const imageCount = Math.max(state.analysisImages?.length || 0, state.imageBase64 ? 1 : 0);
  const productName = String(
    state.productName ||
    analysis.product_name ||
    analysis.product_name_en ||
    state.currentProjectName ||
    ''
  ).trim();
  return {
    image,
    imageCount,
    productName,
    category: analysis.category || '',
    size: analysis.size_estimate || '',
    colors: Array.isArray(analysis.colors) ? analysis.colors : [],
  };
}

function getDbContextSummary() {
  const a = analysisMatchesCurrentImageInput(state.analysis) ? (state.analysis || {}) : {};
  const candidates = [
    a.db_match,
    a.db_product,
    a.dbProduct,
    a.db_facts,
    a.dbFacts,
    a.matched_db_product,
    a.matchedDbProduct,
    a.product_db,
    a.productDb,
  ].filter(Boolean);
  const found = candidates[0] || null;
  if (state.dbMatchBusy) {
    return {
      ready: false,
      title: 'DB 매칭 중',
      detail: `신화사 DB에서 "${state.dbMatchLastQuery || collectSinhwaDbSearchTerms()[0] || '현재 제품'}" 후보를 찾고 있습니다.`,
      canMatch: false,
      busy: true,
      candidates: state.dbMatchCandidates || [],
    };
  }
  if (!found) {
    return {
      ready: false,
      title: state.dbMatchError ? 'DB 매칭 실패' : 'DB 매칭 필요',
      detail: state.dbMatchError || '신화사 DB 연결은 살아 있습니다. 제품명/이미지 분석값으로 후보를 매칭해주세요.',
      canMatch: true,
      candidates: state.dbMatchCandidates || [],
    };
  }
  if (typeof found === 'string') {
    return { ready: true, title: 'DB 자료 있음', detail: found, canMatch: true };
  }
  const spec = found.spec || {};
  const name = found.name || found.product_name || found.jname || found.title || found.item_name || '';
  const size = found.size || found.dimensions || formatDbDimensions(spec) || found.width_mm || found.height_mm || '';
  const color = found.color || found.color_name || found.colors || '';
  const detail = [
    found.jcode ? `상품코드 #${found.jcode}` : '',
    name ? `상품명 ${name}` : '',
    size ? `규격 ${Array.isArray(size) ? size.join(', ') : size}` : '',
    color ? `색상 ${Array.isArray(color) ? color.join(', ') : color}` : '',
    found.product_weight_g ? `제품 ${found.product_weight_g}g` : '',
    Number.isFinite(Number(found.purchase_price)) ? `원가 ${Number(found.purchase_price).toLocaleString('ko-KR')}` : '',
    Number.isFinite(Number(found.stock_qty)) ? `재고 ${Number(found.stock_qty).toLocaleString('ko-KR')}` : '',
  ].filter(Boolean).join(' · ');
  return {
    ready: true,
    title: name ? `${name}${found.jcode ? ` #${found.jcode}` : ''}` : 'DB 확정값 있음',
    detail: detail || 'DB 매칭값을 확인했습니다.',
    canMatch: true,
    match: found,
    candidates: found.candidates || state.dbMatchCandidates || [],
  };
}

