  const marketPlusDryRunTop = document.getElementById('factoryMarketPlusDryRunSendTop');
  if (marketPlusDryRunTop) marketPlusDryRunTop.onclick = () => factorySafeClickMarketPlusSend({ dryRun: true, skipConfirm: true });

  const marketPlusPollResults = document.getElementById('factoryMarketPlusPollResults');
