  suppliers: { codeKeys: ['supplier_code', 'supplier'], nameKeys: ['supplier_name', 'supplier_company_name'], fallback: '현재 공급사' },
  brands: { codeKeys: ['brand_code', 'brand'], nameKeys: ['brand_name'], fallback: '현재 브랜드' },
