      targetFactory.product.imagePreview = preview;
      targetFactory.product.imageName = name;
      targetFactory.product.hasImage = true;
      targetFactory.product.currentUploadImageFingerprint = lockedKey || resolvedInputFingerprint || targetFactory.product.currentUploadImageFingerprint || '';
      targetFactory.product.inputImageFingerprint = lockedKey || resolvedInputFingerprint || targetFactory.product.inputImageFingerprint || '';
