      prompt: asset.prompt || '',
      metadata,
      sourceMap,
      currentRunId: resolvedRunId,
      generationRunId: resolvedRunId,
      productKey: resolvedProductKey,
      inputImageFingerprint: resolvedInputFingerprint,
