// ════════════════════════════════════════════════════════════════
// OPTION IMAGE SORTER — LOGIC
// ════════════════════════════════════════════════════════════════

const OPTION_SORTER_SOURCE_ARCHIVE_TYPE = 'option-sorter-source-upload';
let OPT_SOURCE_ARCHIVE_QUEUE_PROMISE = Promise.resolve();
let OPT_SOURCE_ARCHIVE_PENDING_COUNT = 0;
let OPT_SOURCE_ARCHIVE_RESTORE_PROMISE = null;
let OPT_RESULT_ARCHIVE_RESTORE_PROMISE = null;

function optScheduleSave(delay = 450, options = {}) {
  scheduleLastWorkSave(delay, {
    lightweight: true,
    optionSorterOnly: true,
    ...(options.durable === true ? { durable: true } : {}),
  });
}

async function optPersistGeneratedResultState() {
  await saveLastWorkNow({ server: false, sync: false });
}

function optSourceArchiveId(value = {}) {
  return String(value.archiveId || value.localArchive?.archiveId || value.metadata?.localArchiveId || '').trim();
}

function optSourceArchiveMarker(value = {}) {
  return String(
    value.sourceType ||
    value.metadata?.sourceType ||
    value.sourceMap?.sourceType ||
    value.reason ||
    '',
  ).trim();
}

function optSourceImageArchiveAsset(img = {}) {
  const identity = factoryLocalArchiveIdentity('options');
  const sourceType = OPTION_SORTER_SOURCE_ARCHIVE_TYPE;
  const optionImageId = String(img.id || '').trim();
  const createdAt = Number(img.createdAt || Date.now());
  return {
    id: `option_source_${optionImageId || createdAt}`,
    stageId: 'options',
    type: 'image',
    title: img.name || '옵션 원본 이미지',
    image: optImageSrc(img),
    mime: img.mime || 'image/png',
    workspaceId: identity.workspaceId,
    productKey: identity.productKey,
    inputImageFingerprint: identity.inputImageFingerprint,
    currentRunId: `${identity.currentRunId || 'option_source'}:${optionImageId || createdAt}`,
    createdAt,
    assetKind: 'option-source',
    category: 'option-images',
    categoryLabel: '색상옵션 원본 이미지파일',
    metadata: {
      source: '옵션 분류기 원본 업로드',
      sourceType,
      optionImageId,
      originalName: img.name || '',
    },
    sourceMap: {
      sourceType,
      optionImageId,
    },
  };
}

async function optArchiveSourceImage(imageId = '') {
  const requestedId = String(imageId || '').trim();
  let img = (state.optionSorter?.images || []).find(item => String(item?.id || '') === requestedId);
  if (!img) return false;
  if (optSourceArchiveId(img)) return true;
  const asset = optSourceImageArchiveAsset(img);
  if (!asset.image) return false;
  img.archiveStatus = 'saving';
  img.archiveError = '';
  img.sourceType = OPTION_SORTER_SOURCE_ARCHIVE_TYPE;
  OPT_SOURCE_ARCHIVE_PENDING_COUNT += 1;

  const runSave = async () => {
    try {
      const data = await factoryBackendArchiveAsset(asset, OPTION_SORTER_SOURCE_ARCHIVE_TYPE);
      const archive = data?.archive || {};
      const archiveId = String(archive.archiveId || archive.id || '').trim();
      if (!archiveId) throw new Error('옵션 원본 보관 응답에 archiveId가 없습니다.');
      img = (state.optionSorter?.images || []).find(item => String(item?.id || '') === requestedId);
      if (!img) return true;
      const imageUrl = archive.imageUrl || `/api/local-archive/assets/${encodeURIComponent(archiveId)}/image`;
      img.archiveId = archiveId;
      img.imageUrl = imageUrl;
      img.imagePersistence = 'local-archive-url';
      img.hasImageData = true;
      img.sourceType = OPTION_SORTER_SOURCE_ARCHIVE_TYPE;
      img.archiveStatus = 'saved';
      img.archiveError = '';
      img.localArchive = {
        ...(img.localArchive || {}),
        saving: false,
        saved: true,
        archiveId,
        imageUrl,
        folder: archive.folder || '',
        files: archive.files || {},
        savedAt: archive.savedAt || new Date().toISOString(),
      };
      state.optionSorter.optionSourceArchiveStatus = `원본 사진 ${state.optionSorter.images.filter(item => optSourceArchiveId(item)).length}장 로컬 보관 완료`;
      optScheduleSave(120);
      return true;
    } catch (error) {
      img = (state.optionSorter?.images || []).find(item => String(item?.id || '') === requestedId);
      if (img) {
        img.archiveStatus = 'failed';
        img.archiveError = String(error?.message || error);
      }
      state.optionSorter.optionSourceArchiveStatus = `원본 사진 보관 실패: ${error?.message || error}`;
      optScheduleSave(120);
      return false;
    } finally {
      OPT_SOURCE_ARCHIVE_PENDING_COUNT = Math.max(0, OPT_SOURCE_ARCHIVE_PENDING_COUNT - 1);
      const archiveQueueDrained = OPT_SOURCE_ARCHIVE_PENDING_COUNT === 0;
      if (archiveQueueDrained) {
        optScheduleSave(350);
      }
      if (archiveQueueDrained && state.step === 'optionsorter') render();
    }
  };
  const queued = OPT_SOURCE_ARCHIVE_QUEUE_PROMISE.then(runSave, runSave);
  OPT_SOURCE_ARCHIVE_QUEUE_PROMISE = queued.catch(() => {});
  return queued;
}

async function optRestoreGeneratedResultsFromLocalArchive() {
  if (OPT_RESULT_ARCHIVE_RESTORE_PROMISE) return OPT_RESULT_ARCHIVE_RESTORE_PROMISE;
  const readOnly = typeof workspaceAuthorityIsReadOnly === 'function' && workspaceAuthorityIsReadOnly();
  let os = state.optionSorter;
  if (!os || !Array.isArray(os.optionResults)) {
    return { restored: 0, reason: 'missing-results' };
  }
  const identity = factoryLocalArchiveIdentity('options');
  if (!String(identity.workspaceId || '').trim()) return { restored: 0, reason: 'missing-workspace' };

  OPT_RESULT_ARCHIVE_RESTORE_PROMISE = Promise.resolve().then(async () => {
    os.optionResultArchiveStatus = '현재 작업의 생성 옵션표 보관본을 확인하는 중입니다.';
    if (state.step === 'optionsorter') render();
    const base = (typeof factoryBackendBaseUrl === 'function'
      ? factoryBackendBaseUrl()
      : (state.backendBaseUrl || 'http://127.0.0.1:5050')).replace(/\/+$/, '');
    const query = new URLSearchParams({
      limit: '500',
      workspaceId: identity.workspaceId,
      stageId: 'options',
    });
    if (identity.productKey) query.set('productKey', identity.productKey);
    const response = await workspaceArchiveFetch(`${base}/api/local-archive/assets?${query.toString()}`, { cache: 'no-store' });
    let data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `옵션 생성 결과 보관본 조회 실패: HTTP ${response.status}`);
    }
    const hasArchivedOptionResults = records => (Array.isArray(records) ? records : [])
      .some(record => {
        const resultId = String(record?.optionResultId || '').trim();
        return resultId && !resultId.startsWith('or_group_')
          && String(record?.assetKind || '').trim() !== 'hero';
      });
    const hasArchivedResults = hasArchivedOptionResults(data.assets);
    if ((!Array.isArray(data.assets) || !data.assets.length || !hasArchivedResults) && identity.productKey) {
      const fallbackQuery = new URLSearchParams({
        limit: '500',
        productKey: identity.productKey,
        stageId: 'options',
      });
      const fallbackResponse = await workspaceArchiveFetch(`${base}/api/local-archive/assets?${fallbackQuery.toString()}`, { cache: 'no-store' });
      const fallbackData = await fallbackResponse.json().catch(() => ({}));
      if (!fallbackResponse.ok || fallbackData.ok === false) {
        throw new Error(fallbackData.error || `옵션 생성 결과 제품 보관본 조회 실패: HTTP ${fallbackResponse.status}`);
      }
      data = fallbackData;
    }
    const hasFallbackResults = hasArchivedOptionResults(data.assets);
    if ((!Array.isArray(data.assets) || !data.assets.length || !hasFallbackResults) && identity.inputImageFingerprint) {
      const fingerprintQuery = new URLSearchParams({
        limit: '500',
        inputImageFingerprint: identity.inputImageFingerprint,
        stageId: 'options',
      });
      const fingerprintResponse = await workspaceArchiveFetch(
        `${base}/api/local-archive/assets?${fingerprintQuery.toString()}`,
        { cache: 'no-store' },
      );
      const fingerprintData = await fingerprintResponse.json().catch(() => ({}));
      if (!fingerprintResponse.ok || fingerprintData.ok === false) {
        throw new Error(fingerprintData.error || `옵션 생성 결과 입력 원본 보관본 조회 실패: HTTP ${fingerprintResponse.status}`);
      }
      data = fingerprintData;
    }

    os = state.optionSorter;
    if (!os || !Array.isArray(os.optionResults)) {
      return { restored: 0, reason: 'missing-results' };
    }
    const existingResults = Array.isArray(os.optionResults) ? os.optionResults : [];
    const existingRunIds = new Set(existingResults
      .map(result => String(
        result?.factoryScope?.currentRunId || result?.currentRunId || result?.generationRunId || '',
      ).trim())
      .filter(Boolean));
    const currentScope = factoryOptionResultCurrentScope(factoryRuntimeReadFactory());
    const activeRunIds = new Set(existingRunIds.size
      ? existingRunIds
      : (currentScope.currentRunId ? [currentScope.currentRunId] : []));
    const archiveRecords = (Array.isArray(data.assets) ? data.assets : [])
      .filter(record => String(record?.optionResultId || '').trim())
      .sort((a, b) => Date.parse(a.savedAt || a.createdAt || 0) - Date.parse(b.savedAt || b.createdAt || 0));
    const existingResultRecords = archiveRecords.filter(record => existingResults.some(result => (
      String(result?.id || '').trim() === String(record?.optionResultId || '').trim() ||
      String(result?.archiveId || '').trim() === String(record?.archiveId || record?.id || '').trim()
    )));
    const sourceArchiveIds = new Set((os.images || [])
      .map(image => String(image?.archiveId || image?.localArchive?.archiveId || '').trim())
      .filter(Boolean));
    const sourceWorkspaceIds = new Set((Array.isArray(data.assets) ? data.assets : [])
      .filter(record => sourceArchiveIds.has(String(record?.archiveId || record?.id || '').trim()))
      .map(record => String(record?.workspaceId || record?.metadata?.workspaceId || record?.sourceMap?.workspaceId || '').trim())
      .filter(Boolean));
    const sourceInputFingerprints = new Set((Array.isArray(data.assets) ? data.assets : [])
      .filter(record => sourceArchiveIds.has(String(record?.archiveId || record?.id || '').trim()))
      .map(record => String(record?.inputImageFingerprint || record?.metadata?.inputImageFingerprint || record?.sourceMap?.inputImageFingerprint || '').trim())
      .filter(Boolean));
    const existingResultWorkspaceIds = new Set(existingResultRecords
      .map(record => String(record?.workspaceId || record?.metadata?.workspaceId || record?.sourceMap?.workspaceId || '').trim())
      .filter(Boolean));
    const existingResultInputFingerprints = new Set(existingResultRecords
      .map(record => String(record?.inputImageFingerprint || record?.metadata?.inputImageFingerprint || record?.sourceMap?.inputImageFingerprint || '').trim())
      .filter(Boolean));
    const sourceInputFingerprint = String(identity.inputImageFingerprint || '').trim()
      || (sourceInputFingerprints.size === 1 ? [...sourceInputFingerprints][0] : '');
    const restoredInputFingerprint = sourceInputFingerprint
      || (existingResultInputFingerprints.size === 1 ? [...existingResultInputFingerprints][0] : '');
    const sourceWorkspaceId = sourceWorkspaceIds.size === 1
      ? [...sourceWorkspaceIds][0]
      : (existingResultWorkspaceIds.size === 1 ? [...existingResultWorkspaceIds][0] : '');
    const sourceResultNamespace = !!sourceWorkspaceId && !!restoredInputFingerprint;
    const sourceInputResultIds = new Set();
    const sourceGroupShotResultIds = new Set();
    const recordIsGroupShot = record => (
      String(record?.optionResultId || '').trim().startsWith('or_group_') ||
      String(record?.assetKind || '').trim() === 'hero'
    );
    const matchedExistingRunIds = new Set(archiveRecords
      .filter(record => existingResults.some(result => (
        String(result?.id || '').trim() === String(record?.optionResultId || '').trim() ||
        String(result?.archiveId || '').trim() === String(record?.archiveId || '').trim()
      )))
      .map(record => String(
        record?.currentRunId || record?.generationRunId || record?.metadata?.currentRunId || record?.sourceMap?.currentRunId || '',
      ).trim())
      .filter(Boolean));
    if (matchedExistingRunIds.size) {
      activeRunIds.clear();
      matchedExistingRunIds.forEach(runId => activeRunIds.add(runId));
    }
    if (!activeRunIds.size) {
      const newest = archiveRecords[archiveRecords.length - 1];
      const newestRunId = String(
        newest?.currentRunId || newest?.generationRunId || newest?.metadata?.currentRunId || newest?.sourceMap?.currentRunId || '',
      ).trim();
      if (newestRunId) activeRunIds.add(newestRunId);
    }
    if (sourceResultNamespace) {
      const sourceInputResults = archiveRecords.filter(record => (
        String(record?.workspaceId || record?.metadata?.workspaceId || record?.sourceMap?.workspaceId || '').trim() === sourceWorkspaceId &&
        (typeof factoryIdentityKeysCompatible === 'function'
          ? factoryIdentityKeysCompatible(
            record?.productKey || record?.metadata?.productKey || record?.sourceMap?.productKey || '',
            identity.productKey,
          )
          : factoryNormalizeIdentityText(record?.productKey || record?.metadata?.productKey || record?.sourceMap?.productKey || '') === factoryNormalizeIdentityText(identity.productKey)) &&
        String(record?.inputImageFingerprint || record?.metadata?.inputImageFingerprint || record?.sourceMap?.inputImageFingerprint || '').trim() === restoredInputFingerprint
      ));
      sourceInputResults.forEach(record => sourceInputResultIds.add(String(record?.optionResultId || '').trim()));
      const latestGroupShot = [...sourceInputResults].reverse().find(recordIsGroupShot);
      if (latestGroupShot) sourceGroupShotResultIds.add(String(latestGroupShot.optionResultId || '').trim());
      const latestSourceRunId = String(
        sourceInputResults[sourceInputResults.length - 1]?.currentRunId ||
        sourceInputResults[sourceInputResults.length - 1]?.generationRunId ||
        sourceInputResults[sourceInputResults.length - 1]?.metadata?.currentRunId ||
        sourceInputResults[sourceInputResults.length - 1]?.sourceMap?.currentRunId || '',
      ).trim();
      if (latestSourceRunId) {
        activeRunIds.clear();
        activeRunIds.add(latestSourceRunId);
      }
    }

    const resultsById = new Map(existingResults.map(result => [String(result?.id || '').trim(), result]));
    const existingArchiveIds = new Set(existingResults
      .map(result => String(result?.archiveId || '').trim())
      .filter(Boolean));
    let restored = 0;
    let added = 0;
    let linked = 0;
    for (const record of archiveRecords) {
      const resultId = String(record?.optionResultId || '').trim();
      const archiveId = String(record?.archiveId || record?.id || '').trim();
      const recordRunId = String(
        record?.currentRunId || record?.generationRunId || record?.metadata?.currentRunId || record?.sourceMap?.currentRunId || '',
      ).trim();
      const isSourceGroupShot = sourceGroupShotResultIds.has(resultId);
      const resultKind = recordIsGroupShot(record) ? 'color-group-shot' : (String(record?.assetKind || 'option').trim() || 'option');
      if (!resultId || !archiveId ||
          (sourceResultNamespace && !sourceInputResultIds.has(resultId)) ||
          (!isSourceGroupShot && activeRunIds.size && (!recordRunId || !activeRunIds.has(recordRunId)))) continue;
      const imageUrl = String(record?.imageUrl || `/api/local-archive/assets/${encodeURIComponent(archiveId)}/image`).trim();
      const recordScope = {
        workspaceId: String(record?.workspaceId || record?.metadata?.workspaceId || identity.workspaceId || '').trim(),
        currentRunId: recordRunId || String(currentScope.currentRunId || '').trim(),
        productKey: factoryNormalizeIdentityText(record?.productKey || record?.metadata?.productKey || identity.productKey || ''),
        inputImageFingerprint: String(record?.inputImageFingerprint || record?.metadata?.inputImageFingerprint || restoredInputFingerprint || identity.inputImageFingerprint || '').trim(),
        stageId: 'options',
      };
      const result = resultsById.get(resultId);
      if (!result) {
        if (existingArchiveIds.has(archiveId)) continue;
        const createdAt = record?.createdAt || record?.savedAt || new Date().toISOString();
        const restoredResult = {
          id: resultId,
          resultKind,
          sourceId: '',
          sourceName: String(record?.metadata?.sourceName || '').trim(),
          batchNo: 0,
          batchLabel: '이전 생성안 보존 · 로컬 보관 복원',
          tonePresetName: '',
          optionName: String(record?.title || '보관된 옵션 결과').trim(),
          optionNames: Array.isArray(record?.metadata?.optionNames) ? record.metadata.optionNames : [],
          order: existingResults.length + added + 1,
          mode: 'restored',
          contentMode: 'full_image',
          pipelineName: String(record?.metadata?.pipelineName || '로컬 보관 복원').trim(),
          modeLabel: '로컬 보관 URL 복원',
          modelId: 'local-archive',
          modelLabel: '로컬 보관',
          prompt: '',
          image: null,
          splitImages: [],
          createdAt,
          archiveId,
          imageUrl,
          imagePersistence: 'local-archive-url',
          hasImage: true,
          resultAssetId: String(record?.assetId || '').trim(),
          factoryScope: recordScope,
          generationDetails: { restoredFromLocalArchive: true, archiveId },
        };
        os.optionResults.push(restoredResult);
        if (resultKind === 'color-group-shot') os.optionGroupShotLastResultId = resultId;
        resultsById.set(resultId, restoredResult);
        existingArchiveIds.add(archiveId);
        restored += 1;
        added += 1;
        continue;
      }
      let changed = false;
      if (result.archiveId !== archiveId) {
        result.archiveId = archiveId;
        changed = true;
      }
      if (imageUrl && result.imageUrl !== imageUrl) {
        result.imageUrl = imageUrl;
        changed = true;
      }
      if (record.assetId && result.resultAssetId !== record.assetId) {
        result.resultAssetId = record.assetId;
        changed = true;
      }
      if (result.imagePersistence !== 'local-archive-url') {
        result.imagePersistence = 'local-archive-url';
        changed = true;
      }
      if (result.hasImage !== true) {
        result.hasImage = true;
        changed = true;
      }
      if (result.resultKind !== resultKind) {
        result.resultKind = resultKind;
        changed = true;
      }
      if (resultKind === 'color-group-shot') os.optionGroupShotLastResultId = resultId;
      if (!factoryOptionResultScopeMissingFields(factoryOptionResultScope(result)).length &&
          JSON.stringify(factoryOptionResultScope(result)) !== JSON.stringify(recordScope)) {
        result.factoryScope = recordScope;
        changed = true;
      }
      if (changed) {
        restored += 1;
        linked += 1;
      }
    }
    if (restored) {
      os.optionResultArchiveStatus = added
        ? `로컬 보관본에서 생성 결과 ${added}장을 추가 복원했습니다${linked ? ` · 기존 ${linked}장 연결 갱신` : ''}.`
        : `로컬 보관본에서 생성 결과 ${restored}장을 연결했습니다.`;
      if (!readOnly) optScheduleSave(120);
    } else {
      const savedCount = (os.optionResults || []).filter(result => String(result?.archiveId || result?.imageUrl || '').trim()).length;
      os.optionResultArchiveStatus = savedCount
        ? `생성 결과 ${savedCount}장이 로컬 보관본에 연결되어 있습니다.`
        : '현재 작업의 생성 옵션표 보관본은 아직 없습니다.';
    }
    if (state.step === 'optionsorter') render();
    return { restored, added, linked };
  }).catch(error => {
    os.optionResultArchiveStatus = `옵션 생성 결과 복원 확인 실패: ${error?.message || error}`;
    if (state.step === 'optionsorter') render();
    return { restored: 0, error: String(error?.message || error) };
  }).finally(() => {
    OPT_RESULT_ARCHIVE_RESTORE_PROMISE = null;
  });
  return OPT_RESULT_ARCHIVE_RESTORE_PROMISE;
}

async function optRestoreSourceImagesFromLocalArchive() {
  if (OPT_SOURCE_ARCHIVE_RESTORE_PROMISE) return OPT_SOURCE_ARCHIVE_RESTORE_PROMISE;
  const readOnly = typeof workspaceAuthorityIsReadOnly === 'function' && workspaceAuthorityIsReadOnly();
  let os = state.optionSorter;

  OPT_SOURCE_ARCHIVE_RESTORE_PROMISE = Promise.resolve().then(async () => {
    const initialResultRestore = await optRestoreGeneratedResultsFromLocalArchive();
    os = state.optionSorter;
    if (!os) return { restored: 0, reason: 'missing-state' };
    const identity = factoryLocalArchiveIdentity('options');
    if (!String(identity.workspaceId || '').trim()) return { restored: 0, reason: 'missing-workspace' };

    os.optionSourceArchiveStatus = '현재 작업의 로컬 옵션 원본을 확인하는 중입니다.';
    if (state.step === 'optionsorter') render();
    const base = (typeof factoryBackendBaseUrl === 'function'
      ? factoryBackendBaseUrl()
      : (state.backendBaseUrl || 'http://127.0.0.1:5050')).replace(/\/+$/, '');
    const query = new URLSearchParams({
      limit: '500',
      workspaceId: identity.workspaceId,
      stageId: 'options',
    });
    if (identity.productKey) query.set('productKey', identity.productKey);
    const response = await workspaceArchiveFetch(`${base}/api/local-archive/assets?${query.toString()}`, { cache: 'no-store' });
    let data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `옵션 원본 보관본 조회 실패: HTTP ${response.status}`);
    }
    let usedProductFallback = false;
    const hasCurrentWorkspaceSources = (Array.isArray(data.assets) ? data.assets : [])
      .some(record => optSourceArchiveMarker(record) === OPTION_SORTER_SOURCE_ARCHIVE_TYPE);
    if (!hasCurrentWorkspaceSources && identity.productKey && identity.inputImageFingerprint) {
      const fallbackQuery = new URLSearchParams({
        limit: '500',
        productKey: identity.productKey,
        stageId: 'options',
      });
      const fallbackResponse = await workspaceArchiveFetch(`${base}/api/local-archive/assets?${fallbackQuery.toString()}`, { cache: 'no-store' });
      const fallbackData = await fallbackResponse.json().catch(() => ({}));
      if (!fallbackResponse.ok || fallbackData.ok === false) {
        throw new Error(fallbackData.error || `옵션 원본 제품 보관본 조회 실패: HTTP ${fallbackResponse.status}`);
      }
      data = fallbackData;
      usedProductFallback = true;
    }

    os = state.optionSorter;
    if (!os) return { restored: 0, reason: 'missing-state' };
    const clearedAt = Number(os.optionSourceClearedAt || 0);
    const deleted = new Set(Array.isArray(os.optionSourceDeletedArchiveIds) ? os.optionSourceDeletedArchiveIds : []);
    const records = (Array.isArray(data.assets) ? data.assets : [])
      .filter(record => optSourceArchiveMarker(record) === OPTION_SORTER_SOURCE_ARCHIVE_TYPE)
      .filter(record => usedProductFallback
        ? record.inputImageFingerprint === identity.inputImageFingerprint
        : (!identity.inputImageFingerprint || !record.inputImageFingerprint || record.inputImageFingerprint === identity.inputImageFingerprint))
      .filter(record => !clearedAt || Date.parse(record.savedAt || record.createdAt || 0) > clearedAt)
      .filter(record => !deleted.has(optSourceArchiveId(record)))
      .sort((a, b) => Date.parse(a.savedAt || a.createdAt || 0) - Date.parse(b.savedAt || b.createdAt || 0));
    const existingArchiveIds = new Set((os.images || []).map(optSourceArchiveId).filter(Boolean));
    const existingByArchiveId = new Map((os.images || [])
      .map(item => [optSourceArchiveId(item), item])
      .filter(([archiveId]) => archiveId));
    const existingIds = new Set((os.images || []).map(item => String(item?.id || '')).filter(Boolean));
    let restored = 0;

    for (const record of records) {
      const archiveId = optSourceArchiveId(record);
      if (!archiveId) continue;
      const existing = existingByArchiveId.get(archiveId);
      if (existing) {
        const imageUrl = existing.imageUrl || record.imageUrl || `/api/local-archive/assets/${encodeURIComponent(archiveId)}/image`;
        existing.imageUrl = imageUrl;
        existing.imagePersistence = 'local-archive-url';
        existing.sourceType = existing.sourceType || OPTION_SORTER_SOURCE_ARCHIVE_TYPE;
        existing.archiveStatus = 'saved';
        existing.archiveError = '';
        existing.localArchive = {
          ...(existing.localArchive || {}),
          saving: false,
          saved: true,
          archiveId,
          imageUrl,
          folder: existing.localArchive?.folder || record.folder || '',
          files: existing.localArchive?.files || record.files || {},
          savedAt: existing.localArchive?.savedAt || record.savedAt || record.createdAt || '',
        };
        continue;
      }
      const optionImageId = String(record.metadata?.optionImageId || record.sourceMap?.optionImageId || `oi_archive_${archiveId}`).trim();
      const id = existingIds.has(optionImageId) ? `oi_archive_${archiveId}` : optionImageId;
      const imageUrl = record.imageUrl || `/api/local-archive/assets/${encodeURIComponent(archiveId)}/image`;
      os.images.push({
        id,
        name: String(record.metadata?.originalName || record.title || '복원 옵션 이미지'),
        mime: String(record.files?.imageMime || record.mime || 'image/png'),
        base64: null,
        preview: null,
        createdAt: Date.parse(record.savedAt || record.createdAt || 0) || Date.now(),
        hasImageData: true,
        archiveId,
        imageUrl,
        imagePersistence: 'local-archive-url',
        sourceType: OPTION_SORTER_SOURCE_ARCHIVE_TYPE,
        archiveStatus: 'saved',
        archiveError: '',
        localArchive: {
          saving: false,
          saved: true,
          archiveId,
          imageUrl,
          folder: record.folder || '',
          files: record.files || {},
          savedAt: record.savedAt || record.createdAt || '',
        },
        colorHint: null,
      });
      os.pool.push(id);
      existingIds.add(id);
      existingArchiveIds.add(archiveId);
      restored += 1;
    }
    if (restored) {
      optSyncSlotCountToImages(os);
      os.optionSourceArchiveStatus = `로컬 보관본에서 옵션 원본 ${restored}장을 복원했습니다.`;
    } else {
      const savedCount = (os.images || []).filter(item => optSourceArchiveId(item)).length;
      os.optionSourceArchiveStatus = savedCount
        ? `옵션 원본 ${savedCount}장이 로컬 보관되어 있습니다.`
        : '현재 작업에 로컬 보관된 옵션 원본은 아직 없습니다.';
    }
    let restoredAssignments = false;
    if (typeof restoreOptionSorterLabelsFromFactory === 'function' && typeof factoryRuntimeReadFactory === 'function') {
      const currentOptionSorter = state.optionSorter || os;
      const currentAssignmentCount = (currentOptionSorter.slots || [])
        .reduce((count, slot) => count + (Array.isArray(slot?.imgIds) ? slot.imgIds.length : 0), 0);
      const runtimeFactory = factoryRuntimeReadFactory();
      const factoryWithOptionLabels = runtimeFactory?.product?.finalDb?.option_values
        ? runtimeFactory
        : (state.factory || runtimeFactory);
      const restoredSlotMetadata = restoreOptionSorterLabelsFromFactory(
        currentOptionSorter,
        factoryWithOptionLabels,
      );
      const restoredAssignmentCount = (restoredSlotMetadata.slots || [])
        .reduce((count, slot) => count + (Array.isArray(slot?.imgIds) ? slot.imgIds.length : 0), 0);
      restoredAssignments = restoredAssignmentCount > currentAssignmentCount;
      if (restoredSlotMetadata !== currentOptionSorter) state.optionSorter = restoredSlotMetadata;
    }
    const finalResultRestore = await optRestoreGeneratedResultsFromLocalArchive();
    if (!readOnly && (
      restored
      || restoredAssignments
      || initialResultRestore?.restored
      || finalResultRestore?.restored
    )) optScheduleSave(120, { durable: true });
    if (state.step === 'optionsorter') render();
    return { restored, records: records.length };
  }).catch(error => {
    os.optionSourceArchiveStatus = `옵션 원본 복원 확인 실패: ${error?.message || error}`;
    if (state.step === 'optionsorter') render();
    return { restored: 0, error: String(error?.message || error) };
  }).finally(() => {
    OPT_SOURCE_ARCHIVE_RESTORE_PROMISE = null;
  });
  return OPT_SOURCE_ARCHIVE_RESTORE_PROMISE;
}

function optAddImage(file) {
  const os = state.optionSorter;
  if (os.images.length >= 30) return;
  const reader = new FileReader();
  reader.onload = e => {
    const preview = e.target.result;
    const base64 = preview.split(',')[1];
    const id = 'oi_' + Date.now() + '_' + Math.random().toString(36).slice(2,6);
    os.images.push({
      id,
      name: file.name.replace(/\.[^.]+$/, ''),
      base64,
      mime: file.type,
      preview,
      createdAt: Date.now(),
      hasImageData: true,
      sourceType: OPTION_SORTER_SOURCE_ARCHIVE_TYPE,
      archiveStatus: 'saving',
      archiveError: '',
      colorHint: null,
    });
    os.pool.push(id);
    optSyncSlotCountToImages(os);
    optScheduleSave();
    render();
    optArchiveSourceImage(id).catch(() => {});
    optInferAndStoreImageColorHint(id).catch(() => {});
  };
  reader.readAsDataURL(file);
}

function optAddImages(files) {
  const remaining = 30 - state.optionSorter.images.length;
  Array.from(files).slice(0, remaining).forEach(f => { if (f.type.startsWith('image/')) optAddImage(f); });
}

function optImageSrc(img) {
  if (!img) return '';
  if (img.preview && String(img.preview).startsWith('data:')) return img.preview;
  if (img.base64) return `data:${img.mime || 'image/png'};base64,${img.base64}`;
  if (typeof factoryRuntimeArchiveImageUrl === 'function') {
    const archived = factoryRuntimeArchiveImageUrl(img);
    if (archived) return archived;
  }
  return '';
}

async function optImageDataPart(img) {
  const src = optImageSrc(img);
  const dataUrlMatch = /^data:([^;,]+)?;base64,(.+)$/i.exec(String(src || ''));
  const base64 = img?.base64 || dataUrlMatch?.[2] || '';
  if (base64) return {
    base64,
    mime: img?.mime || dataUrlMatch?.[1] || 'image/png',
  };
  const archiveId = optSourceArchiveId(img);
  if (!archiveId || typeof factoryLocalArchiveAssetImagePart !== 'function') return null;
  const part = await factoryLocalArchiveAssetImagePart(archiveId, {
    mime: img?.mime || 'image/png',
    name: img?.name || '',
    source: 'option-sorter-source',
  });
  return part?.base64
    ? { base64: part.base64, mime: part.mime || img?.mime || 'image/png' }
    : null;
}

function optHasImagePayload(img) {
  return !!optImageSrc(img);
}

function optMissingImagePayloadCount(os = state.optionSorter) {
  return (Array.isArray(os?.images) ? os.images : [])
    .filter(img => img?.hasImageData && !optHasImagePayload(img))
    .length;
}

function optRenderMissingImage(label = '이미지 복원 중') {
  return `<div class="opt-missing-image" style="width:100%;height:100%;min-height:76px;border:1px dashed rgba(148,163,184,.45);border-radius:8px;background:rgba(15,23,42,.55);display:flex;align-items:center;justify-content:center;text-align:center;padding:8px;color:var(--text-m);font-size:11px;line-height:1.45;overflow:hidden">
    ${escapeHtml(label)}
  </div>`;
}

function optRenderImageOrPlaceholder(img, attrs = '', missingLabel = '이미지 복원 중') {
  const src = optImageSrc(img);
  if (src) return `<img src="${src}" loading="lazy" decoding="async" ${attrs}>`;
  return optRenderMissingImage(missingLabel);
}

// DOM → state 동기화 (SortableJS onEnd 후 호출)
function syncOptFromDOM() {
  const os = state.optionSorter;
  const poolEl = document.getElementById('optPoolList');
  if (poolEl) os.pool = [...poolEl.querySelectorAll('[data-img-id]')].map(el => el.dataset.imgId);
  os.slots.forEach(slot => {
    const el = document.getElementById('optSlotList_' + slot.id);
    if (el) slot.imgIds = [...el.querySelectorAll('[data-img-id]')].map(el => el.dataset.imgId);
  });
  optScheduleSave(150);
}

// 슬롯 순서 DOM → state 동기화
function syncOptSlotsFromDOM() {
  const os = state.optionSorter;
  const gridEl = document.getElementById('optSlotGrid');
  if (!gridEl) return;
  const order = [...gridEl.querySelectorAll(':scope > [data-slot-id]')].map(el => el.dataset.slotId);
  if (order.length) os.slots = order.map(id => os.slots.find(s => s.id === id)).filter(Boolean);
  optScheduleSave(150);
}

function optDeleteSlot(slotId) {
  const os = state.optionSorter;
  const slot = os.slots.find(s => s.id === slotId);
  if (slot) { os.pool.unshift(...slot.imgIds); os.slots = os.slots.filter(s => s.id !== slotId); }
  optScheduleSave();
  render();
}

function optFocusSlotNameByIndex(index, selectText = true) {
  requestAnimationFrame(() => {
    const inputs = [...document.querySelectorAll('.opt-slot-name-inp')];
    const target = inputs[index];
    if (!target) return;
    target.focus();
    if (selectText) target.select();
  });
}

function optSyncSlotCountToImages(os = state.optionSorter) {
  const count = Array.isArray(os.images) ? os.images.length : 0;
  if (count <= 0) return;
  if (os.optionSlotSource === 'db' && Array.isArray(os.slots) && os.slots.length >= count) {
    const imageIds = new Set(os.images.map(img => img?.id).filter(Boolean));
    const assigned = new Set();
    os.slots.forEach(slot => {
      slot.imgIds = (Array.isArray(slot.imgIds) ? slot.imgIds : [])
        .filter(id => imageIds.has(id) && !assigned.has(id));
      slot.imgIds.forEach(id => assigned.add(id));
    });
    os.pool = os.images.map(img => img.id).filter(id => id && !assigned.has(id));
    return;
  }
  const nextSlots = [];
  for (let i = 0; i < count; i++) {
    const existing = os.slots?.[i];
    nextSlots.push(existing || { id: 'slot_' + Date.now() + '_' + i, name: (i + 1) + '번', imgIds: [] });
  }
  const keptIds = new Set(nextSlots.map(slot => slot.id));
  const movedBack = [];
  (os.slots || []).forEach(slot => {
    if (!keptIds.has(slot.id) && Array.isArray(slot.imgIds)) movedBack.push(...slot.imgIds);
  });
  os.slots = nextSlots;
  os.pool = [...new Set([...(os.pool || []), ...movedBack])]
    .filter(id => os.images.some(img => img.id === id));
}

function optDownloadSlot(slotIdOrAll) {
  const os = state.optionSorter;
  const pairs = [];
  if (slotIdOrAll === '__all__') {
    os.slots.forEach(slot => {
      slot.imgIds.forEach((id, i) => {
        const img = os.images.find(im => im.id === id);
        if (img) pairs.push({ img, label: slot.name, idx: i + 1 });
      });
    });
    // Also pool (unassigned)
    os.pool.forEach((id, i) => {
      const img = os.images.find(im => im.id === id);
      if (img) pairs.push({ img, label: '미배정', idx: i + 1 });
    });
  } else {
    const slot = os.slots.find(s => s.id === slotIdOrAll);
    if (!slot) return;
    slot.imgIds.forEach((id, i) => {
      const img = os.images.find(im => im.id === id);
      if (img) pairs.push({ img, label: slot.name, idx: i + 1 });
    });
  }
  if (!pairs.length) { alert('다운로드할 이미지가 없습니다.'); return; }
  const downloadable = pairs.filter(({ img }) => optHasImagePayload(img));
  if (!downloadable.length) { alert('이미지 원본이 아직 복원되지 않았습니다. 잠시 후 다시 시도해주세요.'); return; }
  downloadable.forEach(({ img, label, idx }) => {
    const a = document.createElement('a');
    a.href = optImageSrc(img);
    a.download = `${label}_${String(idx).padStart(2, '0')}_${img.name}.jpg`;
    a.click();
  });
}

function ensureOptionSorterDefaults(os = state.optionSorter) {
  if (!os) return;
  os.optionColorImageUsage = os.optionColorImageUsage === 'none' ? 'none' : 'use';
  os.optionGroupShotSelectionMode = os.optionGroupShotSelectionMode === 'custom' ? 'custom' : 'all';
  os.optionGroupShotSelectedImageIds = Array.isArray(os.optionGroupShotSelectedImageIds)
    ? os.optionGroupShotSelectedImageIds.filter(id => (os.images || []).some(image => image?.id === id))
    : [];
  os.optionGroupShotTargetCount = 1;
  os.optionGroupShotPrompt = typeof os.optionGroupShotPrompt === 'string' ? os.optionGroupShotPrompt : '';
  if (typeof os.optionGroupShotRunning !== 'boolean') os.optionGroupShotRunning = false;
  if (!Number.isFinite(Number(os.optionGroupShotProgress))) os.optionGroupShotProgress = 0;
  if (typeof os.optionGroupShotLastResultId !== 'string') os.optionGroupShotLastResultId = null;
  if (typeof os.optionGroupShotLastError !== 'string') os.optionGroupShotLastError = '';
  if (!os.optionImageMode) os.optionImageMode = 'ready';
  if (!os.optionOutputLayout) os.optionOutputLayout = 'all';
  if (!['auto', 'grid', 'rows'].includes(os.optionSheetLayoutMode)) os.optionSheetLayoutMode = 'auto';
  if (typeof os.optionSheetLayoutUserSet !== 'boolean') os.optionSheetLayoutUserSet = false;
  if (!os.optionSheetLayoutUserSet) os.optionSheetLayoutMode = 'auto';
  os.optionSheetCols = clampOptionSheetCount(os.optionSheetCols, os.optionOutputLayout === 'pairs' ? 2 : 2);
  os.optionSheetRows = clampOptionSheetCount(os.optionSheetRows, os.optionOutputLayout === 'pairs' ? 1 : 2);
  os.optionSheetPixelMode = os.optionSheetPixelMode === 'custom' ? 'custom' : 'auto';
  os.optionSheetPixelPreset = ['auto', 'custom', '2k', '4k'].includes(os.optionSheetPixelPreset)
    ? os.optionSheetPixelPreset
    : (os.optionSheetPixelMode === 'custom' ? 'custom' : 'auto');
  os.optionSheetWidth = clampOptionSheetPixels(os.optionSheetWidth, 1246);
  os.optionSheetHeight = clampOptionSheetPixels(os.optionSheetHeight, 1366);
  if (!os.optionSheetMethod) os.optionSheetMethod = 'locked_canvas';
  if (!os.optionContentMode) os.optionContentMode = 'full_image';
  os.optionArchiveEnabled = !!os.optionArchiveEnabled;
  os.optionArchiveFolderName = typeof os.optionArchiveFolderName === 'string' ? os.optionArchiveFolderName : '';
  os.optionArchiveStatus = typeof os.optionArchiveStatus === 'string' ? os.optionArchiveStatus : '';
  os.optionArchiveLastSavedAt = typeof os.optionArchiveLastSavedAt === 'string' ? os.optionArchiveLastSavedAt : '';
  os.optionArchiveSavedCount = Number.isFinite(Number(os.optionArchiveSavedCount)) ? Number(os.optionArchiveSavedCount) : 0;
  if (os.optionSheetMethod === 'locked_canvas' && os.optionContentMode === 'mixed') os.optionContentMode = 'full_image';
  if (os.optionContentMode === 'text_only') os.optionSheetMethod = 'locked_canvas';
  const oldTone = '흰 배경, 동일한 여백, 부드러운 자연광, 은은한 그림자, 상품은 중앙에 또렷하게, 옵션명은 하단 라벨로 깔끔하게';
  if (!os.optionTone || os.optionTone === oldTone) {
    os.optionTone = getOptionTonePreset('default-clean').tone;
  }
  if (!os.optionTonePresetId) os.optionTonePresetId = detectOptionTonePresetId(os.optionTone);
  if (typeof os.optionExtraPrompt !== 'string') os.optionExtraPrompt = '';
  if (!Array.isArray(os.optionGenLogs)) os.optionGenLogs = [];
  if (!Array.isArray(os.optionResults)) os.optionResults = [];
  if (os.styleSample && !optNormalizeStyleSample(os.styleSample)) {
    os.styleSample = null;
    os.styleSampleResultId = null;
    os.styleSampleLibraryId = null;
  }
  if (typeof os.optionGenRunning !== 'boolean') os.optionGenRunning = false;
  if (typeof os.optionGenProgress !== 'number') os.optionGenProgress = 0;
}

function optSafeFilename(value) {
  return String(value || '옵션')
    .replace(/[\\/:*?"<>|]/g, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 80) || '옵션';
}

function optFormatDateTime(value) {
  if (!value) return '시간 기록 없음';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '시간 기록 없음';
  return date.toLocaleString('ko-KR', {
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function optContentModeLabel(mode) {
  if (mode === 'mixed') return '이미지 생성 + 글자 따로';
  if (mode === 'text_only') return '글자/레이아웃만';
  return '이미지+글자 전체 생성';
}

function optImageModeLabel(mode) {
  return mode === 'raw' ? 'RAW 사진 보정' : '정리된 옵션 사진';
}

function optCompactDetailValue(value) {
  if (value === null || value === undefined || value === '') return '없음';
  if (typeof value === 'boolean') return value ? '예' : '아니오';
  if (Array.isArray(value)) return value.length ? value.join(' / ') : '없음';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function optBuildImagePromptMeta(prompt, modelInfo = getCurrentImageRunInfo()) {
  const cfg = state.modelConfig || {};
  const imageModelId = modelInfo?.modelId || getImageModel();
  const activeDirectives = typeof getEffectiveImageDirectives === 'function' ? getEffectiveImageDirectives() : [];
  const brandBlock = typeof buildBrandPromptBlock === 'function' ? buildBrandPromptBlock() : '';
  const layoutBlock = typeof buildLayoutPromptBlock === 'function' ? buildLayoutPromptBlock() : '';
  const sizeHint = (cfg.imageSizeMode === 'custom' && cfg.imageWidth)
    ? `Exact size: ${cfg.imageWidth}px wide${cfg.imageHeight ? ' × ' + cfg.imageHeight + 'px tall' : ''}.`
    : 'Size: 860px wide.';
  return {
    imageModelId,
    providerId: modelInfo?.providerId || getImageProvider(imageModelId),
    providerLabel: modelInfo?.providerLabel || '',
    route: modelInfo?.route || '',
    requestedSize: isOpenAIImageModel(imageModelId) ? getRequestedImageSize(imageModelId) : sizeHint,
    geminiGenerationConfig: isOpenAIImageModel(imageModelId) ? null : {
      temperature: 0.8,
      responseModalities: ['TEXT', 'IMAGE'],
      imageConfig: {
        imageSize: '1K',
        imageOutputOptions: { mimeType: 'image/jpeg' },
      },
    },
    openAiGenerationConfig: isOpenAIImageModel(imageModelId) ? {
      endpoint: 'images/edits when reference images exist, otherwise images/generations',
      size: getRequestedImageSize(imageModelId),
      quality: 'auto',
      output_format: 'png',
      moderation: 'auto',
    } : null,
    clientPromptPrefix: isOpenAIImageModel(imageModelId)
      ? 'Create a professional Korean e-commerce product detail page section image.'
      : `Create a professional Korean e-commerce product detail page section image. Style: clean, modern, high-end Korean shopping mall aesthetic. ${sizeHint}`,
    activeDirectives,
    brandBlock,
    layoutBlock,
    basePromptChars: String(prompt || '').length,
  };
}

function optBuildOptionGenerationDetails({
  os = state.optionSorter,
  sheet,
  allPairs = [],
  pipeline,
  modelInfo,
  prompt,
  finalPromptTrace,
  activeStyleSample,
  continuitySampleName = '',
  hasContinuitySample = false,
  contentMode,
  modeLabel,
  toneName,
  batchNo,
  batchLabel,
  resultCreatedAt,
} = {}) {
  const resolvedContentMode = contentMode || os?.optionContentMode || 'full_image';
  const resolvedImageMode = os?.optionImageMode === 'raw' ? 'raw' : 'ready';
  const resolvedPipeline = pipeline || getOptionGenerationPipeline(os, modelInfo);
  const promptMeta = optBuildImagePromptMeta(prompt, modelInfo);
  const sheetPairs = Array.isArray(sheet?.pairs) ? sheet.pairs : [];
  const renderGrid = optResolveOptionSheetRenderGrid(sheet, os);
  const sheetCols = renderGrid.cols;
  const sheetRows = renderGrid.rows;
  const sheetRowPattern = renderGrid.rowPattern || optGridPattern(sheetRows, sheetCols);
  const sheetSize = optGetOptionSheetSize(os, renderGrid);
  const rowStarts = [];
  sheetRowPattern.reduce((sum, rowCount) => {
    rowStarts.push(sum);
    return sum + rowCount;
  }, 0);
  const references = [
    ...sheetPairs.map((p, idx) => {
      const hint = optGetAuthoritativeColorHint(p.img);
      return {
        order: idx + 1,
        role: `Cell ${idx + 1} 제품 이미지`,
        sourceNo: p.order,
        imageName: p.img?.name || '',
        optionName: p.optionName || '',
        colorHint: hint?.label || '',
        colorHintSource: optColorHintSourceLabel(hint),
        colorConfidence: Number.isFinite(Number(hint?.confidence)) ? Math.round(Number(hint.confidence) * 100) : null,
      };
    }),
  ];
  if (activeStyleSample) {
    references.push({
      order: references.length + 1,
      role: '샘플 이미지 하네스',
      sampleName: activeStyleSample.name || '',
      sourceResultId: activeStyleSample.sourceResultId || '',
      libraryId: activeStyleSample.libraryId || '',
      useFor: '구도/카드/라벨/배경/그림자만 참조',
      notFor: '제품/색상/옵션명/장식 복사 금지',
    });
  }
  if (hasContinuitySample) {
    references.push({
      order: references.length + 1,
      role: '이전 생성 결과 연속성 샘플',
      sampleName: continuitySampleName || '',
      useFor: '다음 페이지처럼 보이도록 캔버스/카드/라벨/그림자/배경을 맞춤',
      notFor: '제품/색상/옵션명 근거로 사용 금지',
    });
  }
  const conflicts = sheetPairs
    .map((p, idx) => ({ cell: idx + 1, sourceNo: p.order, optionName: p.optionName, conflict: optPairColorConflict(p) }))
    .filter(item => item.conflict)
    .map(item => ({
      cell: item.cell,
      sourceNo: item.sourceNo,
      optionName: item.optionName,
      labelColors: item.conflict.labelColors,
      imageColor: item.conflict.imageColor,
      confidence: Math.round((item.conflict.confidence || 0) * 100),
      source: item.conflict.sourceLabel || '',
      modelLabel: item.conflict.modelLabel || '',
      reason: item.conflict.reason || '',
      rule: '옵션명 색상어보다 원본 이미지 색상을 우선',
    }));
  return {
    schemaVersion: 1,
    createdAt: resultCreatedAt || new Date().toISOString(),
    batch: { batchNo, batchLabel },
    model: {
      provider: modelInfo?.providerLabel || promptMeta.providerLabel,
      providerId: modelInfo?.providerId || promptMeta.providerId,
      modelId: modelInfo?.modelId || promptMeta.imageModelId,
      modelLabel: modelInfo?.modelLabel || getImageModelLabel(promptMeta.imageModelId),
      route: modelInfo?.route || promptMeta.route,
    },
    generationMode: {
      pipelineId: resolvedPipeline.id,
      pipelineName: resolvedPipeline.name,
      pipelineHarness: resolvedPipeline.harness,
      contentMode: resolvedContentMode,
      contentModeLabel: optContentModeLabel(resolvedContentMode),
      optionSheetMethod: os?.optionSheetMethod || '',
      imageMode: resolvedImageMode,
      imageModeLabel: modeLabel || optImageModeLabel(resolvedImageMode),
      usesImageModel: !!resolvedPipeline.usesImageModel,
      usesAppText: !!resolvedPipeline.usesAppText,
    },
    tone: {
      tonePresetId: os?.optionTonePresetId || '',
      tonePresetName: toneName || getOptionToneDisplayName(os),
      toneText: os?.optionTone || '',
    },
    outputSplit: {
      optionOutputLayout: os?.optionOutputLayout || 'all',
      optionSheetCols: sheetCols,
      optionSheetRows: sheetRows,
      rowPattern: sheetRowPattern,
      selectedLayout: renderGrid.selectedLabel,
      maxOptionsPerSheet: renderGrid.capacity,
      pixelMode: sheetSize.mode,
      width: sheetSize.width,
      height: sheetSize.height,
      sheetIndex: sheet?.index || 1,
      sheetLabel: sheet?.label || '',
      sheetLayout: sheet?.layout || '',
      sheetOptionCount: sheetPairs.length,
      totalOptionCount: allPairs.length,
    },
    mapping: {
      allOptions: allPairs.map(p => {
        const hint = optGetAuthoritativeColorHint(p.img);
        return {
          sourceNo: p.order,
          imageName: p.img?.name || '',
          optionName: p.optionName || '',
          colorHint: hint?.label || '',
          colorHintSource: optColorHintSourceLabel(hint),
        };
      }),
      sheetCells: sheetPairs.map((p, idx) => ({
        cell: idx + 1,
        row: (() => {
          for (let r = 0; r < rowStarts.length; r += 1) {
            if (idx >= rowStarts[r] && idx < rowStarts[r] + sheetRowPattern[r]) return r + 1;
          }
          return 1;
        })(),
        column: (() => {
          for (let r = 0; r < rowStarts.length; r += 1) {
            if (idx >= rowStarts[r] && idx < rowStarts[r] + sheetRowPattern[r]) return idx - rowStarts[r] + 1;
          }
          return idx + 1;
        })(),
        sourceNo: p.order,
        imageName: p.img?.name || '',
        optionName: p.optionName || '',
      })),
      references,
      colorLocks: sheetPairs.map((p, idx) => optColorLockLine(p, idx)),
      colorConflicts: conflicts,
    },
    styleSample: activeStyleSample ? {
      name: activeStyleSample.name || '',
      id: activeStyleSample.id || '',
      libraryId: activeStyleSample.libraryId || '',
      sourceResultId: activeStyleSample.sourceResultId || '',
      copyAllowed: ['제품 각도 규율', '그리드 구조', '카드 비율', '테두리', '간격', '배경 톤', '조명', '그림자', '라벨 pill 양식'],
      copyForbidden: ['제품 자체', '상품 색상', '옵션명', '장식', '자수/비즈', '끈 위치', '샘플 텍스트 내용'],
    } : null,
    continuity: {
      enabled: !!hasContinuitySample,
      sampleName: continuitySampleName || '',
      rule: hasContinuitySample
        ? '직전 성공 결과를 다음 시트의 연속성 기준으로 첨부'
        : '첫 시트이거나 이전 성공 결과가 없어 연속성 샘플 미첨부',
    },
    harness: {
      productPreservation: [
        '원본 제품 사진이 실제 판매 상품 기준',
        '실루엣, 비율, 색상, 원단, 끈, 자수/비즈, 여밈, 봉제선 변경 금지',
        '옵션명은 라벨 텍스트일 뿐 색상 명령이 아님',
        '원본 배경/테이블/촬영 각도는 제품 정체성이 아니므로 템플릿에 맞게 정리 가능',
        '톤앤매너가 제품 보존과 충돌하면 제품 보존 우선',
      ],
      templateUniformity: [
        '동일 카드 크기',
        '동일 배경색',
        '동일 제품 각도/세워짐',
        '동일 제품 스케일/여백',
        '동일 그림자',
        '동일 하단 라벨 위치/크기/글자 스타일',
      ],
    },
    canvasTheme: resolvedPipeline.usesImageModel ? null : getOptionCanvasTheme(os),
    promptTrace: {
      basePromptChars: String(prompt || '').length,
      storedPromptChars: String(finalPromptTrace || prompt || '').length,
      clientPromptPrefix: promptMeta.clientPromptPrefix,
      requestedSize: promptMeta.requestedSize,
      activeDirectives: promptMeta.activeDirectives,
      brandBlockChars: String(promptMeta.brandBlock || '').length,
      layoutBlockChars: String(promptMeta.layoutBlock || '').length,
      geminiGenerationConfig: promptMeta.geminiGenerationConfig,
      openAiGenerationConfig: promptMeta.openAiGenerationConfig,
      appPostProcess: resolvedContentMode === 'mixed'
        ? '이미지 생성 후 앱이 고정 좌표로 옵션명을 오버레이'
        : '앱 텍스트 후처리 없음',
    },
  };
}

