function applyOptionGenerationPipeline(os = state.optionSorter, pipelineId = 'local_canvas') {
  if (!os) return;
  if (pipelineId === 'ai_full_image') {
    os.optionSheetMethod = 'ai_sheet';
    os.optionContentMode = 'full_image';
  } else if (pipelineId === 'ai_image_app_text') {
    os.optionSheetMethod = 'ai_sheet';
    os.optionContentMode = 'mixed';
  } else if (pipelineId === 'text_only') {
    os.optionSheetMethod = 'locked_canvas';
    os.optionContentMode = 'text_only';
  } else {
    os.optionSheetMethod = 'locked_canvas';
    os.optionContentMode = 'full_image';
  }
}

const OPTION_COLOR_WORDS = [
  { id:'pink', label:'핑크', words:['핑크','분홍','연핑','꽃핑','꽃분홍','핑'] },
  { id:'red', label:'빨강', words:['빨강','빨간','레드','홍색','적색','빨'] },
  { id:'orange', label:'주황/산호', words:['주황','오렌지','산호','코랄'] },
  { id:'yellow', label:'노랑', words:['노랑','노란','옐로','황색','노랭','골드'] },
  { id:'green', label:'초록', words:['초록','녹색','그린','녹두','연두'] },
  { id:'mint', label:'민트', words:['민트'] },
  { id:'blue', label:'파랑/청색', words:['파랑','파란','블루','청색','하늘','네이비','남색'] },
  { id:'purple', label:'보라', words:['보라','퍼플','자주','바이올렛'] },
  { id:'black', label:'검정', words:['검정','블랙','흑색'] },
  { id:'white', label:'흰색', words:['흰색','화이트','백색','아이보리','크림'] },
  { id:'beige', label:'베이지', words:['베이지','베이지색','살구','누드'] },
];

function optColorById(id) {
  return OPTION_COLOR_WORDS.find(c => c.id === id) || null;
}

function optExtractLabelColors(text) {
  const normalized = String(text || '').replace(/\s+/g, '').toLowerCase();
  if (!normalized) return [];
  return OPTION_COLOR_WORDS
    .filter(color => color.words.some(word => normalized.includes(String(word).toLowerCase())))
    .map(color => color.id);
}

function optRgbToHsv(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  let h = 0;
  if (delta) {
    if (max === r) h = ((g - b) / delta) % 6;
    else if (max === g) h = (b - r) / delta + 2;
    else h = (r - g) / delta + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  return { h, s: max ? delta / max : 0, v: max };
}

function optColorCategoryFromRgb(r, g, b) {
  const { h, s, v } = optRgbToHsv(r, g, b);
  if (v > 0.86 && s < 0.16) return 'white';
  if (v < 0.18) return 'black';
  if (s < 0.14) return null;
  if (h >= 330 || h < 8) return (b > 105 && r > 150) ? 'pink' : 'red';
  if (h < 22) return r > 170 && g > 70 && b > 70 ? 'pink' : 'orange';
  if (h < 48) return 'orange';
  if (h < 72) return 'yellow';
  if (h < 145) return 'green';
  if (h < 178) return 'mint';
  if (h < 255) return 'blue';
  if (h < 318) return 'purple';
  return 'pink';
}

function optColorCompatible(a, b) {
  if (!a || !b) return true;
  if (a === b) return true;
  const close = new Set([
    'pink:red', 'red:pink',
    'orange:yellow', 'yellow:orange',
    'green:mint', 'mint:green',
    'white:beige', 'beige:white',
  ]);
  return close.has(`${a}:${b}`);
}

const OPTION_COLOR_HINT_METHOD = 'product-mask-v2';
const OPTION_COLOR_VISION_HINT_METHOD = 'llm-vision-v1';

const OPTION_COLOR_ID_ALIASES = {
  red: ['red', 'scarlet', 'crimson'],
  pink: ['pink', 'rose'],
  orange: ['orange'],
  yellow: ['yellow', 'gold', 'golden'],
  green: ['green', 'olive'],
  mint: ['mint', 'teal', 'aqua', 'turquoise'],
  blue: ['blue', 'navy', 'skyblue', 'sky blue'],
  purple: ['purple', 'violet', 'lavender'],
  black: ['black', 'charcoal'],
  white: ['white', 'ivory', 'cream', 'offwhite', 'off white'],
  beige: ['beige', 'tan', 'sand'],
};

function optNormalizeColorToken(value) {
  return String(value || '').replace(/[\s_\-./]+/g, '').toLowerCase();
}

function optResolveColorId(value) {
  const normalized = optNormalizeColorToken(value);
  if (!normalized || normalized === 'unknown' || normalized === 'none') return '';
  for (const color of OPTION_COLOR_WORDS) {
    const candidates = [
      color.id,
      color.label,
      ...(color.words || []),
      ...(OPTION_COLOR_ID_ALIASES[color.id] || []),
    ].map(optNormalizeColorToken);
    if (candidates.includes(normalized)) return color.id;
  }
  for (const color of OPTION_COLOR_WORDS) {
    const candidates = [
      color.id,
      color.label,
      ...(color.words || []),
      ...(OPTION_COLOR_ID_ALIASES[color.id] || []),
    ].map(optNormalizeColorToken);
    if (candidates.some(candidate => candidate && normalized.includes(candidate))) return color.id;
  }
  return '';
}

function optNormalizeConfidence(value, fallback = 0) {
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized.endsWith('%')) {
      const n = Number.parseFloat(normalized);
      if (Number.isFinite(n)) return Math.max(0, Math.min(1, n / 100));
    }
    const map = { high: 0.86, medium: 0.62, low: 0.34, overall: fallback };
    if (Object.prototype.hasOwnProperty.call(map, normalized)) return map[normalized];
  }
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(0, Math.min(1, n > 1 ? n / 100 : n));
}

function optParseLooseJson(text) {
  const raw = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
  try { return JSON.parse(raw); } catch(e) {}
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch(e) {}
  }
  return null;
}

function optNormalizeVisionColorHint(raw, modelInfo = getCurrentLlmRunInfo()) {
  const data = raw && typeof raw === 'object' ? raw : {};
  const rawId = data.dominant_product_color_id || data.product_color_id || data.color_id || data.id || '';
  const rawLabel = data.dominant_product_color_label || data.product_color_label || data.color_label || data.label || '';
  const id = optResolveColorId(rawId) || optResolveColorId(rawLabel);
  const meta = optColorById(id);
  const confidence = optNormalizeConfidence(data.confidence, id ? 0.64 : 0);
  const visibleColors = Array.isArray(data.visible_colors) ? data.visible_colors.map(item => ({
    id: optResolveColorId(item?.id || item?.label || item?.color || ''),
    label: String(item?.label || item?.color || item?.id || '').trim(),
    area: String(item?.area || '').trim(),
    reason: String(item?.reason || '').trim(),
  })).filter(item => item.id || item.label) : [];
  return {
    id: id || 'unknown',
    label: meta?.label || String(rawLabel || rawId || '색상 미확인').trim() || '색상 미확인',
    confidence,
    method: OPTION_COLOR_VISION_HINT_METHOD,
    source: 'llm_vision',
    modelId: modelInfo?.modelId || '',
    modelLabel: modelInfo?.modelLabel || modelInfo?.modelId || '',
    providerId: modelInfo?.providerId || '',
    providerLabel: modelInfo?.providerLabel || '',
    reason: String(data.reason || data.evidence || '').trim(),
    isMulticolor: !!data.is_multicolor,
    visibleColors,
    raw: data,
    createdAt: new Date().toISOString(),
  };
}

function optBuildVisionColorPrompt(img) {
  const colorList = OPTION_COLOR_WORDS.map(color => `${color.id}=${color.label}`).join(', ');
  return `You are checking ONE uploaded product photo for an ecommerce option selector.
Return ONLY JSON.

Task:
- Identify the main visible color of the product itself.
- Ignore background, table, paper, lighting color cast, shadows, labels, sample sheets, and text.
- If the product has small accents, choose the dominant body color and list accents separately.
- Use one of these exact color IDs: ${colorList}, unknown.

Image name: ${img?.name || 'uploaded option image'}

JSON schema:
{
  "dominant_product_color_id": "one allowed id or unknown",
  "dominant_product_color_label": "Korean label",
  "confidence": 0.0,
  "is_multicolor": false,
  "visible_colors": [{"id":"allowed id","label":"Korean label","area":"main|accent","reason":"short Korean reason"}],
  "reason": "short Korean evidence sentence"
}`;
}

async function optInferImageVisionColorHint(img, options = {}) {
  const imagePart = await optImageDataPart(img);
  if (!imagePart) return null;
  const { mime, base64 } = imagePart;
  let llm;
  try {
    llm = getLLMClient();
  } catch(e) {
    if (!options.silent) optAppendLogs(state.optionSorter, `AI 비전 색상 판정 생략: ${e.message || e}`);
    return null;
  }
  const modelInfo = getCurrentLlmRunInfo();
  const prompt = optBuildVisionColorPrompt(img);
  let rawText = '';
  if (llm instanceof GeminiAPI) {
    const body = {
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mime, data: base64 } },
        ],
      }],
      generationConfig: { temperature: 0.1, maxOutputTokens: 768 },
    };
    const data = await llm._generateContent(llm.model, body);
    tokenTracker.record(llm.model, data.usageMetadata?.promptTokenCount, data.usageMetadata?.candidatesTokenCount, false, '옵션색상판정');
    rawText = data.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('\n') || '';
  } else if (llm instanceof OpenAIAPI) {
    const body = {
      model: llm.model,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mime};base64,${base64}`, detail: 'low' } },
        ],
      }],
      max_completion_tokens: 768,
      temperature: 0.1,
    };
    const res = await fetch(`${llm.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${llm.apiKey}` },
      body: JSON.stringify(body),
    });
    const data = await res.json();
    if (!res.ok || data.error) throw new Error(data?.error?.message || data?.error || `HTTP ${res.status}`);
    tokenTracker.record(llm.model, data.usage?.prompt_tokens, data.usage?.completion_tokens, false, '옵션색상판정');
    rawText = data.choices?.[0]?.message?.content || '';
  } else if (llm instanceof GptOAuthAPI) {
    rawText = await llm._exec(prompt, {
      imageBase64: base64,
      mimeType: mime,
      purpose: '옵션색상판정',
      timeoutMs: 120000,
      jsonOnly: true,
    });
  }
  const parsed = optParseLooseJson(rawText);
  if (!parsed) throw new Error('AI 비전 색상 판정 응답을 JSON으로 해석하지 못했습니다.');
  return optNormalizeVisionColorHint(parsed, modelInfo);
}

async function optInferAndStoreImageVisionColorHint(imgId, os = state.optionSorter, options = {}) {
  const img = os.images.find(im => im.id === imgId);
  if (!img || !optHasImagePayload(img)) return null;
  if (!options.force && img.colorVisionHint?.method === OPTION_COLOR_VISION_HINT_METHOD) return img.colorVisionHint;
  try {
    const hint = await optInferImageVisionColorHint(img, options);
    if (hint) img.colorVisionHint = hint;
    optScheduleSave();
    if (!options.silent) render();
    return img.colorVisionHint || null;
  } catch(e) {
    img.colorVisionHint = {
      id: 'unknown',
      label: '색상 미확인',
      confidence: 0,
      method: OPTION_COLOR_VISION_HINT_METHOD,
      source: 'llm_vision',
      error: e.message || String(e),
      createdAt: new Date().toISOString(),
    };
    optScheduleSave();
    if (!options.silent) render();
    return img.colorVisionHint;
  }
}

async function optEnsureImageVisionColorHints(os = state.optionSorter, options = {}) {
  const targets = (os.images || []).filter(img => optHasImagePayload(img) && (options.force || img.colorVisionHint?.method !== OPTION_COLOR_VISION_HINT_METHOD));
  if (!targets.length) return;
  if (!hasLlmConnection()) {
    if (!options.silent) optAppendLogs(os, 'AI 비전 색상 판정 생략: LLM 연결이 없어 픽셀 추정색을 사용합니다.');
    return;
  }
  os.optionVisionColorBusy = true;
  if (!options.silent) render();
  try {
    for (const img of targets) {
      await optInferAndStoreImageVisionColorHint(img.id, os, { ...options, silent: true });
    }
  } finally {
    os.optionVisionColorBusy = false;
    optScheduleSave(80);
    if (!options.silent) render();
  }
}

function optApplyNumberedVisionColorSlotNames(os = state.optionSorter) {
  let renamed = 0;
  os.slots.forEach((slot, index) => {
    const img = os.images.find(item => item.id === slot.imgIds?.[0]);
    const hint = optGetAuthoritativeColorHint(img);
    if (!optIsUsableColorHint(hint)) return;
    const label = String(hint.label || '').replace(/^\s*\d+\s*[.)번-]?\s*/, '').trim();
    if (!label || label === '색상 미확인') return;
    slot.name = `${index + 1}.${label}`;
    renamed += 1;
  });
  os.optionAutoColorNameStatus = renamed
    ? `GPT OAuth 색상 판정으로 ${renamed}개 슬롯명을 번호와 함께 저장했습니다.`
    : 'GPT OAuth 판정에서 확정 가능한 색상명이 없어 기존 슬롯명을 유지했습니다.';
  return renamed;
}

async function optRefreshVisionColorHints(options = {}) {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  const cfg = normalizeModelConfig(state.modelConfig);
  if (options.requireGptOAuth && (cfg.llmProvider !== 'gpt_oauth' || !isGptOAuthConnected())) {
    throw new Error('모델 설정에서 ChatGPT 로그인 OAuth를 선택하고 연결 상태를 확인해주세요.');
  }
  optAppendLogs(os, 'AI 비전 색상 판정 시작: 배경/그림자보다 상품 본체 색상을 우선 확인합니다.');
  optScheduleSave(80);
  render();
  await optEnsureImageVisionColorHints(os, { force: true, silent: false });
  const judged = (os.images || []).filter(img => img.colorVisionHint?.method === OPTION_COLOR_VISION_HINT_METHOD && img.colorVisionHint.id !== 'unknown').length;
  const renamed = options.applySlotNames ? optApplyNumberedVisionColorSlotNames(os) : 0;
  optAppendLogs(os, judged ? `AI 비전 색상 판정 완료: ${judged}장 판정값을 충돌 경고에 우선 적용합니다.` : 'AI 비전 색상 판정 완료: 확정 색상이 없어 픽셀 추정색을 계속 사용합니다.');
  if (options.applySlotNames) optAppendLogs(os, os.optionAutoColorNameStatus);
  optScheduleSave(80);
  if (options.applySlotNames) await saveLastWorkNow({ force: true });
  render();
  return { judged, renamed };
}

function optColorHintMinConfidence(hint) {
  if (!hint) return 1;
  return hint.method === OPTION_COLOR_VISION_HINT_METHOD ? 0.35 : 0.16;
}

function optIsUsableColorHint(hint) {
  return !!(hint?.id && hint.id !== 'unknown' && Number.isFinite(Number(hint.confidence)) && Number(hint.confidence) >= optColorHintMinConfidence(hint));
}

function optGetAuthoritativeColorHint(img) {
  if (optIsUsableColorHint(img?.colorVisionHint)) return img.colorVisionHint;
  if (optIsUsableColorHint(img?.colorHint)) return img.colorHint;
  return img?.colorVisionHint || img?.colorHint || null;
}

function optColorHintSourceLabel(hint) {
  if (!hint) return '';
  if (hint.method === OPTION_COLOR_VISION_HINT_METHOD) return 'AI 비전 판정';
  if (hint.method === OPTION_COLOR_HINT_METHOD) return '픽셀 자동 추정';
  return '색상 판정';
}

function optRgbDistance(a, b) {
  if (!a || !b) return 999;
  return Math.sqrt(
    Math.pow((a.r || 0) - (b.r || 0), 2) +
    Math.pow((a.g || 0) - (b.g || 0), 2) +
    Math.pow((a.b || 0) - (b.b || 0), 2)
  );
}

function optEstimateImageBackgroundRgb(data, size) {
  let r = 0, g = 0, b = 0, n = 0;
  const edge = Math.max(6, Math.round(size * 0.08));
  for (let y = 0; y < size; y += 2) {
    for (let x = 0; x < size; x += 2) {
      if (!(x < edge || y < edge || x >= size - edge || y >= size - edge)) continue;
      const i = (y * size + x) * 4;
      const a = data[i + 3];
      if (a < 180) continue;
      r += data[i]; g += data[i + 1]; b += data[i + 2]; n += 1;
    }
  }
  return n ? { r: r / n, g: g / n, b: b / n } : null;
}

async function optInferImageColorHint(src) {
  const img = await loadImageElement(src);
  const size = 120;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(img, 0, 0, size, size);
  const data = ctx.getImageData(0, 0, size, size).data;
  const bg = optEstimateImageBackgroundRgb(data, size);
  const scores = new Map();
  const sums = new Map();
  let totalScore = 0;
  let candidatePixels = 0;
  for (let y = 0; y < size; y += 2) {
    for (let x = 0; x < size; x += 2) {
      const i = (y * size + x) * 4;
    const r = data[i], g = data[i + 1], b = data[i + 2], a = data[i + 3];
    if (a < 180) continue;
    const { s, v } = optRgbToHsv(r, g, b);
      if (v > 0.95 && s < 0.22) continue;
    if (v < 0.12) continue;
      const bgDistance = optRgbDistance({ r, g, b }, bg);
      if (bg && bgDistance < 42) continue;
      if (bg && bgDistance < 64 && s < 0.38) continue;
      if (s < 0.18) continue;
    const id = optColorCategoryFromRgb(r, g, b);
    if (!id || id === 'white' || id === 'black') continue;
      const nx = (x + 0.5) / size - 0.5;
      const ny = (y + 0.5) / size - 0.5;
      const centerWeight = 1 + Math.max(0, 1 - Math.sqrt(nx * nx + ny * ny) / 0.72) * 1.6;
      const saturationWeight = 1 + s * 3.2;
      const productWeight = bg ? Math.min(2.4, Math.max(0.7, bgDistance / 55)) : 1;
      const weight = centerWeight * saturationWeight * productWeight;
      totalScore += weight;
      candidatePixels += 1;
      scores.set(id, (scores.get(id) || 0) + weight);
      const sum = sums.get(id) || { r:0, g:0, b:0, n:0, weight:0 };
      sum.r += r * weight; sum.g += g * weight; sum.b += b * weight; sum.n += 1; sum.weight += weight;
    sums.set(id, sum);
    }
  }
  const sorted = [...scores.entries()].sort((a, b) => b[1] - a[1]);
  if (!sorted.length) return null;
  const [id, score] = sorted[0];
  const secondScore = sorted[1]?.[1] || 0;
  const sum = sums.get(id);
  const hex = sum?.weight
    ? `#${[sum.r / sum.weight, sum.g / sum.weight, sum.b / sum.weight].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('')}`
    : '';
  const meta = optColorById(id);
  const dominance = totalScore ? score / totalScore : 0;
  const separation = score ? Math.max(0, Math.min(1, (score - secondScore) / score)) : 0;
  const confidence = Math.max(0, Math.min(1, dominance * 0.68 + separation * 0.32));
  return {
    id,
    label: meta?.label || id,
    confidence,
    hex,
    method: OPTION_COLOR_HINT_METHOD,
    candidatePixels,
    backgroundRgb: bg ? {
      r: Math.round(bg.r),
      g: Math.round(bg.g),
      b: Math.round(bg.b),
    } : null,
  };
}

async function optInferAndStoreImageColorHint(imgId, os = state.optionSorter, options = {}) {
  const img = os.images.find(im => im.id === imgId);
  const src = optImageSrc(img);
  if (!img || !src) return null;
  if (!options.force && img.colorHint?.method === OPTION_COLOR_HINT_METHOD) return img.colorHint;
  try {
    const hint = await optInferImageColorHint(src);
    img.colorHint = hint || { id:'unknown', label:'색상 미확인', confidence:0, hex:'' };
    optScheduleSave();
    if (!options.silent) render();
    return img.colorHint;
  } catch(e) {
    img.colorHint = { id:'unknown', label:'색상 미확인', confidence:0, hex:'' };
    optScheduleSave();
    if (!options.silent) render();
    return img.colorHint;
  }
}

async function optEnsureImageColorHints(os = state.optionSorter, options = {}) {
  const targets = (os.images || []).filter(img => optHasImagePayload(img) && (options.force || !img.colorHint || img.colorHint.method !== OPTION_COLOR_HINT_METHOD));
  for (const img of targets) {
    await optInferAndStoreImageColorHint(img.id, os, options);
  }
}

function optWarmColorHints(os = state.optionSorter) {
  if (!os || os.optionColorHintBusy) return;
  if (!(os.images || []).some(img => optHasImagePayload(img) && (!img.colorHint || img.colorHint.method !== OPTION_COLOR_HINT_METHOD))) return;
  os.optionColorHintBusy = true;
  setTimeout(async () => {
    try {
      await optEnsureImageColorHints(os, { silent: true });
    } finally {
      os.optionColorHintBusy = false;
      optScheduleSave(80);
      render();
    }
  }, 0);
}

function optPairColorConflict(pair) {
  const labelColors = optExtractLabelColors(pair?.optionName);
  const hint = optGetAuthoritativeColorHint(pair?.img);
  if (!labelColors.length || !optIsUsableColorHint(hint)) return null;
  if (labelColors.some(labelColor => optColorCompatible(labelColor, hint.id))) return null;
  return {
    labelColorIds: labelColors,
    labelColors: labelColors.map(id => optColorById(id)?.label || id),
    imageColorId: hint.id,
    imageColor: hint.label || hint.id,
    confidence: hint.confidence,
    method: hint.method || '',
    sourceLabel: optColorHintSourceLabel(hint),
    modelLabel: hint.modelLabel || '',
    reason: hint.reason || '',
  };
}

function optColorLockLine(pair, idx = 0) {
  const hint = optGetAuthoritativeColorHint(pair?.img);
  const labelColors = optExtractLabelColors(pair?.optionName).map(id => optColorById(id)?.label || id);
  const conflict = optPairColorConflict(pair);
  const visual = hint?.label && hint.id !== 'unknown'
    ? `source product color is judged as ${hint.label} by ${optColorHintSourceLabel(hint) || 'color check'} (confidence ${Math.round((hint.confidence || 0) * 100)}%)`
    : 'source image visual color is authoritative';
  const reason = hint?.reason ? ` Evidence: ${hint.reason}` : '';
  return `Cell ${idx + 1} / source No. ${pair.order}: ${visual}.${reason} Option label "${pair.optionName}" is TEXT ONLY${labelColors.length ? ` and contains color word(s): ${labelColors.join(', ')}` : ''}.${conflict ? ` WARNING: label color word conflicts with visible source color. Preserve the uploaded product's visible ${conflict.imageColor} color and render the label text exactly as "${pair.optionName}". Do NOT recolor the product to ${conflict.labelColors.join(', ')}.` : ''}`;
}

function optFormatColorHintSummary(hint) {
  if (!hint?.label) return '';
  const confidence = Number.isFinite(Number(hint.confidence)) ? ` · ${Math.round(Number(hint.confidence) * 100)}%` : '';
  const model = hint.modelLabel ? ` · ${hint.modelLabel}` : '';
  const reason = hint.reason ? ` · ${hint.reason}` : '';
  return `${optColorHintSourceLabel(hint) || '색상 판정'}: ${hint.label}${confidence}${model}${reason}`;
}

function optRenderOptionColorHintRows(pair) {
  const active = optGetAuthoritativeColorHint(pair?.img);
  const vision = pair?.img?.colorVisionHint;
  const pixel = pair?.img?.colorHint;
  const rows = [];
  if (active?.label && active.id !== 'unknown') rows.push({ cls: 'active', text: `원본색 기준: ${optFormatColorHintSummary(active)}` });
  if (vision?.method === OPTION_COLOR_VISION_HINT_METHOD && (!active || active.method !== OPTION_COLOR_VISION_HINT_METHOD)) {
    const reason = vision.error ? ` · ${vision.error}` : '';
    rows.push({ cls: 'muted', text: `AI 비전 판정: ${vision.label || '색상 미확인'}${reason}` });
  }
  if (pixel?.label && (!active || active.method !== OPTION_COLOR_HINT_METHOD)) {
    rows.push({ cls: 'muted', text: `보조값: ${optFormatColorHintSummary(pixel)}` });
  }
  return rows.map(row => `<div class="src" style="${row.cls === 'active' ? 'color:var(--text-d);font-weight:800' : 'color:var(--text-m)'}">${escapeHtml(row.text)}</div>`).join('');
}

function optBatchLabel(batchNo) {
  const n = Math.max(1, Number(batchNo) || 1);
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let value = n;
  let label = '';
  while (value > 0) {
    value -= 1;
    label = alphabet[value % 26] + label;
    value = Math.floor(value / 26);
  }
  return `${label}안`;
}

function optNextBatchNo(os = state.optionSorter) {
  const results = Array.isArray(os.optionResults) ? os.optionResults : [];
  const maxBatch = results.reduce((max, result) => Math.max(max, Number(result?.batchNo) || 0), 0);
  return maxBatch + 1;
}

function optAppendLogs(os, lines, limit = 60) {
  const next = [...(Array.isArray(os.optionGenLogs) ? os.optionGenLogs : []), ...[].concat(lines).filter(Boolean)];
  os.optionGenLogs = next.slice(-limit);
}

function optDataUrlToImagePart(dataUrl) {
  const match = String(dataUrl || '').match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return null;
  return { mime: match[1], base64: match[2] };
}

function optionSorterColorImagesDisabled(os = state.optionSorter) {
  return (os?.optionColorImageUsage || 'use') === 'none';
}

function clearOptionColorSectionPlacement(options = {}) {
  let changed = false;
  if (state.cuts?.placement && Object.prototype.hasOwnProperty.call(state.cuts.placement, 'size_color')) {
    delete state.cuts.placement.size_color;
    changed = true;
  }
  if (state.sectionImages?.size_color) {
    delete state.sectionImages.size_color;
    changed = true;
  }
  if (state.sectionContents?.size_color) {
    delete state.sectionContents.size_color;
    changed = true;
  }
  if (changed && options.save !== false) savePlacement();
  return changed;
}

function optSetColorImageUsage(usage, os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const nextUsage = usage === 'none' ? 'none' : 'use';
  if (os.optionColorImageUsage === nextUsage) return false;
  os.optionColorImageUsage = nextUsage;
  if (nextUsage === 'none') {
    clearOptionColorSectionPlacement();
    optAppendLogs(os, '색상이미지 안씀: 섹션설정에서 색상옵션 섹션과 옵션표 배치를 제외했습니다.');
  } else {
    optAppendLogs(os, '색상이미지 사용: 옵션표 결과를 섹션설정 색상옵션 섹션에 다시 사용할 수 있습니다.');
  }
  return true;
}

function optNormalizeStyleSample(sample) {
  if (!sample || typeof sample !== 'object' || !sample.image) return null;
  return {
    id: sample.id || uid('sample'),
    libraryId: sample.libraryId || '',
    sourceResultId: sample.sourceResultId || '',
    name: String(sample.name || '옵션표 샘플'),
    image: sample.image,
    tonePresetName: sample.tonePresetName || '',
    pipelineName: sample.pipelineName || '',
    modelLabel: sample.modelLabel || '',
    sourceName: sample.sourceName || '',
    createdAt: sample.createdAt || new Date().toISOString(),
    savedAt: sample.savedAt || new Date().toISOString(),
  };
}

function optGetStyleSampleLibrary() {
  const items = loadJson(STORAGE_KEYS.optionStyleSamples, []);
  return Array.isArray(items)
    ? items.map(optNormalizeStyleSample).filter(Boolean).slice(0, 24)
    : [];
}

function optSaveStyleSampleLibrary(samples) {
  const normalized = (Array.isArray(samples) ? samples : []).map(optNormalizeStyleSample).filter(Boolean).slice(0, 24);
  try {
    localStorage.setItem(STORAGE_KEYS.optionStyleSamples, JSON.stringify(normalized));
    return true;
  } catch (e) {
    console.warn('Option style sample save failed:', e);
    return false;
  }
}

function optRememberStyleSample(sample, os = state.optionSorter) {
  const normalized = optNormalizeStyleSample({
    ...sample,
    libraryId: sample?.libraryId || uid('samplelib'),
    savedAt: new Date().toISOString(),
  });
  if (!normalized) return null;
  const existing = optGetStyleSampleLibrary()
    .filter(item => item.libraryId !== normalized.libraryId && item.sourceResultId !== normalized.sourceResultId);
  const ok = optSaveStyleSampleLibrary([normalized, ...existing]);
  optAppendLogs(os, ok
    ? `샘플 보관함 저장: ${normalized.name}`
    : '샘플 보관함 저장 실패: 브라우저 저장 공간이 부족할 수 있습니다. 현재 활성 샘플은 작업 안에서는 유지됩니다.');
  return normalized;
}

function optBuildStyleSampleFromResult(result) {
  const image = factoryOptionSorterResultDisplayImage(result);
  if (!image) return null;
  return optNormalizeStyleSample({
    id: uid('sample'),
    sourceResultId: result.id,
    name: `${result.tonePresetName || '옵션표'} · ${result.optionName || '샘플'}`,
    image,
    tonePresetName: result.tonePresetName,
    pipelineName: result.pipelineName,
    modelLabel: result.modelLabel,
    sourceName: result.sourceName,
    createdAt: result.createdAt,
  });
}

function optSetStyleSample(sample, os = state.optionSorter, options = {}) {
  const normalized = optNormalizeStyleSample(sample);
  if (!normalized) return false;
  const remembered = options.saveToLibrary === false ? normalized : optRememberStyleSample(normalized, os) || normalized;
  os.styleSample = remembered;
  os.styleSampleResultId = remembered.sourceResultId || '';
  os.styleSampleLibraryId = remembered.libraryId || '';
  optAppendLogs(os, `샘플 이미지 하네스 적용: ${remembered.name}`);
  return true;
}

function optSetStyleSampleFromResult(resultId, os = state.optionSorter) {
  const result = (os.optionResults || []).find(item => item.id === resultId);
  const sample = optBuildStyleSampleFromResult(result);
  const ok = optSetStyleSample(sample, os, { saveToLibrary: true });
  if (ok) ensureDefaultSectionPlacements({ forceOption: true });
  return ok;
}

function optSetStyleSampleFromLibrary(libraryId, os = state.optionSorter) {
  const sample = optGetStyleSampleLibrary().find(item => item.libraryId === libraryId);
  return optSetStyleSample(sample, os, { saveToLibrary: false });
}

function optClearStyleSample(os = state.optionSorter) {
  os.styleSample = null;
  os.styleSampleResultId = null;
  os.styleSampleLibraryId = null;
  optAppendLogs(os, '샘플 이미지 하네스를 해제했습니다. 다음 생성은 톤앤매너 프리셋만 기준으로 진행합니다.');
}

function optDeleteStyleSampleFromLibrary(libraryId, os = state.optionSorter) {
  const remaining = optGetStyleSampleLibrary().filter(item => item.libraryId !== libraryId);
  optSaveStyleSampleLibrary(remaining);
  if (os.styleSampleLibraryId === libraryId) optClearStyleSample(os);
  else optAppendLogs(os, '샘플 보관함에서 삭제했습니다.');
}

function optGetActiveStyleSample(os = state.optionSorter) {
  const active = optNormalizeStyleSample(os?.styleSample);
  if (active) return active;
  const result = (os?.optionResults || []).find(item => item.id === os?.styleSampleResultId);
  return optBuildStyleSampleFromResult(result);
}

function optGetActiveStyleSampleImagePart(os = state.optionSorter) {
  const sample = optGetActiveStyleSample(os);
  if (!sample?.image) return null;
  const part = optDataUrlToImagePart(sample.image);
  return part ? { ...part, name: sample.name } : null;
}

function getOptionImagePairs(os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const images = os.images || [];
  const assigned = [];
  (os.slots || []).forEach((slot, slotIdx) => {
    (slot.imgIds || []).forEach(imgId => {
      const img = images.find(im => im.id === imgId);
      if (!img) return;
      assigned.push({
        img,
        pairKey: `${slot.id}:${img.id}`,
        slotId: slot.id,
        slotIndex: slotIdx + 1,
        optionName: (slot.name || '').trim() || img.name || `${slotIdx + 1}번`,
        source: '슬롯 배정 순서',
      });
    });
  });
  const byKey = new Map(assigned.map(pair => [pair.pairKey, pair]));
  const requested = Array.isArray(os.optionPairOrder) ? os.optionPairOrder : [];
  const orderedKeys = [
    ...requested.filter(key => byKey.has(key)),
    ...assigned.map(pair => pair.pairKey).filter(key => !requested.includes(key)),
  ];
  os.optionPairOrder = orderedKeys;
  return orderedKeys.map((key, index) => ({ ...byKey.get(key), order: index + 1, slotIndex: index + 1 }));
}

function optSwapOptionPairOrder(firstKey, secondKey, os = state.optionSorter) {
  const pairs = getOptionImagePairs(os);
  const order = pairs.map(pair => pair.pairKey);
  const firstIndex = order.indexOf(firstKey);
  const secondIndex = order.indexOf(secondKey);
  if (firstIndex < 0 || secondIndex < 0 || firstIndex === secondIndex) return false;
  [order[firstIndex], order[secondIndex]] = [order[secondIndex], order[firstIndex]];
  os.optionPairOrder = order;
  optScheduleSave();
  return true;
}

function optRenderOptionMapCard(pair) {
  return `<article class="opt-option-map-card" data-opt-map-pair-key="${escAttr(pair.pairKey)}">
    <button class="opt-map-drag-handle" type="button" title="이 사진과 옵션명 묶음을 다른 위치와 교환"><span class="material-icons-outlined">drag_indicator</span></button>
    ${optRenderImageOrPlaceholder(pair.img, `alt="${escapeHtml(pair.img.name)}" role="button" tabindex="0" data-opt-preview-img="${pair.img.id}" title="${escapeHtml(pair.img.name)} 크게 보기"`, '이미지 복원 중')}
    <div style="min-width:0">
      <div class="order">${pair.order}번 사진 → ${pair.order}번 옵션</div>
      <div class="name">${escapeHtml(pair.optionName)}</div>
      <div class="src">${escapeHtml(pair.img.name)}</div>
      ${optRenderOptionColorHintRows(pair)}
      ${optPairColorConflict(pair) ? `<div class="opt-option-map-conflict">옵션명 색상어와 ${escapeHtml(optPairColorConflict(pair).sourceLabel || '원본색 판정')}이 달라 보입니다. 상품색은 원본 기준으로 고정됩니다.</div>` : ''}
    </div>
  </article>`;
}

function optRenderOptionMapLayout(sheets = []) {
  return sheets.map(sheet => {
    let offset = 0;
    return `<section class="opt-option-map-sheet" data-opt-map-sheet="${sheet.index}">
      ${sheet.totalSheets > 1 ? `<div class="opt-option-map-sheet-title">${escapeHtml(sheet.label)} · ${escapeHtml(sheet.rowPattern.join('/'))}</div>` : ''}
      ${sheet.rowPattern.map((count, rowIndex) => {
        const rowPairs = sheet.pairs.slice(offset, offset + count);
        offset += count;
        return `<div class="opt-option-map-row" data-opt-map-row-index="${rowIndex}" style="grid-template-columns:repeat(${Math.max(1, count)},minmax(0,1fr))">${rowPairs.map(optRenderOptionMapCard).join('')}</div>`;
      }).join('')}
    </section>`;
  }).join('');
}

function optGetOptionSheetGrid(os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const cols = clampOptionSheetCount(os.optionSheetCols, os.optionOutputLayout === 'pairs' ? 2 : 2);
  const rows = clampOptionSheetCount(os.optionSheetRows, os.optionOutputLayout === 'pairs' ? 1 : 2);
  return {
    cols,
    rows,
    capacity: Math.max(1, cols * rows),
    label: `${rows}x${cols} 옵션표`,
  };
}

function optResolveOptionSheetRenderGrid(sheet = null, os = state.optionSorter) {
  const selectedLayout = optGetSelectedLayoutPattern(os, Array.isArray(sheet?.pairs) ? sheet.pairs.length : 0);
  const selectedCols = clampOptionSheetCount(sheet?.selectedCols || sheet?.cols, selectedLayout.selectedCols);
  const selectedRows = clampOptionSheetCount(sheet?.selectedRows || sheet?.rows, selectedLayout.selectedRows);
  const selectedPattern = optNormalizeRowPattern(sheet?.selectedPattern || selectedLayout.selectedPattern, 30);
  const selectedCapacity = Math.max(1, sheet?.capacity || optPatternCellCount(selectedPattern) || selectedCols * selectedRows);
  const pairCount = Array.isArray(sheet?.pairs)
    ? sheet.pairs.length
    : Number.isFinite(Number(sheet?.pairCount)) ? Number(sheet.pairCount) : selectedCapacity;
  const realCount = Math.max(0, Math.min(selectedCapacity, Number.parseInt(pairCount, 10) || 0));
  const rowPattern = optCompactPatternForCount(sheet?.rowPattern || selectedPattern, realCount || selectedCapacity);
  const cols = Math.max(...rowPattern);
  const rows = rowPattern.length;
  return {
    cols,
    rows,
    capacity: selectedCapacity,
    realCount,
    rowPattern,
    selectedCols,
    selectedRows,
    selectedPattern,
    selectedLabel: sheet?.selectedLabel || selectedLayout.selectedLabel || `${selectedRows}x${selectedCols}`,
    label: rowPattern.join(','),
  };
}

function optGetOptionSheetRawPixelSize(grid = null) {
  const cols = clampOptionSheetCount(grid?.cols, 2);
  const rows = clampOptionSheetCount(grid?.rows, 2);
  const tileW = 560;
  const tileH = 620;
  const gap = 34;
  const pad = 46;
  const width = pad * 2 + cols * tileW + (cols - 1) * gap;
  const height = pad * 2 + rows * tileH + (rows - 1) * gap;
  return {
    width,
    height,
    cols,
    rows,
    aspect: width / height,
  };
}

function optGetOptionSheetPixelRecommendations(os = state.optionSorter, gridOverride = null) {
  ensureOptionSorterDefaults(os);
  const grid = gridOverride || optGetOptionSheetGrid(os);
  const raw = optGetOptionSheetRawPixelSize(grid);
  const twoK = optScaleOptionSheetSize(raw.width, raw.height, 2048, { allowUpscale: true });
  const fourK = optScaleOptionSheetSize(raw.width, raw.height, 4096, { allowUpscale: true });
  const auto = optScaleOptionSheetSize(raw.width, raw.height, 4096, { allowUpscale: false });
  return {
    ...raw,
    twoK,
    fourK,
    auto,
    label: `${raw.rows}x${raw.cols}`,
  };
}

function optPixelPresetLabel(preset) {
  if (preset === '2k') return '2K 가성비';
  if (preset === '4k') return '4K 최고화질';
  if (preset === 'custom') return '직접 지정';
  return '자동 크기';
}

function optGetPixelAspectWarning(size, rec) {
  const width = Number(size?.width) || 0;
  const height = Number(size?.height) || 0;
  const targetAspect = Number(rec?.aspect) || 1;
  if (width <= 0 || height <= 0 || targetAspect <= 0) return '';
  const currentAspect = width / height;
  const ratioGap = Math.max(currentAspect / targetAspect, targetAspect / currentAspect);
  if (ratioGap < 1.22) return '';
  const target = Math.max(width, height) <= 2300 ? rec.twoK : rec.fourK;
  return `현재 ${width}px x ${height}px은 ${rec.label} 배치 비율과 차이가 큽니다. 권장값은 ${target.width}px x ${target.height}px입니다.`;
}

function optApplyOptionSheetPixelPreset(os = state.optionSorter, preset = 'auto', gridOverride = null) {
  ensureOptionSorterDefaults(os);
  const rec = optGetOptionSheetPixelRecommendations(os, gridOverride);
  if (preset === '2k' || preset === '4k') {
    const target = preset === '2k' ? rec.twoK : rec.fourK;
    os.optionSheetPixelMode = 'custom';
    os.optionSheetPixelPreset = preset;
    os.optionSheetWidth = target.width;
    os.optionSheetHeight = target.height;
    return target;
  }
  if (preset === 'custom') {
    const target = rec.auto;
    os.optionSheetPixelMode = 'custom';
    os.optionSheetPixelPreset = 'custom';
    os.optionSheetWidth = target.width;
    os.optionSheetHeight = target.height;
    return target;
  }
  os.optionSheetPixelMode = 'auto';
  os.optionSheetPixelPreset = 'auto';
  return rec.auto;
}

function optRefreshOptionSheetPixelForLayout(os = state.optionSorter, gridOverride = null) {
  if (!os || os.optionSheetPixelMode !== 'custom') return null;
  const preset = ['2k', '4k'].includes(os.optionSheetPixelPreset) ? os.optionSheetPixelPreset : 'custom';
  return optApplyOptionSheetPixelPreset(os, preset, gridOverride);
}

function optGetOptionSheetSize(os = state.optionSorter, gridOverride = null) {
  ensureOptionSorterDefaults(os);
  const grid = gridOverride || optGetOptionSheetGrid(os);
  const raw = optGetOptionSheetRawPixelSize(grid);
  const rawAutoWidth = raw.width;
  const rawAutoHeight = raw.height;
  const autoSize = optScaleOptionSheetAutoSize(raw.width, raw.height);
  const autoWidth = autoSize.width;
  const autoHeight = autoSize.height;
  const custom = os.optionSheetPixelMode === 'custom';
  return {
    mode: custom ? 'custom' : 'auto',
    preset: custom ? (os.optionSheetPixelPreset || 'custom') : 'auto',
    width: custom ? clampOptionSheetPixels(os.optionSheetWidth, autoWidth) : autoWidth,
    height: custom ? clampOptionSheetPixels(os.optionSheetHeight, autoHeight) : autoHeight,
    autoWidth,
    autoHeight,
  };
}

async function optApplyOptionSheetPixelSize(dataUrl, os = state.optionSorter) {
  const size = optGetOptionSheetSize(os);
  if (!dataUrl || size.mode !== 'custom') return dataUrl;
  return resizeImageDataUrl(dataUrl, size.width, size.height);
}

function buildOptionSelectionPrompt(pair, pairs, os = state.optionSorter) {
  const mode = os.optionImageMode === 'raw' ? 'raw' : 'ready';
  const tone = (os.optionTone || '').trim() || '흰 배경, 동일한 여백, 부드러운 자연광, 은은한 그림자, 상품은 중앙에 또렷하게';
  const tonePresetName = getOptionToneDisplayName(os);
  const pipeline = getOptionGenerationPipeline(os);
  const mapping = pairs.map(p => `${p.order}. uploaded image "${p.img.name}" -> option name "${p.optionName}"`).join('\n');
  const colorLocks = pairs.map((p, idx) => optColorLockLine(p, idx)).join('\n');
  const modeRule = mode === 'raw'
    ? `RAW PHOTO REFINEMENT MODE:
The uploaded image may be a rough original photo. Clean the background, unify lighting, crop, spacing, shadow, and ecommerce presentation so it becomes a polished option-selection image.
Allowed and required when needed: remove the original photo background, correct exposure, straighten/rotate the product into the target option-card orientation, add clean white/neutral background, add subtle shadow, center the product.
Forbidden: changing the product silhouette, color, fabric, ornament, string/handle position, decoration, closure, size impression, or making it into a different product.`
    : `READY OPTION PHOTO MODE:
The uploaded image is already close to an option-selection photo. Do only minimal polish: consistent crop, consistent margin, clean frame, very light background/lighting adjustment.
Preserve the product appearance as much as possible, but do not preserve mismatched source-photo background, table color, camera tilt, or casual snapshot framing when the option sheet template requires a cleaner standardized card. Do not redesign, redraw, or beautify into a different product.`;

  return `Create ONE square ecommerce option-selection image for a Korean shopping mall.

Actual generation pipeline: ${pipeline.name}
NON-NEGOTIABLE PRODUCT PRESERVATION HARNESS:
The uploaded product photo is the sales product reference. Preserve silhouette, length/width ratio, fabric texture, color, string position, bead/embroidery ornament, closure, seams, and distinctive decoration. Do not invent a new product or use the option label as a color command. If tone/style conflicts with product preservation, ignore the tone/style.

CRITICAL ORDER AND NAME LOCK - follow exactly:
Full option mapping for this batch:
${mapping}

This generation is ONLY for mapping No. ${pair.order}.
Source image: "${pair.img.name}"
Exact option name: "${pair.optionName}"
Do not swap, reorder, translate, shorten, rename, or borrow any name/color/product detail from another option.
If the image includes a text label, the label must be exactly "${pair.optionName}" and no other option name.
The final output file/card will be used as option No. ${pair.order}, so the visual must represent this exact source image and this exact option name only.

OPTION LABEL IS NOT A COLOR COMMAND:
The option name is only text printed on the lower label. It must NEVER be used to recolor or redesign the product.
If the option name color word conflicts with the uploaded image color, preserve the uploaded image color and print the option name exactly as text.
Color lock notes:
${colorLocks}

STYLE/TONE LAYER - apply only after the preservation harness:
Selected tone preset: ${tonePresetName}
${tone}
Tone may affect only background, card border, lighting/shadow softness, label panel mood, and neatness. Tone must never modify the product itself.

${modeRule}

Output requirements:
- 1:1 square option thumbnail/card.
- Product centered and clearly visible.
- Clean ecommerce option selector style, not a full detail-page section.
- Keep the product identity locked to the uploaded source image.
- Do not generate multiple products in one image.

${buildProductIdentityGuard('full_image')}`;
}

function getOptionOutputSheets(pairs, os = state.optionSorter) {
  const sheets = [];
  const selected = optGetSelectedLayoutPattern(os, pairs.length);
  const capacity = Math.max(1, selected.capacity);
  const totalSheets = Math.max(1, Math.ceil(pairs.length / capacity));
  for (let i = 0; i < pairs.length; i += capacity) {
    const chunk = pairs.slice(i, i + capacity);
    const rowPattern = optCompactPatternForCount(selected.selectedPattern, chunk.length || capacity);
    const rows = rowPattern.length;
    const cols = Math.max(...rowPattern);
    sheets.push({
      index: sheets.length + 1,
      pairs: chunk,
      label: totalSheets <= 1 ? '전체 옵션표' : `전체 옵션표 ${sheets.length + 1}/${totalSheets}`,
      layout: `${rowPattern.join(',')} 행별 칸수 (${rows}행, 최대 ${cols}칸)`,
      cols,
      rows,
      rowPattern,
      selectedCols: selected.selectedCols,
      selectedRows: selected.selectedRows,
      selectedPattern: selected.selectedPattern,
      selectedLabel: selected.selectedLabel,
      capacity,
      totalSheets,
    });
  }
  return sheets;
}

function buildOptionSelectionSheetPrompt(sheet, allPairs, os = state.optionSorter, options = {}) {
  const mode = os.optionImageMode === 'raw' ? 'raw' : 'ready';
  const contentMode = os.optionContentMode || 'full_image';
  const tone = (os.optionTone || '').trim();
  const extraPrompt = String(os.optionExtraPrompt || '').trim();
  const tonePresetName = getOptionToneDisplayName(os);
  const pipeline = getOptionGenerationPipeline(os);
  const styleSample = optGetActiveStyleSample(os);
  const continuitySampleName = String(options.continuitySampleName || '').trim();
  const hasContinuitySample = !!continuitySampleName;
  const grid = optResolveOptionSheetRenderGrid(sheet, os);
  const size = optGetOptionSheetSize(os, grid);
  const allMapping = allPairs.map(p => `${p.order}. uploaded image "${p.img.name}" -> option name "${p.optionName}"`).join('\n');
  const colorLocks = sheet.pairs.map((p, idx) => optColorLockLine(p, idx)).join('\n');
  const rowStarts = [];
  (grid.rowPattern || []).reduce((sum, rowCount) => {
    rowStarts.push(sum);
    return sum + rowCount;
  }, 0);
  const sheetMapping = sheet.pairs.map((p, idx) => {
    let row = 1;
    for (let r = 0; r < rowStarts.length; r += 1) {
      const start = rowStarts[r];
      const end = start + (grid.rowPattern[r] || 0);
      if (idx >= start && idx < end) {
        row = r + 1;
        break;
      }
    }
    const col = idx - (rowStarts[row - 1] || 0) + 1;
    return `Cell ${idx + 1} (row ${row}, column ${col} of ${grid.rowPattern[row - 1] || grid.cols}): source image No. ${p.order} "${p.img.name}" -> exact label "${p.optionName}"`;
  }).join('\n');
  const rowHarness = (grid.rowPattern || []).map((rowCount, idx) => {
    const start = (rowStarts[idx] || 0) + 1;
    const end = start + rowCount - 1;
    return `Row ${idx + 1}: exactly ${rowCount} cell(s), filled by Cell ${start}${end > start ? ` through Cell ${end}` : ''}.`;
  }).join('\n');
  const referenceOrder = sheet.pairs.map((p, idx) => `Reference image ${idx + 1} attached to this API call = Cell ${idx + 1} = global source No. ${p.order} = exact label "${p.optionName}"`).join('\n');
  const styleSampleOrder = [
    styleSample
      ? `Reference image ${sheet.pairs.length + 1} attached after the product references = USER STYLE TEMPLATE SAMPLE ONLY: "${styleSample.name}". It is NOT a product option, NOT a color source, and NOT a label source.`
      : 'No user style template sample is attached.',
    hasContinuitySample
      ? `Reference image ${sheet.pairs.length + (styleSample ? 2 : 1)} attached after the product references${styleSample ? ' and user style sample' : ''} = PREVIOUS GENERATED SHEET CONTINUITY SAMPLE ONLY: "${continuitySampleName}". It is NOT a product option, NOT a color source, and NOT a label source.`
      : 'No previous generated sheet continuity sample is attached for this sheet.',
  ].join('\n');
  const orientationLabel = size.width > size.height ? 'WIDE HORIZONTAL LANDSCAPE' : size.width < size.height ? 'TALL VERTICAL PORTRAIT' : 'SQUARE';
  const forbiddenAutoGrid = `Do NOT auto-balance, reflow, wrap, square off, or reinterpret this layout. Do NOT change it into any other compact grid or near-square collage unless that exact row pattern is listed below.`;
  const layoutRule = `STRICT USER GRID GEOMETRY - ROWS x COLUMNS:
The user-selected layout capacity is "${grid.selectedLabel}" with capacity for ${grid.capacity} option card(s).
This actual sheet contains ${sheet.pairs.length} real option card(s).
Render this actual sheet using exactly ${grid.rows} horizontal row(s), with this row-by-row cell count pattern:
${rowHarness}
Maximum column count in this sheet is ${grid.cols}. Rows with fewer cells must keep those cells centered/aligned in the same card style, not filled with fake products.
Canvas orientation must be ${orientationLabel}. Final output size target: ${size.width}px wide x ${size.height}px tall.
${forbiddenAutoGrid}
Fill cells in row-major order from left to right, top to bottom. This sheet contains exactly ${sheet.pairs.length} real option card(s).
Do not invent extra products or labels for unused capacity. Keep all real cards the same size, style, margin, label position, and product scale.
If a later generic image-size hint conflicts with this option-sheet target, ignore the generic hint and follow this exact row pattern: ${grid.rowPattern.join(',')}.`;
  const modeRule = mode === 'raw'
    ? `RAW PHOTO UNIFICATION:
The source images may be rough originals. Clean and unify the presentation across all cells in THIS ONE OUTPUT IMAGE.
Every cell must share the same background color, lighting direction, product scale, upright orientation, crop, shadow strength, label size, label position, and typography.
Original source-photo backgrounds, table/floor colors, beige paper, shadows, camera tilt, and diagonal snapshot angles are NOT product identity. Remove/replace them so every cell matches the option-sheet template.`
    : `READY OPTION PHOTO UNIFICATION:
The source images are already close to option images. Do not redesign the products. Normalize crop, product scale, margin, background tone, label style, and product orientation across all cells in THIS ONE OUTPUT IMAGE.
If one source photo has a different background or tilted/diagonal snapshot composition, extract the same product identity and place it into the shared template instead of copying that raw photo composition.`;
  const contentRule = contentMode === 'full_image'
    ? `CONTENT MODE - FULL IMAGE:
The option names MUST be generated directly inside the final image by the image model.
Each lower label pill must contain the exact Korean option name from the mapping. The label text is part of the image itself.
This is the Nano Banana / Gemini image model's responsibility. Do not leave labels blank.`
    : contentMode === 'mixed'
      ? `CONTENT MODE - IMAGE PLUS SEPARATE TEXT:
Do NOT render option-name text inside the generated image.
Create the unified product/card/background image only. Leave a consistent blank lower label area in every cell.
The app will overlay the exact option-name text after image generation, using fixed coordinates.`
      : `CONTENT MODE - TEXT/LAYOUT ONLY:
Do not create a visual product image. Produce a clear option-sheet layout plan and exact option-label list only.`;
  const hardHarness = `NON-NEGOTIABLE PRODUCT PRESERVATION HARNESS - APPLY BEFORE ANY STYLE/TONE:
1. The uploaded product photo is the legal sales product reference. Preserve the product identity above all visual beautification.
2. Do NOT change silhouette, pouch length/width ratio, mouth/opening shape, fabric texture, color, string position, bead/embroidery ornament, closure, visible seams, or any distinctive decoration.
3. Do NOT invent a new product, add decorative bands, add new embroidery, add new labels on the product body, add handles, change pouch type, or make the product round/short/wide if the source is slim/rectangular.
4. Do NOT treat the option name as a color command. Option labels are text only. If label text conflicts with visible source color, keep the source product color.
5. Product identity does NOT include the original photo background, table color, paper backdrop, raw camera angle, or casual snapshot composition. Those must be replaced/normalized to match the shared option-sheet template.
6. All cells must share the same harnessed template: same grid geometry, same card size, same product scale, same product angle, same upright/straightened orientation, same margin, same lighting direction, same shadow level, same lower label zone.
7. If a source product is photographed diagonally or lying down but the sample/template is upright, straighten and re-place the product into the upright template while preserving its color, shape, ornament, strings, and fabric.
8. If tone/style conflicts with product preservation, ignore the tone/style and preserve the source product.
9. The final image must be an option selector, not a new advertising hero cut.`;
  const toneRule = `STYLE/TONE LAYER - APPLY ONLY AFTER THE HARNESS ABOVE:
Selected tone preset: ${tonePresetName}
${tone || 'Keep a clean ecommerce option selector style.'}
Tone may affect only background color, card border, light/shadow softness, label panel mood, and overall neatness. Tone must never modify the product itself.`;
  const extraPromptRule = extraPrompt
    ? `USER ADDITIONAL PROMPT (OPTIONAL FREEFORM INSTRUCTION):
${extraPrompt}
Apply this only after the product preservation harness and mapping locks.
It may refine layout mood, spacing emphasis, label styling, or background cleanliness.
It must NEVER change product identity, product colors, option order, option names, or invent extra products.`
    : '';
  const styleSampleRule = styleSample ? `STYLE TEMPLATE SAMPLE HARNESS - USE FOR CONSISTENCY ONLY:
The final attached reference image is the user's chosen sample sheet. Copy its option-sheet structure as closely as possible:
- same product orientation and angle discipline
- same grid geometry and card proportions
- same card border radius, border weight, and spacing
- same background tone and lighting mood
- same shadow direction, softness, and intensity
- same lower label pill shape, location, size, typography feeling, and margin rhythm

Do NOT copy products, colors, option names, product decorations, or text content from the sample sheet.
For every cell, the product image attached for that cell remains the only authority for product color, shape, ornament, string position, and fabric.
The sample sheet is authority for background, card geometry, label style, shadow, margin, and product orientation discipline.
If the sample sheet conflicts with the current product references, preserve the current product references and copy only the reusable layout/style traits.` : '';
  const continuityRule = hasContinuitySample ? `MULTI-SHEET CONTINUITY HARNESS - STRICT:
The final attached continuity reference is the successfully generated previous sheet from this same batch.
This current sheet must look like the next page of the same option selector set, not a newly designed sheet.
Match the previous sheet more strictly than the tone preset:
- same canvas crop and outer margin
- same card border color, thickness, radius, and spacing
- same product uprightness, centered placement, scale, and shadow treatment
- same label pill width/height/position/border/text style
- same background color and lighting
Do NOT let one product cell keep its raw source-photo background or diagonal pose if the previous sheet uses upright cards.
Only the current product reference images determine the products and colors.` : '';
  const seriesRule = allPairs.length > grid.capacity
    ? `This request is sheet ${sheet.index || 1} of a multi-sheet series because the selected layout capacity can hold ${grid.capacity} option(s). Keep the exact same template, crop discipline, label style, background, shadow, and product orientation across all sheets in the series.`
    : `This selected layout capacity can hold all ${allPairs.length} option(s) in ONE sheet. Do not split, wrap, or redesign it as a square collage.`;

  return `Create ONE unified option-selection sheet image for a Korean shopping mall.

Actual generation pipeline: ${pipeline.name}
${pipeline.harness}

THIS IS NOT A SQUARE COLLAGE AND NOT FOUR SEPARATE IMAGES. Output exactly one final sheet image for this request.
${layoutRule}

CRITICAL GLOBAL MAPPING LOCK:
All option mapping for the entire uploaded set:
${allMapping}

CRITICAL SHEET CELL LOCK:
This sheet must contain exactly these cells, in this exact order and position:
${sheetMapping}

CRITICAL ATTACHED IMAGE ORDER LOCK:
${referenceOrder}
${styleSampleOrder}
Use reference image 1 only for cell 1, reference image 2 only for cell 2, and so on. Never mix reference images between cells.
${seriesRule}

Do not swap cells. Do not change option names. Do not use a label from another source image.
The option name is only the label text. It is NOT a visual instruction and must NEVER change the source product color.
If a label says "노랑" but the uploaded reference image is green, keep the product green and print the exact label text "노랑".
Color/source locks for this sheet:
${colorLocks}

${hardHarness}

${styleSampleRule}

${continuityRule}

Every cell must have the same visual template:
- identical card size
- identical background color
- identical product angle: front-facing upright vertical composition unless the product physically cannot stand that way; do not leave only one cell diagonal/raw
- identical product scale and margin
- identical shadow softness
- identical lower label pill width, height, position, font size, font weight, border, and shadow
- if this mode uses text inside the image, exact option label text from the mapping

${contentRule}

${modeRule}

${toneRule}

${extraPromptRule}

Product identity protection:
Preserve each source product color, ornament, fabric, string position, bead/embroidery detail, and silhouette.
Never turn any option into a different product. Never add decorative bands, new embroidery, handles, extra strings, new closures, or new labels on the product body.
If beautification conflicts with accuracy or consistency, choose accuracy and consistency.

${buildProductIdentityGuard('full_image')}`;
}

function loadImageElement(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    try {
      const imageUrl = new URL(String(src || ''), window.location.href);
      if ((imageUrl.protocol === 'http:' || imageUrl.protocol === 'https:') && imageUrl.origin !== window.location.origin) {
        img.crossOrigin = 'anonymous';
      }
    } catch (_) {}
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

function drawFittedImage(ctx, img, x, y, w, h) {
  const ratio = Math.min(w / img.naturalWidth, h / img.naturalHeight);
  const dw = img.naturalWidth * ratio;
  const dh = img.naturalHeight * ratio;
  ctx.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
}

function drawFittedText(ctx, text, x, y, maxWidth, baseSize = 34) {
  let size = baseSize;
  ctx.font = `800 ${size}px Pretendard, Arial, sans-serif`;
  while (ctx.measureText(text).width > maxWidth && size > 10) {
    size -= 1;
    ctx.font = `800 ${size}px Pretendard, Arial, sans-serif`;
  }
  ctx.fillText(text, x, y);
}

function roundRect(ctx, x, y, w, h, r, fill = true, stroke = false) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
  if (fill) ctx.fill();
  if (stroke) ctx.stroke();
}

function optGetPatternCellPosition(index, rowPattern = [], maxCols = 1) {
  let offset = 0;
  const cols = Math.max(1, maxCols || Math.max(...(rowPattern || [1])));
  for (let row = 0; row < rowPattern.length; row += 1) {
    const rowCount = rowPattern[row] || cols;
    if (index < offset + rowCount) {
      const colInRow = index - offset;
      const emptySlots = Math.max(0, cols - rowCount);
      return {
        row,
        col: colInRow + emptySlots / 2,
        colInRow,
        rowCount,
      };
    }
    offset += rowCount;
  }
  return { row: 0, col: index, colInRow: index, rowCount: cols };
}

async function optComposeOptionSheetCanvas(sheet, os = state.optionSorter) {
  const contentMode = os.optionContentMode || 'full_image';
  const theme = getOptionCanvasTheme(os);
  const grid = optResolveOptionSheetRenderGrid(sheet, os);
  const cols = grid.cols;
  const rows = grid.rows;
  const rowPattern = grid.rowPattern || optGridPattern(rows, cols);
  const size = optGetOptionSheetSize(os, grid);
  const width = size.width;
  const height = size.height;
  const minSide = Math.min(width, height);
  const pad = Math.max(18, Math.min(70, minSide * 0.04));
  const gap = Math.max(10, Math.min(42, minSide * 0.025));
  const tileW = Math.max(24, (width - pad * 2 - (cols - 1) * gap) / cols);
  const tileH = Math.max(24, (height - pad * 2 - (rows - 1) * gap) / rows);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = theme.bg;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < sheet.pairs.length; i++) {
    const pair = sheet.pairs[i];
    const pos = optGetPatternCellPosition(i, rowPattern, cols);
    const col = pos.col;
    const row = pos.row;
    const x = pad + col * (tileW + gap);
    const y = pad + row * (tileH + gap);
    ctx.fillStyle = theme.cardBg;
    ctx.strokeStyle = theme.border;
    ctx.lineWidth = 2;
    ctx.shadowColor = theme.shadow;
    ctx.shadowBlur = 18;
    ctx.shadowOffsetY = 10;
    roundRect(ctx, x, y, tileW, tileH, theme.cardRadius, true, true);
    ctx.shadowColor = 'transparent';

    const src = optImageSrc(pair.img);
    if (!src) throw new Error(`${pair.optionName || pair.img?.name || '옵션'} 원본 이미지가 아직 복원되지 않았습니다.`);
    const img = await loadImageElement(src);
    ctx.save();
    ctx.filter = os.optionImageMode === 'raw' ? theme.imageFilterRaw : theme.imageFilterReady;
    const imagePadX = Math.max(10, tileW * 0.09);
    const imagePadTop = Math.max(10, tileH * 0.055);
    const imagePadBottom = Math.max(54, tileH * 0.25);
    drawFittedImage(ctx, img, x + imagePadX, y + imagePadTop, tileW - imagePadX * 2, tileH - imagePadTop - imagePadBottom);
    ctx.restore();

    const labelW = Math.max(42, Math.min(tileW * 0.72, tileW - Math.max(22, tileW * 0.14)));
    const labelH = Math.max(22, Math.min(58, tileH * 0.12));
    const labelX = x + (tileW - labelW) / 2;
    const labelY = y + tileH - labelH - Math.max(14, tileH * 0.055);
    ctx.fillStyle = theme.labelBg;
    ctx.strokeStyle = theme.labelBorder;
    ctx.lineWidth = 2;
    ctx.shadowColor = theme.labelShadow;
    ctx.shadowBlur = 8;
    ctx.shadowOffsetY = 4;
    roundRect(ctx, labelX, labelY, labelW, labelH, theme.labelRadius, true, true);
    ctx.shadowColor = 'transparent';
    if (contentMode === 'full_image') {
      ctx.fillStyle = theme.labelText;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      drawFittedText(ctx, pair.optionName, labelX + labelW / 2, labelY + labelH / 2 + 1, labelW - Math.max(12, labelW * 0.10), Math.max(12, Math.min(30, labelH * 0.52)));
    }
  }
  return canvas.toDataURL('image/png');
}

async function optOverlayOptionLabelsOnGeneratedSheet(imageDataUrl, sheet, os = state.optionSorter) {
  if (!imageDataUrl || !sheet?.pairs?.length) return imageDataUrl;
  const theme = getOptionCanvasTheme(os);
  const img = await loadImageElement(imageDataUrl);
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth || img.width;
  canvas.height = img.naturalHeight || img.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

  const grid = optResolveOptionSheetRenderGrid(sheet, os);
  const cols = grid.cols;
  const rows = grid.rows;
  const rowPattern = grid.rowPattern || optGridPattern(rows, cols);
  const outerPadX = canvas.width * 0.055;
  const outerPadY = canvas.height * 0.055;
  const gapX = canvas.width * 0.03;
  const gapY = canvas.height * 0.03;
  const cellW = (canvas.width - outerPadX * 2 - gapX * (cols - 1)) / cols;
  const cellH = (canvas.height - outerPadY * 2 - gapY * (rows - 1)) / rows;

  for (let i = 0; i < sheet.pairs.length; i++) {
    const pair = sheet.pairs[i];
    const pos = optGetPatternCellPosition(i, rowPattern, cols);
    const col = pos.col;
    const row = pos.row;
    const cellX = outerPadX + col * (cellW + gapX);
    const cellY = outerPadY + row * (cellH + gapY);
    const labelW = Math.min(cellW * 0.68, canvas.width * 0.32);
    const labelH = Math.max(34, Math.min(64, cellH * 0.115));
    const labelX = cellX + (cellW - labelW) / 2;
    const labelY = cellY + cellH - labelH - Math.max(18, cellH * 0.055);

    ctx.fillStyle = theme.labelBg;
    ctx.strokeStyle = theme.labelBorder;
    ctx.lineWidth = Math.max(2, canvas.width / 680);
    ctx.shadowColor = theme.labelShadow;
    ctx.shadowBlur = Math.max(5, canvas.width * 0.008);
    ctx.shadowOffsetY = Math.max(2, canvas.height * 0.004);
    roundRect(ctx, labelX, labelY, labelW, labelH, Math.min(theme.labelRadius, labelH / 2), true, true);
    ctx.shadowColor = 'transparent';
    ctx.fillStyle = theme.labelText;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    drawFittedText(ctx, pair.optionName, labelX + labelW / 2, labelY + labelH / 2 + 1, labelW - 26, Math.max(20, Math.min(34, labelH * 0.55)));
  }
  return canvas.toDataURL('image/png');
}

function optGetOptionSheetCellGeometry(sheet, os = state.optionSorter, imageWidth = 1, imageHeight = 1, strategy = 'generated') {
  const grid = optResolveOptionSheetRenderGrid(sheet, os);
  const cols = grid.cols;
  const rows = grid.rows;
  const rowPattern = grid.rowPattern || optGridPattern(rows, cols);
  const geos = [];

  if (strategy === 'locked_canvas') {
    const size = optGetOptionSheetSize(os, grid);
    const scaleX = imageWidth / Math.max(1, size.width);
    const scaleY = imageHeight / Math.max(1, size.height);
    const minSide = Math.min(size.width, size.height);
    const pad = Math.max(18, Math.min(70, minSide * 0.04));
    const gap = Math.max(10, Math.min(42, minSide * 0.025));
    const tileW = Math.max(24, (size.width - pad * 2 - (cols - 1) * gap) / cols);
    const tileH = Math.max(24, (size.height - pad * 2 - (rows - 1) * gap) / rows);
    for (let i = 0; i < sheet.pairs.length; i++) {
      const pos = optGetPatternCellPosition(i, rowPattern, cols);
      geos.push({
        pair: sheet.pairs[i],
        index: i,
        x: Math.max(0, Math.round((pad + pos.col * (tileW + gap)) * scaleX)),
        y: Math.max(0, Math.round((pad + pos.row * (tileH + gap)) * scaleY)),
        w: Math.max(1, Math.round(tileW * scaleX)),
        h: Math.max(1, Math.round(tileH * scaleY)),
      });
    }
    return geos;
  }

  const outerPadX = imageWidth * 0.055;
  const outerPadY = imageHeight * 0.055;
  const gapX = imageWidth * 0.03;
  const gapY = imageHeight * 0.03;
  const cellW = (imageWidth - outerPadX * 2 - gapX * (cols - 1)) / cols;
  const cellH = (imageHeight - outerPadY * 2 - gapY * (rows - 1)) / rows;
  for (let i = 0; i < sheet.pairs.length; i++) {
    const pos = optGetPatternCellPosition(i, rowPattern, cols);
    geos.push({
      pair: sheet.pairs[i],
      index: i,
      x: Math.max(0, Math.round(outerPadX + pos.col * (cellW + gapX))),
      y: Math.max(0, Math.round(outerPadY + pos.row * (cellH + gapY))),
      w: Math.max(1, Math.round(cellW)),
      h: Math.max(1, Math.round(cellH)),
    });
  }
  return geos;
}

async function optSplitOptionSheetResultImage(imageDataUrl, sheet, os = state.optionSorter, strategy = 'generated') {
  if (!imageDataUrl || !sheet?.pairs?.length) return [];
  const img = await loadImageElement(imageDataUrl);
  const width = img.naturalWidth || img.width || 1;
  const height = img.naturalHeight || img.height || 1;
  const geos = optGetOptionSheetCellGeometry(sheet, os, width, height, strategy);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  return geos.map((geo, idx) => {
    const cropX = Math.min(width - 1, Math.max(0, geo.x));
    const cropY = Math.min(height - 1, Math.max(0, geo.y));
    const cropW = Math.max(1, Math.min(width - cropX, geo.w));
    const cropH = Math.max(1, Math.min(height - cropY, geo.h));
    canvas.width = cropW;
    canvas.height = cropH;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);
    const optionName = geo.pair?.optionName || `${idx + 1}번 옵션`;
    return {
      order: idx + 1,
      sourceOrder: geo.pair?.order || '',
      sourceId: geo.pair?.img?.id || '',
      sourceName: geo.pair?.img?.name || '',
      optionName,
      fileName: `${String(idx + 1).padStart(2, '0')}_${optSafeArchiveFileName(optionName)}.png`,
      image: canvas.toDataURL('image/png'),
    };
  });
}

function optGetGroupShotSelectedImages(os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const available = (Array.isArray(os?.images) ? os.images : []).filter(image => (
    image?.id && optHasImagePayload(image)
  ));
  if (os.optionGroupShotSelectionMode !== 'custom') return available;
  const selectedIds = new Set(os.optionGroupShotSelectedImageIds || []);
  return available.filter(image => selectedIds.has(image.id));
}

function optSetGroupShotImageSelected(imageId, selected, os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const id = String(imageId || '').trim();
  if (!id || !(os.images || []).some(image => image?.id === id)) return false;
  const selectedIds = new Set(optGetGroupShotSelectedImages(os).map(image => image.id));
  if (selected) selectedIds.add(id);
  else selectedIds.delete(id);
  os.optionGroupShotSelectionMode = 'custom';
  os.optionGroupShotSelectedImageIds = (os.images || [])
    .map(image => image?.id)
    .filter(imageIdValue => selectedIds.has(imageIdValue));
  return selectedIds.has(id);
}

function optSelectAllGroupShotImages(os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  os.optionGroupShotSelectionMode = 'all';
  os.optionGroupShotSelectedImageIds = [];
  return (os.images || []).length;
}

function optClearGroupShotImages(os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  os.optionGroupShotSelectionMode = 'custom';
  os.optionGroupShotSelectedImageIds = [];
  return 0;
}

function buildOptionGroupShotPrompt(images = [], os = state.optionSorter) {
  const productName = String(state.productName || factoryRuntimeReadFactory()?.product?.productName || '상품').trim();
  const sourceList = images.map((image, index) => (
    `Reference ${index + 1}: preserve the exact product shape, material, ornament, and visible color from "${image.name || `${index + 1}번 색상`}"`
  )).join('\n');
  const extraPrompt = String(os?.optionGroupShotPrompt || '').trim();
  return `Create exactly ONE polished Korean ecommerce representative group-shot image for "${productName}".

REFERENCE LOCK:
${sourceList}

COMPOSITION:
- Show every selected color variant together in one cohesive representative product photo.
- Use one clean, bright neutral studio background with balanced spacing and a premium shopping-mall hero-image feeling.
- Keep every item fully visible, similarly scaled, sharp, and easy to compare.
- Arrange the variants naturally as one product family, not as separate cards, a contact sheet, a grid, or a collage.
- When many variants are attached, use a compact layered or gently fanned composition without hiding any selected product.

NON-NEGOTIABLE PRESERVATION:
- Preserve each selected source product's exact color, silhouette, fabric/material, strings, beads, embroidery, seams, closure, and distinctive decoration.
- Do not invent colors, omit selected variants, duplicate variants, merge products, recolor products, add text, add labels, add logos, or add option names.
- Background, lighting, spacing, and camera composition may be standardized; product identity may not be redesigned.

OUTPUT:
- Exactly one final image.
- Representative-product-photo composition suitable for the main image candidate list.
- No text, no watermark, no frame, no split panels.
${extraPrompt ? `\nUSER ADDITIONAL DIRECTION:\n${extraPrompt}\nApply it only to background, spacing, lighting, and composition. It must not override product or color preservation.` : ''}

${buildProductIdentityGuard('representative_image')}`;
}

async function optGenerateOptionGroupShot(options = {}) {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  const optionGroupShotTargetCount = 1;
  const selectedImages = optGetGroupShotSelectedImages(os);
  if (!selectedImages.length) {
    os.optionGroupShotLastError = '단체컷에 넣을 색상용 이미지를 한 장 이상 선택해주세요.';
    optAppendLogs(os, `단체컷 생성 중단: ${os.optionGroupShotLastError}`);
    optScheduleSave(100);
    render();
    return null;
  }
  if (!hasImageConnection()) {
    os.optionGroupShotLastError = '단체컷 생성에 필요한 이미지 API 연결이 없습니다.';
    optAppendLogs(os, `단체컷 생성 중단: ${os.optionGroupShotLastError}`);
    optScheduleSave(100);
    render();
    return null;
  }
  factoryEnsureArchiveStageRunId('options');
  const resultFactoryScope = factoryOptionResultCurrentScope(factoryRuntimeReadFactory());
  const resultScopeReady = !factoryOptionResultScopeMissingFields(resultFactoryScope).length;
  const prompt = buildOptionGroupShotPrompt(selectedImages, os);
  const first = await optImageDataPart(selectedImages[0]);
  const extras = [];
  for (const image of selectedImages.slice(1)) extras.push(await optImageDataPart(image));
  if (!first || extras.some(item => !item)) {
    os.optionGroupShotLastError = '선택한 색상용 이미지 원본이 아직 복원되지 않았습니다.';
    optAppendLogs(os, `단체컷 생성 중단: ${os.optionGroupShotLastError}`);
    optScheduleSave(100);
    render();
    return null;
  }

  os.optionGroupShotRunning = true;
  os.optionGroupShotProgress = 8;
  os.optionGroupShotLastError = '';
  optAppendLogs(os, `색상 단체컷 1장 생성 시작: 선택 ${selectedImages.length}/${(os.images || []).length}장`);
  optScheduleSave(100);
  render();
  await waitForNextPaint();

  try {
    const modelInfo = getCurrentImageRunInfo();
    os.optionGroupShotProgress = 35;
    render();
    const image = await generateWithSelectedImageModel(prompt, first.base64, first.mime, extras, {
      promptIntro: 'Create exactly one Korean ecommerce representative product group-shot image.',
      purpose: '색상 단체컷 대표이미지 후보',
      sizeHintText: 'Square or near-square representative product image. Keep every selected color variant fully visible.',
    });
    if (options.operationToken && !factoryRuntimeIsOperationCurrent(options.operationToken)) {
      throw factoryRuntimeStaleActionError('factory/optionsorter:generateGroupShot');
    }
    if (!image) throw new Error('이미지 응답이 비어 있습니다.');
    const batchNo = optNextBatchNo(os);
    const batchLabel = optBatchLabel(batchNo);
    const createdAt = new Date().toISOString();
    const result = {
      id: `or_group_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      resultKind: 'color-group-shot',
      sourceId: selectedImages.map(imageItem => imageItem.id).join(','),
      sourceName: selectedImages.map(imageItem => imageItem.name).join(' / '),
      batchNo,
      batchLabel,
      optionName: `색상 단체컷 · 대표이미지 후보 (${selectedImages.length}색)`,
      optionNames: selectedImages.map(imageItem => imageItem.name || '색상'),
      order: (os.optionResults || []).length + 1,
      mode: 'group-shot',
      contentMode: 'full_image',
      pipelineId: 'ai_color_group_shot',
      pipelineName: '색상 단체컷 1장 생성',
      usesImageModel: true,
      usesAppText: false,
      modeLabel: `대표이미지형 · 선택 ${selectedImages.length}색`,
      prompt,
      image,
      splitImages: [],
      modelId: modelInfo.modelId,
      modelLabel: modelInfo.modelLabel,
      createdAt,
      factoryScope: resultScopeReady ? { ...resultFactoryScope } : undefined,
      generationDetails: {
        schemaVersion: 1,
        createdAt,
        batch: { batchNo, batchLabel },
        model: {
          modelId: modelInfo.modelId,
          modelLabel: modelInfo.modelLabel,
          providerId: modelInfo.providerId,
          providerLabel: modelInfo.providerLabel,
          route: modelInfo.route,
        },
        generationMode: {
          pipelineId: 'ai_color_group_shot',
          pipelineName: '색상 단체컷 1장 생성',
          contentMode: 'full_image',
          imageModeLabel: '대표이미지형 단체컷',
          usesImageModel: true,
          usesAppText: false,
        },
        outputSplit: {
          sheetIndex: 1,
          sheetLabel: '색상 단체컷',
          sheetOptionCount: selectedImages.length,
          targetCount: optionGroupShotTargetCount,
        },
        mapping: {
          references: selectedImages.map((imageItem, index) => ({
            order: index + 1,
            role: 'selected_color_variant',
            imageName: imageItem.name || '',
          })),
          sheetCells: [],
          colorConflicts: [],
        },
        harness: {
          productPreservation: ['선택한 각 색상 원본의 형태·소재·장식·색상을 그대로 유지'],
          templateUniformity: ['모든 선택 색상을 한 장의 대표이미지형 스튜디오 구도로 배치'],
        },
        promptTrace: {
          storedPromptChars: prompt.length,
          activeDirectives: String(os.optionGroupShotPrompt || '').trim() ? ['사용자 추가 지시'] : [],
        },
      },
    };
    os.optionResults.push(result);
    os.optionGroupShotLastResultId = result.id;
    os.optionGroupShotProgress = 78;
    render();

    const archivedAsset = await factoryArchiveOptionSorterResultToWorkfile(result, {
      reason: options.reason || 'option-group-shot-generated',
    });
    if (archivedAsset) {
      optAppendLogs(os, result.heroAssetId
        ? '단체컷 저장 완료: 옵션분류기 결과와 대표이미지 후보에 함께 연결했습니다.'
        : '단체컷 저장 완료: 옵션분류기 결과에 보관했습니다. 현재 작업 범위 확인 후 대표이미지 후보 연결이 완료됩니다.');
    } else {
      optAppendLogs(os, '단체컷 생성 완료: 현재 작업 범위가 없어 옵션분류기 결과에만 보관했습니다.');
    }
    if (os.optionArchiveEnabled) {
      await optArchiveOptionResult(result);
      optAppendLogs(os, '단체컷 폴더 자동 저장 완료');
    }
    os.optionGroupShotProgress = 100;
    await optPersistGeneratedResultState();
    return result;
  } catch (error) {
    os.optionGroupShotLastError = error?.message || String(error);
    optAppendLogs(os, `색상 단체컷 생성 실패: ${os.optionGroupShotLastError}`);
    optScheduleSave(100);
    return null;
  } finally {
    os.optionGroupShotRunning = false;
    await optPersistGeneratedResultState();
    render();
  }
}

async function optGenerateOptionImages() {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  if (os.optionGenRunning) return;
  if (optionSorterColorImagesDisabled(os)) {
    clearOptionColorSectionPlacement();
    optAppendLogs(os, '생성 건너뜀: 색상이미지 안씀이 선택되어 옵션표를 만들지 않습니다.');
    optScheduleSave(100);
    render();
    return;
  }
  let pairs = getOptionImagePairs(os);
  if (!pairs.length) {
    optAppendLogs(os, '생성 중단: 옵션표를 만들 사진이 없습니다. 이미지를 업로드하거나 슬롯에 배정해주세요.');
    optScheduleSave(100);
    render();
    alert('옵션 선택 이미지를 만들 사진을 먼저 업로드해주세요.');
    return;
  }
  const batchNo = optNextBatchNo(os);
  const batchLabel = optBatchLabel(batchNo);
  const toneName = getOptionToneDisplayName(os);
  factoryEnsureArchiveStageRunId('options');
  const resultFactoryScope = factoryOptionResultCurrentScope(factoryRuntimeReadFactory());
  const resultScopeReady = !factoryOptionResultScopeMissingFields(resultFactoryScope).length;
  const generatedResultIds = [];
  const existingResultCount = Array.isArray(os.optionResults) ? os.optionResults.length : 0;
  os.optionGenRunning = true;
  os.optionGenProgress = 3;
  optAppendLogs(os, [
    `${toneName} 생성 시작(${batchLabel}): 기존 결과 ${existingResultCount}장은 유지하고 새 결과를 추가합니다.`,
    '색상/매핑 점검 중...',
    resultScopeReady
      ? '현재 작업 범위를 잠근 뒤 생성합니다. 생성 결과는 조립공장 현재 후보로만 보낼 수 있습니다.'
      : '현재 작업 범위가 완전하지 않아 생성 결과는 자동 전송하지 않습니다. 제품명과 기본이미지를 확인한 뒤 결과 카드에서 현재 작업 후보로 보내기를 눌러주세요.',
  ]);
  optScheduleSave(100);
  render();
  await waitForNextPaint();

  try {
    const colorCheckLogs = [];
    if (hasLlmConnection()) {
      await optEnsureImageVisionColorHints(os, { silent: true });
      colorCheckLogs.push('색상 판정: AI 비전 판정값을 픽셀 자동 추정보다 우선 적용합니다.');
    } else {
      colorCheckLogs.push('색상 판정: LLM 연결이 없어 픽셀 자동 추정색으로 충돌 경고를 계산합니다.');
    }
    await optEnsureImageColorHints(os, { silent: true });
    pairs = getOptionImagePairs(os);
    const sheets = getOptionOutputSheets(pairs, os);
    let contentMode = os.optionContentMode || 'full_image';
    let activePipeline = getOptionGenerationPipeline(os);
    let useAiSheet = activePipeline.usesImageModel && contentMode !== 'text_only';
    let activeStyleSample = optGetActiveStyleSample(os);
    if (activeStyleSample && !activeStyleSample.libraryId) {
      const rememberedStyleSample = optRememberStyleSample(activeStyleSample, os);
      if (rememberedStyleSample) {
        os.styleSample = rememberedStyleSample;
        os.styleSampleLibraryId = rememberedStyleSample.libraryId || '';
        activeStyleSample = rememberedStyleSample;
      }
    }
    const activeStyleSamplePart = optGetActiveStyleSampleImagePart(os);
    const startLogs = [...colorCheckLogs];
    if (useAiSheet && !hasImageConnection()) {
      optAppendLogs(os, [
        `생성 중단: ${activePipeline.name}은 이미지 API 연결이 필요합니다.`,
        '선택한 생성 방식은 자동으로 웹 내부 캔버스 합성으로 바꾸지 않았습니다. API 연결을 확인하거나 직접 웹 내부 캔버스 합성을 선택해주세요.',
      ]);
      throw new Error(`${activePipeline.name}에 필요한 이미지 API 연결이 없습니다.`);
    }
    const colorConflicts = pairs.map(pair => ({ pair, conflict: optPairColorConflict(pair) })).filter(item => item.conflict);
    if (useAiSheet && colorConflicts.length) {
      startLogs.push(`옵션명 색상과 원본 이미지 색상이 다른 항목 ${colorConflicts.length}개 감지: 선택한 ${activePipeline.name} 방식을 유지하고, 색상/형태 보존 하네스를 강화해서 진행합니다.`);
      colorConflicts.forEach(({ pair, conflict }) => {
        startLogs.push(`${pair.order}번 "${pair.optionName}": 라벨 색상어(${conflict.labelColors.join(', ')}) ≠ ${conflict.sourceLabel || '원본색 판정'}(${conflict.imageColor})`);
      });
    }
    const selectedLayout = optGetSelectedLayoutPattern(os, pairs.length || 1);
    const sheetSize = optGetOptionSheetSize(os, { rows: selectedLayout.selectedRows, cols: selectedLayout.selectedCols });
    startLogs.push(`옵션표 배치/픽셀: ${selectedLayout.selectedLabel} · 최대 ${selectedLayout.capacity}개/장 · 행별 ${selectedLayout.selectedPattern.join('/')}칸 · ${sheetSize.width}px x ${sheetSize.height}px (${sheetSize.mode === 'custom' ? '직접 지정' : '자동'})`);
    os.optionGenProgress = 0;
    optAppendLogs(os, [
      ...startLogs,
      `실제 생성 방식: ${activePipeline.name}`,
      activePipeline.harness,
      activeStyleSample
        ? `샘플 이미지 하네스 사용: ${activeStyleSample.name} · 제품/색상 근거가 아니라 레이아웃/각도/라벨/배경 기준으로만 참조합니다.`
        : '샘플 이미지 하네스 없음: 톤앤매너 프리셋과 매핑 잠금만 기준으로 생성합니다.',
      '원본색 잠금: 옵션명은 라벨 텍스트로만 사용하고, 상품 색상/형태는 업로드 원본 이미지를 기준으로 유지합니다.',
      `매핑 잠금: ${pairs.map(p => `${p.order}번=${p.optionName}`).join(' / ')}`,
    ]);
    if (!Array.isArray(os.optionResults)) os.optionResults = [];
    optScheduleSave(100);
    render();
    await waitForNextPaint();

    let seriesContinuityPart = null;
    let seriesContinuityName = '';
    for (const sheet of sheets) {
      const modelInfo = getCurrentImageRunInfo();
      const pipeline = getOptionGenerationPipeline(os, modelInfo);
      const modeLabel = os.optionImageMode === 'raw' ? 'RAW 사진 보정' : '정리된 옵션 사진';
      const prompt = buildOptionSelectionSheetPrompt(sheet, pairs, os, {
        continuitySampleName: seriesContinuityName,
        hasContinuitySample: !!seriesContinuityPart,
      });
      const finalPromptTrace = contentMode === 'mixed'
        ? `${prompt}\n\nAPP POST-PROCESS OVERLAY:\nAfter Nano Banana / Gemini returns the image without option-name text, the app overlays the exact Korean option labels using fixed grid coordinates. This app overlay is part of the final output pipeline and prevents label spelling/order hallucination. Labels overlaid by the app:\n${sheet.pairs.map((p, idx) => `Cell ${idx + 1}: ${p.optionName}`).join('\n')}`
        : prompt;
      const sheetNames = sheet.pairs.map(p => `${p.order}번 ${p.optionName}`).join(' / ');
      const resultToneName = getOptionToneDisplayName(os);
      optAppendLogs(os, `${resultToneName} ${sheet.index}번 옵션표 생성 중(${batchLabel}): ${sheetNames} (${pipeline.name}, ${modeLabel}, ${sheet.layout})${seriesContinuityPart ? ' · 이전 시트 연속성 샘플 첨부' : ''}`);
      os.optionGenProgress = Math.round(((sheet.index - 1) / sheets.length) * 100);
      optScheduleSave(100);
      render();
      await waitForNextPaint();
      try {
        let image = null;
        let methodLabel = pipeline.name;
        if (contentMode === 'text_only') {
          image = null;
        } else if (os.optionSheetMethod === 'locked_canvas') {
          image = await optComposeOptionSheetCanvas(sheet, os);
        } else {
          const first = await optImageDataPart(sheet.pairs[0].img);
          const extras = [];
          for (const pair of sheet.pairs.slice(1)) extras.push(await optImageDataPart(pair.img));
          if (!first || extras.some(item => !item)) throw new Error('옵션 원본 이미지가 아직 복원되지 않았습니다. 잠시 후 다시 생성해주세요.');
          if (activeStyleSamplePart) {
            extras.push({
              base64: activeStyleSamplePart.base64,
              mime: activeStyleSamplePart.mime,
              role: 'style_template_sample',
              name: activeStyleSamplePart.name,
            });
          }
          if (seriesContinuityPart) {
            extras.push({
              base64: seriesContinuityPart.base64,
              mime: seriesContinuityPart.mime,
              role: 'previous_sheet_continuity_sample',
              name: seriesContinuityName || '이전 시트 연속성 샘플',
            });
          }
          const sheetGridForPrompt = optResolveOptionSheetRenderGrid(sheet, os);
          const sheetSizeForPrompt = optGetOptionSheetSize(os, sheetGridForPrompt);
          image = await generateWithSelectedImageModel(prompt, first.base64, first.mime, extras, {
            promptIntro: 'Create exactly one Korean e-commerce option-selection sheet image, not a product detail page section.',
            sizeHintText: `Exact option-sheet canvas target: ${sheetSizeForPrompt.width}px wide × ${sheetSizeForPrompt.height}px tall. User row pattern is ${sheetGridForPrompt.rowPattern.join(',')} cell(s) per row, meaning ${sheetGridForPrompt.rows} row(s), maximum ${sheetGridForPrompt.cols} column(s), and ${sheet.pairs.length} real product cell(s) on this sheet. Preserve this aspect ratio and do not output a square collage unless this exact row pattern is square.`,
          });
          if (image && contentMode === 'mixed') {
            image = await optOverlayOptionLabelsOnGeneratedSheet(image, sheet, os);
          }
          if (image) {
            image = await optApplyOptionSheetPixelSize(image, os);
          }
        }
        if (!image && contentMode !== 'text_only') throw new Error('이미지 응답이 비어 있습니다.');
        const resultCreatedAt = new Date().toISOString();
        const resultOptionName = `${resultToneName} · ${sheet.label} (${sheet.pairs.length}개 옵션)`;
        const generationDetails = optBuildOptionGenerationDetails({
          os,
          sheet,
          allPairs: pairs,
          pipeline,
          modelInfo,
          prompt,
          finalPromptTrace,
          activeStyleSample,
          continuitySampleName: seriesContinuityName || '',
          hasContinuitySample: !!seriesContinuityPart,
          contentMode,
          modeLabel,
          toneName: resultToneName,
          batchNo,
          batchLabel,
          resultCreatedAt,
        });
        let splitImages = [];
        if (image && contentMode !== 'text_only') {
          try {
            splitImages = await optSplitOptionSheetResultImage(
              image,
              sheet,
              os,
              os.optionSheetMethod === 'locked_canvas' ? 'locked_canvas' : 'generated'
            );
            if (splitImages.length) optAppendLogs(os, `개별 옵션 이미지 분리 완료: ${splitImages.length}장`);
          } catch (splitError) {
            optAppendLogs(os, `개별 옵션 이미지 분리 실패: ${splitError.message || splitError}`);
          }
        }
        const resultRecord = {
          id: 'or_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
          sourceId: sheet.pairs.map(p => p.img.id).join(','),
          sourceName: sheet.pairs.map(p => p.img.name).join(' / '),
          batchNo,
          batchLabel,
          tonePresetId: os.optionTonePresetId || detectOptionTonePresetId(os.optionTone),
          tonePresetName: resultToneName,
          optionName: resultOptionName,
          optionNames: sheet.pairs.map(p => p.optionName),
          order: sheet.index,
          mode: os.optionImageMode,
          contentMode,
          pipelineId: pipeline.id,
          pipelineName: pipeline.name,
          usesImageModel: pipeline.usesImageModel,
          usesAppText: pipeline.usesAppText,
          modeLabel: `${resultToneName} · ${modeLabel} · ${methodLabel}`,
          tone: os.optionTone,
          prompt: finalPromptTrace,
          image,
          splitImages,
          modelId: contentMode === 'text_only' ? 'layout-only' : (pipeline.usesImageModel ? modelInfo.modelId : 'local-canvas-composer'),
          modelLabel: pipeline.engineLabel,
          styleSampleId: activeStyleSample?.id || '',
          styleSampleLibraryId: activeStyleSample?.libraryId || '',
          styleSampleName: activeStyleSample?.name || '',
          continuitySampleName: seriesContinuityName || '',
          generationDetails,
          createdAt: resultCreatedAt,
          factoryScope: resultScopeReady ? { ...resultFactoryScope } : undefined,
        };
        os.optionResults.push(resultRecord);
        generatedResultIds.push(resultRecord.id);
        if (image && contentMode !== 'text_only') {
          try {
            const archivedAsset = await factoryArchiveOptionSorterResultToWorkfile(resultRecord, { reason: 'option-result-generated' });
            optAppendLogs(os, archivedAsset
              ? `작업파일 로컬 저장 완료: ${resultOptionName}`
              : `작업파일 로컬 저장 대기: ${resultOptionName} · 현재 작업파일/제품/원본 식별자를 먼저 확인해주세요.`);
          } catch (workfileArchiveError) {
            optAppendLogs(os, `작업파일 로컬 저장 실패: ${resultOptionName} · ${workfileArchiveError.message || workfileArchiveError}`);
          }
        }
        if (os.optionArchiveEnabled) {
          try {
            await optArchiveOptionResult(resultRecord);
            optAppendLogs(os, `폴더 자동 저장 완료: ${resultOptionName}`);
          } catch (archiveError) {
            optAppendLogs(os, `폴더 자동 저장 실패: ${archiveError.message || archiveError}`);
          }
        }
        if (image && contentMode !== 'text_only') {
          const continuityPart = optDataUrlToImagePart(image);
          if (continuityPart) {
            seriesContinuityPart = {
              ...continuityPart,
              name: `${resultOptionName} · ${optFormatDateTime(resultCreatedAt)}`,
            };
            seriesContinuityName = seriesContinuityPart.name;
          }
        }
        optAppendLogs(os, `${resultToneName} ${sheet.index}번 옵션표 완료(${batchLabel}): ${sheetNames}`);
        await optPersistGeneratedResultState();
      } catch(e) {
        optAppendLogs(os, `${getOptionToneDisplayName(os)} ${sheet.index}번 옵션표 실패(${batchLabel}): ${e.message || e}`);
        optScheduleSave(100);
      }
      os.optionGenProgress = Math.round((sheet.index / sheets.length) * 100);
      render();
      await waitForNextPaint();
    }
    if (generatedResultIds.length) os.optionLastGeneratedResultIds = generatedResultIds;
    if (
      state.step !== 'factory' &&
      typeof factoryImportOptionSorterResults === 'function' &&
      generatedResultIds.length
    ) {
      const syncedCount = factoryImportOptionSorterResults({ silent: true, skipRender: true });
      if (syncedCount > 0) {
        optAppendLogs(os, `조립공장 연동 완료: 색상옵션표 ${syncedCount}장을 현재 작업 후보로 보냈습니다.`);
      }
    }
    optAppendLogs(os, `${toneName} 옵션 선택 이미지 생성 작업이 끝났습니다(${batchLabel}). 이전 결과와 함께 비교할 수 있게 보존했습니다.`);
  } catch(e) {
    optAppendLogs(os, `${toneName} 옵션표 생성 중단(${batchLabel}): ${e.message || e}`);
  } finally {
    os.optionGenRunning = false;
    os.optionGenProgress = 100;
    await optPersistGeneratedResultState();
    render();
  }
}

function optDownloadOptionResult(resultId) {
  const os = state.optionSorter;
  const result = (os.optionResults || []).find(r => r.id === resultId);
  const image = factoryOptionSorterResultDisplayImage(result);
  if (!image) return;
  const a = document.createElement('a');
  a.href = image;
  a.download = `${String(result.order).padStart(2, '0')}_${optSafeFilename(result.optionName)}_옵션선택.png`;
  a.click();
}

function optDownloadOptionResultSplits(resultId) {
  const os = state.optionSorter;
  const result = (os.optionResults || []).find(r => r.id === resultId);
  const splits = Array.isArray(result?.splitImages) ? result.splitImages.filter(item => item?.image) : [];
  splits.forEach((item, idx) => {
    setTimeout(() => {
      const a = document.createElement('a');
      a.href = item.image;
      a.download = item.fileName || `${String(item.order || idx + 1).padStart(2, '0')}_${optSafeFilename(item.optionName || '옵션')}.png`;
      a.click();
    }, idx * 120);
  });
}

function optGetReusableColorImagesFromResult(result) {
  if (!result) return [];
  const optionNames = Array.isArray(result.optionNames) ? result.optionNames : [];
  return (Array.isArray(result.splitImages) ? result.splitImages : [])
    .map((item, idx) => {
      const part = optDataUrlToImagePart(item?.image);
      if (!part) return null;
      const optionName = String(item.optionName || optionNames[idx] || item.sourceName || `${idx + 1}번`).trim();
      return {
        order: item.order || idx + 1,
        sourceOrder: item.sourceOrder || '',
        sourceId: item.sourceId || '',
        sourceName: item.sourceName || '',
        optionName,
        image: item.image,
        mime: part.mime,
        base64: part.base64,
      };
    })
    .filter(Boolean);
}

function optUseExistingColorImagesFromResult(resultId, os = state.optionSorter) {
  ensureOptionSorterDefaults(os);
  const result = (os.optionResults || []).find(item => item.id === resultId);
  const reusable = optGetReusableColorImagesFromResult(result);
  if (!result || !reusable.length) {
    optAppendLogs(os, '기존색상쓰기 실패: 개별 옵션 이미지가 남아 있는 생성 결과를 선택해주세요.');
    alert('이 결과에는 다시 쓸 수 있는 개별 옵션 이미지가 없습니다. 개별 이미지가 분리된 결과를 선택해주세요.');
    return 0;
  }
  const remaining = Math.max(0, 30 - (os.images || []).length);
  if (!remaining) {
    optAppendLogs(os, '기존색상쓰기 중단: 옵션 이미지는 최대 30장까지 사용할 수 있습니다.');
    alert('옵션 이미지는 최대 30장까지 사용할 수 있습니다.');
    return 0;
  }
  const startedAt = Date.now();
  const importedAt = new Date().toISOString();
  const selected = reusable.slice(0, remaining);
  const startIndex = os.images.length;
  const importedIds = [];
  selected.forEach((item, idx) => {
    const id = `oi_existing_${startedAt}_${idx}_${Math.random().toString(36).slice(2, 6)}`;
    const name = item.optionName || `기존색상 ${startIndex + idx + 1}번`;
    importedIds.push(id);
    os.images.push({
      id,
      name,
      base64: item.base64,
      mime: item.mime || 'image/png',
      preview: item.image,
      colorHint: null,
      colorVisionHint: null,
      source: '기존 옵션표 분리 이미지',
      importedFromOptionResultId: result.id,
      importedFromOptionResultName: result.optionName || '',
      importedSourceOrder: item.sourceOrder || item.order || '',
      importedSourceName: item.sourceName || '',
      importedAt,
    });
    os.pool.push(id);
  });
  optSyncSlotCountToImages(os);
  selected.forEach((item, idx) => {
    const slot = os.slots[startIndex + idx];
    if (slot) slot.name = item.optionName || slot.name || `${startIndex + idx + 1}번`;
  });
  const limited = reusable.length > selected.length ? ` · 30장 제한으로 ${selected.length}/${reusable.length}장만 추가` : '';
  optAppendLogs(os, `기존색상쓰기 완료: ${result.optionName || '이전 생성 결과'}에서 ${selected.length}장 추가${limited}`);
  saveLastWorkNow();
  importedIds.forEach(id => optInferAndStoreImageColorHint(id, os, { silent: true }).catch(() => {}));
  return selected.length;
}

function optDownloadAllOptionResults() {
  const os = state.optionSorter;
  (os.optionResults || []).forEach(result => optDownloadOptionResult(result.id));
}

const OPTION_ARCHIVE_SETTING_ID = 'optionArchiveDirectory';
let optionArchiveDirectoryHandle = null;
let optionArchiveStatusLoadStarted = false;

function optArchiveSupported() {
  return typeof window !== 'undefined' && typeof window.showDirectoryPicker === 'function';
}

function optArchiveDateFolder(value = new Date()) {
  const d = value instanceof Date ? value : new Date(value || Date.now());
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function optArchiveTimeStamp(value = new Date()) {
  const d = value instanceof Date ? value : new Date(value || Date.now());
  const hh = String(d.getHours()).padStart(2, '0');
  const mi = String(d.getMinutes()).padStart(2, '0');
  const ss = String(d.getSeconds()).padStart(2, '0');
  return `${hh}${mi}${ss}`;
}

function optSafeArchiveFileName(value, fallback = 'option') {
  return optSafeFilename(value || fallback).replace(/[.]+$/g, '').slice(0, 90) || fallback;
}

async function optWriteFileToDirectory(dirHandle, fileName, content, type = 'application/octet-stream') {
  const handle = await dirHandle.getFileHandle(optSafeArchiveFileName(fileName, 'file'), { create: true });
  const value = content instanceof Blob ? content : new Blob([content], { type });
  await workspacePersistenceApi().saveArchiveFile(handle, value);
}

async function optGetArchiveDirectoryHandle() {
  if (optionArchiveDirectoryHandle) return optionArchiveDirectoryHandle;
  try {
    const saved = await workspaceGet(WORKSPACE_DB.appSettings, OPTION_ARCHIVE_SETTING_ID);
    if (saved?.handle) {
      optionArchiveDirectoryHandle = saved.handle;
      if (state.optionSorter) {
        state.optionSorter.optionArchiveFolderName = saved.name || optionArchiveDirectoryHandle.name || state.optionSorter.optionArchiveFolderName || '';
      }
      return optionArchiveDirectoryHandle;
    }
  } catch (e) {
    console.warn('Option archive directory load failed:', e);
  }
  return null;
}

async function optEnsureArchivePermission(handle, request = false) {
  if (!handle) return false;
  if (typeof handle.queryPermission !== 'function') return true;
  const opts = { mode: 'readwrite' };
  let permission = await handle.queryPermission(opts);
  if (permission === 'granted') return true;
  if (request && typeof handle.requestPermission === 'function') {
    permission = await handle.requestPermission(opts);
  }
  return permission === 'granted';
}

async function optChooseArchiveFolder() {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  if (!optArchiveSupported()) {
    os.optionArchiveStatus = '이 브라우저는 폴더 직접 저장을 지원하지 않습니다. Chrome/Edge에서 localhost로 열어주세요.';
    optScheduleSave();
    render();
    return;
  }
  try {
    let handle;
    try {
      handle = await window.showDirectoryPicker({
        id: 'kuasangse-option-archive',
        mode: 'readwrite',
        startIn: 'desktop',
      });
    } catch (pickerError) {
      if (pickerError?.name === 'AbortError') throw pickerError;
      handle = await window.showDirectoryPicker({ mode: 'readwrite' });
    }
    const ok = await optEnsureArchivePermission(handle, true);
    if (!ok) throw new Error('폴더 쓰기 권한이 허용되지 않았습니다.');
    optionArchiveDirectoryHandle = handle;
    await workspacePut(WORKSPACE_DB.appSettings, {
      id: OPTION_ARCHIVE_SETTING_ID,
      name: handle.name || '',
      handle,
      savedAt: new Date().toISOString(),
    });
    os.optionArchiveEnabled = true;
    os.optionArchiveFolderName = handle.name || '선택한 폴더';
    os.optionArchiveStatus = `저장 폴더 연결됨: ${os.optionArchiveFolderName}`;
    optAppendLogs(os, `옵션 결과 폴더 저장 연결: ${os.optionArchiveFolderName}`);
    saveLastWorkNow();
    render();
  } catch (e) {
    if (e?.name === 'AbortError') return;
    os.optionArchiveStatus = `저장 폴더 지정 실패: ${e.message || e}`;
    optScheduleSave();
    render();
  }
}

async function optLoadArchiveFolderStatus(options = {}) {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  const handle = await optGetArchiveDirectoryHandle();
  if (handle) {
    os.optionArchiveFolderName = handle.name || os.optionArchiveFolderName || '선택한 폴더';
    const granted = await optEnsureArchivePermission(handle, false);
    if (!os.optionArchiveStatus || options.refresh) {
      os.optionArchiveStatus = granted
        ? `저장 폴더 준비됨: ${os.optionArchiveFolderName}`
        : `저장 폴더 권한 확인 필요: ${os.optionArchiveFolderName}`;
    }
  }
  if (options.render !== false) render();
}

async function optGetArchiveTargetDirectory(result, os = state.optionSorter) {
  const root = await optGetArchiveDirectoryHandle();
  if (!root) throw new Error('저장 폴더가 지정되지 않았습니다.');
  const ok = await optEnsureArchivePermission(root, true);
  if (!ok) throw new Error('저장 폴더 쓰기 권한이 없습니다.');
  const created = new Date(result?.createdAt || Date.now());
  const dateDir = await root.getDirectoryHandle(optArchiveDateFolder(created), { create: true });
  const batchDir = await dateDir.getDirectoryHandle(optSafeArchiveFileName(result?.batchLabel || `batch_${result?.batchNo || 'unknown'}`, 'batch'), { create: true });
  const folderName = `${String(result?.order || 0).padStart(2, '0')}_${optArchiveTimeStamp(created)}_${optSafeArchiveFileName(result?.optionName || result?.id || 'option_sheet', 'option_sheet')}`;
  return batchDir.getDirectoryHandle(folderName, { create: true });
}

function optSourceImagesForResult(result, os = state.optionSorter) {
  const ids = String(result?.sourceId || '').split(',').filter(Boolean);
  return ids.map((id, idx) => {
    const img = (os.images || []).find(item => item.id === id);
    return img ? { img, idx } : null;
  }).filter(Boolean);
}

function optArchiveMetadataForResult(result, os = state.optionSorter, files = {}) {
  const cleanResult = cloneData(result || {}) || {};
  delete cleanResult.image;
  if (Array.isArray(cleanResult.splitImages)) {
    cleanResult.splitImages = cleanResult.splitImages.map(item => {
      const copy = { ...item, hasImage: !!item.image };
      delete copy.image;
      return copy;
    });
  }
  const cleanSources = optSourceImagesForResult(result, os).map(({ img, idx }) => ({
    order: idx + 1,
    id: img.id,
    name: img.name,
    mime: img.mime,
    optionName: result?.optionNames?.[idx] || '',
    file: files.sources?.[idx] || '',
  }));
  return {
    schemaVersion: 1,
    archivedAt: new Date().toISOString(),
    app: 'kuasangse app.html option sorter',
    files,
    result: cleanResult,
    prompt: result?.prompt || '',
    generationDetails: cloneData(result?.generationDetails || null),
    sourceImages: cleanSources,
  };
}

async function optArchiveOptionResult(result, options = {}) {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  if (!result) return false;
  if (!options.force && !os.optionArchiveEnabled) return false;
  const dir = await optGetArchiveTargetDirectory(result, os);
  const files = {};
  if (result.image) {
    const blob = dataUrlToBlob(result.image);
    const ext = imageExtFromMime(blob.type || 'image/png');
    const imageFile = `result.${ext}`;
    await optWriteFileToDirectory(dir, imageFile, blob, blob.type || 'image/png');
    files.resultImage = imageFile;
  }
  if (result.prompt) {
    await optWriteFileToDirectory(dir, 'prompt.txt', result.prompt, 'text/plain;charset=utf-8');
    files.prompt = 'prompt.txt';
  }
  const sources = optSourceImagesForResult(result, os);
  if (sources.length) {
    const sourceDir = await dir.getDirectoryHandle('sources', { create: true });
    files.sources = [];
    for (const { img, idx } of sources) {
      const srcDataUrl = optImageSrc(img);
      if (!srcDataUrl) {
        files.sources[idx] = '';
        continue;
      }
      const blob = dataUrlToBlob(srcDataUrl);
      const ext = imageExtFromMime(blob.type || img.mime || 'image/png');
      const fileName = `${String(idx + 1).padStart(2, '0')}_${optSafeArchiveFileName(result.optionNames?.[idx] || img.name || 'source')}.${ext}`;
      await optWriteFileToDirectory(sourceDir, fileName, blob, blob.type || img.mime || 'image/png');
      files.sources[idx] = `sources/${fileName}`;
    }
  }
  if (Array.isArray(result.splitImages) && result.splitImages.length) {
    const splitDir = await dir.getDirectoryHandle('individuals', { create: true });
    files.individuals = [];
    for (let idx = 0; idx < result.splitImages.length; idx++) {
      const split = result.splitImages[idx];
      if (!split?.image) {
        files.individuals[idx] = '';
        continue;
      }
      const blob = dataUrlToBlob(split.image);
      const ext = imageExtFromMime(blob.type || 'image/png');
      const fileName = `${String(split.order || idx + 1).padStart(2, '0')}_${optSafeArchiveFileName(split.optionName || 'option')}.${ext}`;
      await optWriteFileToDirectory(splitDir, fileName, blob, blob.type || 'image/png');
      files.individuals[idx] = `individuals/${fileName}`;
    }
  }
  const metadata = optArchiveMetadataForResult(result, os, files);
  await optWriteFileToDirectory(dir, 'metadata.json', JSON.stringify(metadata, null, 2), 'application/json;charset=utf-8');
  result.archivedAt = metadata.archivedAt;
  result.archiveFolderName = dir.name || '';
  os.optionArchiveLastSavedAt = metadata.archivedAt;
  os.optionArchiveSavedCount = Number(os.optionArchiveSavedCount || 0) + 1;
  os.optionArchiveStatus = `저장 완료: ${result.optionName || result.id}`;
  return true;
}

async function optArchiveAllOptionResults() {
  const os = state.optionSorter;
  ensureOptionSorterDefaults(os);
  const results = (os.optionResults || []).filter(result => result?.image || result?.prompt);
  if (!results.length) {
    os.optionArchiveStatus = '저장할 옵션 생성 결과가 없습니다.';
    render();
    return;
  }
  try {
    if (!(await optGetArchiveDirectoryHandle())) {
      await optChooseArchiveFolder();
      if (!(await optGetArchiveDirectoryHandle())) return;
    }
    let count = 0;
    for (const result of results) {
      const ok = await optArchiveOptionResult(result, { force: true });
      if (ok) count += 1;
    }
    os.optionArchiveEnabled = true;
    os.optionArchiveStatus = `현재 결과 ${count}장을 폴더에 저장했습니다.`;
    optAppendLogs(os, os.optionArchiveStatus);
    saveLastWorkNow();
    render();
  } catch (e) {
    os.optionArchiveStatus = `폴더 저장 실패: ${e.message || e}`;
    optAppendLogs(os, os.optionArchiveStatus);
    optScheduleSave();
    render();
  }
}

// ════════════════════════════════════════════════════════════════
// OPTION IMAGE SORTER — RENDER
// ════════════════════════════════════════════════════════════════
function renderOptCard(imgId, os) {
  const img = os.images.find(im => im.id === imgId);
  if (!img) return '';
  const imageLabel = escapeHtml(img.name);
  return `<div class="opt-dc" data-img-id="${imgId}" data-opt-quick-assign="${imgId}" title="${imageLabel} · 미배정 사진은 더블클릭으로 다음 빈 슬롯에 배정">
    ${optRenderImageOrPlaceholder(img, `alt="${imageLabel}" loading="lazy" decoding="async" width="104" height="104"`, '이미지 복원 중')}
    <button type="button" class="opt-card-preview" data-opt-preview-img="${imgId}" aria-label="${imageLabel} 사진 크게 보기" title="사진 크게 보기">+</button>
    <div class="opt-dc-tip">${escapeHtml(img.name)}</div>
  </div>`;
}

function renderOptionSorterImagePreviewModal(os) {
  const result = (os.optionResults || []).find(r => r.id === os.previewResultId);
  if (result) {
    const image = factoryOptionSorterResultDisplayImage(result);
    return `<div class="modal-overlay opt-image-preview-overlay" id="optImagePreviewOverlay" data-opt-preview-backdrop>
      <div class="modal opt-image-preview-modal" onclick="event.stopPropagation()">
        <div class="opt-image-preview-head">
          <div style="min-width:0">
            <div class="opt-image-preview-title">${String(result.order).padStart(2, '0')}. ${escapeHtml(result.optionName)}</div>
            <div class="opt-image-preview-sub">${escapeHtml(result.pipelineName || '생성 방식 기록 없음')} · ${escapeHtml(result.modeLabel || '')} · ${escapeHtml(result.modelLabel || '')} · 생성 ${escapeHtml(optFormatDateTime(result.createdAt))}</div>
          </div>
          <button type="button" class="btn-sm" id="closeOptImagePreview" data-opt-preview-close>닫기</button>
        </div>
        ${image ? `<div class="opt-image-preview-stage">
    <img src="${image}" alt="${escapeHtml(result.optionName)} 옵션 선택 이미지 확대" loading="eager" decoding="async">
        </div>` : `<div class="opt-image-preview-stage" style="display:block;color:var(--text);font-size:14px;line-height:1.8">
          <b>옵션 배치안</b>
          <ol style="margin:10px 0 0 20px">
            ${(result.optionNames || []).map(name => `<li>${escapeHtml(name)}</li>`).join('')}
          </ol>
        </div>`}
        <details style="margin-top:10px">
          <summary style="font-size:12px;color:var(--primary-h);cursor:pointer;font-weight:800">생성 프롬프트 보기</summary>
          <pre style="white-space:pre-wrap;word-break:keep-all;overflow-wrap:anywhere;overflow:visible;margin-top:8px;background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:10px;font-size:11px;line-height:1.6;color:var(--text-d)">${escapeHtml(result.prompt || '')}</pre>
        </details>
      </div>
    </div>`;
  }
  const img = os.images.find(im => im.id === os.previewImageId);
  if (!img) return '';
  return `<div class="modal-overlay opt-image-preview-overlay" id="optImagePreviewOverlay" data-opt-preview-backdrop>
    <div class="modal opt-image-preview-modal" onclick="event.stopPropagation()">
      <div class="opt-image-preview-head">
        <div style="min-width:0">
          <div class="opt-image-preview-title">${escapeHtml(img.name)}</div>
          <div class="opt-image-preview-sub">업로드 원본을 확대해서 봅니다. 이미지 영역은 스크롤로 세부를 확인할 수 있습니다.</div>
        </div>
        <button type="button" class="btn-sm" id="closeOptImagePreview" data-opt-preview-close>닫기</button>
      </div>
      <div class="opt-image-preview-stage">
        ${optRenderImageOrPlaceholder(img, `alt="${escapeHtml(img.name)} 원본 확대"`, '이미지 원본 복원 중입니다. 잠시 후 다시 열어주세요.')}
      </div>
    </div>
  </div>`;
}

function optRenderDetailKv(label, value) {
  return `<div class="opt-generation-detail-kv">
    <div class="k">${escapeHtml(label)}</div>
    <div class="v">${escapeHtml(optCompactDetailValue(value))}</div>
  </div>`;
}

function optRenderDetailList(items) {
  const safeItems = (Array.isArray(items) ? items : []).filter(item => item !== null && item !== undefined && item !== '');
  if (!safeItems.length) return '<div>기록 없음</div>';
  return safeItems.map(item => `<div>${escapeHtml(optCompactDetailValue(item))}</div>`).join('');
}

function optFallbackGenerationDetails(result = {}) {
  return {
    schemaVersion: 0,
    createdAt: result.createdAt || '',
    batch: { batchLabel: result.batchLabel || '' },
    model: {
      modelId: result.modelId || '',
      modelLabel: result.modelLabel || '',
      provider: '',
      route: '',
    },
    generationMode: {
      pipelineId: result.pipelineId || '',
      pipelineName: result.pipelineName || '',
      contentMode: result.contentMode || '',
      contentModeLabel: optContentModeLabel(result.contentMode),
      imageModeLabel: result.modeLabel || '',
      usesImageModel: !!result.usesImageModel,
      usesAppText: !!result.usesAppText,
    },
    tone: {
      tonePresetName: result.tonePresetName || '',
      toneText: result.tone || '',
    },
    outputSplit: {
      sheetIndex: result.order || '',
      sheetLabel: result.optionName || '',
      sheetOptionCount: Array.isArray(result.optionNames) ? result.optionNames.length : '',
    },
    mapping: {
      sheetCells: (result.optionNames || []).map((name, idx) => ({ cell: idx + 1, optionName: name })),
      references: [],
      colorConflicts: [],
    },
    styleSample: result.styleSampleName ? { name: result.styleSampleName } : null,
    continuity: {
      enabled: !!result.continuitySampleName,
      sampleName: result.continuitySampleName || '',
    },
    harness: {
      productPreservation: ['기존 결과라 상세 하네스 기록은 축약 표시됩니다.'],
      templateUniformity: [],
    },
    promptTrace: {
      storedPromptChars: String(result.prompt || '').length,
      activeDirectives: [],
      appPostProcess: result.contentMode === 'mixed' ? '앱 텍스트 오버레이' : '',
    },
  };
}

function renderOptionGenerationDetails(result = {}) {
  const details = result.generationDetails || optFallbackGenerationDetails(result);
  const model = details.model || {};
  const mode = details.generationMode || {};
  const tone = details.tone || {};
  const split = details.outputSplit || {};
  const mapping = details.mapping || {};
  const styleSample = details.styleSample || null;
  const continuity = details.continuity || {};
  const harness = details.harness || {};
  const promptTrace = details.promptTrace || {};
  const references = (mapping.references || []).map(ref => {
    const parts = [
      `Ref ${ref.order || '?'}`,
      ref.role || '',
      ref.sourceNo ? `원본 ${ref.sourceNo}번` : '',
      ref.optionName ? `옵션 "${ref.optionName}"` : '',
      ref.imageName ? `이미지 ${ref.imageName}` : '',
      ref.sampleName ? `샘플 ${ref.sampleName}` : '',
      ref.colorHint ? `${ref.colorHintSource || '색상 판정'} ${ref.colorHint}${ref.colorConfidence !== null && ref.colorConfidence !== undefined ? ` ${ref.colorConfidence}%` : ''}` : '',
    ].filter(Boolean);
    return parts.join(' · ');
  });
  const cells = (mapping.sheetCells || []).map(cell => {
    const pos = cell.row && cell.column ? `${cell.row}행 ${cell.column}열` : `Cell ${cell.cell}`;
    return `Cell ${cell.cell}: ${pos} · 원본 ${cell.sourceNo || '?'}번 · ${cell.imageName || '이미지명 없음'} · 라벨 "${cell.optionName || ''}"`;
  });
  const conflicts = (mapping.colorConflicts || []).map(item => {
    const source = item.source ? `${item.source} ` : '';
    const model = item.modelLabel ? ` · ${item.modelLabel}` : '';
    const reason = item.reason ? ` · 근거: ${item.reason}` : '';
    return `Cell ${item.cell}: 라벨 색상어(${(item.labelColors || []).join(', ')})와 ${source}원본색(${item.imageColor || ''}, ${item.confidence || 0}%${model}) 충돌 → 원본색 우선${reason}`;
  });
  return `<details class="opt-generation-details">
    <summary>상세내역 보기</summary>
    <div class="opt-generation-detail-body">
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">생성 방식</div>
        <div class="opt-generation-detail-grid">
          ${optRenderDetailKv('파이프라인', mode.pipelineName)}
          ${optRenderDetailKv('콘텐츠 방식', mode.contentModeLabel || mode.contentMode)}
          ${optRenderDetailKv('사진 모드', mode.imageModeLabel)}
          ${optRenderDetailKv('AI 이미지 모델 사용', mode.usesImageModel)}
          ${optRenderDetailKv('앱 글자 후처리', mode.usesAppText)}
          ${optRenderDetailKv('배치', details.batch?.batchLabel)}
        </div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">모델 / API</div>
        <div class="opt-generation-detail-grid">
          ${optRenderDetailKv('제공자', model.provider || model.providerId)}
          ${optRenderDetailKv('모델명', model.modelLabel)}
          ${optRenderDetailKv('모델 ID', model.modelId)}
          ${optRenderDetailKv('연결 경로', model.route)}
          ${optRenderDetailKv('요청 크기', promptTrace.requestedSize)}
          ${optRenderDetailKv('생성 시각', optFormatDateTime(details.createdAt || result.createdAt))}
        </div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">톤앤매너 / 분할</div>
        <div class="opt-generation-detail-grid">
          ${optRenderDetailKv('톤 프리셋', tone.tonePresetName)}
          ${optRenderDetailKv('시트', `${split.sheetIndex || ''} · ${split.sheetLabel || ''}`)}
          ${optRenderDetailKv('레이아웃', split.sheetLayout)}
          ${optRenderDetailKv('선택 배치', split.selectedLayout)}
          ${optRenderDetailKv('행별 칸수', Array.isArray(split.rowPattern) ? split.rowPattern.join(',') : `${split.optionSheetCols || '?'} x ${split.optionSheetRows || '?'}`)}
          ${optRenderDetailKv('시트당 최대 옵션', split.maxOptionsPerSheet)}
          ${optRenderDetailKv('출력 픽셀', split.width && split.height ? `${split.width}px x ${split.height}px (${split.pixelMode || 'auto'})` : '')}
          ${optRenderDetailKv('이번 시트 옵션 수', split.sheetOptionCount)}
          ${optRenderDetailKv('전체 옵션 수', split.totalOptionCount)}
        </div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">참조 이미지 첨부 순서</div>
        <div class="opt-generation-detail-list">${optRenderDetailList(references)}</div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">셀 매핑</div>
        <div class="opt-generation-detail-list">${optRenderDetailList(cells)}</div>
      </div>
      ${conflicts.length ? `<div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">색상 충돌 잠금</div>
        <div class="opt-generation-detail-list">${optRenderDetailList(conflicts)}</div>
      </div>` : ''}
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">샘플 / 연속성</div>
        <div class="opt-generation-detail-grid">
          ${optRenderDetailKv('샘플명', styleSample?.name || result.styleSampleName)}
          ${optRenderDetailKv('샘플 보관 ID', styleSample?.libraryId)}
          ${optRenderDetailKv('연속성 사용', continuity.enabled)}
          ${optRenderDetailKv('연속성 기준', continuity.sampleName || result.continuitySampleName)}
        </div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">하네스 규칙</div>
        <div class="opt-generation-detail-list">${optRenderDetailList([...(harness.productPreservation || []), ...(harness.templateUniformity || [])])}</div>
      </div>
      <div class="opt-generation-detail-section">
        <div class="opt-generation-detail-title">프롬프트 / 후처리</div>
        <div class="opt-generation-detail-grid">
          ${optRenderDetailKv('저장 프롬프트 글자 수', promptTrace.storedPromptChars)}
          ${optRenderDetailKv('기본 프롬프트 글자 수', promptTrace.basePromptChars)}
          ${optRenderDetailKv('활성 지시문 수', (promptTrace.activeDirectives || []).length)}
          ${optRenderDetailKv('앱 후처리', promptTrace.appPostProcess)}
        </div>
        <textarea class="opt-generation-prompt" readonly>${escapeHtml(result.prompt || '')}</textarea>
      </div>
    </div>
  </details>`;
}

function renderOptionGroupShotPanel(os = state.optionSorter, options = {}) {
  ensureOptionSorterDefaults(os);
  const compact = options.compact === true;
  const context = String(options.context || (compact ? 'factory' : 'optionsorter'));
  const images = Array.isArray(os.images) ? os.images : [];
  const selectedIds = new Set(optGetGroupShotSelectedImages(os).map(image => image.id));
  const selectedCount = selectedIds.size;
  const missingPayloadCount = images.filter(image => !optHasImagePayload(image)).length;
  const latestResult = (os.optionResults || []).find(result => (
    result?.id === os.optionGroupShotLastResultId && result?.resultKind === 'color-group-shot'
  )) || [...(os.optionResults || [])].reverse().find(result => result?.resultKind === 'color-group-shot');
  const latestImage = latestResult ? factoryOptionSorterResultDisplayImage(latestResult) : '';
  const canGenerate = selectedCount > 0 && !missingPayloadCount && !os.optionGroupShotRunning;
  const disabledReason = os.optionGroupShotRunning
    ? '색상 단체컷을 생성 중입니다.'
    : (!images.length
      ? '색상용 이미지를 먼저 넣어주세요.'
      : (missingPayloadCount ? `원본 이미지 ${missingPayloadCount}장을 복원 중입니다.` : '단체컷에 넣을 색상을 한 장 이상 선택해주세요.'));
  const selectionSummary = os.optionGroupShotSelectionMode === 'all'
    ? `전체 ${selectedCount}장 자동 선택`
    : `일부 ${selectedCount}/${images.length}장 선택`;
  return `<section class="opt-group-shot-panel ${compact ? 'compact' : ''}" data-opt-group-shot-panel="${escAttr(context)}">
    <div class="opt-group-shot-head">
      <div>
        <div class="opt-group-shot-title">
          <span class="material-icons-outlined">groups</span>
          색상 단체컷 · 대표이미지 후보
        </div>
        <div class="opt-group-shot-desc">
          기본은 색상용 이미지 전체를 사용해 대표이미지 느낌의 단체컷을 정확히 1장 만듭니다. 색상이 많으면 아래에서 필요한 색만 골라 생성할 수 있습니다.
        </div>
      </div>
      <div class="opt-group-shot-actions">
        <button type="button" class="btn-sm" data-opt-group-shot-select-all ${disabledAttr(!images.length || os.optionGroupShotRunning, !images.length ? '선택할 색상용 이미지가 없습니다.' : '생성 중에는 선택을 바꿀 수 없습니다.')}>전체 선택</button>
        <button type="button" class="btn-sm" data-opt-group-shot-clear ${disabledAttr(!images.length || os.optionGroupShotRunning, !images.length ? '선택할 색상용 이미지가 없습니다.' : '생성 중에는 선택을 바꿀 수 없습니다.')}>선택 해제</button>
        <button type="button" class="btn-primary" id="optGenerateGroupShot" ${disabledAttr(!canGenerate, disabledReason)}>
          <span class="material-icons-outlined">${os.optionGroupShotRunning ? 'hourglass_empty' : 'auto_awesome'}</span>
          ${os.optionGroupShotRunning ? `생성 중 ${Math.round(Number(os.optionGroupShotProgress || 0))}%` : '단체컷 1장 생성'}
        </button>
      </div>
    </div>
    <div class="opt-group-shot-status ${selectedCount ? 'ready' : 'warn'}">
      <b data-opt-group-shot-selected-count>${escapeHtml(selectionSummary)}</b>
      <span>생성 결과는 옵션분류기 결과에 로컬 보관되고 조립공장 대표이미지 후보에도 자동 연결됩니다.</span>
    </div>
    ${images.length ? `<div class="opt-group-shot-grid">
      ${images.map((image, index) => {
        const selected = selectedIds.has(image.id);
        return `<button type="button"
          class="opt-group-shot-source ${selected ? 'selected' : ''}"
          data-opt-group-shot-image="${escAttr(image.id)}"
          data-opt-group-shot-selected="${selected ? 'true' : 'false'}"
          role="checkbox"
          aria-checked="${selected ? 'true' : 'false'}"
          ${disabledAttr(os.optionGroupShotRunning, '생성 중에는 선택을 바꿀 수 없습니다.')}>
          <span class="opt-group-shot-check material-icons-outlined">${selected ? 'check_circle' : 'radio_button_unchecked'}</span>
          ${optRenderImageOrPlaceholder(image, `alt="${escapeHtml(image.name || `${index + 1}번 색상`)}" loading="lazy"`, '원본 복원 중')}
          <span class="opt-group-shot-name">${escapeHtml(image.name || `${index + 1}번 색상`)}</span>
        </button>`;
      }).join('')}
    </div>` : `<div class="opt-group-shot-empty">색상용 이미지를 넣으면 전체가 자동 선택되어 여기에 표시됩니다.</div>`}
    <div class="opt-group-shot-prompt-row">
      <label for="optGroupShotPrompt">단체컷 추가 지시 <span>선택</span></label>
      <textarea id="optGroupShotPrompt" placeholder="예: 앞줄 3개는 세워서, 나머지는 뒤에 부드럽게 펼쳐 배치">${escapeHtml(os.optionGroupShotPrompt || '')}</textarea>
    </div>
    ${latestResult ? `<div class="opt-group-shot-latest">
      ${latestImage ? `<img src="${escAttr(latestImage)}" alt="최근 생성한 색상 단체컷" loading="lazy">` : ''}
      <div>
        <b>최근 단체컷 보존됨</b>
        <span>${escapeHtml(latestResult.optionName || '색상 단체컷')} · ${escapeHtml(optFormatDateTime(latestResult.createdAt))}</span>
        <span>${latestResult.heroAssetId ? '대표이미지 후보로 추가됨 · 사용 선택 대기' : '대표이미지 후보 연결 대기'}</span>
      </div>
    </div>` : ''}
    ${os.optionGroupShotLastError ? `<div class="app-notice danger opt-group-shot-error"><span class="material-icons-outlined">error</span><span>${escapeHtml(os.optionGroupShotLastError)}</span></div>` : ''}
  </section>`;
}

function renderOptionImageGeneratorPanel(os) {
  ensureOptionSorterDefaults(os);
  const pairs = getOptionImagePairs(os);
  optWarmColorHints(os);
  const colorImagesDisabled = optionSorterColorImagesDisabled(os);
  const assignedPairCount = pairs.length;
  const unassignedImageCount = Math.max(0, (os.images || []).length - assignedPairCount);
  const missingPairPayloadCount = pairs.filter(pair => !optHasImagePayload(pair.img)).length;
  const canGenerate = !colorImagesDisabled
    && pairs.length > 0
    && unassignedImageCount === 0
    && missingPairPayloadCount === 0
    && !os.optionGenRunning;
  const generateDisabledReason = os.optionGenRunning
    ? '옵션 이미지를 생성 중입니다.'
    : (colorImagesDisabled
      ? '색상이미지 안씀이 선택되어 옵션표 생성과 섹션 배치를 건너뜁니다.'
      : (unassignedImageCount > 0
        ? `미배정 사진 ${unassignedImageCount}장을 옵션 이름 슬롯에 먼저 배정해주세요.`
        : (missingPairPayloadCount > 0 ? '원본 이미지 복원 중입니다. 잠시 후 다시 시도해주세요.' : '이미지를 먼저 업로드해주세요.')));
  const modelInfo = getCurrentImageRunInfo();
  const sourceLabel = '슬롯 배정 순서 기준';
  const sheets = getOptionOutputSheets(pairs, os);
  const sheetGrid = optGetOptionSheetGrid(os);
  const selectedLayout = optGetSelectedLayoutPattern(os, pairs.length || 1);
  const selectedGrid = { rows: selectedLayout.selectedRows, cols: selectedLayout.selectedCols };
  const sheetSize = optGetOptionSheetSize(os, selectedGrid);
  const pixelRecommendations = optGetOptionSheetPixelRecommendations(os, selectedGrid);
  const pixelWarning = optGetPixelAspectWarning(sheetSize, pixelRecommendations);
  const pixelPreset = sheetSize.mode === 'custom' ? (sheetSize.preset || 'custom') : 'auto';
  const layoutCandidates = optBuildOptionLayoutCandidates(pairs.length);
  const currentPatternKey = optRowPatternKey(selectedLayout.selectedPattern);
  const manualLayout = !!os.optionSheetLayoutUserSet && os.optionSheetLayoutMode !== 'auto';
  const directPatternValue = os.optionSheetLayoutMode === 'rows'
    ? (os.optionSheetRowPattern || selectedLayout.selectedPattern.join(','))
    : `${sheetGrid.rows}*${sheetGrid.cols}`;
  const layoutPlanSummary = optLayoutSummaryFromSheets(sheets);
  const isTwoByTwoPreset = sheetGrid.cols === 2 && sheetGrid.rows === 2;
  const isTwoByOnePreset = sheetGrid.cols === 2 && sheetGrid.rows === 1;
  const outputSummary = `${selectedLayout.selectedLabel} · 최대 ${selectedLayout.capacity}개/장 · ${layoutPlanSummary} · ${sheetSize.width}px x ${sheetSize.height}px`;
  const currentTonePresetId = os.optionTonePresetId || detectOptionTonePresetId(os.optionTone);
  const currentToneName = getOptionToneDisplayName(os);
  const pipeline = getOptionGenerationPipeline(os, modelInfo);
  const engineLabel = pipeline.engineLabel;
  const engineNotice = `${currentToneName} 톤 · ${pipeline.description} ${pipeline.harness}`;
  const activeStyleSample = optGetActiveStyleSample(os);
  const hasLlmForVisionColor = hasLlmConnection();
  const canRunVisionColor = pairs.length > 0 && !os.optionVisionColorBusy && hasLlmForVisionColor;
  const visionColorCount = pairs.filter(pair => optIsUsableColorHint(pair.img?.colorVisionHint)).length;
  const pixelColorCount = pairs.filter(pair => optIsUsableColorHint(pair.img?.colorHint)).length;
  const styleSampleLibrary = optGetStyleSampleLibrary();
  const styleSampleNotice = activeStyleSample
    ? (pipeline.usesImageModel
      ? '다음 나노바나나 생성부터 이 샘플의 각도, 카드, 라벨, 배경, 그림자 양식을 스타일 템플릿으로 같이 보냅니다.'
      : '현재 선택한 웹 내부 캔버스 합성은 앱 좌표로 통일합니다. 샘플은 보관되어 있고, 나노바나나 방식으로 바꾸면 참조됩니다.')
    : '샘플을 정하지 않으면 지금처럼 톤앤매너와 기본 하네스만으로 생성합니다.';
  const archiveSupported = optArchiveSupported();
  const archiveFolderLabel = os.optionArchiveFolderName || '폴더 미지정';
  const archiveStatus = os.optionArchiveStatus || (archiveSupported
    ? 'D드라이브의 원하는 폴더를 직접 선택하면, 생성 이미지와 프롬프트 기록을 파일로 계속 저장합니다.'
    : '현재 브라우저는 폴더 직접 저장을 지원하지 않습니다. Chrome/Edge에서 localhost로 열어주세요.');
  const archiveLastSaved = os.optionArchiveLastSavedAt ? optFormatDateTime(os.optionArchiveLastSavedAt) : '아직 없음';
  const pipelineCards = [
    {
      id: 'local_canvas',
      title: '웹 내부 캔버스 합성',
      tags: ['AI 미사용', '앱 글자', '상품 보존 최우선'],
      desc: '원본 사진을 앱이 같은 카드/라벨 좌표에 배치합니다. 가장 안전하지만 원본 사진의 촌스러움도 일부 남을 수 있습니다.',
      cls: 'recommended',
    },
    {
      id: 'ai_full_image',
      title: '전체 나노바나나 생성',
      tags: ['AI 이미지', 'AI 글자', '예쁨 우선'],
      desc: '상품, 배경, 카드, 옵션명까지 모델이 한 장으로 생성합니다. 하네스를 강하게 걸지만 제품/글자 흔들림 위험이 가장 큽니다.',
      cls: '',
    },
    {
      id: 'ai_image_app_text',
      title: '나노바나나 이미지 + 앱 글자',
      tags: ['AI 이미지', '앱 글자', '추천 AI 방식'],
      desc: 'AI는 배경/조명/카드만 통일하고 옵션명은 앱이 고정 좌표로 얹습니다. 글자 오류를 줄이면서 이미지 정돈을 노리는 방식입니다.',
      cls: 'recommended',
    },
  ];
  const colorConflicts = pairs.map(pair => ({ pair, conflict: optPairColorConflict(pair) })).filter(item => item.conflict);
  const factory = factoryRuntimeReadFactory();
  const currentBatchResultIds = new Set((Array.isArray(os.optionLastGeneratedResultIds) ? os.optionLastGeneratedResultIds : [])
    .map(id => String(id || '').trim())
    .filter(Boolean));
  const currentBatchResults = (os.optionResults || []).filter(result => currentBatchResultIds.has(String(result?.id || '').trim()));
  const currentFactoryOptionResultIds = new Set((typeof factoryUsableAssetsForStage === 'function'
    ? factoryUsableAssetsForStage('options', factory)
    : []
  ).map(asset => String(asset?.sourceMap?.optionResultId || '').trim()).filter(Boolean));
  const currentBatchCanSend = currentBatchResults.length > 0 && currentBatchResults.every(result => {
    const scope = factoryOptionSorterResultMatchesCurrentJob(result, factory);
    return scope.ok;
  });
  const colorSafetyNote = colorConflicts.length
    ? `색상명과 원본 이미지 색상이 다른 항목 ${colorConflicts.length}개가 보입니다. AI 비전 판정값을 우선 적용하고, 없을 때만 픽셀 추정값으로 판단합니다. 생성 방식은 자동 전환하지 않고 현재 선택한 ${pipeline.name} 방식으로 진행합니다.`
    : `옵션명은 라벨 텍스트로만 쓰고, 실제 상품 색상은 업로드 원본 이미지를 기준으로 고정합니다. 색상 판정은 AI 비전 ${visionColorCount}장 / 픽셀 추정 ${pixelColorCount}장 상태입니다.`;
  return `${renderOptionGroupShotPanel(os, { context: 'optionsorter' })}
  <div class="opt-option-gen-panel">
    <div class="opt-option-gen-head">
      <div>
        <div class="opt-option-gen-title" data-opt-workflow-step="3">
          <span class="material-icons-outlined" style="font-size:18px;color:var(--primary-h)">auto_fix_high</span>
          3. 배치 확인 및 옵션표 생성
        </div>
        <div class="opt-option-gen-desc">
          사진 순서와 옵션 이름 순서를 먼저 잠그고, 여러 옵션을 한 장의 같은 양식으로 묶어 생성합니다. 1번 사진은 1번 옵션명, 2번 사진은 2번 옵션명처럼 짝을 절대 바꾸지 않습니다.
        </div>
      </div>
      <button class="btn-primary" id="optGenerateOptions" style="padding:9px 16px" ${disabledAttr(!canGenerate, generateDisabledReason)}>
        <span class="material-icons-outlined" style="font-size:17px">${os.optionGenRunning ? 'hourglass_empty' : 'auto_awesome'}</span>
        ${os.optionGenRunning ? `생성 중 ${os.optionGenProgress || 0}%` : `옵션표 생성 · ${sheets.length}장`}
      </button>
    </div>

    <div class="app-notice ${unassignedImageCount > 0 ? 'warn' : 'ok'}" style="margin:0 0 12px;padding:10px 12px">
      <span class="material-icons-outlined">${unassignedImageCount > 0 ? 'link_off' : 'check_circle'}</span>
      <span>${unassignedImageCount > 0
        ? `이름 매칭이 끝나지 않았습니다. 위 작업대에서 미배정 사진 ${unassignedImageCount}장을 슬롯으로 드래그해주세요.`
        : `사진 ${assignedPairCount}장과 옵션 이름 ${assignedPairCount}개가 매칭됐습니다. 이 매칭 수로 행열과 출력 장수를 계산합니다.`}</span>
    </div>

    <label class="label">옵션표 칸 배치</label>
    <div class="opt-layout-mode-bar">
      <button type="button" class="btn-sm ${manualLayout ? '' : 'active'}" data-opt-layout-auto ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 배치를 바꿀 수 없습니다.')}>
        <span class="material-icons-outlined">auto_awesome</span> 사진 수로 자동 배치
      </button>
      <button type="button" class="btn-sm ${manualLayout ? 'active' : ''}" data-opt-layout-manual ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 배치를 바꿀 수 없습니다.')}>
        <span class="material-icons-outlined">grid_view</span> 직접 조정
      </button>
      <span>${manualLayout ? '직접 정한 행열을 유지합니다.' : `매칭 ${pairs.length}장을 장당 최대 12칸으로 자동 분할합니다.`}</span>
    </div>

    ${manualLayout ? `
      ${pairs.length > 0 && pairs.length <= 10 ? `<div class="opt-layout-candidate-grid">
        ${layoutCandidates.map(candidate => `<button type="button" class="opt-layout-candidate ${candidate.key === currentPatternKey ? 'active' : ''}" data-opt-layout-pattern="${escapeHtml(candidate.pattern.join(','))}">
          ${optRenderPatternPreview(candidate.pattern)}
          <b>${escapeHtml(candidate.title)}</b>
          <span>${escapeHtml(candidate.desc)} · ${candidate.pattern.join('/')}칸</span>
        </button>`).join('')}
      </div>` : ''}
      <div class="input-group" style="margin:8px 0 10px">
        <label class="label" for="optSheetPatternInput">직접 배치 입력</label>
        <input type="text" class="input" id="optSheetPatternInput" value="${escapeHtml(directPatternValue)}" placeholder="예: 5*6, 3*3+1, 4,4,4,2" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 배치를 바꿀 수 없습니다.')}>
        <div style="font-size:11px;color:var(--text-m);line-height:1.55;margin-top:5px">5*6은 5행 6열, 3*3+1은 3행 3칸 뒤 1칸 추가, 쉼표 입력은 행별 칸수입니다.</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin:8px 0 10px">
        <div class="input-group" style="margin-bottom:0">
          <label class="label" for="optSheetColsInput">최대 열</label>
          <input type="number" class="input" id="optSheetColsInput" min="1" max="30" step="1" value="${sheetGrid.cols}" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 칸수를 바꿀 수 없습니다.')}>
        </div>
        <div class="input-group" style="margin-bottom:0">
          <label class="label" for="optSheetRowsInput">행 수</label>
          <input type="number" class="input" id="optSheetRowsInput" min="1" max="30" step="1" value="${sheetGrid.rows}" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 칸수를 바꿀 수 없습니다.')}>
        </div>
      </div>` : ''}

    <div class="opt-layout-direct-preview">
      <div class="opt-layout-direct-head">
        <b>${manualLayout ? '직접 배치 결과' : '자동 배치 결과'}</b>
        <span>${escapeHtml(selectedLayout.selectedPattern.join('/'))}칸 · 최대 ${selectedLayout.capacity}개/장 · 총 ${sheets.length}장</span>
      </div>
      <div id="optLayoutDirectPreview">${optRenderPatternPreview(selectedLayout.selectedPattern || [1])}</div>
    </div>
    <input type="hidden" id="optSheetCapacityInput" value="${selectedLayout.capacity}개 / 총 ${sheets.length}장">

    <label class="label">옵션표 픽셀</label>
    <div class="opt-option-mode-grid">
      <button type="button" class="opt-option-mode-card ${pixelPreset === 'auto' ? 'active' : ''}" data-opt-sheet-pixel-mode="auto">
        <b>자동 크기</b>
        <span>칸수에 맞춰 앱이 ${sheetSize.autoWidth}px x ${sheetSize.autoHeight}px로 계산합니다.</span>
      </button>
      <button type="button" class="opt-option-mode-card ${pixelPreset === 'custom' ? 'active' : ''}" data-opt-sheet-pixel-mode="custom">
        <b>직접 지정</b>
        <span>아래 가로/세로 px 값으로 최종 옵션표 이미지를 강제합니다.</span>
      </button>
    </div>
    <div class="opt-option-mode-grid" style="margin-top:8px">
      <button type="button" class="opt-option-mode-card ${pixelPreset === '2k' ? 'active recommended' : ''}" data-opt-pixel-preset="2k" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 픽셀 프리셋을 바꿀 수 없습니다.')}>
        <b>2K 가성비 적용</b>
        <span id="optPixel2kValue">${pixelRecommendations.twoK.width}px x ${pixelRecommendations.twoK.height}px</span>
      </button>
      <button type="button" class="opt-option-mode-card ${pixelPreset === '4k' ? 'active recommended' : ''}" data-opt-pixel-preset="4k" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 픽셀 프리셋을 바꿀 수 없습니다.')}>
        <b>4K 최고화질 적용</b>
        <span id="optPixel4kValue">${pixelRecommendations.fourK.width}px x ${pixelRecommendations.fourK.height}px</span>
      </button>
    </div>
    <div id="optPixelRecommendationSummary" style="font-size:11px;color:var(--text-m);line-height:1.55;margin:6px 0 8px">
      권장 최대: 4K ${pixelRecommendations.fourK.width}px x ${pixelRecommendations.fourK.height}px · 2K ${pixelRecommendations.twoK.width}px x ${pixelRecommendations.twoK.height}px
    </div>
    <div id="optPixelAspectWarning" style="font-size:11px;color:${pixelWarning ? 'var(--danger)' : 'var(--text-m)'};line-height:1.55;margin:-2px 0 8px">
      ${escapeHtml(pixelWarning)}
    </div>
    <div ${sheetSize.mode !== 'custom' ? 'title="직접 지정을 선택하면 픽셀값을 입력할 수 있습니다."' : ''} style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:8px 0 10px;${sheetSize.mode !== 'custom' ? 'opacity:.55' : ''}">
      <div class="input-group" style="margin-bottom:0">
        <label class="label" for="optSheetWidthInput">가로 px</label>
        <input type="number" class="input" id="optSheetWidthInput" min="320" max="4096" step="1" value="${sheetSize.width}" ${disabledAttr(os.optionGenRunning || sheetSize.mode !== 'custom', os.optionGenRunning ? '옵션표 생성 중에는 픽셀값을 바꿀 수 없습니다.' : '직접 지정을 선택하면 가로 픽셀을 입력할 수 있습니다.')}>
      </div>
      <div class="input-group" style="margin-bottom:0">
        <label class="label" for="optSheetHeightInput">세로 px</label>
        <input type="number" class="input" id="optSheetHeightInput" min="320" max="4096" step="1" value="${sheetSize.height}" ${disabledAttr(os.optionGenRunning || sheetSize.mode !== 'custom', os.optionGenRunning ? '옵션표 생성 중에는 픽셀값을 바꿀 수 없습니다.' : '직접 지정을 선택하면 세로 픽셀을 입력할 수 있습니다.')}>
      </div>
    </div>
    <div id="optSheetOutputSummary" style="font-size:11px;color:var(--text-m);line-height:1.55;margin:-2px 0 9px">
      현재 출력: ${escapeHtml(outputSummary)}. ${manualLayout ? '직접 정한 행열' : '매칭된 사진 수 기반 자동 배치'}로 시트가 생성됩니다.
    </div>

    <label class="label">생성 후 상세페이지 반영</label>
    <div class="opt-option-mode-grid">
      <button type="button" class="opt-option-mode-card ${!colorImagesDisabled ? 'active recommended' : ''}" data-opt-color-image-usage="use">
        <b>색상옵션 섹션에 사용</b>
        <span>완성한 옵션표를 상세페이지의 색상옵션 섹션에 배치합니다.</span>
      </button>
      <button type="button" class="opt-option-mode-card ${colorImagesDisabled ? 'active recommended' : ''}" data-opt-color-image-usage="none">
        <b>상세페이지에 사용 안 함</b>
        <span>옵션표 생성과 색상옵션 섹션 배치를 건너뛰고, 섹션설정에서도 색상옵션 카드를 제외합니다.</span>
      </button>
    </div>
    ${colorImagesDisabled ? `<div class="app-notice warn" style="margin:0 0 12px;padding:9px 11px">
      <span class="material-icons-outlined">visibility_off</span>
      <span>상세페이지에 사용 안 함 상태입니다. 섹션설정과 기존 상세페이지 구성에서 색상옵션 섹션이 빠집니다.</span>
    </div>` : ''}

    <label class="label">원본/상세정보 폴더 저장</label>
    <div style="border:1px solid rgba(99,102,241,.22);background:rgba(99,102,241,.07);border-radius:10px;padding:10px;margin:0 0 12px">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap">
        <div style="min-width:0;flex:1">
          <div style="font-size:12px;font-weight:900;color:var(--text);line-height:1.45">
            ${os.optionArchiveEnabled ? '자동 저장 켜짐' : '자동 저장 꺼짐'} · ${escapeHtml(archiveFolderLabel)}
          </div>
          <div style="font-size:11px;color:var(--text-m);line-height:1.55;margin-top:4px">
            생성 이미지 원본 파일, metadata.json, prompt.txt, 사용 원본 사진을 선택 폴더 아래 날짜/배치별 하위 폴더에 저장합니다. 최근 저장: ${escapeHtml(archiveLastSaved)} · 누적 ${Number(os.optionArchiveSavedCount || 0)}장
          </div>
          <div id="optArchiveStatus" style="font-size:11px;color:${archiveSupported ? 'var(--text-d)' : 'var(--warn)'};line-height:1.55;margin-top:5px">${escapeHtml(archiveStatus)}</div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          <button type="button" class="btn-sm" id="optChooseArchiveFolder" ${disabledAttr(!archiveSupported || os.optionGenRunning, !archiveSupported ? '이 브라우저는 폴더 직접 저장을 지원하지 않습니다.' : '생성 중에는 폴더를 바꿀 수 없습니다.')}>폴더 지정</button>
          <button type="button" class="btn-sm" id="optToggleArchiveAuto" ${disabledAttr(os.optionGenRunning, '생성 중에는 자동 저장 상태를 바꿀 수 없습니다.')}>${os.optionArchiveEnabled ? '자동 저장 끄기' : '자동 저장 켜기'}</button>
          <button type="button" class="btn-sm" id="optArchiveAllResults" ${disabledAttr(!(os.optionResults || []).length || os.optionGenRunning, !(os.optionResults || []).length ? '저장할 생성 결과가 없습니다.' : '생성 중에는 전체 저장을 실행할 수 없습니다.')}>현재 결과 전체 저장</button>
        </div>
      </div>
    </div>

    <label class="label">실제 생성 방식</label>
    <div class="opt-option-mode-grid">
      ${pipelineCards.map(card => `<button type="button" class="opt-option-mode-card ${card.cls || ''} ${pipeline.id === card.id ? 'active' : ''}" data-opt-pipeline="${card.id}">
        <b>${escapeHtml(card.title)}</b>
        <div>${card.tags.map((tag, idx) => `<span class="tag ${idx === 0 && tag.includes('AI 미사용') ? 'warn' : idx === 2 ? 'ok' : ''}">${escapeHtml(tag)}</span>`).join('')}</div>
        <span>${escapeHtml(card.desc)}</span>
      </button>`).join('')}
    </div>
    <div style="font-size:11px;color:var(--text-m);line-height:1.55;margin:-2px 0 9px">
      톤앤매너는 아래 하네스 뒤에 붙는 보조 지시입니다. 어떤 방식을 골라도 사진-옵션명 순서, 원본색, 제품 형태 보존이 최우선입니다.
    </div>

    <div class="opt-option-mode-grid">
      <button type="button" class="opt-option-mode-card ${os.optionImageMode === 'ready' ? 'active' : ''}" data-opt-option-mode="ready">
        <b>정리된 옵션 사진 기준</b>
        <span>이미 옵션용으로 어느 정도 가다듬은 사진입니다. 형태를 거의 그대로 두고 여백, 밝기, 라벨 스타일만 통일합니다.</span>
      </button>
      <button type="button" class="opt-option-mode-card ${os.optionImageMode === 'raw' ? 'active' : ''}" data-opt-option-mode="raw">
        <b>RAW 사진 보정 기준</b>
        <span>원본/거친 사진입니다. 배경, 조명, 구도를 정리하지만 상품 형태와 장식은 바꾸지 않도록 강하게 잠급니다.</span>
      </button>
    </div>

    <label class="label">톤앤매너 프리셋</label>
    <div class="opt-tone-preset-grid">
      ${OPTION_TONE_PRESETS.map(preset => `<button type="button" class="opt-tone-preset ${currentTonePresetId === preset.id ? 'active' : ''}" data-opt-tone-preset="${preset.id}" title="${escapeHtml(preset.tone)}">
        <b>${escapeHtml(preset.name)}</b>
        <span>${escapeHtml(preset.desc)}</span>
      </button>`).join('')}
    </div>
    <div style="font-size:11px;color:var(--text-m);line-height:1.55;margin:-2px 0 9px">
      프리셋은 배경, 조명, 라벨 분위기만 바꿉니다. 사진-옵션명 매핑, 원본 색상, 원본 형태 보존 원칙은 모든 프리셋에 공통으로 강제됩니다.
    </div>

    <label class="label" for="optOptionTone">공통 톤앤매너</label>
    <textarea class="opt-option-tone" id="optOptionTone" placeholder="예: 흰 배경, 동일한 여백, 부드러운 그림자, 하단 옵션명 라벨">${escapeHtml(os.optionTone || '')}</textarea>

    <label class="label" for="optOptionExtraPrompt">AI 생성 추가 프롬프트 (선택)</label>
    <textarea class="opt-option-tone" id="optOptionExtraPrompt" placeholder="예: 라벨은 더 얇게, 카드 간격 넓게, 배경은 순백에 가깝게, 제품 그림자는 아주 약하게">${escapeHtml(os.optionExtraPrompt || '')}</textarea>
    <div style="font-size:11px;color:var(--text-m);line-height:1.55;margin:-2px 0 10px">
      옵션표 생성 버튼 직전에 붙는 자유 지시문입니다. 제품 색/형태/옵션명 순서는 건드리지 않고, 레이아웃·분위기·라벨 스타일만 보정합니다.
    </div>

    <div class="opt-option-map">
      <div class="opt-option-map-title" style="justify-content:space-between;gap:8px;flex-wrap:wrap">
        <span style="display:inline-flex;align-items:center;gap:6px;min-width:0">
          <span class="material-icons-outlined" style="font-size:15px;color:var(--ok)">lock</span>
          생성 전 매핑 확인 · ${escapeHtml(sourceLabel)}
        </span>
        <button type="button" class="btn-sm" id="optVisionColorCheck" ${disabledAttr(!canRunVisionColor, os.optionVisionColorBusy ? 'AI 비전 색상 판정 중입니다.' : (!pairs.length ? '이미지를 먼저 업로드해주세요.' : 'LLM 연결이 있어야 AI 비전 색상 판정을 실행할 수 있습니다.'))}>
          ${os.optionVisionColorBusy ? '<span class="spinner" style="width:12px;height:12px;border-width:2px"></span>' : '<span class="material-icons-outlined" style="font-size:14px">visibility</span>'}
          ${os.optionVisionColorBusy ? '비전 판정 중' : 'AI 비전 색상 판정'}
        </button>
      </div>
      ${pairs.length ? optRenderOptionMapLayout(sheets) : `<div style="font-size:12px;color:var(--text-m)">이미지를 올리면 여기에 사진 순서와 옵션 이름 매핑이 표시됩니다.</div>`}
      <div id="optOutputPlanSummary" style="font-size:11px;color:var(--text-m);margin-top:8px">출력 예정: ${sheets.length || 0}장 · ${escapeHtml(outputSummary)}</div>
    </div>

    <div style="margin-top:10px;border:1px solid ${colorConflicts.length ? 'rgba(245,158,11,.35)' : 'rgba(34,197,94,.25)'};background:${colorConflicts.length ? 'rgba(245,158,11,.08)' : 'rgba(34,197,94,.07)'};border-radius:10px;padding:9px;font-size:12px;line-height:1.55;color:${colorConflicts.length ? 'var(--warn)' : 'var(--ok)'}">
      ${escapeHtml(colorSafetyNote)}
    </div>

    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:10px;font-size:11px;color:var(--text-m)">
      <span class="status-chip">생성 엔진: <strong>${escapeHtml(engineLabel)}</strong></span>
      <span class="status-chip">선택 톤: <strong>${escapeHtml(currentToneName)}</strong></span>
      <span>실제 방식: <strong>${escapeHtml(pipeline.name)}</strong> · 생성 프롬프트에는 위 매핑표와 제품 보존 하네스가 먼저 들어갑니다.</span>
    </div>
    <div style="margin-top:8px;border:1px solid rgba(99,102,241,.25);background:rgba(99,102,241,.08);border-radius:10px;padding:9px;font-size:12px;line-height:1.55;color:var(--text-d)">
      ${escapeHtml(engineNotice)}
    </div>

    <div class="opt-style-sample-box">
      <div class="opt-style-sample-head">
        <div class="opt-style-sample-title">
          <span class="material-icons-outlined" style="font-size:16px;color:var(--ok)">center_focus_strong</span>
          샘플 이미지 하네스 · 참고 옵션 디자인
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          <button class="btn-sm" id="optUploadStyleSample" ${disabledAttr(os.optionGenRunning, '옵션표 생성 중에는 샘플을 바꿀 수 없습니다.')}>
            <span class="material-icons-outlined" style="font-size:14px">upload</span> 참고 샘플 업로드
          </button>
          <button class="btn-sm" id="optClearStyleSample" ${disabledAttr(!activeStyleSample, '현재 적용된 샘플이 없습니다.')}>샘플 해제</button>
          <input type="file" id="optStyleSampleFileInput" accept="image/*" style="display:none">
        </div>
      </div>
      ${activeStyleSample ? `<div class="opt-style-sample-active">
          <img src="${activeStyleSample.image}" alt="${escapeHtml(activeStyleSample.name)} 샘플" loading="lazy" decoding="async">
        <div class="opt-style-sample-copy">
          <div style="font-weight:900;color:var(--text);margin-bottom:3px">${escapeHtml(activeStyleSample.name)}</div>
          <div>${escapeHtml(styleSampleNotice)}</div>
          <div style="margin-top:5px;color:var(--text-m)">복제 기준: 제품 각도/구도, 카드 간격, 배경, 라벨 양식, 그림자. 복제 금지: 상품색, 옵션명, 장식, 형태. 상품 자체는 절대 따라 그리지 않습니다.</div>
        </div>
      </div>` : `<div class="opt-style-sample-copy">외부 옵션표 디자인 샘플을 업로드하거나, 마음에 드는 결과 카드에서 <b>샘플로 지정</b>을 누르면 보관함에도 저장됩니다. 샘플은 <b>옵션 디자인 양식만</b> 참고하고 상품 자체는 절대 복사하지 않습니다.</div>`}
      ${styleSampleLibrary.length ? `<div class="opt-style-sample-library">
        ${styleSampleLibrary.slice(0, 8).map(sample => `<div class="opt-style-sample-card">
              <img src="${sample.image}" alt="${escapeHtml(sample.name)}" loading="lazy" decoding="async">
          <div style="min-width:0">
            <div class="name">${escapeHtml(sample.name)}</div>
            <div class="meta">${escapeHtml(sample.tonePresetName || '톤 기록 없음')} · ${escapeHtml(sample.pipelineName || '방식 기록 없음')}</div>
            <div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:5px">
              <button class="btn-sm" data-opt-load-style-sample="${sample.libraryId}">불러오기</button>
              <button class="btn-sm" data-opt-delete-style-sample="${sample.libraryId}" style="color:var(--err)">삭제</button>
            </div>
          </div>
        </div>`).join('')}
      </div>` : ''}
    </div>

    ${os.optionGenLogs?.length ? `<div class="opt-option-log">
      ${os.optionGenLogs.slice(-12).map(line => `<div class="opt-option-log-line">${escapeHtml(line)}</div>`).join('')}
    </div>` : ''}

    ${os.optionResults?.length ? `<div id="optStoredOptionResults" style="margin-top:14px">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px">
        <div style="font-size:13px;font-weight:900;color:var(--text)">생성된 옵션 선택 이미지 ${os.optionResults.length}장 · 이전 생성안 보존</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${currentBatchResults.length ? `<button class="btn-sm opt-option-result-send-factory" id="optSendCurrentOptionResultsToFactory" data-opt-send-current-results="${escapeHtml(currentBatchResults.map(result => result.id).join(','))}" title="현재 생성안 전체를 현재 작업의 색상옵션 후보로 보냅니다." ${disabledAttr(!currentBatchCanSend, '현재 생성안에 이전 작업 범위 결과가 섞여 있어 전체 전송할 수 없습니다. 각 카드에서 확인해주세요.')}><span class="material-icons-outlined" style="font-size:15px">precision_manufacturing</span>조립공장으로 ${currentBatchResults.length}장 보내기</button>` : ''}
          <span class="status-chip">조립공장 현재 후보 ${currentFactoryOptionResultIds.size}장</span>
          <button class="btn-sm" id="optDownloadAllOptionResults">전체 다운로드</button>
          <button class="btn-sm" id="optClearOptionResults" style="color:var(--err)">비교 결과 전체 비우기</button>
        </div>
      </div>
      <div class="opt-option-results">
        ${os.optionResults.map((result, resultIndex) => {
          const isSample = !!activeStyleSample && activeStyleSample.sourceResultId === result.id;
          const resultOrder = Math.max(1, Number.isFinite(Number(result?.order)) ? Number(result.order) : resultIndex + 1);
          const resultImage = factoryOptionSorterResultDisplayImage(result, factory);
          const splitCount = Array.isArray(result.splitImages) ? result.splitImages.filter(item => item?.image).length : 0;
          const reusableColorCount = optGetReusableColorImagesFromResult(result).length;
          const resultScope = factoryOptionSorterResultMatchesCurrentJob(result, factory);
          const hasFactoryCandidate = currentFactoryOptionResultIds.has(String(result?.id || '').trim());
          const canSendToFactory = !!factoryOptionSorterResultImage(result, factory) && resultScope.ok;
          const factoryActionLabel = hasFactoryCandidate
            ? '조립공장 후보 보기'
            : (resultScope.ok
              ? '조립공장 후보로 보내기'
              : ((resultScope.reason === 'result-scope-missing' || resultScope.reason === 'result-scope-incomplete')
                ? '이전 작업 결과'
                : '현재 작업 후보로 보낼 수 없음'));
          const factoryActionReason = resultScope.reason === 'scope-mismatch'
            ? '이전 작업 결과는 현재 후보에 넣을 수 없습니다.'
            : ((resultScope.reason === 'result-scope-missing' || resultScope.reason === 'result-scope-incomplete')
              ? '작업 범위가 없는 이전 생성 결과입니다. 현재 후보에 넣지 않습니다. 현재 작업에서 다시 생성해주세요.'
            : (resultScope.reason === 'current-scope-incomplete'
              ? '현재 작업의 제품명, 기본이미지, 실행 범위를 먼저 확인해주세요.'
              : (factoryOptionSorterResultImage(result, factory) ? '' : '이미지 원본을 복원한 뒤 보낼 수 있습니다.')));
          const existingColorDisabledReason = reusableColorCount
            ? '옵션 이미지는 최대 30장까지 사용할 수 있습니다.'
            : '개별 옵션 이미지가 있는 생성 결과만 기존색상으로 다시 사용할 수 있습니다.';
          return `<div class="opt-option-result ${isSample ? 'sample' : ''}">
          ${resultImage
              ? `<img src="${resultImage}" alt="${escapeHtml(result.optionName)}" data-opt-preview-result="${result.id}" title="클릭해서 크게 보기" loading="lazy" decoding="async">`
            : `<div data-opt-preview-result="${result.id}" title="클릭해서 배치안 보기" style="aspect-ratio:1/1;border:1px dashed var(--border);border-radius:10px;background:rgba(255,255,255,.03);display:flex;align-items:center;justify-content:center;text-align:center;padding:12px;color:var(--text-d);font-size:12px;line-height:1.6;cursor:pointer">글자/레이아웃만<br>${(result.optionNames || []).map(n => escapeHtml(n)).join('<br>')}</div>`}
          <div class="name">${String(resultOrder).padStart(2, '0')}. ${escapeHtml(result.optionName)}</div>
          <div class="opt-option-result-badges">
            <span>${escapeHtml(result.tonePresetName || '톤 기록 없음')}</span>
            <span>${escapeHtml(result.pipelineName || '방식 기록 없음')}</span>
            <span>${escapeHtml(result.batchLabel || '이전 생성안')}</span>
            ${splitCount ? `<span>개별 ${splitCount}장</span>` : ''}
            ${reusableColorCount ? `<span>기존색상 ${reusableColorCount}장</span>` : ''}
            ${result.styleSampleName ? `<span>샘플:${escapeHtml(result.styleSampleName).slice(0, 18)}</span>` : ''}
            ${hasFactoryCandidate ? '<span>조립공장 후보</span>' : (!resultScope.ok ? '<span>이전 작업 결과</span>' : '')}
          </div>
          <div class="meta">${escapeHtml(result.sourceName || '')}<br>${escapeHtml(result.modeLabel || '')}<br>${escapeHtml(result.modelLabel || '')}<br>생성 ${escapeHtml(optFormatDateTime(result.createdAt))}${result.continuitySampleName ? `<br>연속성 기준: ${escapeHtml(result.continuitySampleName)}` : ''}</div>
          ${renderOptionGenerationDetails(result)}
          <div class="opt-option-result-actions">
            <button class="btn-sm" data-opt-preview-result="${result.id}">크게 보기</button>
            <button class="btn-sm opt-option-result-send-factory" data-opt-send-factory-result="${result.id}" title="이 옵션표만 현재 작업의 색상옵션 후보로 보냅니다." ${disabledAttr(!canSendToFactory, factoryActionReason)}><span class="material-icons-outlined" style="font-size:14px">precision_manufacturing</span>${factoryActionLabel}</button>
            <button class="btn-sm" data-opt-use-existing-colors="${result.id}" ${disabledAttr(!reusableColorCount || os.images.length >= 30, existingColorDisabledReason)}>기존색상쓰기${reusableColorCount ? ` ${reusableColorCount}장` : ''}</button>
            <button class="btn-sm" data-opt-set-style-sample="${result.id}" ${disabledAttr(!resultImage || isSample, isSample ? '이미 현재 샘플입니다.' : '이미지가 있어야 샘플로 지정할 수 있습니다.')}>${isSample ? '현재 샘플' : '샘플로 지정'}</button>
            <button class="btn-sm" data-opt-download-result="${result.id}" ${disabledAttr(!resultImage, '이미지가 없는 글자/레이아웃만 결과입니다.')}>다운로드</button>
            <button class="btn-sm" data-opt-download-splits="${result.id}" ${disabledAttr(!splitCount, '개별 옵션 이미지가 아직 없습니다.')}>개별 ${splitCount || ''}장</button>
            <button class="btn-sm" data-opt-archive-result="${result.id}">폴더 저장</button>
          </div>
        </div>`;
        }).join('')}
      </div>
    </div>` : ''}
  </div>`;
}

function renderOptionSorterSourceStrip(os) {
  const assignedIds = new Set((os.slots || []).flatMap(slot => slot.imgIds || []));
  return `<section class="opt-workflow-panel" id="optSourceStrip">
    <div class="opt-workflow-head" data-opt-workflow-step="1">
      <div>
        <b>1. 업로드 사진 확인</b>
        <span>업로드 순서를 유지하며, 모든 원본 사진을 이 화면 맨 위에서 바로 확인합니다.</span>
      </div>
      <span class="status-chip" id="optSourceMatchStatus">총 ${os.images.length}장 · 매칭 ${assignedIds.size}장</span>
    </div>
    <div class="opt-source-strip">
      ${os.images.map((img, index) => `<button type="button" class="opt-source-card ${assignedIds.has(img.id) ? 'assigned' : ''}" data-opt-preview-img="${img.id}" data-opt-source-card="${img.id}" aria-label="${escapeHtml(img.name)} 사진 크게 보기" title="${escapeHtml(img.name)} 크게 보기">
        <span class="opt-source-index">${index + 1}</span>
        ${optRenderImageOrPlaceholder(img, `alt="${escapeHtml(img.name)}"`, '이미지 복원 중')}
        <span class="opt-source-plus" aria-hidden="true">+</span>
        <span class="opt-source-name">${escapeHtml(img.name)}</span>
        <span class="opt-source-state">${assignedIds.has(img.id) ? '매칭됨' : '미배정'}</span>
      </button>`).join('')}
    </div>
  </section>`;
}

function renderOptionSorterAssignmentWorkspace(os) {
  const assigned = (os.slots || []).reduce((sum, slot) => sum + (slot.imgIds || []).length, 0);
  return `<section class="opt-workflow-panel" id="optAssignmentWorkspace">
    <div class="opt-workflow-head" data-opt-workflow-step="2">
      <div>
        <b>2. 사진과 옵션 이름 매칭</b>
        <span>미배정 사진을 원하는 이름 슬롯으로 드래그합니다. 이 순서와 이름이 생성 결과에 그대로 사용됩니다.</span>
      </div>
      <span class="status-chip ${os.pool.length ? 'warn' : 'ok'}" id="optAssignmentMatchStatus">${assigned}/${os.images.length}장 매칭</span>
    </div>

    <div class="opt-pool-wrap" id="optPoolWrap" style="opacity:${os.pool.length === 0 ? '.55' : '1'}">
      <div class="opt-assignment-heading">
        <span>미배정 <strong id="optPoolStatus" style="color:${os.pool.length > 0 ? 'var(--warn)' : 'var(--ok)'}">${os.pool.length > 0 ? os.pool.length + '장' : '없음'}</strong></span>
        <span>더블클릭하면 다음 빈 슬롯 · 드래그하면 원하는 슬롯</span>
      </div>
      <div id="optPoolList" class="opt-pool-list">
        ${os.pool.map(id => renderOptCard(id, os)).join('')}
      </div>
    </div>

    <div class="opt-assignment-heading">
      <span>옵션 이름 슬롯 (${os.slots.length}개)</span>
      <span>슬롯은 ⠿로 순서 변경 · 이름은 클릭하여 수정</span>
    </div>
    <div id="optSlotGrid" class="opt-slot-grid">
      ${os.slots.map((slot, idx) => `
        <div class="opt-slot-card" data-slot-id="${slot.id}">
          <div class="opt-slot-head">
            <span class="opt-slot-handle" title="드래그하여 슬롯 순서 변경">⠿</span>
            <span class="opt-slot-num">${idx + 1}</span>
            <input class="opt-slot-name-inp" data-slot-name="${slot.id}" value="${escapeHtml(slot.name)}" placeholder="이름" title="클릭하여 이름 수정">
            <span class="opt-slot-cnt" data-opt-slot-count="${slot.id}">${slot.imgIds.length}장</span>
            <button class="opt-slot-del" data-slot-del="${slot.id}" title="슬롯 삭제">✕</button>
          </div>
          <div id="optSlotList_${slot.id}" class="opt-slot-list${slot.imgIds.length === 0 ? ' is-empty' : ''}" data-slot-id="${slot.id}">
            ${slot.imgIds.map(id => renderOptCard(id, os)).join('')}
          </div>
          <button class="btn-sm" data-opt-dl-slot="${slot.id}" style="font-size:10px;padding:3px 0;width:100%;justify-content:center;gap:3px">
            <span class="material-icons-outlined" style="font-size:12px">download</span>${escapeHtml(slot.name)}
          </button>
        </div>`).join('')}
    </div>
  </section>`;
}

// ════════════════════════════════════════════════════════════════
// AUTOMATION ENGINE
// ════════════════════════════════════════════════════════════════
async function autoProcessOne() {
  if (!driveService) {
    autoLog('err', 'Drive가 연결되지 않음');
    return;
  }
  if (!state.auto.inputFolderId || !state.auto.outputFolderId) {
    autoLog('err', '입력/출력 폴더가 설정되지 않음');
    return;
  }

  let autoLLM;
  try { autoLLM = getLLMClient(); } catch(e) { autoLog('err', e.message); return; }
  const autoImageReady = hasImageConnection();

  // 1. List images in input folder
  autoLog('info', '입력 폴더 스캔 중...');
  state.auto.currentMsg = '폴더 스캔 중...';
  state.auto.currentProgress = 0;
  render();

  let files;
  try {
    files = await driveService.listImages(state.auto.inputFolderId);
  } catch(e) {
    // 인증 만료인 경우 자동 갱신 시도
    if (e.message.includes('invalid authentication') || e.message.includes('401') || e.message.includes('Request had invalid')) {
      autoLog('info', '토큰 만료 감지 — 자동 갱신 시도...');
      try {
        await refreshDriveToken();
        files = await driveService.listImages(state.auto.inputFolderId);
      } catch(e2) {
        autoLog('err', `토큰 갱신 후에도 실패: ${e2.message}`);
        state.auto.currentItem = null;
        render();
        return;
      }
    } else {
      autoLog('err', `폴더 스캔 실패: ${e.message}`);
      state.auto.currentItem = null;
      render();
      return;
    }
  }

  // 2. Filter already processed
  const unprocessed = files.filter(f => !state.auto.processedFileIds.has(f.id));
  autoLog('info', `전체 ${files.length}장, 미처리 ${unprocessed.length}장`);

  if (unprocessed.length === 0) {
    autoLog('info', '처리할 새 이미지가 없습니다. 대기합니다.');
    state.auto.currentItem = null;
    render();
    return;
  }

  // 3. Pick the first unprocessed file
  const file = unprocessed[0];
  state.auto.currentItem = { id: file.id, name: file.name };
  state.auto.currentProgress = 5;
  state.auto.currentMsg = `${file.name} 다운로드 중...`;
  autoLog('info', `처리 시작: ${file.name}`);
  render();

  try {
    // 4. Download the image
    const imgData = await driveService.downloadFile(file.id);
    state.auto.currentProgress = 15;
    state.auto.currentMsg = 'AI 분석 중...';
    render();

    // 5. Analyze with selected LLM
    const analysis = await autoLLM.analyzeImage(imgData.base64, imgData.mime);
    autoLog('ok', `분석 완료: ${analysis.product_name || file.name}`);
    state.auto.currentProgress = 25;
    state.auto.currentMsg = '경쟁 분석 중...';
    render();

    // 6. Competitor search
    let compRef = '';
    try {
      const comp = await autoLLM.searchSimilarProducts(analysis.product_name || analysis.product_name_en, analysis.category);
      compRef = JSON.stringify(comp).substring(0, 1000);
      autoLog('ok', `경쟁 분석 완료: ${comp.similar_products?.length || 0}개`);
    } catch(e) {
      autoLog('err', '경쟁 분석 스킵: ' + e.message);
    }
    state.auto.currentProgress = 30;

    // 7. Generate current detail sections
    const sectionContents = {};
    const sectionImages = {};
    const instructions = state.sectionInstructions; // use saved instructions
    const automationSections = orderedSections();

    for (let i = 0; i < automationSections.length; i++) {
      const s = automationSections[i];
      const pct = Math.round(30 + ((i / Math.max(automationSections.length, 1)) * 60));
      state.auto.currentProgress = pct;
      state.auto.currentMsg = `[${i+1}/${automationSections.length}] ${s.name} 생성 중...`;
      render();

      try {
        const mode = getSectionGenerationMode(s.id);
        const basis = getSectionBasisModeInfo(s.id);
        const effectiveCompRef = basis.id === 'image_analysis' ? '' : compRef;
        const contentPrompt = buildSectionPromptInstructions(s.id, instructions[s.id] || '');
        const content = await autoLLM.generateSectionContent(
          s,
          buildSectionScopedAnalysisPayload(s.id, analysis),
          contentPrompt,
          effectiveCompRef
        );
        content.generation_mode = mode;
        content.generation_basis = basis.id;
        content.generation_basis_label = basis.shortLabel;
        sectionContents[s.id] = content;

        // Image generation follows the selected image model
        if (mode !== 'text_only' && autoImageReady) {
          try {
            const imgPrompt = buildSectionImagePrompt(s, content, mode, analysis);
            attachSectionPromptTrace(s, content, {
              trigger: 'auto',
              contentPrompt,
              imagePrompt: imgPrompt,
              imageApiPrompt: buildImageApiPromptEnvelope(imgPrompt),
              compRef: effectiveCompRef,
              analysisOverride: analysis,
              sourceImageUsed: !!imgData.base64,
            });
            const img = await generateWithSelectedImageModel(imgPrompt, imgData.base64, imgData.mime);
            if (img) sectionImages[s.id] = img;
          } catch(e) {}
        } else {
          attachSectionPromptTrace(s, content, { trigger: 'auto', contentPrompt, compRef: effectiveCompRef, analysisOverride: analysis, sourceImageUsed: !!imgData.base64 });
        }
      } catch(e) {
        autoLog('err', `섹션 ${s.name} 실패: ${e.message}`);
        sectionContents[s.id] = { headline: s.name, subheadline: '생성 실패', body_text: e.message, color_scheme: {background:'#fff',text_primary:'#c00',text_secondary:'#e00'}, font_suggestion:{headline_size:'32px',body_size:'14px'} };
      }
      await new Promise(r => setTimeout(r, 500));
    }

    state.auto.currentProgress = 92;
    state.auto.currentMsg = 'HTML 생성 및 업로드 중...';
    render();

    // 8. Build HTML
    const htmlContent = buildExportHtml(analysis, sectionContents, sectionImages);

    // 9. Upload to Drive
    const productName = analysis.product_name || file.name.replace(/\.[^.]+$/, '');
    const fileName = `${productName}_상세페이지_${new Date().toISOString().slice(0,10)}.html`;
    const uploaded = await driveService.uploadHtml(state.auto.outputFolderId, fileName, htmlContent);
    autoLog('ok', `✅ 업로드 완료: ${fileName}`);

    // 10. Mark as processed
    state.auto.processedFileIds.add(file.id);
    localStorage.setItem('auto_processed_ids', JSON.stringify([...state.auto.processedFileIds]));
    state.auto.totalProcessed++;
    localStorage.setItem('auto_total_processed', state.auto.totalProcessed);
    state.auto.completed.unshift({ name: file.name, finishedAt: new Date().toLocaleTimeString('ko-KR'), error: null });
    if (state.auto.completed.length > 50) state.auto.completed.length = 50;
    localStorage.setItem('auto_completed', JSON.stringify(state.auto.completed));
    state.auto.currentItem = null;
    state.auto.currentProgress = 100;
    state.auto.currentMsg = '';
    render();

  } catch(e) {
    autoLog('err', `처리 실패 (${file.name}): ${e.message}`);
    state.auto.completed.unshift({ name: file.name, finishedAt: new Date().toLocaleTimeString('ko-KR'), error: e.message });
    if (state.auto.completed.length > 50) state.auto.completed.length = 50;
    localStorage.setItem('auto_completed', JSON.stringify(state.auto.completed));
    state.auto.currentItem = null;
    render();
  }
}

// ════════════════════════════════════════════════════════════════
// IMAGE CUTS — RENDER
// ════════════════════════════════════════════════════════════════
function cutsAppendRunLog(message, type = 'info', detail = '') {
  const c = state.cuts || {};
  const text = String(message || '').trim();
  if (!text) return;
  const logs = Array.isArray(c.runLogs) ? c.runLogs : [];
  const last = logs[logs.length - 1];
  const cleanDetail = String(detail || '').trim();
  if (last && last.message === text && last.detail === cleanDetail && last.type === type) return;
  c.runLogs = [
    ...logs,
    {
      ts: Date.now(),
      time: new Date().toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      message: text,
      detail: cleanDetail,
      type,
    },
  ].slice(-40);
  c.runStatus = text;
  c.runStatusType = type;
}

function cutsSetBlockingError(message) {
  state.error = message;
  cutsAppendRunLog(message, 'error');
  if (state.cuts) {
    state.cuts.runBusy = false;
    state.cuts.sizeRunBusy = false;
    (Array.isArray(state.cuts.prompts) ? state.cuts.prompts : []).forEach(p => {
      if (p) {
        p.generating = false;
        delete p.generationStartedAt;
      }
    });
    (Array.isArray(state.cuts.sizePrompts) ? state.cuts.sizePrompts : []).forEach(p => {
      if (p) {
        p.generating = false;
        delete p.generationStartedAt;
      }
    });
  }
  savePrompts();
  cutsScheduleLightSave(500);
  renderPreservingMainScroll();
  return false;
}

function clearCutGenerationRuntimeState(options = {}) {
  const c = state.cuts || {};
  let changed = false;
  if (c.runBusy) { c.runBusy = false; changed = true; }
  if (c.sizeRunBusy) { c.sizeRunBusy = false; changed = true; }
  (Array.isArray(c.prompts) ? c.prompts : []).forEach(p => {
    if (p?.generating) {
      p.generating = false;
      changed = true;
    }
  });
  (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).forEach(p => {
    if (p?.generating) {
      p.generating = false;
      changed = true;
    }
  });
  if (changed && options.log !== false) {
    cutsAppendRunLog('멈춘 생성 상태를 초기화했습니다.', 'warn', '프롬프트와 생성 결과는 유지했습니다.');
  }
  if (changed && options.save !== false) {
    savePrompts();
    cutsScheduleLightSave(500);
  }
  if (changed && options.render !== false) renderPreservingMainScroll();
  return changed;
}

function cutsClearOverdueGenerationRuntime(options = {}) {
  const c = state.cuts || {};
  const now = Date.now();
  let changed = false;
  const cleared = [];
  const clearPrompt = (prompt, index, stageId) => {
    if (!prompt?.generating) return;
    const startedAt = Number(prompt.generationStartedAt || 0);
    if (!startedAt) return;
    const normalizedStage = factoryNormalizeCutPromptStage(stageId || prompt.stageId || prompt.factoryStageId || 'cuts');
    const timeoutMs = cutRequestTimeoutMs(normalizedStage) + 15000;
    if (now - startedAt <= timeoutMs) return;
    const isSize = normalizedStage === 'size';
    const label = isSize ? `사이즈컷 ${index + 1}` : `컷 ${index + 1}`;
    const message = isSize
      ? `${label} AI 생성 요청이 ${Math.round(cutRequestTimeoutMs(normalizedStage) / 1000)}초를 초과했습니다. 생성 상태를 풀고 다시 실행할 수 있게 했습니다.`
      : cutGenerationTimeoutMessage(label, cutRequestTimeoutMs(normalizedStage));
    prompt.generating = false;
    delete prompt.generationStartedAt;
    prompt.error = prompt.error || message;
    prompt.warning = prompt.warning || '';
    const runId = prompt.currentRunId || prompt.generationRunId || prompt.factoryGenerationRunId || '';
    if (runId && typeof factoryMarkImageStageRunInactive === 'function') {
      factoryMarkImageStageRunInactive(normalizedStage, runId);
    }
    factoryMarkImageStageTimeoutState(normalizedStage, message, {
      at: now,
      onlyIncomplete: true,
    });
    cleared.push(label);
    changed = true;
  };
  (Array.isArray(c.prompts) ? c.prompts : []).forEach((prompt, index) => clearPrompt(prompt, index, prompt?.stageId || prompt?.factoryStageId || c.factoryStageId || 'cuts'));
  (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).forEach((prompt, index) => clearPrompt(prompt, index, 'size'));
  if (!changed) return false;
  if (!(Array.isArray(c.prompts) && c.prompts.some(prompt => prompt?.generating))) c.runBusy = false;
  if (!(Array.isArray(c.sizePrompts) && c.sizePrompts.some(prompt => prompt?.generating))) c.sizeRunBusy = false;
  const detail = `${cleared.join(', ')} 요청이 제한 시간을 넘겼습니다. 이전 성공 후보는 보존하고 멈춘 실행 표시만 해제했습니다.`;
  if (options.log !== false) cutsAppendRunLog('오래 멈춘 생성 상태를 정리했습니다.', 'warn', detail);
  if (options.save !== false) {
    savePrompts();
    cutsScheduleLightSave(500);
  }
  if (options.render) renderPreservingMainScroll();
  return true;
}

let cutsRenderMaintenanceMemo = { key: '', at: 0 };

function cutsRenderMaintenanceKey(c = state.cuts) {
  const factory = typeof factoryRuntimeReadFactory === 'function' ? factoryRuntimeReadFactory() : (state.factory || {});
  const assets = Array.isArray(factory?.assets) ? factory.assets : [];
  const tail = assets.slice(-8).map(asset => [
    asset?.id || '',
    asset?.stageId || '',
    asset?.updatedAt || asset?.savedAt || asset?.createdAt || '',
    asset?.currentRunId || asset?.generationRunId || '',
  ].join(':')).join('|');
  const inputKey = typeof factoryCurrentInputImageFingerprint === 'function'
    ? factoryCurrentInputImageFingerprint(factory)
    : '';
  const productKey = typeof factoryCurrentProductKey === 'function'
    ? factoryCurrentProductKey(factory)
    : '';
  return [
    productKey,
    inputKey,
    c?.factoryStageId || '',
    c?.sizeFactoryStageId || '',
    c?.promptSlotCount || 0,
    c?.sizePromptSlotCount || 0,
    assets.length,
    tail,
  ].join('::');
}

function cutsShouldRunRenderMaintenance(c = state.cuts, sessionImageHydrationPending = false) {
  if (sessionImageHydrationPending) return false;
  if (typeof factoryActiveImageStageRunKeys !== 'undefined' && factoryActiveImageStageRunKeys.size) return false;
  if (c?.runBusy || c?.sizeRunBusy) return false;
  const cutGenerating = (Array.isArray(c?.prompts) ? c.prompts : []).some(prompt => prompt?.generating);
  const sizeGenerating = (Array.isArray(c?.sizePrompts) ? c.sizePrompts : []).some(prompt => prompt?.generating);
  if (cutGenerating || sizeGenerating) return false;
  const key = cutsRenderMaintenanceKey(c);
  const now = Date.now();
  if (key !== cutsRenderMaintenanceMemo.key || now - Number(cutsRenderMaintenanceMemo.at || 0) > 15000) {
    cutsRenderMaintenanceMemo = { key, at: now };
    return true;
  }
  return false;
}

function cutsCurrentLockedProductSourceState(stageId = '') {
  const normalizedStage = typeof factoryNormalizeStageScope === 'function'
    ? factoryNormalizeStageScope(stageId)
    : String(stageId || '').trim();
  const required = ['hero', 'size', 'cuts'].includes(normalizedStage);
  if (!required) return { required: false, ready: true, stageId: normalizedStage, message: '' };
  const part = typeof factorySourceImagePart === 'function'
    ? factorySourceImagePart(normalizedStage, { preferStageInput: false })
    : null;
  if (part?.base64) {
    return {
      required: true,
      ready: true,
      stageId: normalizedStage,
      message: '',
    };
  }
  if (factoryHasRecoverableProductImageMarker(factoryRuntimeReadFactory())) {
    return {
      required: true,
      ready: true,
      recoverable: true,
      stageId: normalizedStage,
      message: '현재 제품 원본은 보관함에서 복구해 생성합니다.',
    };
  }
  return {
    required: true,
    ready: false,
    stageId: normalizedStage,
    message: '현재 제품 원본이 비어 있습니다. 1단계 제품 사진/이름 확인에서 제품 이미지를 먼저 넣어주세요.',
  };
}

function cutsScheduleLightSave(delay = 900) {
  if (typeof scheduleLastWorkSave === 'function') {
    scheduleLastWorkSave(delay, { lightweight: true });
    return;
  }
  setTimeout(() => {
    try { saveLastWorkNow?.({ sync: false }); } catch(e) {}
  }, delay);
}

function cutsScheduleAssetPersistence() {
  if (typeof scheduleSessionAssetSaveIfChanged === 'function') {
    scheduleSessionAssetSaveIfChanged();
    return;
  }
  if (typeof saveSessionAssetsToDbIfChanged === 'function') {
    setTimeout(() => {
      try { saveSessionAssetsToDbIfChanged().catch(() => {}); } catch(e) {}
    }, 0);
  }
}

async function cutsYieldAfterRender(delayMs = 60) {
  if (typeof factoryYieldToPaint === 'function') {
    await factoryYieldToPaint(delayMs);
    return;
  }
  await new Promise(resolve => setTimeout(resolve, delayMs));
}

const FACTORY_IMAGE_GENERATION_STAGE_IDS = ['hero', 'size', 'cuts'];
const factoryActiveImageStageRunKeys = new Set();
const factoryActiveImageRequestKeys = new Map();
const FACTORY_IMAGE_GENERATION_PAGE_SESSION_ID = typeof uid === 'function'
  ? uid('factory_image_page')
  : `factory_image_page_${Date.now()}_${Math.random().toString(36).slice(2)}`;

function factoryImageStageRunKey(stageId = '', runId = '') {
  const normalizedStage = typeof factoryNormalizeStageScope === 'function'
    ? factoryNormalizeStageScope(stageId)
    : String(stageId || '').trim();
  return `${normalizedStage}:${String(runId || '')}`;
}

function factoryImageStageKeyPrefix(stageId = '') {
  const normalizedStage = typeof factoryNormalizeStageScope === 'function'
    ? factoryNormalizeStageScope(stageId)
    : String(stageId || '').trim();
  return normalizedStage ? `${normalizedStage}:` : '';
}

function factoryImageStageHasAnyActiveKey(stageId = '') {
  const prefix = factoryImageStageKeyPrefix(stageId);
  if (!prefix) return factoryActiveImageStageRunKeys.size > 0;
  return Array.from(factoryActiveImageStageRunKeys).some(key => String(key || '').startsWith(prefix));
}

function factoryImageRequestKey(stageId = '', label = '', runId = '') {
  const normalizedStage = typeof factoryNormalizeStageScope === 'function'
    ? factoryNormalizeStageScope(stageId)
    : String(stageId || '').trim();
  const safeLabel = String(label || '').replace(/\s+/g, '_').slice(0, 40);
  const safeRun = String(runId || '').replace(/\s+/g, '_').slice(0, 80);
  return `${normalizedStage || 'cuts'}:${safeRun}:${safeLabel}:${Date.now()}:${Math.random().toString(36).slice(2, 8)}`;
}

function factoryMarkImageRequestActive(key = '', info = {}) {
  if (!key) return;
  factoryActiveImageRequestKeys.set(String(key), {
    ...cloneData(info || {}),
    startedAt: Date.now(),
  });
}

function factoryMarkImageRequestInactive(key = '') {
  if (!key) return;
  factoryActiveImageRequestKeys.delete(String(key));
}

function factoryHasActiveImageRequest(stageId = '') {
  const prefix = factoryImageStageKeyPrefix(stageId);
  if (!prefix) return factoryActiveImageRequestKeys.size > 0;
  return Array.from(factoryActiveImageRequestKeys.keys()).some(key => String(key || '').startsWith(prefix));
}

function factoryMarkImageStageRunActive(stageId = '', runId = '') {
  if (!stageId || !runId) return;
  factoryActiveImageStageRunKeys.add(factoryImageStageRunKey(stageId, runId));
}

function factoryMarkImageStageRunInactive(stageId = '', runId = '') {
  if (!stageId || !runId) return;
  factoryActiveImageStageRunKeys.delete(factoryImageStageRunKey(stageId, runId));
}

function factoryImageStageHasActiveRun(stageId = '', stage = {}) {
  const runIds = uniqueApiKeys([
    stage?.latestGenerationRunId,
    stage?.currentRunId,
    stage?.generationRunId,
  ].filter(Boolean));
  return runIds.some(runId => factoryActiveImageStageRunKeys.has(factoryImageStageRunKey(stageId, runId)));
}

function factoryPromptHasCurrentPageGenerationRuntime(prompt = {}) {
  if (!prompt?.generating) return false;
  const pageSessionId = String(
    prompt.generationPageSessionId ||
    prompt.metadata?.generationPageSessionId ||
    ''
  ).trim();
  return !!pageSessionId && pageSessionId === FACTORY_IMAGE_GENERATION_PAGE_SESSION_ID;
}

function factoryHasCurrentPageImageGenerationRun(c = state.cuts || {}) {
  if (typeof factoryActiveImageRequestKeys !== 'undefined' && factoryActiveImageRequestKeys.size) return true;
  if (typeof factoryActiveImageStageRunKeys !== 'undefined' && factoryActiveImageStageRunKeys.size) return true;
  const prompts = Array.isArray(c?.prompts) ? c.prompts : [];
  const sizePrompts = Array.isArray(c?.sizePrompts) ? c.sizePrompts : [];
  return prompts.some(factoryPromptHasCurrentPageGenerationRuntime) ||
    sizePrompts.some(factoryPromptHasCurrentPageGenerationRuntime);
}

function cutsHasActiveImageGeneration(c = state.cuts || {}) {
  const prompts = Array.isArray(c?.prompts) ? c.prompts : [];
  const sizePrompts = Array.isArray(c?.sizePrompts) ? c.sizePrompts : [];
  return !!(
    c?.runBusy ||
    c?.sizeRunBusy ||
    prompts.some(prompt => prompt?.generating) ||
    sizePrompts.some(prompt => prompt?.generating) ||
    factoryActiveImageRequestKeys.size ||
    factoryActiveImageStageRunKeys.size
  );
}

function factoryClearDisconnectedImageGenerationRuntime(options = {}) {
  const c = state.cuts || {};
  const now = Date.now();
  let changed = false;
  let clearedCount = 0;

  const clearPrompt = (prompt, index, stageId) => {
    if (!prompt || typeof prompt !== 'object' || !prompt.generating) return;
    const normalizedStage = factoryNormalizeCutPromptStage(stageId || prompt.stageId || prompt.factoryStageId || 'cuts');
    const pageSessionId = String(prompt.generationPageSessionId || prompt.metadata?.generationPageSessionId || '').trim();
    const fromThisPage = !!pageSessionId && pageSessionId === FACTORY_IMAGE_GENERATION_PAGE_SESSION_ID;
    const startedAt = Number(prompt.generationStartedAt || 0);
    const elapsed = startedAt ? now - startedAt : Number.MAX_SAFE_INTEGER;
    const hasActiveRequest = factoryHasActiveImageRequest(normalizedStage);
    const hasActiveStage = factoryImageStageHasAnyActiveKey(normalizedStage);
    const maxWait = cutRequestTimeoutMs(normalizedStage) + 15000;
    const preflightGraceMs = 10000;

    if (elapsed <= maxWait && (hasActiveRequest || hasActiveStage)) return;
    if (fromThisPage && elapsed <= maxWait && elapsed <= preflightGraceMs) return;

    prompt.generating = false;
    delete prompt.generationStartedAt;
    delete prompt.generationPageSessionId;
    if (prompt.metadata?.generationPageSessionId) {
      prompt.metadata = { ...cloneData(prompt.metadata || {}) };
      delete prompt.metadata.generationPageSessionId;
    }
    if (!prompt.error) {
      const label = normalizedStage === 'size' ? `사이즈컷 ${index + 1}` : `컷 ${index + 1}`;
      prompt.error = `${label}의 실제 이미지 API 요청이 남아 있지 않아 멈춘 생성 표시를 해제했습니다. 다시 생성을 누르면 새 요청을 보냅니다.`;
    }
    changed = true;
    clearedCount += 1;
  };

  (Array.isArray(c.prompts) ? c.prompts : []).forEach((prompt, index) => {
    clearPrompt(prompt, index, prompt?.stageId || prompt?.factoryStageId || c.factoryStageId || 'cuts');
  });
  (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).forEach((prompt, index) => {
    clearPrompt(prompt, index, 'size');
  });

  const anyCutGenerating = (Array.isArray(c.prompts) ? c.prompts : []).some(prompt => prompt?.generating);
  const anySizeGenerating = (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).some(prompt => prompt?.generating);
  if (c.runBusy && !anyCutGenerating && !factoryImageStageHasAnyActiveKey(c.factoryStageId || 'cuts') && !factoryHasActiveImageRequest(c.factoryStageId || 'cuts')) {
    c.runBusy = false;
    changed = true;
  }
  if (c.sizeRunBusy && !anySizeGenerating && !factoryImageStageHasAnyActiveKey('size') && !factoryHasActiveImageRequest('size')) {
    c.sizeRunBusy = false;
    changed = true;
  }

  if (!changed) return false;
  if (options.log !== false) {
    cutsAppendRunLog(
      '실제 요청 없는 생성 표시를 정리했습니다.',
      'warn',
      clearedCount
        ? `${clearedCount}개 생성 표시는 브라우저 새로고침/중단 뒤 실제 API 요청이 남아 있지 않았습니다. 다시 누르면 새 요청을 보냅니다.`
        : '실제 API 요청이 없는 전체 생성 잠금을 해제했습니다.'
    );
  }
  if (options.save !== false) {
    savePrompts();
    cutsScheduleLightSave(400);
  }
  if (options.render) renderPreservingMainScroll();
  return true;
}

function factoryTouchImageStageRun(stageId = '', runId = '', options = {}) {
  const normalizedStage = factoryNormalizeStageScope(stageId) || String(stageId || '').trim();
  if (!FACTORY_IMAGE_GENERATION_STAGE_IDS.includes(normalizedStage)) return false;
  if (!options.factory) {
    return factoryRuntimeUpdateOwnedFactory(
      'factory/assets:touchImageStageRun',
      'factory-assets',
      draft => factoryTouchImageStageRun(stageId, runId, { ...options, factory: draft }),
    ).result;
  }
  const factory = options.factory;
  if (!factory.stages) factory.stages = {};
  const stage = factory.stages[normalizedStage] || {};
  const nextRunId = String(runId || stage.currentRunId || stage.latestGenerationRunId || stage.generationRunId || '').trim();
  if (!nextRunId) return false;
  const now = Date.now();
  factory.stages[normalizedStage] = stage;
  stage.currentRunId = nextRunId;
  stage.latestGenerationRunId = nextRunId;
  stage.generationRunId = stage.generationRunId || nextRunId;
  stage.status = options.status || stage.status || 'running';
  if (options.message) stage.message = String(options.message || '');
  if (!stage.runStartedAt) stage.runStartedAt = now;
  stage.runHeartbeatAt = now;
  stage.updatedAt = now;
  if (Number.isFinite(Number(options.expectedItemCount)) && Number(options.expectedItemCount) > 0) {
    stage.expectedItemCount = Number(options.expectedItemCount);
  }
  if (Number.isFinite(Number(options.completedItemCount)) && Number(options.completedItemCount) >= 0) {
    stage.completedItemCount = Number(options.completedItemCount);
  }
  return true;
}

function factoryImageStageRunningTimeoutMs(stageId = '', stage = {}) {
  const normalizedStage = factoryNormalizeStageScope(stageId) || String(stageId || '').trim();
  const requestTimeout = typeof cutRequestTimeoutMs === 'function'
    ? cutRequestTimeoutMs(normalizedStage)
    : (normalizedStage === 'size' ? 30000 : 120000);
  const perRequest = Math.max(30000, Number(requestTimeout) || 120000);
  const expected = Math.max(1, Math.min(12, Number(stage?.expectedItemCount || stage?.targetCount || 1) || 1));
  return Math.max(perRequest + 15000, (perRequest * expected) + 45000);
}

function factoryMarkImageStageTimeoutState(stageId = '', message = '', options = {}) {
  if (!options.factory) {
    return factoryRuntimeUpdateOwnedFactory(
      'factory/assets:markImageStageTimeout',
      'factory-assets',
      draft => factoryMarkImageStageTimeoutState(stageId, message, { ...options, factory: draft }),
    ).result;
  }
  const normalizedStage = factoryNormalizeStageScope(stageId) || String(stageId || '').trim();
  if (!['hero', 'size', 'cuts'].includes(normalizedStage)) return false;
  const stage = options.factory.stages?.[normalizedStage];
  if (!stage || typeof stage !== 'object') return false;
  if (
    options.onlyIncomplete === true &&
    Number(stage.expectedItemCount || 0) > 0 &&
    Number(stage.completedItemCount || 0) >= Number(stage.expectedItemCount || 0)
  ) {
    return false;
  }
  const updatedAt = Number(options.at || Date.now()) || Date.now();
  stage.status = 'error';
  stage.message = String(message || '이미지 생성 요청이 제한 시간을 초과했습니다.');
  stage.runHeartbeatAt = updatedAt;
  stage.updatedAt = updatedAt;
  return true;
}

function factoryImageStageRunIds(stage = {}) {
  return uniqueApiKeys([
    stage?.latestGenerationRunId,
    stage?.currentRunId,
    stage?.generationRunId,
  ].filter(Boolean));
}

function factoryClearActiveImageStageRunKeys(stageId = '', stage = {}) {
  factoryImageStageRunIds(stage).forEach(runId => {
    factoryActiveImageStageRunKeys.delete(factoryImageStageRunKey(stageId, runId));
  });
}

function factoryImageStageHasPromptRuntime(stageId = '') {
  const normalizedStage = factoryNormalizeStageScope(stageId) || String(stageId || '').trim();
  const c = state.cuts || {};
  if (normalizedStage === 'size') {
    return !!c.sizeRunBusy || (Array.isArray(c.sizePrompts) && c.sizePrompts.some(prompt => !!prompt?.generating));
  }
  if (normalizedStage === 'cuts') {
    return !!c.runBusy || (Array.isArray(c.prompts) && c.prompts.some(prompt => !!prompt?.generating));
  }
  return false;
}

function factoryHasRestoredImageGenerationRuntime(factory, options = {}) {
  const c = state.cuts || {};
  const hasBusyStage = FACTORY_IMAGE_GENERATION_STAGE_IDS.some(stageId => {
    const stage = factory?.stages?.[stageId];
    if (!stage || typeof stage !== 'object') return false;
    return String(stage.status || '') === 'running' ||
      /생성\s*중|재생성\s*요청|전용 엔진|응답 대기|검수\s*중/i.test(String(stage.message || ''));
  });
  if (hasBusyStage) return true;
  if (options.clearCutsRuntime === false || factoryActiveImageStageRunKeys.size) return false;
  return !!(
    c.runBusy ||
    c.sizeRunBusy ||
    (Array.isArray(c.prompts) && c.prompts.some(prompt => prompt?.generating || prompt?.generationStartedAt || prompt?.generationPageSessionId || prompt?.metadata?.generationPageSessionId)) ||
    (Array.isArray(c.sizePrompts) && c.sizePrompts.some(prompt => prompt?.generating || prompt?.generationStartedAt || prompt?.generationPageSessionId || prompt?.metadata?.generationPageSessionId))
  );
}

function factoryClearRestoredImageGenerationRuntime(options = {}) {
  const snapshot = factoryRuntimeReadFactory();
  if (!factoryHasRestoredImageGenerationRuntime(snapshot, options)) return false;
  const receipt = factoryRuntimeUpdateOwnedFactory(
    'factory/assets:clearRestoredImageGenerationRuntime',
    'factory-assets',
    draft => factoryClearRestoredImageGenerationRuntimeOwned(draft, options),
  );
  if (receipt.result && options.save !== false) {
    savePrompts();
    if (typeof scheduleLastWorkSave === 'function') scheduleLastWorkSave(250);
    else saveLastWorkNow();
  }
  return receipt.result;
}

function factoryClearRestoredImageGenerationRuntimeOwned(factory, options = {}) {
  const c = state.cuts || {};
  const clearCutsRuntime = options.clearCutsRuntime !== false;
  let changed = false;
  let clearedStages = 0;
  const clearedStageLabels = [];
  let timedOutStages = 0;
  let ghostActiveStages = 0;

  FACTORY_IMAGE_GENERATION_STAGE_IDS.forEach(stageId => {
    const stage = factory.stages?.[stageId];
    if (!stage || typeof stage !== 'object') return;
    const status = String(stage.status || '');
    const message = String(stage.message || '');
    const looksBusy = status === 'running' || /생성\s*중|재생성\s*요청|전용 엔진|응답 대기|검수\s*중/i.test(message);
    if (!looksBusy) return;
    const hasActiveRun = factoryImageStageHasActiveRun(stageId, stage);
    if (hasActiveRun) {
      if (!['size', 'cuts'].includes(stageId) || factoryImageStageHasPromptRuntime(stageId)) return;
      factoryClearActiveImageStageRunKeys(stageId, stage);
      ghostActiveStages += 1;
      changed = true;
    }
    const startedAt = Number(stage.runHeartbeatAt || stage.runStartedAt || stage.updatedAt || 0);
    const timedOut = !!(startedAt && Date.now() - startedAt > factoryImageStageRunningTimeoutMs(stageId, stage));
    if (timedOut) {
      factoryClearActiveImageStageRunKeys(stageId, stage);
      timedOutStages += 1;
    }
    const usableCount = typeof factoryUsableAssetsForStage === 'function'
      ? factoryUsableAssetsForStage(stageId, factory).length
      : (Array.isArray(factory.assets) ? factory.assets.filter(asset => asset?.stageId === stageId && !asset.rejected).length : 0);
    stage.status = usableCount > 0 ? 'review' : 'idle';
    stage.message = usableCount > 0
      ? `${timedOut ? '응답 제한 시간을 넘긴' : '새로고침으로 남은'} ${factoryStageLabel(stageId)} 진행 표시를 해제했습니다. 후보 ${usableCount}개를 확인해주세요.`
      : `${timedOut ? '응답 제한 시간을 넘긴' : '새로고침으로 남은'} ${factoryStageLabel(stageId)} 진행 표시를 해제했습니다. 다시 생성할 수 있습니다.`;
    stage.runStartedAt = null;
    stage.updatedAt = Date.now();
    clearedStages += 1;
    clearedStageLabels.push(factoryStageLabel(stageId));
    changed = true;
  });

  if (clearCutsRuntime && !factoryActiveImageStageRunKeys.size) {
    const clearPromptRuntime = prompt => {
      if (!prompt || typeof prompt !== 'object') return;
      if (prompt.generating) {
        prompt.generating = false;
        changed = true;
      }
      if (prompt.generationStartedAt) {
        delete prompt.generationStartedAt;
        changed = true;
      }
      if (prompt.generationPageSessionId) {
        delete prompt.generationPageSessionId;
        changed = true;
      }
      if (prompt.metadata?.generationPageSessionId) {
        prompt.metadata = { ...cloneData(prompt.metadata || {}) };
        delete prompt.metadata.generationPageSessionId;
        changed = true;
      }
    };
    if (c.runBusy) {
      c.runBusy = false;
      changed = true;
    }
    if (c.sizeRunBusy) {
      c.sizeRunBusy = false;
      changed = true;
    }
    (Array.isArray(c.prompts) ? c.prompts : []).forEach(clearPromptRuntime);
    (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).forEach(clearPromptRuntime);
  }

  if (!changed) return false;
  const recoveredGoal = factory.goalRun || {};
  const looksLikeInterruptedImageRun = !String(recoveredGoal.failureReason || '').trim()
    && /이미지|대표|사이즈|옵션|컷/.test(String(recoveredGoal.currentStage || ''))
    && /생성\s*중|재생성\s*요청|응답\s*대기|검수\s*중/.test(String(recoveredGoal.currentStage || ''));
  if (
    (recoveredGoal.running || looksLikeInterruptedImageRun)
    && !recoveredGoal.activeOperationId
    && !factoryActiveImageStageRunKeys.size
  ) {
    factory.goalRun.running = false;
    factory.goalRun.stopRequested = false;
    factory.goalRun.failureReason = factory.goalRun.failureReason || '이전 이미지 생성이 화면 복원 중 끊겨 진행 표시를 해제했습니다. 기존 후보와 저장 이미지는 유지했습니다.';
    factory.goalRun.currentStage = '생성 대기';
  }
  if (options.log !== false && clearedStages) {
    const label = clearedStages === 1 ? '진행 표시 1개' : `진행 표시 ${clearedStages}개`;
    const reason = timedOutStages
      ? 'API 응답 제한 시간을 넘어 실제 진행을 확인할 수 없어 해제했습니다.'
      : (ghostActiveStages ? '실제 생성 요청이 없는 상태로 남아 있어 해제했습니다.' : '새로고침 뒤 남은 상태라 해제했습니다.');
    const stages = clearedStageLabels.filter(Boolean).join(', ') || '이미지 생성';
    factoryLog(`${stages} 상태 복구 완료: ${label} · ${reason} 기존 후보와 저장 이미지는 유지했습니다.`, 'warn', factory);
    cutsAppendRunLog('이미지 생성 상태 복구 완료', 'warn', `${stages} ${label}를 해제했습니다. 저장된 후보와 이미지 결과는 유지했습니다.`);
  }
  return true;
}

function latestCutGenerationLogStatus(logs = [], label = '') {
  if (!label) return null;
  let latest = null;
  (Array.isArray(logs) ? logs : []).forEach(log => {
    const message = String(log?.message || '');
    if (!message.startsWith(`${label} 생성`)) return;
    const ts = Number(log?.ts || 0);
    if (latest && ts < latest.ts) return;
    if (/생성 완료/.test(message)) latest = { ts, status: 'done' };
    else if (/생성 실패|생성 중단/.test(message)) latest = { ts, status: 'error' };
    else if (/생성 시작/.test(message)) latest = { ts, status: 'running' };
  });
  return latest;
}

function isCutGenerationStale(prompt, latest) {
  if (!prompt?.generating || !latest || latest.status !== 'running') return false;
  const startedAt = Number(prompt.generationStartedAt || latest.ts || 0);
  if (!startedAt) return false;
  return Date.now() - startedAt > (Number(CUTS_IMAGE_GENERATION_TIMEOUT_MS) || 240000) + 5000;
}

function clearFinishedCutGenerationFlagsFromLogs(options = {}) {
  if (typeof factoryActiveImageStageRunKeys !== 'undefined' && factoryActiveImageStageRunKeys.size) return false;
  const c = state.cuts || {};
  const logs = Array.isArray(c.runLogs) ? c.runLogs : [];
  let changed = false;
  let staleCount = 0;
  (Array.isArray(c.prompts) ? c.prompts : []).forEach((prompt, index) => {
    if (!prompt?.generating) return;
    const latest = latestCutGenerationLogStatus(logs, `컷 ${index + 1}`);
    if (!latest) return;
    if (latest.status === 'running' && !isCutGenerationStale(prompt, latest)) return;
    if (latest.status === 'running') staleCount += 1;
    prompt.generating = false;
    delete prompt.generationStartedAt;
    changed = true;
  });
  (Array.isArray(c.sizePrompts) ? c.sizePrompts : []).forEach((prompt, index) => {
    if (!prompt?.generating) return;
    const latest = latestCutGenerationLogStatus(logs, `사이즈컷 ${index + 1}`);
    if (!latest) return;
    if (latest.status === 'running' && !isCutGenerationStale(prompt, latest)) return;
    if (latest.status === 'running') staleCount += 1;
    prompt.generating = false;
    delete prompt.generationStartedAt;
    changed = true;
  });
  if (c.runBusy && !((c.prompts || []).some(p => p?.generating))) {
    c.runBusy = false;
    changed = true;
  }
  if (c.sizeRunBusy && !((c.sizePrompts || []).some(p => p?.generating))) {
    c.sizeRunBusy = false;
    changed = true;
  }
  if (changed) {
    if (!((c.prompts || []).some(p => p?.generating))) c.runBusy = false;
    if (!((c.sizePrompts || []).some(p => p?.generating))) c.sizeRunBusy = false;
    if (staleCount) {
      cutsAppendRunLog('오래 멈춘 생성 표시를 정리했습니다.', 'warn', '생성 요청이 타임아웃 기준을 넘겨 진행 표시를 해제했습니다. 다시 생성할 수 있습니다.');
    } else {
      cutsAppendRunLog('완료된 생성 표시를 정리했습니다.', 'warn', '생성 결과 저장 후 화면 갱신이 늦어 남아 있던 진행 표시를 해제했습니다.');
    }
    if (options.save !== false) {
      savePrompts();
      saveLastWorkNow();
    }
  }
  return changed;
}

function cutGenerationTimeoutMessage(label = '이미지컷', timeoutMs = CUTS_IMAGE_GENERATION_TIMEOUT_MS) {
  const sec = Math.round((Number(timeoutMs) || Number(CUTS_IMAGE_GENERATION_TIMEOUT_MS) || 240000) / 1000);
  return `${label} 생성 요청이 ${sec}초를 초과했습니다. API 응답이 멈춘 것으로 보고 생성 상태를 풀었습니다. 모델/API 연결을 확인한 뒤 다시 실행해주세요.`;
}

function cutRequestTimeoutMs(stageId = 'cuts') {
  const base = Number(CUTS_IMAGE_GENERATION_TIMEOUT_MS) || 240000;
  if (String(stageId || '') === 'size') return Math.max(120000, Math.min(base, 240000));
  return Math.max(120000, Math.min(base, 240000));
}

function markCutUiTimeout(stageId = 'cuts', idx = 0, message = '') {
  const normalizedStage = factoryNormalizeCutPromptStage(stageId || 'cuts');
  const c = state.cuts || {};
  const isSizeStage = normalizedStage === 'size';
  const prompts = isSizeStage ? (c.sizePrompts || []) : (c.prompts || []);
  const prompt = prompts[idx];
  const label = isSizeStage ? `사이즈컷 ${idx + 1}` : `컷 ${idx + 1}`;
  const finalMessage = message || cutGenerationTimeoutMessage(label, cutRequestTimeoutMs(normalizedStage));
  if (prompt) {
    prompt.generating = false;
    delete prompt.generationStartedAt;
    prompt.error = finalMessage;
    prompt.warning = '';
  }
  if (isSizeStage) {
    if (!(c.sizePrompts || []).some(item => item?.generating)) c.sizeRunBusy = false;
  } else if (!(c.prompts || []).some(item => item?.generating)) {
    c.runBusy = false;
  }
  const factory = factoryRuntimeReadFactory();
  const stage = factory.stages?.[normalizedStage] || {};
  const runId = factoryCurrentStageRunId(normalizedStage, factory) ||
    stage.currentRunId ||
    stage.latestGenerationRunId ||
    stage.generationRunId ||
    prompt?.generationRunId ||
    '';
  if (runId) factoryMarkImageStageRunInactive(normalizedStage, runId);
  factoryMarkImageStageTimeoutState(normalizedStage, finalMessage);
  state.error = finalMessage;
  cutsAppendRunLog(`${label} 생성 시간 초과`, 'error', finalMessage);
  savePrompts();
  cutsScheduleLightSave(500);
  renderPreservingMainScroll();
}

async function runCutGenerationWithUiTimeout(stageId = 'cuts', idx = 0, runner = null) {
  const normalizedStage = factoryNormalizeCutPromptStage(stageId || 'cuts');
  const label = normalizedStage === 'size' ? `사이즈컷 ${idx + 1}` : `컷 ${idx + 1}`;
  const requestTimeout = cutRequestTimeoutMs(normalizedStage);
  const uiTimeout = requestTimeout + 15000;
  const message = normalizedStage === 'size'
    ? `${label} AI 생성 요청이 ${Math.round(requestTimeout / 1000)}초를 초과했습니다. 생성 상태를 풀었습니다. 모델/API 연결을 확인한 뒤 다시 실행해주세요.`
    : cutGenerationTimeoutMessage(label, requestTimeout);
  let timedOut = false;
  let timer = null;
  const work = Promise.resolve()
    .then(() => (typeof runner === 'function' ? runner() : false))
    .catch(error => {
      if (timedOut) {
        cutsAppendRunLog(`${label} 늦은 오류 폐기`, 'warn', error?.message || String(error));
        return false;
      }
      throw error;
    });
  const timeout = new Promise(resolve => {
    timer = setTimeout(() => {
      timedOut = true;
      markCutUiTimeout(normalizedStage, idx, message);
      resolve(false);
    }, uiTimeout);
  });
  try {
    return await Promise.race([work, timeout]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function generateImageWithAbortableTimeout(label, prompt, base64, mime, extraImages = [], options = {}) {
  const stageId = options.stageId || 'cuts';
  const timeoutMs = Number(options.timeoutMs || cutRequestTimeoutMs(stageId)) || 120000;
  const message = options.timeoutMessage || cutGenerationTimeoutMessage(label, timeoutMs);
  const executeImageGeneration = typeof options.executor === 'function'
    ? options.executor
    : generateWithSelectedImageModel;
  const executionOptions = { ...options };
  delete executionOptions.executor;
  const upstreamSignal = options.signal || options.operationSignal || null;
  delete executionOptions.operationSignal;
  const runInfo = typeof getCurrentImageRunInfo === 'function' ? getCurrentImageRunInfo() : {};
  const requestKey = factoryImageRequestKey(stageId, label, options.runId || options.generationRunId || options.factoryGenerationRunId || '');
  const routeText = [
    runInfo.providerLabel || '',
    runInfo.modelLabel || runInfo.modelId || '',
    runInfo.route || '',
    `제한 ${Math.round(timeoutMs / 1000)}초`,
  ].filter(Boolean).join(' · ');
  factoryMarkImageRequestActive(requestKey, {
    stageId,
    label,
    runId: options.runId || options.generationRunId || options.factoryGenerationRunId || '',
    modelId: runInfo.modelId || '',
    route: runInfo.route || '',
  });
  cutsAppendRunLog(`${label} 이미지 API 요청 시작`, 'info', routeText || `제한 ${Math.round(timeoutMs / 1000)}초`);
  if (typeof AbortController !== 'function') {
    try {
      return await withTimeout(
        executeImageGeneration(prompt, base64, mime, extraImages, executionOptions),
        timeoutMs,
        message
      );
    } finally {
      factoryMarkImageRequestInactive(requestKey);
      cutsAppendRunLog(`${label} 이미지 API 요청 종료`, 'info', routeText || '');
    }
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(message), timeoutMs);
  const abortFromUpstream = () => controller.abort(upstreamSignal?.reason || 'operation aborted');
  if (upstreamSignal?.aborted) abortFromUpstream();
  else upstreamSignal?.addEventListener?.('abort', abortFromUpstream, { once: true });
  try {
    return await executeImageGeneration(prompt, base64, mime, extraImages, {
      ...executionOptions,
      signal: controller.signal,
    });
  } catch (e) {
    const aborted = e?.name === 'AbortError' || controller.signal.aborted;
    if (aborted) throw new Error(message);
    throw e;
  } finally {
    upstreamSignal?.removeEventListener?.('abort', abortFromUpstream);
    factoryMarkImageRequestInactive(requestKey);
    cutsAppendRunLog(`${label} 이미지 API 요청 종료`, 'info', routeText || '');
    clearTimeout(timer);
  }
}

function cutGeneratingHelperText(prompt, label = '이미지컷') {
  const timeoutSec = Math.round(cutRequestTimeoutMs(prompt?.stageId || prompt?.factoryStageId || 'cuts') / 1000);
  const startedAt = Number(prompt?.generationStartedAt || 0);
  const elapsed = startedAt ? Math.max(0, Math.floor((Date.now() - startedAt) / 1000)) : 0;
  return startedAt
    ? `${label} API 응답 대기 중 · ${elapsed}초 경과 / 최대 ${timeoutSec}초`
    : `${label} API 응답 대기 중 · 최대 ${timeoutSec}초`;
}

function wrapCanvasText(ctx, text, x, y, maxWidth, lineHeight, maxLines = 4) {
  const words = String(text || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const lines = [];
  let line = '';
  words.forEach(word => {
    const next = line ? `${line} ${word}` : word;
    if (ctx.measureText(next).width <= maxWidth || !line) {
      line = next;
    } else {
      lines.push(line);
      line = word;
    }
  });
  if (line) lines.push(line);
  lines.slice(0, maxLines).forEach((item, index) => {
    const suffix = index === maxLines - 1 && lines.length > maxLines ? '...' : '';
    ctx.fillText(item + suffix, x, y + index * lineHeight);
  });
  return Math.min(lines.length, maxLines) * lineHeight;
}

function sizeFactsForCanvas() {
  const facts = factoryCollectDbSizeFacts();
  const primary = [];
  const push = (label, value) => {
    const text = String(value || '').trim();
    if (text) primary.push({ label, value: text });
  };
  const byLabel = label => facts.find(fact => fact.label === label)?.value || '';
  push('사이즈/규격', byLabel('사이즈/규격'));
  push('가로', byLabel('가로'));
  push('세로', byLabel('세로'));
  push('높이/두께', byLabel('높이/두께'));
  push('제품 무게', byLabel('제품 무게'));
  facts.forEach(fact => {
    if (!primary.some(item => item.label === fact.label && item.value === fact.value)) push(fact.label, fact.value);
  });
  return primary.filter(item => item.value).slice(0, 8);
}

async function generateLocalSizeCutImage(primaryImage, promptText = '') {
  if (!primaryImage?.base64) throw new Error('로컬 사이즈 이미지를 만들 원본 이미지가 없습니다.');
  const mime = primaryImage.mime || 'image/png';
  const img = await loadImageElement(`data:${mime};base64,${primaryImage.base64}`);
  const canvas = document.createElement('canvas');
  canvas.width = 1200;
  canvas.height = 900;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#f7f4ee';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#ffffff';
  roundRect(ctx, 54, 54, 1092, 792, 28, true, false);
  ctx.strokeStyle = 'rgba(15,23,42,.12)';
  ctx.lineWidth = 2;
  roundRect(ctx, 54, 54, 1092, 792, 28, false, true);

  ctx.fillStyle = '#111827';
  ctx.font = '900 44px Pretendard, Arial, sans-serif';
  ctx.fillText('SIZE INFO', 92, 124);
  ctx.font = '500 22px Pretendard, Arial, sans-serif';
  ctx.fillStyle = '#64748b';
  ctx.fillText('DB에 확정된 실제 규격만 표기합니다.', 92, 160);

  drawFittedImage(ctx, img, 78, 190, 610, 560);

  const facts = sizeFactsForCanvas();
  const startX = 720;
  let y = 220;
  ctx.font = '800 28px Pretendard, Arial, sans-serif';
  ctx.fillStyle = '#111827';
  ctx.fillText('제품 규격', startX, y);
  y += 36;

  if (!facts.length) {
    ctx.fillStyle = '#dc2626';
    ctx.font = '800 26px Pretendard, Arial, sans-serif';
    ctx.fillText('DB 사이즈 정보 없음', startX, y + 20);
  } else {
    facts.forEach((fact, index) => {
      const rowY = y + index * 68;
      ctx.fillStyle = '#eff6ff';
      roundRect(ctx, startX, rowY, 360, 48, 18, true, false);
      ctx.fillStyle = '#2563eb';
      ctx.font = '800 19px Pretendard, Arial, sans-serif';
      ctx.fillText(fact.label, startX + 18, rowY + 30);
      ctx.fillStyle = '#111827';
      ctx.font = '900 24px Pretendard, Arial, sans-serif';
      drawFittedText(ctx, fact.value, startX + 146, rowY + 31, 200, 24);
    });
    y += facts.length * 68 + 12;
  }

  const prompt = String(promptText || '').trim();
  if (prompt) {
    ctx.fillStyle = '#f8fafc';
    roundRect(ctx, startX, Math.min(y, 680), 360, 86, 16, true, false);
    ctx.fillStyle = '#475569';
    ctx.font = '600 18px Pretendard, Arial, sans-serif';
    wrapCanvasText(ctx, prompt, startX + 18, Math.min(y, 680) + 30, 324, 24, 2);
  }

  ctx.fillStyle = '#0f172a';
  ctx.font = '700 18px Pretendard, Arial, sans-serif';
  ctx.fillText('상세페이지 자동화 · 로컬 사이즈 이미지', 92, 812);
  return canvas.toDataURL('image/png');
}

async function generateLocalFactoryImageCut(primaryImage, promptText = '', options = {}) {
  if (!primaryImage?.base64) throw new Error('로컬 이미지를 만들 현재 제품 이미지가 없습니다.');
  const mime = primaryImage.mime || 'image/png';
  const img = await loadImageElement(`data:${mime};base64,${primaryImage.base64}`);
  const canvas = document.createElement('canvas');
  canvas.width = 1200;
  canvas.height = 900;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = options.stageId === 'hero' ? '#f6f1ea' : '#f8fafc';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#ffffff';
  roundRect(ctx, 72, 64, 1056, 708, 30, true, false);
  ctx.strokeStyle = 'rgba(15,23,42,.10)';
  ctx.lineWidth = 2;
  roundRect(ctx, 72, 64, 1056, 708, 30, false, true);

  drawFittedImage(ctx, img, 150, 118, 900, 560);

  const label = options.stageId === 'hero' ? '대표이미지 로컬 결과' : '이미지컷 로컬 결과';
  ctx.fillStyle = '#111827';
  ctx.font = '900 34px Pretendard, Arial, sans-serif';
  ctx.fillText(label, 92, 824);
  ctx.font = '600 19px Pretendard, Arial, sans-serif';
  ctx.fillStyle = '#64748b';
  wrapCanvasText(ctx, String(promptText || '').trim() || '이미지 API 오류로 현재 제품 사진 기준 로컬 후보를 만들었습니다.', 92, 854, 980, 24, 1);
  return canvas.toDataURL('image/png');
}

function cutsVisibleLogText(value = '') {
  return String(value || '')
    .replace(/이미지\s*API\s*실패로\s*현재\s*제품\s*사진\s*기준\s*로컬\s*대체컷\s*생성:\s*/g, '이미지 API 실패: ')
    .replace(/로컬\s*대체\s*생성\s*완료/g, '이미지 API 실패')
    .replace(/로컬\s*대체컷/g, '이전 로컬 결과')
    .replace(/대체컷/g, '이전 로컬 결과')
    .replace(/로컬\s*사이즈컷\s*대체/g, '로컬 사이즈 이미지 생성 차단')
    .replace(/안전후보/g, '임시후보');
}

