// ── bindEvents 확장 (이미지컷) ──
function cutsLockedStageForCurrentProductUpload() {
  const c = state.cuts || {};
  const mainStage = String(c.factoryStageId || '').trim();
  if (['hero', 'cuts', 'size'].includes(mainStage)) return mainStage;
  const sizeStage = String(c.sizeFactoryStageId || '').trim();
  if (sizeStage === 'size') return 'size';
  return '';
}

function cutsPromoteFileToCurrentProduct(file, stageId = 'cuts') {
  const normalizedStage = ['hero', 'size', 'cuts'].includes(String(stageId || '')) ? String(stageId || '') : 'cuts';
  if (!file?.type?.startsWith('image/')) return false;
  const store = factoryRuntimeRequireStore();
  const operationToken = store.getOperationToken();
  const selectedFactory = store.getSnapshot().factory;
  const operationIdentity = factorySourceOperationIdentity(selectedFactory, operationToken);
  const cutsSelectedFileIdentity = Object.freeze({
    file,
    name: String(file.name || ''),
    type: String(file.type || ''),
    size: Number(file.size) || 0,
    lastModified: Number(file.lastModified) || 0,
    operationIdentity,
    operationToken,
  });
  const previousReader = cutsPromoteFileToCurrentProduct.activeReader;
  if (previousReader && typeof previousReader.abort === 'function') {
    try { previousReader.abort(); } catch(e) {}
  }
  const reader = new FileReader();
  cutsPromoteFileToCurrentProduct.activeReader = reader;
  cutsPromoteFileToCurrentProduct.activeFile = file;
  cutsPromoteFileToCurrentProduct.activeFileIdentity = cutsSelectedFileIdentity;
  let firstTerminalEvent = '';
  const cleanupTerminalEvent = () => {
    reader.onload = null;
    reader.onerror = null;
    reader.onabort = null;
    if (cutsPromoteFileToCurrentProduct.activeReader === reader) {
      cutsPromoteFileToCurrentProduct.activeReader = null;
    }
    if (cutsPromoteFileToCurrentProduct.activeFile === file) {
      cutsPromoteFileToCurrentProduct.activeFile = null;
    }
    if (cutsPromoteFileToCurrentProduct.activeFileIdentity === cutsSelectedFileIdentity) {
      cutsPromoteFileToCurrentProduct.activeFileIdentity = null;
    }
  };
  const terminalEvent = (kind, event = null) => {
    if (firstTerminalEvent) return;
    firstTerminalEvent = kind;
    const selectionIsCurrent = cutsPromoteFileToCurrentProduct.activeReader === reader &&
      cutsPromoteFileToCurrentProduct.activeFile === file &&
      cutsPromoteFileToCurrentProduct.activeFileIdentity === cutsSelectedFileIdentity;
    cleanupTerminalEvent();
    if (kind !== 'load' || !selectionIsCurrent || !store.isOperationCurrent(operationToken)) return;
    const currentBeforeCommit = store.getSnapshot().factory;
    if (!factorySourceOperationIdentityMatches(operationIdentity, currentBeforeCommit)) return;
    const preview = event?.target?.result;
    const rawBase64 = String(preview || '').split(',')[1] || '';
    const base64 = typeof imageBase64Only === 'function' ? imageBase64Only(rawBase64) : rawBase64;
    if (!base64) return;
    const mime = typeof inferImageMimeFromBase64 === 'function'
      ? inferImageMimeFromBase64(base64, file.type || 'image/png')
      : (file.type || 'image/png');
    const name = file.name || '제품사진';
    const uploadedAt = Date.now();
    let receipt;
    try {
      receipt = factoryRuntimeUpdateOwnedFactory(
        'factory/source:promoteCutsInputFile',
        'factory-assets',
        factory => {
          if (!store.isOperationCurrent(operationToken)) {
            throw factoryRuntimeStaleActionError('factory/source:promoteCutsInputFile');
          }
          if (!factorySourceOperationIdentityMatches(operationIdentity, factory)) {
            throw factoryRuntimeStaleActionError('factory/source:promoteCutsInputFile');
          }
          const identityMeta = typeof factoryCurrentProductIdentityMeta === 'function'
            ? factoryCurrentProductIdentityMeta(factory, [factory.product?.productName, factory.product?.userProductName])
            : { productName: factory.product?.productName || factory.product?.userProductName || '', productIdentityKey: factory.product?.productKey || '' };
          const inputImageFingerprint = factoryStampLockedInputImage(
            factory,
            { base64, mime, preview, name, productName: identityMeta.productName, productKey: identityMeta.productIdentityKey },
            {
              name,
              setAt: uploadedAt,
              productName: identityMeta.productName,
              productKey: identityMeta.productIdentityKey,
              deferPeerState: true,
            },
          );
          if (!inputImageFingerprint) throw new Error('selected image promotion failed');
          return {
            ok: true,
            identity: operationIdentity,
            composition: { base64, mime, preview, name },
            archivePayload: { base64, mime, preview, name, inputImageFingerprint, uploadedAt },
          };
        },
      );
    } catch(e) {
      return;
    }
    const committedOperationToken = store.getOperationToken();
    const committedFactory = receipt?.snapshot?.factory;
    if (!receipt?.result?.ok || !committedFactory || !store.isOperationCurrent(committedOperationToken)) return;
    if (store.getSnapshot().factory !== committedFactory) return;
    if (!factorySourceOperationIdentityMatches(receipt.result.identity, committedFactory)) return;
    if (!factoryApplyCommittedSourceImageComposition(receipt.result.composition, {
      force: true,
      operationToken: committedOperationToken,
    })) return;
    if (!store.isOperationCurrent(committedOperationToken)) return;
    factoryApplyCutsSourceImageToState(normalizedStage, receipt.result.composition, {
      factory: committedFactory,
      log: false,
    });
    cutsAppendRunLog('제품 원본 등록 완료', 'ok', `${name} · 현재 작업 전용 기본이미지로 고정했습니다.`);
    if (typeof factoryArchiveCurrentInputImage === 'function' &&
      store.isOperationCurrent(committedOperationToken) &&
      factorySourceOperationIdentityMatches(receipt.result.identity, committedFactory)) {
      factoryArchiveCurrentInputImage(receipt.result.archivePayload, {
        reason: 'cuts-current-product-upload',
        operationIdentity: receipt.result.identity,
        operationToken: committedOperationToken,
      })
        .then(saved => {
          if (saved &&
            factorySourceOperationIdentityMatches(receipt.result.identity, store.getSnapshot().factory) &&
            typeof factoryRefreshLocalArchiveAssets === 'function') {
            factoryRefreshLocalArchiveAssets({ auto: true, silent: true }).catch(() => {});
          }
        })
        .catch(() => {});
    }
    savePrompts();
    cutsScheduleLightSave(600);
    renderPreservingMainScroll();
  };
  reader.onload = event => terminalEvent('load', event);
  reader.onerror = event => terminalEvent('error', event);
  reader.onabort = event => terminalEvent('abort', event);
  try {
    reader.readAsDataURL(file);
  } catch(e) {
    terminalEvent('throw');
    return false;
  }
  return true;
}

function loadCutSource(file) {
  const lockedStage = cutsLockedStageForCurrentProductUpload();
  if (lockedStage) {
    cutsPromoteFileToCurrentProduct(file, lockedStage);
    return;
  }
  state.cuts.sourceMime = file.type;
  const reader = new FileReader();
  reader.onload = e => {
    state.cuts.sourcePreview = e.target.result;
    state.cuts.sourceBase64 = e.target.result.split(',')[1];
    state.cuts.styleReferenceEnabled = true;
    cutsScheduleLightSave(600);
    render();
  };
  reader.readAsDataURL(file);
}

function loadCutWorkImage(file) {
  state.cuts.workImageMime = file.type;
  const reader = new FileReader();
  reader.onload = e => {
    state.cuts.workImagePreview = e.target.result;
    state.cuts.workImageBase64 = e.target.result.split(',')[1];
    saveLastWorkNow();
    render();
  };
  reader.readAsDataURL(file);
}

function clearWorkImage() {
  state.cuts.workImageBase64 = null;
  state.cuts.workImageMime = null;
  state.cuts.workImagePreview = null;
  saveLastWorkNow();
  render();
}

function clearCutSourceImage() {
  if (['hero', 'cuts'].includes(String(state.cuts?.factoryStageId || ''))) {
    cutsAppendRunLog('현재 제품 원본은 해제할 수 없습니다.', 'warn', '조립공장 대표/이미지컷 생성에서는 현재 업로드 사진을 제품 기준으로 고정합니다.');
    render();
    return;
  }
  state.cuts.sourceBase64 = null;
  state.cuts.sourceMime = null;
  state.cuts.sourcePreview = null;
  state.cuts.styleReferenceEnabled = false;
  saveLastWorkNow();
  render();
}

async function runCutsWorkDriveAutomation() {
  if (!driveService && !(await ensureDriveServiceReady())) { state.error = 'Drive가 연결되어 있지 않습니다. 자동화 탭에서 연결하세요.'; render(); return; }
  const folderId = state.cuts.workDriveFolderId;
  if (!folderId) { state.error = '작업 이미지 Drive 폴더 ID를 입력하세요.'; render(); return; }
  const hasPrompts = state.cuts.prompts.some(p => p.prompt.trim());
  if (!hasPrompts) { state.error = '프롬프트를 하나 이상 입력하세요.'; render(); return; }

  state.cuts.workDriveRunning = true;
  render();

  try {
    const files = await driveService.listImages(folderId);
    if (files.length === 0) {
      state.error = '폴더에 이미지가 없습니다.';
      state.cuts.workDriveRunning = false;
      render();
      return;
    }

    for (const file of files) {
      state.progressMsg = `작업 이미지 처리 중: ${file.name}`;
      render();
      try {
        const imgData = await driveService.downloadFile(file.id);
        const workImgOverride = { base64: imgData.base64, mime: imgData.mime };
        // 이 작업 이미지로 모든 컷 생성
        for (let i = 0; i < state.cuts.prompts.length; i++) {
          if (!state.cuts.prompts[i].prompt.trim()) continue;
          await generateCut(i, workImgOverride);
          await new Promise(r => setTimeout(r, 600));
        }
        // 결과를 Drive 출력 폴더가 있으면 업로드 (자동화 output 폴더 재사용)
        if (state.auto.outputFolderId && driveService) {
          for (let i = 0; i < state.cuts.prompts.length; i++) {
            const cut = state.cuts.prompts[i];
            if (!cut.result) continue;
            try {
              const baseName = file.name.replace(/\.[^.]+$/, '');
              const blob = await (await fetch(cut.result)).blob();
              const jpegBlob = await convertToJpegBlob(blob);
              await driveService.uploadImage(state.auto.outputFolderId, `${baseName}_cut${i+1}.jpg`, jpegBlob);
            } catch(e2) { console.warn('Drive 업로드 실패:', e2.message); }
          }
        }
      } catch(e) {
        console.warn(`${file.name} 처리 실패:`, e.message);
      }
    }
    state.progressMsg = '';
    state.cuts.workDriveRunning = false;
    render();
  } catch(e) {
    state.error = `Drive 자동화 실패: ${e.message}`;
    state.cuts.workDriveRunning = false;
    render();
  }
}

async function convertToJpegBlob(blob) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      canvas.getContext('2d').drawImage(img, 0, 0);
      URL.revokeObjectURL(url);
      canvas.toBlob(b => b ? resolve(b) : reject(new Error('변환 실패')), 'image/jpeg', 0.92);
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('이미지 로드 실패')); };
    img.src = url;
  });
}

function buildExportHtml(analysis, sectionContents, sectionImages, detailImageBlocks = []) {
  if (typeof syncFixedSectionPlacementImages === 'function') {
    syncFixedSectionPlacementImages({ savePlacement: false });
    sectionImages = state.sectionImages || sectionImages;
  }
  let sectionsHtml = '';
  for (const s of orderedSections()) {
    const content = sectionContents[s.id];
    const img = sectionImages[s.id];
    const displayableImg = typeof displayableImageSrc === 'function' ? displayableImageSrc(img) : img;
    if (!content && !displayableImg) continue;
    sectionsHtml += renderSectionTemplate(s, content, img, 'export');
    sectionsHtml += renderDetailImageBlocksAfter(s.id, 'export', detailImageBlocks);
  }
  const fixedTopHtml = typeof renderFixedDetailImageForExport === 'function' ? renderFixedDetailImageForExport('brand') : '';
  const fixedBottomHtml = typeof renderFixedDetailImageForExport === 'function'
    ? `${renderFixedDetailImageForExport('package')}${renderFixedDetailImageForExport('return')}`
    : '';
  return `<!DOCTYPE html><html lang="ko"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>${analysis?.product_name||'상세페이지'}</title><link href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@300;400;500;700;900&display=swap" rel="stylesheet"><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Pretendard','Noto Sans KR',sans-serif;color:#333}img{max-width:100%;height:auto}section{width:100%}.fixed-detail-page-image{line-height:0;background:#fff}.fixed-detail-page-image img{display:block;width:100%;height:auto}</style></head><body>${fixedTopHtml}${sectionsHtml}${fixedBottomHtml}</body></html>`;
}

function startAutomation() {
  if (state.auto.running) return;
  state.auto.running = true;
  autoLog('info', `자동화 시작 (${state.auto.intervalMin}분 간격)`);

  // Run immediately
  autoProcessOne();

  // Schedule
  state.auto.timerId = setInterval(() => {
    if (!state.auto.currentItem) { // 이전 작업 완료된 경우만
      const now = new Date();
      state.auto.nextRunAt = new Date(now.getTime() + state.auto.intervalMin * 60000).toLocaleTimeString('ko-KR');
      autoProcessOne();
    }
  }, state.auto.intervalMin * 60 * 1000);

  const now = new Date();
  state.auto.nextRunAt = new Date(now.getTime() + state.auto.intervalMin * 60000).toLocaleTimeString('ko-KR');
  render();
}

function stopAutomation() {
  state.auto.running = false;
  if (state.auto.timerId) {
    clearInterval(state.auto.timerId);
    state.auto.timerId = null;
  }
  state.auto.nextRunAt = null;
  autoLog('info', '자동화 중지됨');
  render();
}

